-- ----------------------------
-- Table structure for texts
-- ----------------------------
DROP TABLE IF EXISTS "texts";
CREATE TABLE "texts" (
  "id" text,
  "name" text,
  "desc" text,
  "str1" text,
  "str2" text,
  "str3" text,
  "str4" text,
  "str5" text,
  "str6" text,
  "str7" text,
  "str8" text,
  "str9" text,
  "str10" text,
  "str11" text,
  "str12" text,
  "str13" text,
  "str14" text,
  "str15" text,
  "str16" text,
  "isok" integer,
  PRIMARY KEY ("id")
);

-- ----------------------------
-- Records of texts
-- ----------------------------
INSERT INTO "texts" VALUES ('RD/ST01-JP001', '七道魔导士', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[自己墓地的怪兽的属性的种类]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP002', '风使者 特鲁尼', '【条件】可以将1张手牌送入墓地发动。
【效果】选对手场上的1只怪兽变更表示形式（攻击表示表为表侧守备表示，守备表示变为表侧攻击表示）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP003', '魔剑士 应答之剑', '让傀儡炎魔挥舞自己的魔剑。似乎与炎魔比试胜出的人会被魔剑认可为真正的执剑者。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP004', '水魔法师', '与水心意相通的魔法师青年。其苍蓝而华丽的飞舞身姿令敌人也着迷。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP005', '黑暗术士', '染指禁忌之术的魔术师。他还不知道他所渴望的那种力量所需的代价是什么。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP006', '神秘荷官', '【条件】可以将手牌的1只怪兽（魔法师族）送入墓地发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP007', '魔兽 钨狼', '著名魔法师的前使魔。运用不知不觉超越主人的魔力，自由自在地操纵火焰愚弄敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP008', '咒术弓箭手', '被风爱着的年轻的弓箭名手。用魔力创造出来的箭可以一直不停地飞下去。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP009', '光之萨满', '【条件】可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（等级4以下/魔法师族）。这个回合，那只怪兽可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP010', '落单使魔', '被认为是隐藏有强大力量的使魔。原本就是个容易感到寂寞的孩子，但和同伴失散之后最近更加寂寞了。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP011', '风精的加护', '【条件】可以将1张手牌送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（魔法师族），其攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP012', '魔力水流', '【条件】自己场上有表侧表示怪兽（魔法师族）的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP013', '黑暗启示', '【条件】对手怪兽的攻击宣言时，可以使自己墓地的4只怪兽（魔法师族）返回卡组发动。
【效果】将对手场上的攻击表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST01-JP014', '火星之幕', '【条件】自己的墓地有怪兽（魔法师族）的场合，对手怪兽的攻击宣言时可以发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP001', '连击龙 德拉基亚斯', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这个回合，这张卡用战斗将怪兽破坏的战斗阶段里，这张卡可以仅1次再攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP002', '重力压龙', '【条件】可以将1张手牌送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，直到回合结束时其攻击力、守备力下降700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP003', '火口的守卫龙', '阻拦在通往火龙王国的路上的守门人。忍耐不下其吐息的人没有继续前进的资格。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP004', '暗黑龙骑士', '率领暗黑军势的龙骑士。毫无怜悯之心的一击强力无比。其手中的邪剑会吞食敌人的灵魂不断成长。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP005', '辉岩龙', '起源于地下矿脉的龙。以未知的矿石发出的能源作为动力源来不断战斗。其超硬度的打击威力不一般！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP006', '双刃龙', '【条件】可以将1张手牌送入墓地发动。
【效果】这个回合，这张卡可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP007', '龙之祈子', '继承古代的龙之血脉的年轻巫女。为了一族的安宁而每日不断祈祷。据说她那清澈的眼眸中，有着可以改变看到的人的未来的力量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP008', '龙蝙蝠', '是鸟还是兽，连学者们的意见也有所分歧的谜之生物。因其成群结队地飞行时的样子看起来也像龙，说不定也有可能是龙。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP009', '不死鸟之龙', '【条件】可以将1张手牌送入墓地发动。
【效果】选自己墓地的1只怪兽（等级5以上/龙族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP010', '小巧玲龙', '热爱和平的小型龙。亲近人类，向它丢果实的话会靠近。挂在脖子上的指环里似乎隐藏了什么厉害的秘密。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP011', '龙力重压', '【条件】可以将手牌的3只怪兽（龙族）送入墓地发动。
【效果】将双方场上的怪兽全部破坏。用这个效果将怪兽破坏的场合，可以选自己墓地的1只怪兽（等级4以下/龙族），以表侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP012', '火龙的热闪', '【条件】自己场上有表侧表示怪兽（龙族）的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP013', '龙之遭遇', '【条件】对手召唤或特殊召唤怪兽时可以发动。
【效果】将手牌的1只怪兽（龙族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ST02-JP014', '反攻的龙击', '【条件】自己场上的怪兽（龙族）被对手怪兽的攻击破坏时，可以将1张手牌送入墓地发动。
【效果】选对手场上的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VS01-JP001', '七道魔女', '【条件】可以将1张手牌送入墓地发动。
【效果】将手牌的1只怪兽（等级7以上/暗属性/魔法师族）以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤「七道魔导士」的场合，这张卡的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP000', '蓝眼白龙', '拥有引以为傲的高攻击力的传说之龙。不管是怎样的对手都能粉碎，其破坏力无法估计。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP001', '蜥蜴兵', '从龙派生出来的兽人种。在龙族之中体形小而敏捷。战略性丰富。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP002', '下级龙', '不太强，连吐息攻击也做不到的低级的龙。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP003', '古之守护龟', '重视传统，怀念着古老美好的时代。当年真好。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP004', '封印之锁', '有紧紧绑住对手并施以封印的力量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP005', '火面忍者 赤红卷面', '对筋道十足和独特的口感很是自信的忍者。无论多少人都不能从他那汤水充足的面条的束缚逃走。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP006', '宝贝霸王龙', '霸王龙的孩子。有着非常凶暴的性格。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP007', '菊石骑士', '很久以前守护大海防范外敌的菊石骑士。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP008', '小蛾虫', '不知道成长之后会变成怎样的虫的细小的幼虫。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP009', '白骨', '不管哪里都会出现的骸骨妖怪。攻击虽然很弱但是一旦多起来就很不得了。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP010', '银牙狼', '闪耀白银光辉的狼。外表美丽但性格凶暴。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP011', '小精怪', '喜欢恶作剧的小恶魔。从黑暗中袭击。要当心！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP012', '圣鸟', '尾巴非常长的鸟。全身散发着神圣的光。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP013', '月魔使', '住在月亮上的魔法师。用月亮拥有的魔力迷住对手。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP014', '机械攻击者', '用于特攻而被制作出来的机械。用突击将敌人扫倒在地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP015', '伏地龙', '力量变得衰弱，不能再在天空飞的龙。可是攻击还是很强。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP016', '极斧袭击者', '手持巨斧的战士。将自己逼至极限来把肉体锻炼好。挥舞两把斧头作出的攻击非常强力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP061', '椰果心变', '天使般的恶魔店员。送过去还是不送过去，心在微微颤抖着。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP017', '机器栗子', '【条件】自己场上没有这张卡以外的怪兽的场合，可以支付500生命值发动。
【效果】选自己墓地的1只「机器栗子」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP018', '耳语妖精', '【条件】可以将1张手牌送入墓地发动。
【效果】选对手墓地的最多2只怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP019', '火焰巨像', '【条件】可以支付600生命值发动。
【效果】选对手场上的1只表侧表示怪兽，其守备力直到回合结束时下降600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP020', '圣剑士的持柄者 希尔特', '【条件】无
【效果】选自己场上的1只攻击表示怪兽（战士族），其攻击力直到回合结束时上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP022', '晓之勇者 莱达克罗斯', '【条件】可以使自己墓地的2只怪兽（魔法师族）返回卡组发动。
【效果】将手牌的最多2只怪兽（等级5以下/魔法师族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP024', '龙队布局投球手', '【条件】自己场上没有这张卡以外的怪兽的场合可以发动。
【效果】选自己墓地的1只「龙队翻盘击球手」以表侧守备表示特殊召唤到自己的场上。这个回合，自己不能用怪兽（等级6以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP025', '龙队翻盘击球手', '【条件】自己场上没有这张卡以外的怪兽的场合可以发动。
【效果】选自己墓地的1只「龙队布局投球手」以表侧守备表示特殊召唤到自己的场上。这个回合，自己不能用怪兽（等级6以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP026', '龙力杀戮者', '【条件】自己场上有这张卡以外的表侧表示怪兽（等级7以上/龙族）的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP028', '彩光之首席吉他手', '【条件】可以支付1000生命值发动。
【效果】自己场上的全部表侧表示怪兽的攻击力直到回合结束时上升[对手场上的怪兽的数量]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP029', '魔将 夜目流罗', '【条件】这张卡召唤的回合，可以将这张卡的表示形式变更发动（攻击表示变为表侧守备表示，守备表示变更为表侧攻击表示）。
【效果】直到下个对手回合结束时，这张卡表侧表示期间，双方不能高等召唤怪兽（等级7以上）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP030', '火面上忍 极粗面', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】自己场上的全部表侧表示怪兽（炎族）的攻击力直到回合结束时上升[自己墓地的通常怪兽的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP031', '守护的龙魔导士', '【条件】可以将手牌的1只怪兽（魔法师族或者龙族）送入墓地发动。
【效果】选自己场上的1只怪兽。这个回合，那只怪兽不会被对手的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP032', '雷之雷霆', '【条件】可以将1张手牌送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP033', '音速耶格尔战机', '【条件】无
【效果】对手恢复1000生命值，这张卡的攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP034', '沃洛斯假面', '【条件】可以将1张手牌送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（等级6以下），其原攻击力直到回合结束时变为1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP035', '撒旦甲虫王', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽，其攻击力直到回合结束时上升[自己墓地的怪兽（等级1）的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP036', '交战鱼 类鲨巨齿鱼', '【条件】可以将手牌的1只怪兽（水属性）送入墓地发动。
【效果】选对手场上的1只守备表示怪兽变为表侧攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP037', '贯通！', '【条件】无
【效果】选自己场上的1只表侧表示怪兽。这个回合，那只怪兽的攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP038', '寻回之力', '【条件】可以使自己墓地的3只怪兽（魔法师族）返回卡组发动。
【效果】自己从卡组抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP039', '王道魔导-暴风', '【条件】自己场上有表侧表示怪兽（等级7以上/魔法师族）的场合，可以将手牌的1只怪兽（风属性）送入墓地发动。
【效果】选对手场上的最多3只怪兽变更表示形式（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP040', '旧神之印', '【条件】可以支付1000生命值发动。
【效果】将对手场上的里侧表示的卡全部确认。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP041', '大槌粉碎', '【条件】可以将1张手牌送入墓地发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP042', '火星', '【条件】无
【效果】给予对手200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP043', '暗的来访', '【条件】可以将2张手牌送入墓地发动。
【效果】选自己或者对手场上的1只表侧表示怪兽变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP044', '单方翻转', '【条件】对手场上有2只以上的里侧表示怪兽的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽变为表侧攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP045', '山', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（龙族·鸟兽族·雷族）的攻击力、守备力就上升200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP046', '反击炸弹', '【条件】对手怪兽的攻击宣言时，可以将1张手牌送入墓地发动。
【效果】给予对手[攻击过来的怪兽的等级]×200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP047', '地缚灵的引诱', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】要承受那次攻击的自己的怪兽由自己重新选。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP048', '突风', '【条件】自己场上的魔法卡被对手的效果破坏时可以发动。
【效果】选自己或者对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP049', '暴虐的报应', '【条件】自己场上的表侧表示的2只以上的通常怪兽同时被对手的效果破坏时可以发动。
【效果】选自己墓地的最多2只怪兽，以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP050', '加1命', '【条件】自己场上的怪兽被对手的攻击或者对手的效果破坏时可以发动。
【效果】选自己墓地的1只通常怪兽（等级1）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP01-JP021', '七道魔女', '【条件】可以将1张手牌送入墓地发动。
【效果】将手牌的1只怪兽（等级7以上/暗属性/魔法师族）以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤「七道魔导士」的场合，这张卡的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP000', '黑魔导士', '在魔法师中，攻击力、守备力都是最高级别。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP001', '龙队关键守门员', '手握队伍关键的男子。不管是什么东西飞过来，都会拼了命挡下。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP002', '电气飞吻小妹', '让人有点发麻的飞吻。心情都传达过去了。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP003', '电吉他天使', '翩然降落凡间的吉他。演奏出的音色就像天使一样。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP004', '猛犸的墓场', '守护同伴墓地的猛犸。破坏墓地的话会被无情地攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP005', '角龙', '身长着角的恐龙。其突击攻击非常强力！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP006', '泡沫期精灵', '柔弱的姿态已是过去。喜爱玩乐但是守身如玉。零层次月魔使是她的传呼机朋友。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP007', '零层次月魔使', '摆脱了每月平平无奇的日常的魔法师。用月亮所拥有的魔力虏获车夫和饭票。和黑妹妆剑士加南是死党。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP008', '黑妹妆剑士 加南', '将不夜城作为主战场的女战士。即使化了黑妹妆也是剑盾不离手。和泡沫期精灵是一生之友。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP009', '兽机界 旋翼机胡狼', '追求快乐而不断狂飙的野兽。是个只会向觉得自己能赢的对手寻衅的滑头家伙，受到预想外的反击就很不经打。一旦和别人结成帮派就会情绪高涨而常常有种自己很厉害的错觉，以致他并没有明白自己只身一人的时候就什么也干不了的事实。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP010', '兽机界 越野车狗', '从老人那里把仅剩那点儿狗粮抢走的狗。对作恶多端的自己很是陶醉但没什么信念的狗。明明以前是那么的讨厌戴着狗环的生活，现在却觉得有主人就已经是多么幸福的一件事。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP011', '兽机界 摩托狼', '寻求粮食和汽油而不断抢劫民众的野兽。常常被以为是独行狼性格，实则是相信着恶即正义并为组织尽心尽力。明明是坏家伙，可为什么其远吠声却是如此的感染人呢。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP012', '喷水梭鱼', '会驱使喷水推进器，以令人惊愕的速度突击过来哦。也有声音质疑它究竟是不是鱼。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP013', '热镖颌针鱼', '拥有攻击时会发热、突出的吻部的鱼。其清淡的风味受到美食家的喜爱。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP014', '妖鸟少女', '祈愿可以华丽飞舞、进行敏锐的攻击的妖鸟的少女。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP015', '诱仙恶女', '侍奉黑暗的女战士。将对手血祭是其生存意义。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP016', '七道法师', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（等级7以上），其攻击力直到回合结束时下降400。自己场上有表侧表示的「七道魔导士」的场合，再使选的怪兽的攻击力直到回合结束时下降[自己墓地的怪兽（魔法师族）的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP017', '闪电击秃鹰', '【条件】可以将手牌的1只怪兽送入墓地发动。
【效果】拥有与这个效果的条件送入墓地的怪兽相同的属性的对手场上的全部表侧表示怪兽的攻击力、守备力直到回合结束时下降[这个效果的条件送入墓地的怪兽的等级]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP018', '重击流星人', '【条件】这张卡召唤的回合，自己场上有表侧表示怪兽（等级7以上/魔法师族）的场合，可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】将对手场上的表侧表示怪兽（等级6以上）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP019', '龙队后卫', '【条件】自己场上有攻击表示的「龙队关键守门员」的场合，可以将1张手牌送入墓地发动。
【效果】选自己场上的1只表侧表示的「龙队关键守门员」和对手场上的1只攻击表示怪兽变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP020', '龙队射手', '【条件】自己场上有表侧表示的「龙队关键守门员」的场合，可以将1张手牌送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽。这个回合，那只怪兽的攻击力上升400，其攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP021', '惊愕刺拳龙', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】对手场上的攻击力最高的表侧表示怪兽全部攻击力直到回合结束时下降[自己场上的攻击力最高的表侧表示怪兽的攻击力]。这个回合，这张卡攻击的只能是攻击表示怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP022', '穿击龙 贯钉强击龙', '【条件】这张卡召唤的回合，可以将卡组最上面的卡送入墓地发动。
【效果】自己抽[对手场上的怪兽的数量]。那之后，自己选[这个效果抽的数量]的手牌按照喜欢的顺序全部返回卡组上面或按照喜欢的顺序全部返回卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP023', '浪漫小拨片', '【条件】自己的生命值比对手少的场合，可以支付500生命值发动。
【效果】从自己卡组上面将3张卡送入墓地。那之中有怪兽（念动力族）的场合，选自己墓地的1只怪兽（念动力族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP024', '摇滚话筒歌手', '【条件】自己的生命值为2000以下的场合可以发动。
【效果】对手场上的全部表侧表示怪兽的攻击力、守备力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP025', '碎光之超能力袭击者', '【条件】自己的生命值为1000以下的场合可以发动。
【效果】选对手场上最多2只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP026', '斗将 是也', '【条件】无
【效果】选自己场上的1只表侧守备表示（战士族）变为攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP027', '招赘之神 迪安·凯特', '【条件】可以将1张手牌送入墓地发动。
【效果】自己恢复1000生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP028', '兽机界王 弹射恶魔金刚', '【条件】可以将自己场上的这张卡以外的最多2只表侧表示怪兽（兽战士族） 送入墓地发动。
【效果】按照[被这个效果的条件送入墓地的怪兽的数量]选对手场上的守备表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP029', '超级恐龙王', '【条件】这张卡召唤或特殊召唤的自己的主要阶段，可以将卡组最上面的卡送入墓地发动。
【效果】选自己墓地的1只通常怪兽（等级6以下/恐龙族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP030', '邪影 黑暗潜伏者', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1张魔法陷阱卡破坏，给予对手1000伤害。那之后，这张卡返回持有者的手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP031', '皇家魔族 重金属', '【条件】将怪兽（等级5以上）解放来召唤这张卡的回合可以发动。
【效果】选对手场上的等级最低的1只表侧表示怪兽（等级8以下），这张卡的攻击力直到回合结束时上升[选的怪兽的攻击力]。选的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP032', '波导炮 巨炮金枪鱼', '【条件】可以将1张手牌送入墓地发动。
【效果】选自己场上的最多2只表侧表示怪兽（鱼族/攻击力1000以下）。这个回合，那些怪兽可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP033', '恶魔的呼笛', '【条件】自己场上没有这张卡以外的怪兽，自己墓地的通常怪兽有3只以上存在的场合可以发动。
【效果】将自己场上的这张卡送入墓地。那之后，选自己墓地的1只通常怪兽，以表侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP034', '交灵章鱼巫女', '【条件】可以支付800生命值发动。
【效果】选自己墓地的1只通常怪兽，这张卡的攻击力直到回合结束时上升[选的怪兽的等级]×100。那之后，使选的怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP035', '无罪枪兵', '【条件】可以将1张手牌送入墓地发动。
【效果】这个回合，这张卡的攻击会贯通（攻击守备表示怪兽时，若其攻击力超过那个守备力则给予超过数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP036', '王道魔导-地壳变动', '【条件】自己场上有表侧表示怪兽（等级7以上/魔法师族）的场合，可以将手牌的1只怪兽（地属性）送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降[自己墓地的攻击力最高的怪兽的攻击力]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP037', '摇篮曲拘束', '【条件】自己场上有2只以上的表侧表示怪兽（念动力族）的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP038', '彻夜狂欢', '【条件】无
【效果】使自己场上的攻击表示怪兽（水族）全部变为守备表示，自己恢复[被这个效果变为守备表示的怪兽的数量]×400生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP039', '世纪末兽机界', '【条件】无
【效果】只要这张卡在场地区以表侧表示存在，双方场上的表侧表示怪兽（兽战士族·恶魔族·机械族）的攻击力就上升300，双方场上的表侧表示怪兽（龙族·魔法师族·天使族）的攻击力就下降300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP040', '千把刀', '【条件】自己场上有表侧表示的「黑魔导士」的场合可以发动。
【效果】选对手场上的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP041', '黑·魔·导', '【条件】自己场上有表侧表示的「黑魔导士」的场合可以发动。
【效果】将对手场上的魔法陷阱卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP042', '神风剑', '【条件】无
【效果】选自己场上的2只表侧表示的通常怪兽和对手场上的1只表侧表示怪兽（等级8以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP043', '属性变更弹', '【条件】可以向对手展示手牌的1只怪兽发动。
【效果】选对手场上的最多3只表侧表示怪兽。这个回合，那些怪兽的属性变为与这个效果的条件展示过的怪兽相同的属性。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP044', '蓝药水', '【条件】无
【效果】自己恢复400生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP045', '复活的泡沫期-镜面球', '【条件】对手召唤怪兽（等级5以上）时可以发动。
【效果】选自己墓地的1只怪兽（水族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP046', '狂暴与共谋', '【条件】自己场上的表侧表示的通常怪兽的种族为2种类以上的场合，对手召唤怪兽时可以发动。
【效果】选对手场上的1只表侧表示怪兽（等级6以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP047', '强制午休', '【条件】对手召唤怪兽（等级4以下）时，对手场上没有那只怪兽以外的怪兽的场合可以发动。
【效果】使那只怪兽变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP048', '死灵的束缚', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降[与那只怪兽相同种族的对手墓地的怪兽的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP049', '2分区阻拦', '【条件】对手怪兽的攻击宣言时，可以将手牌的2只通常怪兽（等级2）送入墓地发动。
【效果】选最多2只对手场上的表侧表示怪兽变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP02-JP050', '猛吹雪', '【条件】自己场上的陷阱卡被对手的效果破坏时可以发动。
【效果】选自己或者对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP000', '恶魔的召唤', '使用黑暗的力量，迷惑人心的恶魔。在恶魔族里以强大的力量自豪。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP001', '光明术士', '把自己奉献给上天的魔术师。接受了许多神之祝福的他，会有怎样的未来在等待着他呢？', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP002', '派送机器 新闻嗡', '晨报派送要在早餐前！晚报派送也要在早饭前！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP003', '火面忍者 超硬面', '对硬度很是自信的忍者。为了达到针金面的境界而日以继夜地埋头修行。对水遁之术感到有些棘手。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP004', '蘑菇人', '在潮湿的地方发挥实力！从伞部洒出菌丝攻击！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP005', '胖鸡', '把对手整个吞下，吸收下来作为自己的能量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP006', '格斗鼠 吱助', '目标是成为鼠世界最强的格斗家而在世界流浪的热血鼠。无知地与他交手会吃亏哦。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP007', '宝贝龙', '不要因为这条龙还是个孩子就轻视它。体内隐藏的力量无法估计。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP008', '独眼巨人', '一只眼的巨人。会用粗壮的双臂攻过来。必须注意。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP009', '树精', '森之精灵。借助草木的力量封锁对手的行动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP010', '水之魔导师', '用水围着对手，作出将其包起来般的攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP011', '幻兽王 加塞尔', '跑动速度快得惊人，身姿犹如幻影一般的野兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP012', '多带海大叔', '累坏了的多带海大叔。
最近，好难消除疲劳。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP013', '星战骑 厄开耳克洛斯', '让恶星之力寄宿于身的一人。相信着自己的正义今天也奔走于战场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP014', '火星心少女', '【条件】可以将手牌的1只怪兽（等级4以下）送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降500。那之后，选自己墓地的「火星」「火星之幕」各1张盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP015', '银狼', '【条件】自己场上有这张卡以外的表侧表示怪兽（兽族）的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力、守备力直到回合结束时下降200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP016', '猛兽召唤师', '【条件】对手场上有表侧表示怪兽（等级6以上）的场合，可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】将手牌的1只怪兽（等级7以下/兽族·兽战士族·鸟兽族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP017', '圣剑士的出鞘者 希斯', '【条件】可以使自己墓地的合计4只的怪兽（战士族或者魔法师族）按照喜欢的顺序返回卡组下面发动。
【效果】将手牌的1只怪兽（等级7/战士族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP018', '兽翼刚王 制守', '【条件】[对手场上的表侧表示怪兽的数量]和[自己场上的魔法陷阱卡的数量]相同的场合，可以将自己场上的最多3张魔法陷阱卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，使其攻击力、守备力直到回合结束时下降[因这个效果的条件而送入墓地的的卡的数量]×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP019', '猛爪虎', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[自己场上的表侧表示怪兽（等级7以上）的数量]×400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP020', '宝藏龙', '【条件】这张卡从手牌或墓地特殊召唤的自己的主要阶段，自己墓地有4只以上的怪兽（龙族）的场合可以发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP021', '龙商人', '【条件】可以将1张手牌送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（等级6以下/龙族），其攻击力直到回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP022', '清透寒冰龙', '【条件】可以使自己墓地的1只怪兽（等级5以下/龙族）返回卡组下面发动。
【效果】选对手墓地的最多2只怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP023', '燃烧烈焰龙', '【条件】可以使自己墓地的1只怪兽（等级5以下/龙族）返回卡组下面发动。
【效果】将对手场上的表侧表示的场地魔法卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP024', '远古神现龙', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升600。自己的墓地有「清透寒冰龙」和「燃烧烈焰龙」的场合，可以使那2只返回卡组。返回的场合，可以选对手场上的1只表侧表示怪兽（守备力1500以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP025', '幻击龙 米拉基亚斯', '【条件】可以将手牌的1只怪兽（等级7以上/龙族）送入墓地发动。
【效果】选对手场上的最多2只表侧表示怪兽（等级7以下），其攻击力直到回合结束时下降1500。这个回合，这张卡用战斗将怪兽破坏的战斗阶段里，这张卡可以仅再1次对怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP026', '死魔将 决心', '【条件】可以将手牌全部送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[这个效果的条件送入墓地的卡的数量]×600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP027', '饭票海马', '【条件】自己场上有表侧表示的通常怪兽（光属性/水族）的场合可以发动。
【效果】自己恢复500生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP028', '车夫海马', '【条件】这张卡召唤的回合可以发动。
【效果】选自己墓地的1只通常怪兽（光属性/水族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP029', '诱仙伦巴达恶女', '【条件】无
【效果】选自己墓地的1张「魅惑的不夜城」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP030', '兽机界 三轮车狐狸', '【条件】这张卡召唤的回合，对手场上的怪兽为3只的场合可以发动。
【效果】将手牌的1只怪兽（等级7以下/兽战士族）以表侧表示特殊召唤到自己的场上。这个回合，自己不能用怪兽（等级6以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP031', '兽机界霸者 战王卡车狮虎王', '【条件】可以将自己场上的2只表侧表示怪兽（等级4以下/兽战士族）送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[因这个效果的条件送入墓地的怪兽的等级的合计]×100。这个回合，自己只能用这张卡攻击且只能攻击攻击表示怪兽，可以对对手怪兽全部各作1次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP032', '特报机器 强力小报拟人机', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】对手从自身卡组上面翻开5张卡，双方确认。这张卡的攻击力直到回合结束时上升[翻开的卡之中的怪兽的数量]×100。对手将翻开的卡按照喜欢的顺序返回卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP033', '火面上忍 加面极粗面', '【条件】可以将自己场上的1只表侧表示的通常怪兽（炎族）送入墓地发动。
【效果】给予对手1000伤害。自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP034', '船锚海鳝', '【条件】自己场上有表侧表示的「海」或者「大海洋」的场合可以发动。
【效果】选自己墓地的1只通常怪兽（等级3以下/鱼族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP035', '戏法鸽', '【条件】可以将手牌的1张魔法陷阱卡送入墓地发动。
【效果】选自己墓地的1只怪兽（鸟兽族/攻击力1500以上）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP036', '亮光鹦鹉', '【条件】对手场上有2只以上的表侧表示怪兽的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽。这个回合，那只怪兽的属性变为光属性。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP037', '长盾守卫者', '【条件】可以将这张卡的表示形式变更发动（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。
【效果】选自己场上的1只表侧表示的通常怪兽（守备力2000以上）。这个回合，那只怪兽的攻击力上升500，不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP038', '哨艇 旧日神印号', '【条件】可以使自己墓地的1只通常怪兽返回卡组下面发动。
【效果】选对手场上的1张里侧表示的卡确认。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP039', '救生刀剑鱼', '【条件】自己场上有表侧表示怪兽（等级7/鱼族）的场合，可以使自己墓地的1只怪兽（鱼族）返回卡组下面发动。
【效果】选自己场上最多2只表侧表示怪兽（鱼族），其攻击力直到回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP040', '暗冥冠鹰', '【条件】对手场上有表侧表示怪兽（光属性）的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（鸟兽族），其攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP041', '海龙王 硬鳞鱼鳞鳄', '【条件】这张卡召唤的回合可以发动。
【效果】给予对手[对手场上的魔法陷阱卡的数量]×300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP042', '正道之力', '【条件】自己场上有2只以上的相同属性的表侧表示怪兽的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP043', '龙之回归', '【条件】可以使自己墓地的3只怪兽（龙族）返回卡组发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP044', '火中之栗', '【条件】自己场上有表侧表示怪兽（战士族）的场合可以发动。
【效果】将自己卡组最上面的卡送入墓地。因这个效果有怪兽被送入墓地的场合，选自己场上的1只表侧表示怪兽（战士族），其攻击力直到回合结束时上升[被这个效果送入墓地的怪兽的等级]×300，自己受到那个数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP045', '火面激辣赤热之术', '【条件】无
【效果】选自己场上的1只表侧表示怪兽（炎族）。这个回合，那只怪兽的攻击力上升300，其攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP046', '火面烧心背脂之术', '【条件】无
【效果】选对手场上的1只攻击表示怪兽，其攻击力直到回合结束时下降[自己场上的表侧表示怪兽（炎族）数量]×400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP047', '3K电击', '【条件】自己场上的表侧表示怪兽（水族）为3只的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下），其原攻击力直到回合结束时变为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP048', '魅惑的不夜城', '【条件】无
【效果】只要这张卡在场地区以表侧表示，双方的场上的表侧表示怪兽（光属性）的攻击力就上升200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP049', '水中推进', '【条件】自己场上有表侧表示的「海」或者「大海洋」的场合可以发动。
【效果】选自己场上的1只表侧表示怪兽（鱼族），其攻击力直到回合结束时上升[自己场上的表侧表示怪兽（鱼族）数量]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP051', '千攻火箭', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示的通常怪兽（攻击力1000以下），其攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP052', '海', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（鱼族·海龙族·雷族·水族）的攻击力、守备力就上升200，双方场上的表侧表示怪兽（机械族·炎族）的攻击力、守备力就下降200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP053', '森林', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（昆虫族·兽族·植物族·兽战士族）的攻击力、守备力就上升200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP054', '报道魂', '【条件】自己场上的攻击表示怪兽被对手的攻击或者对手的效果破坏时可以发动。
【效果】选自己墓地的1只「特报机器 强力小报拟人机」或者「派送机器 新闻嗡」以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP055', '噬杀饵球', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】对手场上的全部表侧表示怪兽的攻击力直到回合结束时下降[自己场上的表侧表示怪兽（等级3以下/鱼族）的数量]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP056', '反击盾', '【条件】自己的表侧表示的通常怪兽受到攻击的对手怪兽的攻击宣言时，可以使自己墓地的1只通常怪兽（守备力1000以上）返回卡组发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP057', '反击鸽心', '【条件】自己的攻击表示怪兽（鸟兽族）受到攻击的对手怪兽的攻击宣言时可以发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降[攻击的怪兽的等级]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP050', '大海洋', '【条件】这张卡在自己场上的表侧表示怪兽（水属性）为3只的场合可以发动。
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（水属性以外）的攻击力、守备力就下降300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP058', '强欲之大龟', '【条件】对手召唤怪兽召唤时可以发动。
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP060', '背误射击', '【条件】自己场上的魔法陷阱卡被对手的效果破坏时可以发动。
【效果】选对手场上的1只表侧表示的效果怪兽（等级6以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP03-JP059', '三重破3纪录', '【条件】自己场上的表侧表示的通常怪兽（等级3）为3只的场合，对手怪兽的攻击宣言时可以发动。
【效果】自己场上的全部表侧表示怪兽的攻击力、守备力直到回合结束时上升900。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP000', '人造人-念力震慑者', '【条件】无
【效果】双方不能发动陷阱卡，双方的陷阱卡的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP001', '幻刃兵 钻头蜥蜴', '由龙转生而成的幻人种。活用高战略性和敏捷性，为缩短工期作出贡献。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP002', '幻刃战士 铲子龙', '年轻的幻刃战士。将热情灌注到铲子上，今天也去开掘工地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP003', '幻刃虚兵 大滚轮龙', '老练的幻刃人。会按照工序区分使用6种类的滚轮，不过外行人看不出个中区别。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP004', '拳乐姬 萨克斯拳环', '合奏武队的气氛营造者。强力的音色使其能够单独战斗。左手的武器只靠自己一个人戴不上去。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP005', '斧乐姬 长笛战斧', '合奏武队的冲锋陷阵队长。发出的斧声有着华丽的音色。那服装虽然疑似是用来隐藏暗器，但其实纯粹是怕冷。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP006', '推土破碎公牛', '很高的施工性能和过高的租赁费用。最能展现八分计划的精髓所在。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP007', '受镇压的蚂蚁', '相信总有一天能得到自由而忍受着现在的生活的蚂蚁。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP008', '团结的蚂蚁', '发誓要共同面对强大势力而集结的蚂蚁们。离革命的日子不远了。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP009', '流离的蚂蚁', '平时都在忍受困苦，在心中发誓总有一天要闹一场革命的蚂蚁。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP010', '穴位火山', '活用地热的火热指压！穴位就让我按上去吧火山！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP011', '恍惚的人鱼', '诱惑航海者使其溺死的美丽人鱼。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP012', '提坦的末裔', '古代众神的末裔。擅长隐身术，鲜有人知道其外貌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP013', '饶有情趣的菓子假名姬', '啊～嗯。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP014', '沉默暗杀者', '神出鬼没的暗杀者。一边完成危险的委托一边找寻下落不明的搭档。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP015', '钢机神 镜光革新者', '【条件】无
【效果】选与这张卡相同种族的自己墓地的最多3只怪兽。这张卡的攻击力直到回合结束时上升[选的怪兽的等级合计]×100。那之后，使选的怪兽返回卡组。用这个效果使仅1只的怪兽返回的场合，这个回合，这张卡的攻击会贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP016', '革命皮甲龙', '【条件】可以使自己墓地的4只通常怪兽按照喜欢的顺序返回卡组下面发动。
【效果】这张卡的攻击力直到回合结束时上升[双方场上的怪兽的数量]×700。这个回合，这张卡仅1次不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP017', '化学治疗蓝药师', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】自己恢复400生命值。用这个效果恢复过的场合，可以再从自己的墓地选喜欢的数量的「蓝药水」加入手牌。 ​​​​', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP018', '死返小玉', '【条件】自己场上有这张卡以外的表侧表示怪兽（攻击力0）的场合可以发动。
【效果】从自己卡组上面将2张卡送入墓地。那之中有怪兽（攻击力0）的场合，可以选自己墓地的1只通常怪兽（攻击力0）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP019', '祭神 莫多丽娜', '【条件】无
【效果】选自己场上的1只表侧表示怪兽（等级7以上/战士族）返回持有者的手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP020', '魔将 濑目流罗', '【条件】可以将1张手牌送入墓地发动。
【效果】将手牌的1只怪兽（攻击力0）以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤的怪兽的攻击力直到回合结束时上升[那只怪兽的原守备力]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP021', '幻龙重骑 超斗轮挖掘鳞虫[L]', '【条件】极限模式
【永续效果】这张卡的攻击力上升[自己的手牌的数量]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP022', '幻龙重骑 超斗轮挖掘鳞虫', '和「幻龙重骑 超斗轮挖掘鳞虫[L]」「幻龙重骑 超斗轮挖掘鳞虫[R]」集齐可以极限召唤。
【条件】极限模式
【永续效果】这张卡不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP024', '幻刃龙 建造龙', '【条件】自己或者对手场上有表侧表示的场地魔法卡的场合可以发动。
【效果】选自己墓地的1只通常怪兽（幻龙族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP025', '幻刃妖精 镐头龙', '【条件】可以将手牌的1只怪兽（幻龙族）送入墓地发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP026', '旋乐姬 单簧管查克拉双节棍', '【条件】对手场上有表侧表示怪兽的场合可以发动。
【效果】将自己卡组最上面的卡送入墓地。用这个效果将怪兽（风属性/战士族）送入墓地的场合，选对手场上的1只表侧表示怪兽，其攻击力、守备力直到回合结束时下降[自己场上的表侧表示怪兽（风属性/战士族）的数量]×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP027', '突乐姬 小号拐棍', '【条件】自己墓地有通常怪兽（战士族）的场合可以发动。
【效果】将自己卡组最上面的卡送入墓地。那之后，选自己场上的1只表侧表示怪兽，其攻击力直到回合结束时上升[自己墓地的通常怪兽（战士族）的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP028', '重乐鬼 合奏武斗家', '【条件】可以将1张手牌送入墓地发动。
【效果】这个回合，这张卡表侧表示期间，自己怪兽（风属性/战士族）的攻击宣言时对手不能发动陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP029', '神乐鬼 大管神指', '【条件】对手场上有守备表示怪兽的场合，可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[对手场上的守备表示怪兽的数量]×800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP030', '特上寿司天使 姜百列', '【条件】对手的生命值为4000以上的场合，可以将2张手牌送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下），给予对手[选的怪兽的攻击力]的伤害。这个回合，自己只能用这张卡攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP031', '钻机山魈', '【条件】这张卡召唤或特殊召唤的自己的主要阶段可以发动。
【效果】选最多为[自己场上的表侧表示怪兽（机械族）的数量]的对手场上的里侧守备表示怪兽变为表侧攻击表示。被这个效果变为表侧攻击表示的怪兽的原攻击力直到回合结束时变为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP032', '盾构掘进金刚', '【条件】这张卡召唤或特殊召唤的自己的主要阶段可以发动。
【效果】选对手场上的1只里侧守备表示怪兽破坏。用这个效果将怪兽破坏的场合，这张卡的攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP033', '叛逆之叛旗蚁', '【条件】可以支付100生命值发动。
【效果】自己场上的全部攻击表示怪兽（昆虫族/攻击力100以下）的攻击力直到回合结束时上升[自己场上的怪兽的数量]×800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP034', '按摩岩浆熊', '【条件】自己场上没有这张卡以外的怪兽的场合，可以使自己墓地的1只怪兽（炎族）返回卡组下面发动。
【效果】选自己墓地的1只通常怪兽（炎族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP035', '芳香岩浆熊', '【条件】可以将最多2张手牌送入墓地发动。
【效果】自己恢复[被这个效果的条件送入墓地的卡的数量]×300生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP036', '岩浆按摩师G', '【条件】可以将最多4张手牌送入墓地发动。
【效果】选自己或者对手场上的1只表侧表示怪兽（等级4以下），其攻击力直到回合结束时上升[被这个效果的条件送入墓地的卡的数量]×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP037', '极限岩浆之地幔阿育吠陀', '【条件】可以将手牌的1只怪兽（炎族）送入墓地发动。
【效果】将拥有与被这个效果的条件送入墓地的怪兽相同等级的双方场上的表侧守备表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP038', '阴阳士 逆风', '【条件】自己场上有这张卡以外的表侧表示怪兽（战士族）的场合可以发动。
【效果】选最多为[对手场上的魔法陷阱卡的数量]的对手墓地的怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP039', '种族变更光线', '【条件】可以向对手展示手牌的1只怪兽发动。
【效果】选自己或者对手场上合计最多3只的表侧表示怪兽。这个回合，那些怪兽的种族变为与被这个效果的条件展示的怪兽相同的种族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP040', '远古障壁', '【条件】可以使相同种族的自己墓地的2只怪兽返回卡组发动。
【效果】选自己场上的最多2只表侧表示怪兽（等级8以下）。这个回合，那些怪兽不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP041', '恶星的引导', '【条件】自己场上没有攻击表示怪兽的场合可以发动。
【效果】选自己墓地2只等级合计最多为10以下的通常怪兽（光属性/恶魔族）以表侧攻击表示特殊召唤到自己的场上。这个回合，自己不能用怪兽（恶魔族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP042', '透幻乡的崄峻', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（幻龙族）的攻击力就上升400，守备力就下降400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP043', '地层调查', '【条件】无
【效果】从自己卡组上面翻开[对手场上的卡的数量]的卡，双方确认。那之后，自己使翻开的卡按照喜欢的顺序全部返回卡组上面或按照喜欢的顺序全部返回卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP044', '始幻的咆哮', '【条件】自己场上有表侧表示怪兽（幻龙族）的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡返回持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP045', '乐姬的息吹', '【条件】自己场上的表侧表示怪兽（风属性/战士族）为2只的场合可以发动。
【效果】选自己墓地的1只怪兽（等级6以下/战士族）以表侧表示特殊召唤到自己的场上。这个回合，用这个效果特殊召唤的怪兽不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP046', '重骑师战法', '【条件】可以将自己场上的1只表侧表示的通常怪兽（地属性/机械族）送入墓地发动。
【效果】选自己墓地的1只效果怪兽（地属性/机械族）以表侧表示特殊召唤到自己的场上。这个回合，自己只能以用这个效果特殊召唤的怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP047', '世纪末兽战士传说', '【条件】自己场上有表侧表示怪兽（等级7以上/兽战士族）的场合可以发动。
【效果】选自己墓地的1只怪兽（等级4以下/兽战士族）以表侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP048', '火炎', '【条件】自己场上有2只以上的表侧表示怪兽（炎族）的场合可以发动。
【效果】给予对手300伤害。用这个效果给予对手伤害的场合，可以再选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP049', '大极流', '【条件】无
【效果】将手牌的1只怪兽（鱼族或者海龙族）以表侧表示特殊召唤到自己的场上。那之后，可以选对手墓地的最多5只怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP050', '草原', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（战士族·兽战士族）的攻击力、守备力就上升200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP051', '三角复活', '【条件】自己墓地有相同种族的怪兽3只以上的场合，对手召唤怪兽时可以发动。
【效果】选自己墓地的3只相同种族的怪兽返回卡组。自己场上没有攻击表示怪兽的场合，可以再选自己墓地的1只怪兽（等级7以下）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP052', '左手换剑右手换盾', '【条件】自己的攻击表示的怪兽受到攻击的对手怪兽（等级9以下）的攻击宣言时可以发动。
【效果】攻击过来的怪兽的原攻击力、原守备力直到回合结束时交换。受到攻击的怪兽的原攻击力、原守备力直到回合结束时交换。那之后，可以选自己墓地的1张「右手换盾左手换剑」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP053', '幻刃急攻', '【条件】自己的表侧表示怪兽（幻龙族）受到攻击的对手怪兽的攻击宣言时，可以将手牌的1只怪兽（等级6以下/幻龙族）送入墓地发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降[被这个效果的条件送入墓地的怪兽的攻击力]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP054', '幻刃封锁', '【条件】对手召唤怪兽（等级7以上）时，可以将自己场上的1只表侧表示怪兽（幻龙族）送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽。这个回合，对手不能用拥有与选的怪兽相同种族的怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP055', '重骑起动装置', '【条件】对手召唤怪兽（等级5以上）时可以发动。
【效果】选自己场上的1只表侧表示怪兽（机械族）变更表示形式（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。被这个效果变更表示形式的怪兽的攻击力直到回合结束时上升1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP056', '大巨蚁革命', '【条件】自己场上的表侧表示怪兽（昆虫族/攻击力100以下）为3只的场合，对手怪兽的攻击宣言时可以发动。
【效果】将对手场上的表侧表示怪兽（等级8以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP057', '自由蚁旗', '【条件】对手召唤或特殊召唤怪兽时可以发动。
【效果】选自己手牌或者自己墓地的1只怪兽（昆虫族/攻击力100以下）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP058', '地压的爆发', '【条件】自己场上的攻击表示怪兽（炎族）被对手的攻击或者对手的陷阱卡的效果破坏时可以发动。
【效果】选自己墓地的1只「岩浆按摩师G」或者「极限岩浆之地幔阿育吠陀」以表侧表示特殊召唤到自己的场上。自己的墓地有怪兽（地属性/炎族）的场合，自己再恢复1000生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP059', '珠宝的落穴', '【条件】自己场上的表侧表示怪兽（水族）为3只的场合，对手召唤或特殊召唤怪兽时可以发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP060', '兽机界奥义 兽之拳', '【条件】自己的表侧表示怪兽（等级7～9/兽战士族·恶魔族·机械族）受到攻击的对手怪兽的攻击宣言时可以发动。
【效果】攻击过来的怪兽变为表侧守备表示。用这个效果使怪兽（龙族·魔法师族·天使族）变为守备表示的场合，可以再选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP04-JP023', '幻龙重骑 超斗轮挖掘鳞虫[R]', '【条件】极限模式：可以使自己墓地的1张卡返回卡组下面发动。
【效果】选自己或者对手场上的1张魔法陷阱卡破坏，自己抽1张。用这个效果将场地魔法卡破坏的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP000', '龙破坏之剑士', '【条件】无
【永续效果】这张卡的攻击力上升[对手场上的表侧表示怪兽（龙族）数量和对手墓地的怪兽（龙族）数量的合计]×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP001', '火焰龙', '全身被fire覆盖，有着非常美丽的身姿的龙。虽然不喜欢斗争，但具备很高的攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP002', '可能甜心：D', '隐藏着无限的可能性，带着笑容不断追逐光辉梦想。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP003', '皇家魔族 无浪潮', '与王为伴的异形恶魔。它吞噬一切声音，反弹一切攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP004', '狱卒人鱼', '对落入地狱的坏人严加责罚的暴躁人鱼。惯犯们也叫嚷着说不会再做坏事了求您原谅我，对其评价极高。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP005', '女看守 加南', '以监狱岛为主战场的女战士。用手持的剑与盾发起激烈叱责。惯犯们也叫嚷着说多亏了您我醒悟了，对其评价极高。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP006', '花牙狼之黑花', '潜入阴暗处，解救主人危机的草之一派。即使被击败了，也会从阴草地府赶来。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP007', '花牙武者之龙胆', '潜入阴暗处，在暗地里支撑每场胜仗的草之一派。为了主人会一心一意地竭力战斗。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP008', '炸弹鸟', '投下炸弹的鸟。说不定里面有个小人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP009', '草', 'w', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP010', '浪涌电压蜥蜴', '与落雷一起出现的电气生物。会将身体电流化来入侵回路，使机械故障。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP011', '烤豌豆士兵', '使用剑和豆子攻过来的植物战士。意外地很烫。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP012', '铁钢装甲蚁', '全身被厚装甲覆盖的巨大蚁型生物。毫不留情地阻挡在破坏森林之物的前方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP013', '冰期弹射人', '【条件】这张卡召唤的回合，可以使自己墓地的1只怪兽（水属性）返回卡组下面发动。
【效果】选对手场上的1张魔法陷阱卡返回持有者的手牌。那之后，可以选对手场上的1只表侧表示怪兽，使其攻击力、守备力直到回合结束时下降600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP014', '灰霸炎神 烈破火神[L]', '【条件】极限模式：可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，使其攻击力直到回合结束时下降800。那之后，可以将对手场上的场地魔法卡破坏。用这个效果将场地魔法卡破坏的场合，再给予对手800伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP015', '灰霸炎神 烈破火神', '和「灰霸炎神 烈破火神[L]」「灰霸炎神 烈破火神[R]」集齐可以极限召唤。
【条件】极限模式
【永续效果】这张卡不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP016', '灰霸炎神 烈破火神[R]', '【条件】极限模式：将卡组最上面的卡送入墓地才能发动。
【效果】选自己或者对手场上1只表侧表示怪兽，使其攻击力直到回合结束时下降[选的怪兽的等级]×100。那之后，给予对手[选的怪兽的等级]×100伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP017', '执念之龙', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（攻击力2000以上），使其攻击力直到回合结束时下降400。那之后，可以选自己墓地的1张「龙的执念」盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP018', '安可人偶', '【条件】可以将手牌的1只怪兽送入墓地发动。
【效果】将自己场上的这张卡送入墓地。那之后，可以选自己墓地的「高潮终场」「念动力前奏」合计最多2张盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP019', '可能甜心女郎-Re：D', '【条件】无
【效果】选自己场上的1只表侧表示怪兽（攻击力500以下）返回持有者的手牌。这个回合，这张卡表侧表示期间，自己不能将怪兽（守备力1500以上）以攻击表示高等召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP020', '魔将分队 武组', '【条件】对手场上有怪兽，自己墓地有怪兽（攻击力0）的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽，使其攻击力直到回合结束时上升[自己墓地的怪兽（攻击力0）数量]×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP021', '和假真战士', '【条件】这张卡召唤的回合，可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选自己墓地的通常怪兽（战士族或者鸟兽族）合计最多2只以里侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP022', '魔仙斗 冰朱雀', '【条件】可以使自己墓地的2只卡名不同的怪兽（等级7以上/战士族）按照喜欢的顺序返回卡组下面发动。
【效果】选自己墓地的1只怪兽（等级7以上/战士族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP023', '皇家魔族 相位效果乐手', '【条件】自己场上有表侧表示怪兽（等级7以上/恶魔族）的场合，可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选自己墓地的1只怪兽（等级7以上/恶魔族）以表侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP024', '皇家魔族 死亡厄运', '【条件】将2只怪兽（等级7以上/恶魔族）解放来召唤这张卡的回合可以发动。
【效果】将对手场上的表侧表示怪兽全部破坏。那之后，给予对手[被这个效果破坏的怪兽的原等级合计]×100伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP025', '恶德劫脑虫', '【条件】可以支付1000生命值发动。
【效果】选自己场上的1只表侧表示怪兽（等级8/暗属性）。这个回合，那只怪兽可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP026', '监狱之神 迪安·凯特', '【条件】可以将1张手牌送入墓地发动。
【效果】确认对手的手牌，从那之中选1张卡送入墓地。用这个效果将怪兽（等级7以上）送入墓地的场合，自己恢复1000生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP027', '花牙僧之银荆', '【条件】自己场上有表侧表示怪兽（等级7以上/植物族）的场合可以发动。
【效果】选对手场上的1只守备表示怪兽变为表侧攻击表示。用这个效果将怪兽变为表侧攻击表示的场合，自己的生命值再恢复[选的怪兽的原攻击力]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP028', '花牙美人之昙花', '【条件】这张卡召唤的回合，可以支付500生命值发动。
【效果】选自己墓地的1只通常怪兽（地属性/植物族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP029', '花牙女忍 异邦兰', '【条件】自己的墓地有「花牙女忍 异邦兰」的场合可以发动。
【效果】将手牌的1只怪兽（植物族）送入墓地。那之后，选自己墓地的1只「花牙女忍 异邦兰」以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤的怪兽在结束阶段返回持有者卡组下面。这个回合，这张卡不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP030', '花牙兰狮子 牙兽丸', '【条件】可以将自己场上的1只这张卡以外的表侧表示怪兽（地属性/植物族）送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下/地属性），使其原攻击力直到回合结束时变为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP031', '真花牙女忍 花冠兰', '【条件】可以使自己墓地的1只怪兽（植物族）返回卡组下面发动。
【效果】将手牌的1只怪兽（等级7以下/植物族）以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤的怪兽在结束阶段返回持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP032', '花牙忍 机炮', '【条件】可以将手牌的2只通常怪兽（植物族）送入墓地发动。
【效果】选对手场上的最多2只表侧攻击表示怪兽（等级8以下）破坏。那之后，给予对手[被这个效果破坏的怪兽的数量]×500伤害。这个回合，自己只能用1只怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP033', '爆破心鸽', '【条件】可以向对手展示手牌的2张魔法陷阱卡发动。
【效果】这个回合，要将怪兽（鸟兽族）以攻击表示高等召唤的场合，表侧表示的这张卡可以作为2只的分量来解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP034', '幻书鸽之骑士 夜幻', '【条件】自己的墓地有陷阱卡的场合，可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[自己墓地的陷阱卡的数量]×200。自己的墓地有5张以上的陷阱卡的场合，再给予对手1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP035', '午休斗牛士', '【条件】可以使自己墓地的3只怪兽返回卡组发动。
【效果】选对手场上的1只攻击表示怪兽（等级8以下）变为里侧守备表示。用这个效果将怪兽变为里侧守备表示的场合，可以再选自己墓地的1张「强制午休」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP036', '魔机奇迹少女', '【条件】自己场上有表侧表示怪兽（攻击力100/守备力100）的场合，可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选自己墓地的1只怪兽（等级7/念动力族）在自己场上表侧攻击表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP037', '丰沃之蟠龙', '【条件】可以使自己墓地的1张场地魔法卡返回卡组发动。
【效果】给予对手600伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP038', '星战骑 凯戎', '【条件】对手场上有怪兽的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（等级5以上/恶魔族）。这个回合，那只怪兽的攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP039', '即兴果酱音跃：P跳起！', '【条件】可以将自己场上的1只表侧表示怪兽（念动力族）送入墓地发动。
【效果】将手牌的1只怪兽（等级7/念动力族）以表侧表示特殊召唤到自己的场上。这个效果的条件将「可能甜心：D」送入墓地的场合，用这个效果特殊召唤的怪兽的攻击力直到回合结束时上升1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP040', '即兴果酱音跃：P激活！', '【条件】可以使自己墓地的2只怪兽（念动力族）按照喜欢的顺序返回卡组下面发动。
【效果】选自己墓地的1只通常怪兽（念动力族）加入手牌。用这个效果将「可能甜心：D」加入手牌的场合，自己再恢复1000生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP041', '皇家魔族指令', '【条件】可以将手牌的1只怪兽（恶魔族）送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（光属性/恶魔族），使其攻击力直到回合结束时上升1000。那之后，可以变更那只怪兽的表示形式（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP042', '皇家魔族现场演唱竞技场', '【条件】这张卡在对手场上有怪兽2只以上的场合可以发动。
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（光属性/恶魔族）就不会被陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP043', '摄理的流转', '【条件】可以使自己墓地的4只怪兽（守备力100以下）返回卡组发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP044', '天帝的威眼', '【条件】可以将手牌的1只怪兽送入墓地发动。
【效果】选对手场上的1只怪兽变更表示形式（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。自己场上有表侧表示怪兽（等级10）的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP045', '监狱岛 大姐头巨岩', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方就不能高等召唤怪兽（等级5或6）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP046', '美☆魔女狩猎', '【条件】自己场上有表侧表示怪兽（等级8以上/水族）的场合，可以将手牌的1只怪兽（水族）送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下）破坏。用这个效果将怪兽（魔法师族）破坏的场合，可以再将对手场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP047', '水分补给', '【条件】自己场上有表侧表示怪兽（水族）2只以上的场合可以发动。
【效果】自己恢复500生命值。用这个效果恢复的场合，可以再选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP048', '花牙孢子', '【条件】自己墓地有通常怪兽（等级4以下/植物族）的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选自己墓地的1只通常怪兽（等级4以下/植物族）以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤的怪兽在结束阶段返回持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP049', '不屈的世纪末兽战士', '【条件】自己场上有表侧表示的「世纪末兽机界」的场合，可以支付1000生命值发动。
【效果】选自己墓地的1只怪兽（兽战士族）以表侧表示特殊召唤到自己的场上。这个回合，用这个效果特殊召唤的怪兽的攻击会贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP050', '魔迅雷', '【条件】自己的场上有表侧表示的「恶魔的召唤」或者表侧表示的通常怪兽（等级7以上/恶魔族）的场合可以发动。
【效果】将手牌的1只通常怪兽送入墓地。那之后，给予对手1300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP051', '袭来的自然', '【条件】自己场上有表侧表示怪兽（植物族）的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP052', '昂光的裁决', '【条件】无
【效果】选自己或者对手的墓地的1只怪兽返回持有者的卡组。对手手牌为0张的场合，可以再选对手场上的1只表侧表示怪兽返回持有者的手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP053', '鸟咒战术', '【条件】自己场上有表侧表示怪兽（战士族或者鸟兽族）合计2只以上的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。用这个效果将魔法陷阱卡破坏的场合，可以再选自己墓地的1只怪兽（等级8以下/战士族或者鸟兽族）返回卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP054', '荒野', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（恐龙族·不死族·岩石族）的攻击力、守备力就上升200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP055', '美☆魔女封禁', '【条件】自己场上有表侧表示怪兽（等级8以上/水族）的场合，对手召唤怪兽时可以发动。
【效果】选对手墓地的最多5只怪兽返回卡组。对手场上有表侧表示怪兽（魔法师族）的场合，可以再选对手墓地的最多5只怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP056', '水之泡-崩坏的泡沫期-', '【条件】自己的表侧表示怪兽（等级8以上/水族）受到攻击的对手怪兽的攻击宣言时可以发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降600。对手场上有表侧表示怪兽（魔法师族）的场合，再选对手场上的1只表侧表示怪兽，使其攻击力直到回合结束时下降100万。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/BRG1-JP001', '强大少年 七星道', '【条件】自己墓地有怪兽的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［自己墓地的怪兽的属性种类］×200。对方基本分是700以下的场合，再给与对方7亿伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP057', '花牙踏', '【条件】自己的表侧表示怪兽（植物族）受到攻击的对手怪兽的攻击宣言时，可以使自己墓地的2只怪兽（植物族）按照喜欢的顺序返回卡组下面发动。
【效果】对手场上的攻击表示怪兽全部变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP058', '花牙舞返', '【条件】对手怪兽的直接攻击宣言时，可以使自己墓地的3只怪兽（植物族）返回卡组发动。
【效果】将攻击过来的怪兽破坏。用这个效果将怪兽破坏的场合，可以再选自己墓地的1只怪兽（植物族）以表侧攻击表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP059', '咕咕鸽心碎眼', '【条件】自己场上有表侧表示怪兽（鸟兽族）的场合，对手以表侧表示召唤或特殊召唤怪兽（等级5以上）时可以发动。
【效果】选对手场上的1只攻击表示怪兽变为表侧守备表示。用这个效果将怪兽变为守备表示的场合，再给与对手500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP060', '鸽心小丑钟', '【条件】自己场上有表侧表示怪兽（鸟兽族）的场合，对手召唤怪兽时可以发动。
【效果】选自己墓地的1只「幻书鸽之骑士 夜幻」以表侧表示特殊召唤到自己的场上。那之后，自己恢复1500生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP061', '乐姬的独演', '【条件】自己场上的怪兽为1只的场合，对手怪兽（等级8以下）的攻击宣言时可以发动。
【效果】使那次攻击无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP062', '恶魔的受肉', '【条件】自己的「恶魔的召唤」或者通常怪兽（等级7以上/恶魔族）被对手的攻击破坏时可以发动。
【效果】选自己墓地的1只通常怪兽以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP063', '魔雷冥', '【条件】自己场上有表侧表示的「恶魔的召唤」或者表侧表示的通常怪兽（等级7以上/恶魔族）的场合，对手以表侧表示召唤或特殊召唤怪兽（等级6以上）时可以发动。
【效果】自己受到[对手墓地的怪兽的数量]×100伤害。那之后，使对手墓地的怪兽全部返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP064', '草叶生援', '【条件】对手召唤怪兽时可以发动。
【效果】将手牌的1只怪兽（植物族）以表侧表示特殊召唤到自己的场上。用这个效果将通常怪兽特殊召唤的场合，可以再选自己墓地的最多2只通常怪兽（等级1/植物族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP05-JP065', '积满醋酸的落穴', '【条件】对手召唤效果怪兽（等级3以下）时可以发动。
【效果】将那只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP000', '高科技飞龙', '被机械强化的翼龙。被龙打败而濒死之际被饲主给电子生物化了。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP001', '阳天使 切克闹勒', '以现在进行时奔放起眼的天使。谁也阻止不了了Man。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP002', '闪光新社员 阿新', '不断重复着测试错误，不断更新迭代的新人无人机。不顾一切地运作中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP003', '机业战士 闪光社员阿黑', '为了晋升竞争而耗费大半内存的中坚无人机。在报告书上掀起毁谤的风暴。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP004', '草肚盐烤牛舌牛头人', '舌头和胃袋很厉害的牛怪物。只需一串，无论什么都可以烧烤出来。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP005', '里脊半人马', '人马合一的怪物。干饭速度非常快，谁也追不上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP006', '恶魔牛小排河狸', '拿有恶魔的酱汁和盘子的河狸。显摆着人气部位排名来攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP007', '掩护河马', '要将一切攻击给顶回去，意外地快的河马。能运用履带灵活地游泳。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP008', '土偶甜点 绳文蒙布朗', '在土器里放入蒙布朗蛋糕结果就寄宿了灵魂。其徘徊于高床式仓库街的身影不断引发惨叫。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP009', '穿山火甲', '栖息于火山口的我行我素的生物。有时会点燃身体的火焰使周遭变成火海，但是本人却毫不在乎。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP010', '飞螳螂', '拥有飞行能力的螳螂，非常喜欢吃昆虫。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP011', '北国饺子娘', '提倡改革劳动方法的北国饭店的看板娘。众多企业战士准时下班来店，可是那时候的她本人也回家了。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP012', '疾风幻兽 帕祖祖', '长着4只翅膀的幻兽。在无人知晓的情况下守护着王都。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP013', '多面手女郎', '下至找猫上至重要人物的护卫，样样承包的多面手。最近总是去送午餐，但某天收到了发送人不明的信息。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP014', '七道奇才', '【条件】可以将1张手牌送入墓地发动。
【效果】对手场上的1只拥有与这张卡的攻击力相同的攻击力的表侧表示怪兽（等级8以下），其原攻击力直到回合结束时变为0。自己的墓地有「七道魔导士」的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP015', '火雷神 雷击士', '【条件】这张卡召唤的回合，可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升300。自己墓地有4只以上的卡名不同的怪兽（等级7）的场合，可以再选自己墓地的1只怪兽（等级7）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP016', '恐攻龙 股票破坏龙', '【条件】对手场上有5张以上的卡的场合，可以将1张手牌送入墓地发动。
【效果】对手场上的全部表侧表示怪兽（等级7以下）的攻击力直到回合结束时下降1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP017', '钢击龙 梅塔基亚斯', '【条件】可以将手牌的1只怪兽（等级7以上/龙族）送入墓地发动。
【效果】这个回合，这张卡不会被战斗和对手的陷阱卡的效果破坏，这张卡攻击过怪兽的战斗阶段里，这张卡可以仅1次再攻击怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP018', '迅敏表演者', '【条件】对手场上有怪兽的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽，其攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP019', '未来占者', '【条件】自己场上有表侧表示怪兽（等级7以上/念动力族）的场合可以发动。
【效果】自己抽1张。那之后，自己选1张手牌送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP020', '和平刺者', '【条件】无
【效果】选自己或者对手场上的1只攻击表示怪兽（战士族）变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP021', '魔仙斗 胜朱雀', '【条件】可以将手牌的1只怪兽（等级7以上）送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升1000。这个效果的条件将怪兽（战士族或者鸟兽族）送入墓地的场合，可以再选自己墓地的1只通常怪兽（等级6以下）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP022', '空中方程式飞鹰', '【条件】自己墓地的通常怪兽（风属性）为3只以上的场合可以发动。
【效果】将手牌的1只通常怪兽（风属性）以表侧表示特殊召唤到自己的场上。那之后，可以选自己墓地的1只通常怪兽（等级6以下/风属性）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP023', 'SP社员 警备', '【条件】这张卡召唤或特殊召唤的自己的主要阶段，可以支付600生命值发动。
【效果】选自己墓地的「名片的命死交换」「体力增强剂强力Z」各最多1张盖放到自己的魔法陷阱区。这个回合，自己不能用怪兽（机械族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP024', '暗黑闪光社员王 恶德话术号', '【条件】对手场上有表侧表示怪兽（等级7以上）的场合，可以将手牌的1只怪兽送入墓地发动。
【效果】选自己墓地的「攻击减薪」「战斗左迁」各最多1张盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP025', '七轮之侍 腹身串狼', '【条件】这张卡召唤或特殊召唤的自己的主要阶段，自己墓地有7只以上的怪兽（炎属性）的场合可以发动。
【效果】将对手场上的表侧表示怪兽（等级8以下/攻击力2500以上）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP026', '兽轨动 巨象', '【条件】自己墓地有通常怪兽（等级6以下/兽族）的场合，可以将1张手牌送入墓地发动。
【效果】选自己墓地的1只通常怪兽（等级6以下/兽族）以表侧表示特殊召唤到自己的场上。那之后，自己墓地有3只以上的通常怪兽（兽族）的场合，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP027', '土偶甜点 遮光器猫舌饼干', '【条件】这张卡召唤的回合可以发动。
【效果】从自己卡组上面将3张卡送入墓地。那之中有怪兽（炎族）的场合，可以再选自己墓地的1只怪兽（等级6以上/炎族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP028', '心动饼干糖果屋', '【条件】这张卡召唤的回合可以发动。
【效果】选自己墓地的1只通常怪兽（炎族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP029', '花牙祭之茉莉', '【条件】自己场上有表侧表示的通常怪兽（植物族）的场合可以发动。
【效果】选对手场上的1只守备表示怪兽变为表侧攻击表示。用这个效果变为表侧攻击表示的怪兽是地属性的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP030', '工匠无人机', '【条件】可以将手牌的1只怪兽（机械族）送入墓地发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP031', '突击坦克', '【条件】自己场上的表侧表示怪兽（机械族）为3只的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力、守备力直到回合结束时下降300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP032', '炽热鬣狗', '【条件】自己场上没有这张卡以外的怪兽的场合可以发动。
【效果】从自己卡组上面将[对手场上的怪兽数量]的卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP033', '复位跑者', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】将自己的卡组洗切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP034', '风车鳞虫', '【条件】自己或者对手场上有表侧表示的场地魔法卡的场合，可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP035', '门卫石像鬼', '【条件】可以将手牌的1只怪兽送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽，其等级直到回合结束时上升1。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP036', '卓越风之维埃托', '【条件】可以将1张手牌送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（风属性）。这个回合，那只怪兽的攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP037', '刃棘龙', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升200。那之后，可以选自己墓地的「侏罗纪世界」「荒野」各最多1张加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP038', '扫风之阿扎雷斯', '【条件】可以将2张手牌送入墓地发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP039', '王道魔导-光线转变', '【条件】自己场上有表侧表示怪兽（等级7以上/魔法师族）的场合，可以将手牌的1只怪兽（光属性）送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽，其攻击力直到回合结束时上升[对手场上的攻击力最低的表侧表示怪兽（等级8以下）的攻击力]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP040', '超级新星', '【条件】自己场上的表侧表示怪兽（等级7/光属性以外/龙族）为2只的场合可以发动。
【效果】选自己墓地的1只怪兽（光属性/龙族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP041', '即兴果酱音跃：P谱曲！', '【条件】可以使自己墓地的1只通常怪兽（等级2以下/念动力族）返回卡组上面发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下）返回持有者卡组上面。这个效果的条件使「可能甜心：D」返回卡组上面的场合，可以再选对手墓地的最多2只怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP042', '魔将气流', '【条件】可以将手牌的1只怪兽（战士族）送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（战士族/守备力2000以上），其攻击力直到回合结束时上升[选的怪兽的原本守备力]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP043', '逆风破坏', '【条件】无
【效果】选自己场上的1只表侧表示怪兽（风属性/攻击力2000以上），其攻击力直到回合结束时下降500。那之后，可以选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP044', '风暴音速', '【条件】自己场上有表侧表示怪兽（风属性）2只以上的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力、守备力直到回合结束时下降600。自己场上有表侧表示的「高科技飞龙」的场合，可以再选对手场上的1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP045', '顺风世界', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示的通常怪兽（风属性）的攻击力就上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP046', '名片的命死交换', '【条件】自己场上有表侧表示的「暗黑闪光社员王 恶德话术号」的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽（等级7以下）破坏。用这个效果将怪兽破坏的场合，可以再选自己墓地的1只怪兽（等级5以下/机械族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP047', '体力增强剂强健Z', '【条件】无
【效果】选自己场上的1只表侧表示的通常怪兽，自己恢复[选的怪兽的等级]×100LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP048', '适时击肉', '【条件】自己场上有表侧表示怪兽（等级7以上/兽族）的场合可以发动。
【效果】从自己卡组上面将4张卡送入墓地。用这个效果将4只怪兽（炎属性/兽族）送入墓地的场合，再选自己或者对手场上的1只表侧表示怪兽，其攻击力直到回合结束时上升2900。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP049', '燃兽品质', '【条件】可以使自己墓地的1只怪兽（兽族）返回卡组发动。
【效果】双方场上的全部表侧表示怪兽（炎属性）的攻击力直到回合结束时上升[双方场上的表侧表示怪兽（炎属性）的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP050', '野性厨房', '【条件】这张卡在自己场上的表侧表示怪兽（炎属性）为3只的场合可以发动。
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（炎属性）的攻击力就上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP051', '兽战场的障壁', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽的攻击力就下降200，双方场上的表侧表示的通常怪兽（兽族）的守备力就上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP052', '渡来古讨 干果装饰大蛋糕', '【条件】可以使自己墓地的4只怪兽（炎族）返回卡组发动。
【效果】自己场上的全部表侧表示怪兽（地属性/炎族）的攻击力直到回合结束时上升800。那之后，自己恢复800生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP053', '阴阳封阵', '【条件】可以使自己墓地的4只怪兽返回卡组发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降[选的怪兽的等级]×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP054', '铁之重击', '【条件】自己场上有表侧表示怪兽（机械族）的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP055', '野兽的激怒', '【条件】自己场上有表侧表示怪兽（兽族或者兽战士族）合计2只以上的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。用这个效果将魔法陷阱卡破坏的场合，可以再选自己墓地的1张场地魔法卡返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP056', '狂战士斗技场', '【条件】这张卡从卡组上面将2张卡送入墓地发动。
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽的攻击力就上升100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP057', '实力悬殊的竞争', '【条件】对手召唤怪兽（等级5以上）时可以发动。
【效果】选自己墓地的1只通常怪兽（等级5以下）在自己场上以表侧攻击表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP058', '7机会', '【条件】对手怪兽（等级7以上）的攻击宣言时可以发动。
【效果】自己抽3张，双方确认。那之中有怪兽（等级7）2只以上的场合，自己恢复[那些怪兽（等级7）的数量]×1500生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP059', '念力反击', '【条件】自己的怪兽（念动力族）被对手的攻击破坏时可以发动。
【效果】给予对手1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP060', '魔将决斗斩', '【条件】自己的表侧表示怪兽（战士族）受到攻击的对手怪兽的攻击宣言时可以发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降400。自己场上有表侧表示怪兽（等级8以上/战士族）的场合，可以再选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP061', '援护弹幕', '【条件】自己的表侧表示怪兽（风属性）承受攻击的对手怪兽的攻击宣言时，可以使自己墓地的1只通常怪兽（风属性）返回卡组发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP062', '攻击减薪', '【条件】自己的表侧表示怪兽受到攻击的对手怪兽（等级8以下）的攻击宣言时，可以支付600生命值发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降400。那之后，双方怪兽不会被那次战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP063', '战斗左迁', '【条件】自己的表侧表示怪兽（机械族）受到攻击的对手怪兽的攻击宣言时，可以支付600生命值发动。
【效果】选对手场上的1只攻击表示怪兽变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP064', '永久冻结', '【条件】对手召唤怪兽（攻击力2500以上）时，可以将自己场上的1只怪兽送入墓地发动。
【效果】使那只召唤的怪兽返回持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP06-JP065', '兽骗', '【条件】自己场上有表侧表示怪兽（兽族）的场合，对手将怪兽表侧表示召唤或特殊召唤时可以发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降1000。那之后，可以选自己墓地1只通常怪兽（等级1/兽族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP000', '海龙-代达罗斯', '【条件】可以将自己场上的1张表侧表示的「海」送入墓地发动。
【效果】将这张卡以外的双方场上的卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP001', '战天女 羽璃姫理', '指示前往天界的针路的神使。照亮黑暗化为光明。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP002', '塔库利米诺斯', '身上有鳍，在水中也可以自由行动的海龙的同伴。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP003', '海豚王 伊鲁夸', '受到地球的激浪的揉搓而被灌输入帝王学的海豚。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP004', '我我我外场手', '充满毅力的防守和具有意外性的击球是其魅力的棒球战士。也被称为挡网旁的魔术师，属于留下纪录不多但容易被人记住的类型。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP005', '热辣辣接手', '巧妙的引导配球和飞箭般的传球是其魅力的棒球战士。也被称为扇轴，属于以火热的比赛风格引领队友的类型。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP006', '唰拉拉击球员', '长打能力强的击球是其魅力的棒球战士。也被称为冲锋陷阵的队长，属于很积极从第一球开始挥棒的类型。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP007', '采访机车', '以告密为燃料行驶去获取独家新闻的机车。取证·执笔也是小菜一碟！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP008', '万能调味查察官', '酸甜苦辣都已经充分理解的味道专家。任何料理都能处理恰当咸淡适中。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP009', '火面上忍 加热大杯碗面', '跨越一切局面，连面不绝地进化的火面忍军头领。不受立场和面子的约束，对不面熟的成员也会搭话。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP010', '海胆确认生物', '海里面随处可见的生物。近年虽持续被滥捕但却毫无减少迹象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP011', '死灵师三世', '【条件】这张卡召唤的回合，对手场上有表侧表示怪兽（等级7以上）的场合可以发动。
【效果】选自己墓地的1只通常怪兽（等级3）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP012', '黎明之战士', '【条件】自己场上有表侧表示怪兽（等级7/战士族）的场合可以发动。
【效果】将手牌的1只怪兽（等级7/战士族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP013', '山岚龙', '【条件】可以支付500LP发动。
【效果】将自己卡组最上面的卡送入墓地。那之后，可以选自己墓地的1张「山」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP014', '念力拾音人', '【条件】这张卡召唤或特殊召唤的自己的主要阶段，可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时下降800。那之后，自己可以恢复800生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP015', '鬼将 目座女', '【条件】这张卡召唤的回合，对手场上有表侧表示怪兽（攻击力2500以上）的场合可以发动。
【效果】选自己墓地的1只怪兽（等级7以上/战士族）加入手牌。这个回合，自己不能用怪兽（守备力1900以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP016', '贯贵益荒男', '【条件】自己场上的表侧表示怪兽为3只的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（战士族）。这个回合，那只怪兽的攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP017', '月魔将 鬼目流奈', '【条件】无
【效果】选对手场上的最多2只怪兽变更表示形式（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。用这个效果将表示形式变更的场合，可以再选自己场上的1只表侧表示怪兽变更表示形式。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP018', '皇家魔族 歇段乐手', '【条件】对手场上有表侧表示怪兽（等级8以上）的场合可以发动。
【效果】将手牌的1只通常怪兽（等级5以上/恶魔族）以表侧守备表示特殊召唤到自己的场上。这张卡的等级直到回合结束时上升5。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP019', '槲寄生纳米粒子机', '【条件】自己墓地的怪兽只有怪兽（电子界族）3只的场合可以发动。
【效果】将自己墓地的怪兽（电子界族）全部加入手牌。那之后，自己场上的这张卡返回持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP020', '幻刃天龙 门式起重龙', '【条件】自己或者对手场上有表侧表示的场地魔法卡的场合可以发动。
【效果】选自己墓地的1只「幻刃龙 建造龙」以表侧表示特殊召唤到自己的场上。这个回合，自己不能用怪兽（幻龙族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP021', '轻快海豚', '【条件】自己场上有表侧表示的「海」或者「大海洋」，自己场上有表侧表示的通常怪兽（鱼族·海龙族·雷族·水族）的场合可以发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP022', '海星骑兵', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选对手墓地的1只怪兽回到卡组。自己场上有表侧表示的「海」或者「大海洋」的场合，可以再从自己卡组上面将2张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP023', '单恋海豚', '【条件】可以将手牌的1张「海」或者「大海洋」送入墓地发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP024', '头锤抹香鲸', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降500。自己场上有表侧表示的「海」或者「大海洋」的场合，再给予对手500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP025', '怒怒怒二垒手', '【条件】自己或者对手场上有表侧表示的「热血魂体育场」的场合，可以支付500LP发动。
【效果】这个回合，怪兽（炎属性）以攻击表示高等召唤的场合，表侧表示的这张卡可以作为2只的分量来解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP026', '隆隆隆裁判员', '【条件】可以使自己墓地的1张「热血魂体育场」返回卡组发动。
【效果】选自己墓地的1只通常怪兽（炎属性/守备力400）以表侧表示特殊召唤到自己的场上。这个回合，自己不能用怪兽（炎属性以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP027', '背号99 球儿皇龙 霍姆格兰德拉', '【条件】可以使自己墓地的3只怪兽（炎属性）返回卡组发动。
【效果】选自己墓地的1只「背号39 球儿皇 霍姆」以表侧表示特殊召唤到自己的场上。那之后，这张卡的攻击力直到回合结束时上升2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP028', '背号39 球儿皇 霍姆', '【条件】自己或者对手场上有表侧表示的「热血魂体育场」的场合，可以将自己场上的2只表侧表示怪兽（等级4/炎属性）送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升2500。这个回合，自己只能用这张卡攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP029', '报道狸 话筒狸', '【条件】可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选自己墓地的1只「特报机器 强力小报拟人机」以表侧守备表示特殊召唤到自己的场上。那之后，可以选自己墓地的1只「派送机器 新闻嗡」或者1张「报道魂」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP030', '扫除机器 号外人', '【条件】可以使自己墓地的1只怪兽（地属性/机械族）返回卡组发动。
【效果】从自己卡组上面将2张卡送入墓地。那之中有怪兽（地属性/机械族）的场合，可以再选自己墓地的1只通常怪兽（机械族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP031', '海龙 风哮小鱼鳞鳄', '【条件】对手场上有怪兽的场合，可以使自己墓地的1只「海龙王 硬鳞鱼鳞鳄」或者1张「大极流」返回卡组下面发动。
【效果】将手牌的1只怪兽（鱼族或者海龙族）以表侧表示特殊召唤到自己的场上。这个回合，自己不能用怪兽（水属性以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP032', '海龙骑士', '【条件】可以使自己墓地的2只怪兽返回卡组发动。
【效果】选对手场上的1张里侧表示的魔法陷阱卡确认。对手的墓地有与那张卡同名的卡的场合，可以再将选的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP033', '双头伤齿龙', '【条件】可以将包含通常怪兽的2张手牌送入墓地发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP034', '混沌之勇者 莱达克罗斯·灰浊', '「晓之勇者 莱达克罗斯」＋「黑暗术士」
【条件】可以将卡组最上面的卡送入墓地发动。
【选择效果】●这张卡的攻击力直到回合结束时上升[双方场上的怪兽数量]×300。●将对手场上的里侧表示的魔法陷阱卡全部确认，从那之中选1张破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP035', '可能甜心：D 驱动现场演奏', '「可能甜心：D」＋「念力拾音人」
【条件】对手场上有怪兽的场合可以发动。
【选择效果】●自己受到2000伤害。那之后，可以使对手场上的全部表侧表示怪兽的攻击力直到回合结束时下降3000。●自己恢复1000生命值。那之后，可以选自己墓地的1只怪兽（等级7以上/念动力族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP036', '天翔流丽 夜目照', '「魔将 夜目流罗」＋「战天女 哈里基莉」
【条件】可以将卡组最上面的卡送入墓地发动。
【选择效果】●直到下次对手回合结束时，这张卡表侧表示的期间，这张卡的攻击力上升500，双方不能将怪兽（等级9以下）以表侧攻击表示特殊召唤。●选自己或者对手场上的1只怪兽变更表示形式。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP037', '报道舰轰铠号 疾风迅雷', '「特报机器 强力小报拟人机」＋「派送机器 新闻嗡」
【条件】可以将卡组最上面的卡送入墓地发动。
【效果】对手从自身卡组上面将7张卡翻开，双方确认。对手让翻开的卡按照喜欢的顺序返回卡组上面。自己可以使对手场上的全部表侧表示怪兽的攻击力直到回合结束时下降[翻开的卡之中的怪兽数量]×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP038', '火面特忍 肉增量音爆极粗面', '「火面上忍 加面极粗面」＋「万能调味查察官」
【条件】这张卡特殊召唤的自己的主要阶段可以发动。
【效果】给予对手1000伤害。自己抽1张。用这个效果抽卡的场合，可以再选自己墓地的「火面烧心背脂之术」「火面浓稠返抽之术」各最多1张盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP039', '火面特忍 味噌快熟方便面', '「火面上忍 加热大杯碗面」＋「万能调味查察官」
【条件】可以使自己墓地的3只怪兽（炎族）返回卡组发动。
【效果】这个回合，这张卡的攻击力上升600，其攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP040', '提坦狩人', '「提坦的末裔」＋「子守山羊」
【条件】可以使自己墓地的1只通常怪兽（恶魔族）返回卡组发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP041', '分离器噬神狼 苏尔', '「系统屠龙者 苏尔」＋「接口犬」
【条件】可以从卡组上面将2张卡送入墓地发动。
【效果】自己抽1张。对手场上有怪兽的场合，可以再将手牌的1只怪兽（电子界族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP042', '超魔基地 超大王基地', '【条件】这张卡在自己的LP比对手少的场合可以发动。
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（等级7以上/机械族）的攻击力就上升400，双方场上的表侧表示怪兽（等级10/机械族）就不会被魔法陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP043', '五家的加护', '【条件】自己场上有表侧表示怪兽（战士族·天使族·兽族·鸟兽族·爬虫类族）的场合可以发动。
【效果】选自己场上最多2只表侧表示怪兽。这个回合，那些怪兽不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP044', '奇装天铠', '【条件】可以使自己墓地的3只种族不同的怪兽（等级7以上）按照喜欢的顺序全部返回卡组上面或按照喜欢的顺序全部返回卡组下面发动。
【效果】选自己墓地的1只通常怪兽加入手牌。那之后，可以选对手场上的1只表侧表示怪兽使其攻击力直到回合结束时下降1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP045', '水之形', '【条件】可以将手牌的1张魔法陷阱卡送入墓地发动。
【效果】选自己墓地的1只怪兽（鱼族·海龙族·水族·雷族）以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤的怪兽的攻击力直到回合结束时下降800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP046', '消失的奔流', '【条件】自己场上有表侧表示怪兽（海龙族）的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP047', '热血魂体育场', '【条件】无
【效果】只要这张卡在场地区表侧表示，自己回合里，自己场上的表侧表示怪兽（炎属性）的攻击力就上升400，对手回合里，对手场上的表侧表示怪兽（炎属性）的攻击力就上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP048', '瓦版小报炸', '【条件】自己场上有表侧表示怪兽（地属性/机械族）的场合，可以将手牌的1只怪兽（地属性/机械族）送入墓地发动。
【效果】对手从自身卡组下面将5张卡取出，双方确认。给予对手[确认的卡之中的怪兽数量]×400伤害。对手使确认过的卡按照喜欢的顺序返回卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP049', '新闻分身报', '【条件】自己场上有表侧表示怪兽（等级7以上/地属性/机械族）的场合可以发动。
【效果】选自己墓地的1只「特报机器 强力小报拟人机」以表侧表示特殊召唤到自己的场上。这个回合，用这个效果特殊召唤的怪兽不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP051', '火面浓稠返抽之术', '【条件】可以将最多为自己墓地的通常怪兽（炎族）的数量的手牌送入墓地发动。
【效果】自己抽[这个效果的条件送入墓地的卡的数量]。自己场上有表侧表示的通常怪兽（炎族）的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP052', '七宝船', '【条件】可以将手牌的1只怪兽送入墓地发动。
【效果】自己抽1张。这个效果的条件将怪兽（等级7）送入墓地的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP053', '基调强节奏', '【条件】可以使自己墓地的2只怪兽返回卡组发动。
【效果】选对手墓地的2～7只相同种族的怪兽返回卡组。用这个效果使4只以上的怪兽返回的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP054', '小川', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（等级3以下/鱼族·海龙族·雷族·水族）的攻击力、守备力就上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP055', '手牌活杀', '【条件】无
【效果】有手牌的玩家将手牌全部送入墓地。那之后，自己可以选自己场上的1只表侧表示怪兽使其攻击力直到回合结束时上升[被这个效果送入墓地的卡的数量]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP056', '返回！闲职！！', '【条件】对手怪兽（等级6以上）的攻击宣言时可以发动。
【效果】选自己墓地的1只怪兽（等级6以下/念动力族），自己的LP恢复[选的怪兽的攻击力]。用这个效果恢复1000生命值以上的场合，可以再将选的怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP057', '对冲突', '【条件】自己的表侧表示怪兽（等级10以上）受到攻击的对手怪兽的攻击宣言时可以发动。
【效果】双方怪兽不会被那次战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP058', '海豚反击', '【条件】自己的表侧表示怪兽（鱼族或者海龙族）受到攻击的对手怪兽的攻击宣言时，可以使自己墓地的1张「海」或者「大海洋」返回卡组发动。
【效果】选对手场上的1只攻击力最高的表侧表示怪兽破坏。自己抽1张，双方确认。那张卡是「海」或者「大海洋」的场合，再给予对手500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP059', '伊鲁夸的激浪', '【条件】对手怪兽的直接攻击宣言时，自己场上有表侧表示的「海」或者「大海洋」的场合可以发动。
【效果】对手场上的全部表侧表示怪兽的表示形式变更（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。那之后，可以选自己墓地的1只通常怪兽（海龙族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP060', '我我我毅力', '【条件】自己场上的怪兽被对手的效果破坏时可以发动。
【效果】选自己墓地的1只怪兽（炎属性）以表侧守备表示特殊召唤到自己的场上。用这个效果将「背号39 球儿皇 霍普」或者「背号99 球儿皇龙 霍姆格兰德拉」特殊召唤的场合，可以再选对手场上的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP061', '要求重审9', '【条件】自己的怪兽被对手的攻击破坏时可以发动。
【效果】自己恢复900LP。自己墓地有怪兽（炎属性）9只以上的场合，可以再选自己墓地的1只「背号39 球儿皇 霍普」或者「背号99 球儿皇龙 霍姆格兰德拉」以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP062', '以上是来自现场的报道！', '【条件】对手怪兽的直接攻击宣言时，可以将手牌的1只怪兽（地属性/机械族）送入墓地发动。
【效果】给予对手300伤害。用这个效果给予对手伤害的场合，再在这个回合使自己不会受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP063', '发生事件！', '【条件】自己场上的表侧表示怪兽（机械族）被对手的攻击或者对手的效果破坏时可以发动。
【效果】给予对手300伤害。用这个效果给予对手伤害的场合，可以再选自己墓地的最多2只「采访机车」以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP064', '螺旋间歇泉', '【条件】对手从手牌将怪兽召唤或盖放时可以发动。
【效果】给予对手400伤害。这个回合，对手不能为了作高等召唤而将里侧表示怪兽解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP065', '豪胆防御任务', '【条件】原攻击力为2500以上的对手怪兽（等级8以下）的攻击宣言时可以发动。
【效果】将攻击过来的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP07-JP050', '火面炙烤喷焰之术', '【条件】自己场上有表侧表示怪兽（等级7以上/炎族）的场合可以发动。
【效果】自己场上的全部表侧表示怪兽（炎族）的攻击力直到回合结束时上升[双方墓地的通常怪兽数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP000', '创世神', '这张卡不能从墓地特殊召唤。
【条件】有自己的手牌的场合可以发动。
【效果】选自己墓地的1只怪兽以表侧表示特殊召唤到自己的场上。那之后，自己选1张手牌送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP001', '黑暗飞米粒子机', '连向其他摄理的龙树之源。隐藏着无限的分歧，展现出未知的世界。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP002', '王冠蛇', '总是很开朗且亲近人类的蛇。以配合笛声来跳的舞来使观众着迷。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP003', '古代的蜥蜴战士', '从太古开始就一直保持着从前的外貌的蜥蜴战士。意外地强。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP004', '铠蜥蜴', '身体坚硬的蜥蜴。被那大口咬了的话很快会毙命。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP005', '加速龟 助推龟', '因疯狂的计划而诞生的龟。好像会运用助推器在宇宙空间自由自在地移动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP006', '插头水母', '水母和插头合为一体的生物。其生态有很多谜团。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP007', '线圈鞭冠鱼', '长有发达的发电器官的鮟鱇。用电击和尖牙来攻击敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP008', '感谢的蚂蚁', '对总是支持自己的同伴表示谢意的蚂蚁。下决心要拉拢更多的战友。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP009', '柳安冒险队', '以未知的土地为目标的冒险者们。本来是在比试看能飞到多远的地方去，不知从何时起就变成了结伴一起旅行。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP010', '火狮子', '住在炎之世界的凶暴存在。遇袭的猎物连骨头都不剩。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP011', '七道术士', '【条件】可以将自己场上的3只表侧表示怪兽送入墓地发动。
【效果】选自己墓地的1只怪兽（等级7以下/魔法师族）以表侧表示特殊召唤到自己的场上。用这个效果将「七道魔导士」特殊召唤的场合，可以再选自己墓地的1只「七道魔女」以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP012', '节奏表演者', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】对手将自身卡组最上面的卡送入墓地。用这个效果将魔法陷阱卡送入墓地的场合，可以再使自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP013', '超可爱执行者 菲娜', '【条件】对手场上有表侧表示怪兽（攻击力1700以上）的场合，可以将卡组最上面的卡送入墓地发动。
【效果】自己场上的全部表侧表示怪兽的攻击力直到回合结束时上升200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP014', '战天女 姫理羽璃', '【条件】自己场上没有这张卡以外的怪兽的场合，可以使1张手牌返回卡组下面发动。
【效果】选自己墓地的1只怪兽（天使族/攻击力0）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP015', '机械烧蚀伞护鸟', '【条件】这张卡召唤的回合，自己场上有表侧表示的通常怪兽（风属性）的场合可以发动。
【效果】选自己墓地的1张「顺风世界」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP016', '队长背号39 球儿皇 霍姆普雷特', '【条件】可以使自己墓地的3只怪兽（等级4/炎属性）返回卡组发动。
【效果】这张卡的攻击力直到回合结束时上升1500。自己的LP为1000以下的场合，可以再选对手场上的1只表侧表示怪兽使其攻击力直到回合结束时下降3000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP017', '镰刀变色龙', '【条件】可以支付300LP发动。
【效果】从自己卡组上面将3张卡送入墓地。那之中有通常怪兽（爬虫类族）的场合，再选自己墓地的1只通常怪兽（爬虫类族）加入手牌。发动过这个效果的回合，自己不能用怪兽（爬虫类族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP018', '爪狮变色龙', '【条件】对手场上有里侧表示怪兽的场合，从卡组上面将2张卡送入墓地才能发动。
【效果】选自己场上的1只表侧表示怪兽（等级7以上/爬虫类族）。这个回合，那只怪兽的攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP019', '炽热火焰变色龙', '【条件】自己的LP比对手少的场合，可以支付600LP发动。
【效果】从自己卡组上面将3张卡送入墓地。那之中有怪兽（爬虫类族）的场合，可以再选自己墓地的1只通常怪兽（等级6以下/爬虫类族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP020', '金属大型变色龙', '【条件】自己的LP比对手少的场合，可以支付600LP发动。
【效果】从自己卡组上面将3张卡送入墓地。这张卡的攻击力直到回合结束时上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP021', '捕食炮击变色龙', '【条件】自己的LP为1000以下的场合，可以从卡组上面将5张卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[双方LP的差值]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP022', '蜕皮卡利古拉变色龙', '【条件】无
【永续效果】这张卡的攻击力上升[自己墓地的卡的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP023', '观测龟 间谍卫星龟', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（等级3～8），其等级直到回合结束时下降2。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP024', '火箭龟 模块化火箭古巨龟', '【条件】可以将自己场上最多2只这张卡以外的表侧表示怪兽（爬虫类族）送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[这个效果的条件送入墓地的怪兽的数量]×700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP025', '霹八霹八火花章鱼', '【条件】这张卡召唤的回合，自己场上有表侧表示的通常怪兽（雷族）的场合可以发动。
【效果】这张卡的攻击力直到回合结束时上升400。那之后，给予对手400伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP026', '惠雷之精灵', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选对手墓地的1张卡返回卡组。用这个效果使魔法陷阱卡返回的场合，可以再选对手墓地的1张卡返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP027', '传感鸭嘴兽', '【条件】可以使1张手牌返回卡组下面发动。
【效果】选自己墓地的1只怪兽（等级5以上/雷族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP028', '发射极锹甲', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（等级5以上/雷族），其等级直到回合结束时下降4。那之后，给予对手400伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP029', '爆破大口鲨', '【条件】对手的手牌为1张以下的场合，可以使自己墓地的1只怪兽（雷族）返回卡组发动。
【效果】选自己场上的1只表侧表示怪兽（雷族），其攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP030', '风暴电击驱逐舰', '【条件】对手的手牌为2张以下的场合可以发动。
【效果】选自己墓地的1只通常怪兽（等级4以下/雷族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP031', '雷斗骑 触发龙', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升300。对手的手牌为0张的场合，再在这个回合使这张卡的攻击贯通（攻击守备表示怪兽攻击时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP032', '七道高级魔导士', '「七道魔导士」+「七道魔女」
【条件】无
【永续效果】这张卡的攻击力上升[自己墓地的怪兽（暗属性/魔法师族）的卡名的种类]×300。自己的墓地有7只以上的怪兽（暗属性/魔法师族）的场合，这张卡的攻击会贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP033', '胧击龙 米拉基亚斯之星F', '「幻击龙 米拉基亚斯」+「THE☆天龙」
【条件】可以将卡组最上面的卡送入墓地发动。
【选择效果】●选对手场上最多3只表侧表示怪兽，其攻击力直到回合结束时下降1500。这个回合，这张卡可以对怪兽作2次攻击。●这个回合，这张卡可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP034', '无尽浪漫之闪电吉他', '「梦弦之闪电折叠吉他」+「浪漫小拨片」
【条件】可以使自己墓地的「梦弦之闪电折叠吉他」「浪漫小拨片」各1只返回卡组发动。
【选择效果】●给予对手1500伤害。●自己抽3张。那之后，自己选2张手牌送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP035', '同胞英雄', '「当方英雄」+「当方英雄」
【条件】无
【效果】选自己墓地的1只通常怪兽（等级4以下/战士族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP036', '天翔流丽 濑目照', '「魔将 濑目流罗」+「战天女 羽璃姬理」
【条件】无
【选择效果】●选自己墓地的1只怪兽（等级8以下/战士族或天使族）以表侧表示特殊召唤到自己的场上。●选最多为[自己墓地的怪兽（攻击力0）的数量]的对手墓地的怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP037', '花牙绚烂 名花异邦兰', '「花牙女忍 异邦兰」+「花牙女忍 异邦兰」
【条件】无
【效果】选自己手牌或者自己墓地的1只怪兽（等级8以下/植物族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP038', '花牙潜攻 潜水杜尔迦', '「花牙忍 机炮」+「花牙武者之龙胆」
【条件】对手场上有2只以上的怪兽的场合可以发动。
【效果】将对手场上的表侧表示怪兽（等级6以上）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP039', '钢铁徽章之眼镜王蛇明星', '「虚钢演机」+「王冠蛇」
【条件】可以将1张手牌送入墓地发动。
【选择效果】●自己抽2张。那之后，自己选1张手牌送入墓地。●选对手场上的最多3只表侧表示怪兽（爬虫类族），其攻击力、守备力直到回合结束时下降1000。这个回合，这张卡可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP040', '波塞鱼历险者', '「线圈鞭冠鱼」+「插头水母」
【条件】将卡组最上面的卡送入墓地才能发动。
【效果】自己场上的全部表侧表示怪兽（雷族）的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP041', '火浇摩天鱼', '「霹八霹八火花章鱼」+「插头水母」
【条件】无
【效果】选自己墓地1只「霹八霹八火花章鱼」加入手牌。那之后，给予对手800伤害。对手场上有表侧表示怪兽（等级8）的场合，再在这个回合使这张卡的攻击力上升800，对手场上的全部表侧表示怪兽（等级8）的攻击力下降800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP042', '上等草肚牛头里脊人马兽', '「草肚盐烤牛舌牛头人」+「里脊半人马」
【条件】这张卡特殊召唤的自己主要阶段，可以使自己墓地的4只怪兽（炎属性/兽族）按照喜欢的顺序返回卡组上面发动。
【效果】选自己墓地的「适时击肉」「燃兽品质」「野性厨房」各最多1张加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP043', '荒野的七轮 荷尔蒙·冈麦奎因', '「七轮之侍 腹身串狼」+「万能调味查察官」
【条件】可以使自己墓地的「七轮之侍 腹身串狼」「万能调味查察官」合计2只返回卡组发动。
【效果】将对手场上的表侧表示怪兽（等级9以下/炎属性以外）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP044', '以太疾速攻击者', '「以太探寻者」+「以太寻得者」
【条件】可以使自己墓地的1张「聚变」返回卡组上面或下面发动。
【效果】这张卡的攻击力直到回合结束时上升600。那之后，可以选自己墓地1只通常怪兽返回卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP045', '火神点火灰霸驱动', '【条件】自己场上有表侧表示的极限怪兽（炎属性/战士族）的场合可以发动。
【效果】给予对手800伤害。自己场上有极限模式的怪兽的场合，可以再选对手场上的1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP046', '皇家魔族回音', '【条件】可以使1张手牌返回卡组下面发动。
【效果】选自己手牌或者自己墓地的1只怪兽（等级7以下/恶魔族/守备力0）以表侧表示特殊召唤到自己的场上。用这个效果将怪兽（等级7）特殊召唤的场合，可以再选自己墓地的1只怪兽（恶魔族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP047', '花牙紫吹', '【条件】可以将自己场上的1只表侧表示怪兽（植物族）送入墓地发动。
【效果】选自己或者对手场上的1只守备表示怪兽变为表侧攻击表示。那之后，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP048', '花牙悲愿', '【条件】自己墓地有怪兽（植物族）的场合，可以将自己场上的2只表侧表示怪兽（植物族）送入墓地发动。
【效果】选自己墓地的1只怪兽（植物族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP049', '返垒魔法-牺牲打力', '【条件】可以将自己场上的1只表侧表示怪兽（炎属性）送入墓地发动。
【效果】将手牌的1只怪兽（等级8/炎属性）以表侧表示特殊召唤到自己的场上。这个效果的条件将怪兽（等级8）送入墓地的场合，可以再选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP050', '连赛摇头娃娃', '【条件】无
【效果】选自己墓地的「热血魂体育场」「返垒魔法-牺牲打力」合计最多2张加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP051', '激鳞解放', '【条件】对手场上有怪兽的场合，可以支付1000LP发动。
【效果】从自己卡组上面将5张卡送入墓地。那之中有怪兽（爬虫类族）的场合，可以再选自己场上的1只表侧表示怪兽（爬虫类族）使其攻击力直到回合结束时上升[被这个效果送入墓地的怪兽（爬虫类族）的数量]×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP052', '逆鳞火斩', '【条件】可以将手牌的2只怪兽（爬虫类族）送入墓地发动。
【效果】选拥有[这个效果的条件送入墓地的怪兽的等级合计]以下的等级的对手场上的1只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP053', '间谍卫星观测', '【条件】自己场上有2只以上的表侧表示怪兽（爬虫类族）的场合可以发动。
【效果】将自己卡组最上面的卡翻开，双方确认。那之后，自己使翻开的卡返回卡组上面或下面。并且，可以再选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP054', '烈火龟陨石', '【条件】无
【效果】选自己场上的2只表侧表示怪兽（爬虫类族）和对手场上的1只表侧表示怪兽（等级8以下），其攻击力直到回合结束时下降1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP055', '拍手雷电', '【条件】自己场上有2只以上的表侧表示怪兽（雷族）的场合可以发动。
【效果】对手场上的全部表侧表示怪兽的攻击力、守备力直到回合结束时下降400。自己场上的表侧表示怪兽（雷族）为3只的场合，可以再使自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP056', '闪驱雷击', '【条件】自己场上有表侧表示怪兽（雷族）的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP057', '平行宇宙之门', '【条件】无
【效果】将自己卡组最上面的卡送入墓地。自己的手牌为0张的场合，可以再选自己墓地的最多2只通常怪兽以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP058', '魔雾雨', '【条件】无
【效果】选自己场上的1只表侧表示的「恶魔的召唤」或者表侧表示怪兽（雷族）。将拥有选的怪兽的攻击力以下的守备力的对手场上的表侧表示怪兽全部破坏。这个回合，自己不能用怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP059', '侏罗纪绿洲', '【条件】这张卡在自己场上有表侧表示怪兽（恐龙族）的场合，从卡组上面将2张卡送入墓地可以发动。
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（恐龙族）就不会被怪兽的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP060', '填埋盾', '【条件】对手将怪兽召唤时，可以使自己墓地的1张场地魔法卡返回卡组下面发动。
【效果】那只怪兽变为里侧守备表示。那之后，可以选自己场上的1只表侧表示怪兽（幻龙族）使其攻击力、守备力直到回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP061', '警告鳞光', '【条件】自己场上有表侧表示怪兽（爬虫类族）的场合，对手将怪兽（等级7以上）以表侧表示召唤或特殊召唤时可以发动。
【效果】这个回合，对手不能用怪兽（攻击力3000以上）攻击。并且，可以再选自己墓地的最多5只怪兽（爬虫类族）返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP062', '最强斗志', '【条件】自己的守备表示怪兽受到攻击的对手怪兽（等级9以下）的攻击宣言时可以发动。
【效果】使那次攻击无效。那之后，选自己场上的1只守备表示怪兽变为表侧攻击表示。被这个效果变为表侧攻击表示的怪兽是通常怪兽的场合，再使其攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP063', '神圣装甲 -炸裂之力-', '【条件】对手怪兽的攻击宣言时，可以使自己墓地的3只怪兽返回卡组发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降500。自己的墓地有「炸裂装甲」的场合，可以再选对手场上的最多2只攻击表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP064', '放电', '【条件】对手怪兽的攻击宣言时，可以使自己墓地的2只怪兽（雷族）返回卡组发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降800。那之后，给予对手400伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP08-JP065', '冥土女仆土产', '【条件】自己场上的怪兽被对手的攻击或者对手的效果破坏时可以发动。
【效果】自己抽2张。那之后，可以选自己墓地的1只「死灵女仆 娜娜」以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP000', '左轮手枪龙', '【条件】无
【效果】选对手场上的1只怪兽，进行3次投掷硬币。那之中有2次以上是正面的场合，将那只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP001', '星河波新生龙', '从星河诞生的崭新银河战士。从恒星吸取强大能量来战斗。加纳里·杜·兹威！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP002', '银河星忘却龙', '沃·图·征！奥撒姆·特鲁·古奈特！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP003', '羊界 羊皮地妖', '羊界牧场的新面孔。不劳如地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP004', '羊界 羊毛火妖', '羊界牧场的年长者。其热血指导让周围的人都敬而远之。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP005', '羊界 羊肉夜妖', '羊界牧场的内向孩子。总是待在角落像大人那样稳静。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP006', '魔法羊女 咩～歌小妹', '咩咩旋律♪家畜咩～虐杀咩～！咩～歌小妹是羊界牧场的公主。吃到美味的纸和重要的信就情不自禁地喊出「真香咩～♪」！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP007', '一年的帚', '寄宿有灵魂的扫帚。据说得到此扫帚的人会为了做成一件事而开始努力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP008', '十年的魔剑', '寄宿有灵魂的剑。据说得到此剑的人会刻苦修行等待大显身手的时机。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP009', '百年的古木刀', '寄宿有灵魂的木刀。据说经过各种人之手，一路见证了兴盛与衰亡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP010', '阿特拉斯战斗独角仙', '围绕暗之树液展开争斗的甲虫的一种。隐藏有超乎想象的力量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP011', '王座守护者', '国王离开时，保卫王座不受外敌攻击的王妃。守备力高。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP012', '狮鹫兽卫', '擅长用巨大的躯体作出守备。半吊子的攻击都会被弹回。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP013', '黑手握手者', '【条件】无
【效果】选对手墓地的1张卡返回卡组。自己场上有表侧表示的通常怪兽（等级7以上）的场合，可以再选对手场上的1只攻击表示怪兽变为表侧守备表示', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP014', '救援宇航员', '【条件】对手场上有怪兽，自己场上的表侧表示的通常怪兽为2只的场合可以发动。
【效果】选自己墓地的1只通常怪兽加入手牌。这个回合，自己不能用效果怪兽（等级8以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP015', '臭氧层人', '【条件】可以将1张手牌送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（银河族）。这个回合，那只怪兽不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP016', '碟状幼体穿越侍', '【条件】对手场上有怪兽的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示的「碟状幼体穿越侍」，其攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP017', '卫星天马', '【条件】这张卡召唤的回合可以发动。
【效果】将自己卡组最上面的卡送入墓地。那之后，自己墓地的怪兽为1只以下的场合，可以选对手场上的1只表侧表示怪兽（等级8以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP018', '伟大宇宙帝王', '【条件】可以将1张手牌送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP019', '接合科技霸王龙', '【条件】这张卡召唤的回合，可以使自己墓地的3只怪兽返回卡组发动。
【效果】选对手的魔法陷阱区的1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP020', '羊界 母羊植妖', '【条件】自己场上有表侧表示的通常怪兽（兽族）的场合可以发动。
【效果】选自己墓地的1张「肉与贪欲见面会」或者「羊界-墓地积怨念」盖放到自己的魔法陷阱区。自己场上有表侧表示的「魔法羊女 咩～歌小妹」的场合，可以再使自己恢复600LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP021', '言语妖精', '【条件】这张卡召唤的回合，对手场上有怪兽的场合，可以使自己墓地的3只怪兽返回卡组发动。
【效果】选对手墓地的3只怪兽返回卡组。自己场上的表侧表示怪兽（等级1以外/魔法师族）为2只的场合，可以再选对手墓地的3只怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP022', '旗鱼尖兵 卡朱', '【条件】这张卡召唤的回合可以发动。
【效果】选自己墓地的1张「海豚反击」或者「伊鲁夸的激浪」在自己的魔法与陷阱区域盖放。那之后，可以选自己手牌或者自己墓地1只「海豚王 伊鲁夸」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP023', '公主瓢虫 白', '【条件】可以变更这张卡的表示形式发动（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。
【效果】将手牌的2只怪兽（等级4以下/昆虫族）以表侧表示特殊召唤到自己的场上。那之后，给予对手700伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP024', '大口大口鼠', '【条件】自己场上没有这张卡以外的怪兽的场合，可以使自己墓地的1只怪兽（兽族）返回卡组下面发动。
【效果】选自己墓地的1只通常怪兽（兽族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP025', '贸绩蚕 丝蛋白', '【条件】自己场上有这张卡以外的表侧表示怪兽（昆虫族）的场合，可以从卡组上面将2张卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽。这个回合，那只怪兽的种族变为昆虫族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP026', '治疗壁虎', '【条件】可以使自己墓地的2只怪兽（爬虫类族）返回卡组发动。
【效果】自己恢复500LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP027', '疾速大地运输车', '【条件】对手场上的怪兽为3只的场合，可以使自己墓地的3只怪兽（地属性/机械族）返回卡组发动。
【效果】将手牌的1只怪兽（地属性/机械族）以表侧表示特殊召唤到自己的场上。这个回合，自己不能用怪兽（等级6以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP028', '龙蛾幼虫', '【条件】可以将手牌的1只怪兽（昆虫族）送入墓地发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP029', '阴阳士 刺突', '【条件】自己场上的表侧表示怪兽只有怪兽（战士族）的场合，可以使1张手牌返回卡组下面发动。
【效果】选自己墓地的1只怪兽（战士族/攻击力1000/守备力1000）以表侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP030', '生化机械螳螂', '【条件】可以使自己墓地的1只怪兽（昆虫族）返回卡组发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降300。那之后，可以使那只怪兽的种族直到回合结束时变为昆虫族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP031', '粉碎无人机', '【条件】自己场上有这张卡以外的表侧表示怪兽（地属性/机械族）的场合，可以从卡组上面将2张卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP032', '狂食虫 母螳螂', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（昆虫族），其攻击力、守备力直到回合结束时下降800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP033', '超可爱执行者 菲儿米', '【条件】自己场上有表侧表示的通常怪兽的场合，可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP034', '潜地龙虫 迪古拉', '【条件】无
【效果】从自己卡组上面将2张卡送入墓地。那之中有怪兽（昆虫族）的场合，再使这张卡的攻击力直到回合结束时上升[被这个效果送入墓地的怪兽的数量]×400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP035', '大地三头犬', '【条件】无
【效果】给予对手[自己场上的表侧表示怪兽（地属性/机械族）的数量]×300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP036', '翅甲王 君主独角仙大锹', '【条件】可以使自己墓地的3只怪兽返回卡组发动。
【效果】选对手场上的1只表侧表示怪兽（等级5～8/昆虫族）破坏。这个回合，自己不能用怪兽（昆虫族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP037', '魔导龙骑士-七道基亚斯', '「七道魔导士」+「连击龙 德拉基亚斯」
【条件】对手场上有表侧表示怪兽（等级7以上）的场合，可以将卡组最上面的卡送入墓地发动。
【选择效果】●这个回合，这张卡的攻击力上升[自己墓地的怪兽的种族的种类]×700，并且可以对怪兽作2次攻击。●将双方场上的表侧表示的卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP038', '幻刃栋龙 手工具龙', '「幻刃战士 铲子龙」+「幻刃妖精 镐头龙」
【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升200。自己场上没有表侧表示的场地魔法卡的场合，可以再选自己墓地的1张「透幻乡的险峻」或者「透幻乡的银岭」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP039', '花牙乱心 名花·异邦兰爱之眼', '「花牙女忍 异邦兰」+「花牙女忍 异邦兰」
【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的最多2只表侧表示怪兽，其攻击力、守备力直到回合结束时下降73万。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP040', '帚之英雄', '「当方英雄」+「一年之帚」
【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力、守备力直到回合结束时上升[自己场上的表侧表示怪兽（地属性）的数量]×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP041', '木刀之侍', '「传说的侍将 正树」＋「百年的古木刀」
【条件】这张卡特殊召唤的自己主要阶段可以发动。
【效果】选对手场上的1只表侧表示的通常怪兽破坏。用这个效果将怪兽破坏的场合，可以再选自己墓地的1张「交剑死哀」或者「迎突！」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP042', '浪涌流电龙骑士', '「浪涌电压蜥蜴」＋「浪涌电压蜥蜴」
【条件】对手场上有表侧表示怪兽的场合可以发动。
【效果】选自己墓地的1张「放电」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP043', '流星突击', '【条件】无
【效果】选自己场上的1只表侧表示怪兽（银河族）。这个回合，那只怪兽的攻击会贯通。选的怪兽是通常怪兽的场合，可以再选对手场上的1只怪兽变更表示形式（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP044', '肉与贪欲见面会', '【条件】可以将2张手牌送入墓地发动。
【效果】选自己场上的1只表侧表示的通常怪兽（兽族）。这个回合，那只怪兽可以对怪兽作3次攻击。自己场上有表侧表示的「魔法羊女 咩～歌小妹」的场合，可以再使对手场上的全部表侧表示的效果怪兽的攻击力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP045', '未来采掘', '【条件】对手场上有2只以上的表侧表示怪兽的场合可以发动。
【效果】从自己卡组上面将2张卡翻开，双方确认。自己可以从翻开的卡之中选1只怪兽加入手牌。剩下的卡按照喜欢的顺序返回卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP046', '秘剑！流丽割击', '【条件】对手场上有魔法陷阱卡的场合，可以使自己墓地的1只怪兽（等级8/战士族）返回卡组发动。
【效果】选自己场上的1只表侧表示怪兽（攻击力2500以上/守备力2500以上），其攻击力直到回合结束时上升2500。那之后，选对手场上的1张魔法陷阱卡破坏。这个回合，自己只能用1只怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP047', '守破离剑', '【条件】自己场上有表侧表示的通常怪兽（地属性）的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽（守备力2000以上）破坏。自己恢复800LP，给予对手800伤害。这个回合，自己不能用效果怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP048', '先兆', '【条件】可以将手牌的1只怪兽（地属性）送入墓地发动。
【效果】自己抽1张。自己场上有2只以上的表侧表示的通常怪兽（地属性）的场合，可以再使自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP049', '天道大人之森', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧守备表示怪兽（昆虫族）就不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP050', '昆虫狂暴', '【条件】可以使自己墓地的2只怪兽返回卡组发动。
【效果】自己场上的全部表侧表示怪兽（昆虫族）的攻击力直到回合结束时上升300。对手场上有表侧表示怪兽（昆虫族）的场合，可以再选对手场上的1只表侧表示怪兽（等级8以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP051', '侵入甲虫', '【条件】双方场上的表侧表示怪兽（昆虫族）合计为2只以上的场合，可以将1张手牌送入墓地发动。
【效果】自己抽1张。那之后，可以选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP053', '幽灵旋风', '【条件】自己场上没有怪兽的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。自己墓地的怪兽为3只以下的场合，可以再使自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP054', '奇异壁', '【条件】自己墓地有怪兽（银河族）的场合，对手怪兽的攻击宣言时可以发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP055', '羊界-墓地积怨念', '【条件】自己的攻击表示的通常怪兽（兽族）受到攻击的对手怪兽的攻击宣言时，可以从卡组上面将4张卡送入墓地发动。
【效果】受到攻击的怪兽的攻击力直到回合结束时下降2000。那之后，自己可以选这个效果的条件送入墓地的最多4张卡加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP056', '吉兆之面', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】选自己场上的1只表侧表示怪兽（战士族），其攻击力直到回合结束时上升[选的怪兽的等级]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP057', '手札增刷', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】自己抽卡直到手牌变为5张，自己的手牌全部向对手展示。那之中有怪兽的场合，再使自己恢复[那些怪兽的数量]×200LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP058', '安全漏洞', '【条件】自己场上有表侧表示怪兽（等级7以上/电子界族）的场合，对手怪兽（等级8以下）的攻击宣言时可以发动。
【效果】使攻击过来的怪兽返回持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP059', '破龙的咆钢', '【条件】自己场上有表侧表示的通常怪兽（等级7以上）的场合，对手召唤怪兽（等级7以上）时可以发动。
【效果】将那只召唤的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP060', '交剑死哀', '【条件】自己的怪兽（地属性）被对手怪兽的攻击破坏时可以发动。
【效果】给予对手[自己墓地的通常怪兽（地属性）的数量]×100伤害。用这个效果给予对手伤害的场合，可以再选对手场上的1只表侧表示的通常怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP061', '迎突！', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】选对手场上的1只表侧表示怪兽，给予对手[选的怪兽的等级]×100伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP062', '防虫蚁网', '【条件】对手怪兽（等级8以下）的攻击宣言时，可以使自己墓地的2只怪兽（昆虫族）返回卡组发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降800。自己或者对手场上有表侧守备表示怪兽（昆虫族）的场合，可以再将攻击过来的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP063', '颠倒无视', '【条件】对手召唤或特殊召唤怪兽时可以发动。
【效果】选自己场上的最多3只攻击表示怪兽（昆虫族）变为表侧守备表示。那之后，自己场上有2只以上的表侧守备表示怪兽的场合，可以选对手场上的1只攻击表示怪兽变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP064', '草莓狩猎', '【条件】自己场上的魔法陷阱卡被对手的效果破坏时可以发动。
【效果】选对手场上的1只表侧表示怪兽（攻击力1500以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP065', '圣塔的危机', '【条件】对手召唤怪兽（等级7以上）时可以发动。
【效果】选对手场上的1只表侧表示的效果怪兽（等级8以下）变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP09-JP052', '可爱处决者联合！', '【条件】无
【效果】选自己场上的2只种族不同的表侧表示怪兽。这个回合，要将怪兽以攻击表示高等召唤的场合，选的怪兽可以作为2只的分量来解放。自己场上有表侧表示怪兽（等级6/守备力500）的场合，给予对手800伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP000', '深渊士兵', '【条件】可以将手牌的1只怪兽（水属性）送入墓地发动。
【效果】选自己或者对手场上的1张卡返回持有者的手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP001', '羊界 绵羊水妖', '羊界牧场的慢性子。不慌不忙地观望形势。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP002', '羊界 羔羊雷妖', '羊界牧场的有能者。同伴的举手投足都会让它双眼发光。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP003', '羊界 白羊气妖', '羊界牧场的浪子。身边的喧嚣也成耳边风。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP004', '兵主部', '河童的老大。攻击力意外地高。守备力低。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP005', '神力芭蕾裙瓦尔基莉', '不惜一切努力的天使芭蕾舞者。由于其坚强的心态，再严格的练习也决不会输。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP006', '邪犬铳击 枪猎犬', '对一切敌人使用水枪应战的邪犬。同伴对其也就一般般信赖。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP007', '邪犬拔刀 短刀斗牛犬', '用粗犷的声音吓唬对手的邪犬。威吓效果也就一般般。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP008', '邪犬斗打 拳环甲斐犬', '充满干劲容易乱来的新秀邪犬。握力也就一般般。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP009', '邪犬铳击 手枪松狮犬', '虽然平时不发威但一生气就很恐怖的邪犬。干劲也就一般般。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP010', '邪犬极刀 大刀斑点犬', '统领一群也就一般般的部下的极致邪犬。锋锐程度令人汪分惊奇。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP011', '三宫金G机器人3改', '五号电池是动力源。边散步边看视频是每日惯例。既没干活也没学习。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP012', '33区外星人', '擅长宇宙船的设计与维修的专业人员。正在参加某个设施实行的疯狂计划。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP013', '曲速婆婆三姐妹', '以独特的姿势进行曲速移动的三姐妹。兴趣是和宇宙船并排跑来吓唬驾驶员。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP014', '白色矮星人 三日耳曼', '据传活了300年以上的伯爵。刚理完发无法发射光线攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP015', '鱼石螈守卫', '以惊人坚韧著称的鱼石螈战士。因为穿着又重又硬的铠甲，所以行动缓慢。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP016', '猫女郎', '用敏捷的动作躲避攻击，用锋利的钩爪袭击对手。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP017', '碧牙爆速龙', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】将对手场上的表侧表示怪兽（攻击力1500以下）全部破坏。那之后，这张卡的攻击力直到回合结束时上升[用这个效果破坏的怪兽的数量]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP018', '火葬犬 硝化甘油犬', '【条件】这张卡召唤的回合可以发动。
【效果】给予对手400伤害。这个回合，自己不能用怪兽（炎族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP019', '精力炸药人', '【条件】这张卡召唤的回合可以发动。
【效果】给予对手300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP020', '化学化火精灵', '【条件】可以使自己墓地的3只怪兽（炎族）返回卡组发动。
【效果】对手场上的全部表侧表示怪兽的攻击力直到回合结束时下降[对手墓地的怪兽的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP021', '伞降蘑菇菌落', '【条件】自己场上有表侧表示怪兽（等级7以上/银河族）的场合可以发动。
【效果】选自己墓地的1只「伞降蘑菇菌落」以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP022', '射线暴伽马枪手', '【条件】可以向对手展示手牌的1只怪兽（等级7以上/银河族）发动。
【效果】给予对手[对手场上的表侧表示怪兽的数量]×200伤害。那之后，可以选对手场上的1只表侧表示怪兽使其属性直到回合结束时变为光属性。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP023', '星象迹线枪兵', '【条件】可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】将手牌的1只怪兽（银河族）以表侧表示特殊召唤到自己的场上。用这个效果将怪兽（等级8）特殊召唤的场合，再在这个回合使那只怪兽的攻击力上升400，其攻击会贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP024', '紫外线女郎', '【条件】无
【永续效果】双方不能从墓地特殊召唤怪兽（等级7）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP025', '虚空噬骸兵 镇魂鹰巨人', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[自己场上的表侧表示怪兽（暗属性）的数量]×300。对手场上有表侧表示怪兽（光属性）的场合，再使这张卡的攻击力直到回合结束时上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP026', '羊界 家羊浪妖', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】自己恢复200LP。自己墓地的通常怪兽（兽族）的属性为3种类以上的场合，可以再选自己墓地的1只「魔法羊女 咩～歌小妹」以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP027', '地狱河童 湿身减重者', '【条件】这张卡召唤的回合可以发动。
【效果】选最多为[对手墓地的魔法卡的数量]的对手墓地的通常怪兽（等级7）返回卡组。那之后，可以选自己墓地的1只「河童大帝 滑河骑手」以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP028', '河童大帝 滑河骑手', '【条件】可以将自己场上的1只表侧表示怪兽（水族）送入墓地发动。
【效果】选对手场上的最多2只表侧表示的通常怪兽（等级7以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP029', '俏皮女邪神 努维亚', '【条件】自己场上的表侧表示怪兽（水族）为3只的场合，可以将卡组最上面的卡送入墓地发动。
【效果】自己场上的全部表侧表示怪兽（水族）的攻击力直到回合结束时上升200。那之后，可以选自己墓地的1张「雨中大都市带」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP030', '治疗之神童 迪安·凯特', '【条件】自己场上有表侧表示的场地魔法卡的场合可以发动。
【效果】自己抽1张，双方确认。那张卡是场地魔法卡的场合，自己再恢复1000LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP031', '邪犬雷帝 因陀罗野犬', '【条件】无
【效果】从自己卡组上面将2张卡送入墓地。是在这张卡召唤或特殊召唤的自己的主要阶段发动这个效果的场合，可以再选自己墓地的1只通常怪兽（等级6以下/兽战士族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP032', '邪犬武斗神 湿婆柴犬', '【条件】这张卡召唤或特殊召唤的自己的主要阶段可以发动。
【效果】选自己墓地的1只怪兽（等级5～7/兽战士族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP033', '兽机界贤者 轮滑鞋雄鹿', '【条件】这张卡召唤或特殊召唤的自己的主要阶段，可以支付700LP发动。
【效果】选对手场上的1只攻击表示怪兽变为表侧守备表示。那之后，可以选自己墓地的1张「世纪末兽机界」或者「兽机界奥义 兽之拳」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP034', '草莓新人 小幸', '【条件】可以将手牌的1只怪兽（水族）送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升1500。这个效果的条件将怪兽（攻击力100以下）送入墓地的场合，可以再选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP035', '梦中蝴蝶', '【条件】可以使攻击表示的这张卡变为表侧守备表示发动。
【效果】选对手场上的1只表侧表示怪兽。这个回合，那只怪兽的种族变为昆虫族。自己或者对手场上有这张卡以外的表侧守备表示怪兽的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP036', '劈裂史莱姆', '【条件】可以将自己场上的1只表侧表示怪兽（攻击力1500以上）送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降1000。那之后，可以选自己墓地的1只效果怪兽（等级4/攻击力1500以上）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP037', '阴阳士 右薙', '【条件】自己场上有这张卡以外的表侧表示怪兽（攻击力1000/守备力1000）的场合，可以使1张手牌返回卡组下面发动。
【效果】选自己墓地的1只怪兽（等级8/攻击力2500）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP038', '水稻梯田驱除者', '【条件】这张卡召唤的回合可以发动。
【效果】从自己卡组上面将2张卡送入墓地。对手的魔法陷阱区有卡的场合，可以再选对手场上1只表侧表示的通常怪兽变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP039', '尖头狩猎 掘地鼹鼠', '【条件】自己墓地有10只以上的怪兽的场合，可以使自己墓地的3只怪兽（兽战士族）返回卡组发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP040', '雷霆瞪羚', '【条件】对手的手牌为0张的场合，可以使自己墓地的2只怪兽返回卡组发动。
【效果】选自己场上的1只表侧表示怪兽。这个回合，那只怪兽的攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP041', '投人的巨魔', '【条件】可以将自己场上的1只表侧表示的通常怪兽送入墓地发动。
【效果】给予对手800伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP042', '狂暴牛鬼', '【条件】无
【效果】进行1次抛硬币。是正面的场合，给予对手1000伤害。是反面的场合，自己受到1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP043', 'A魔熊花莉莉丝', '「业余花莉莉丝」＋「AI可能甜甜熊」
【条件】无
【效果】选对手场上的1只怪兽返回持有者的手牌。那之后，对手可以将自身手牌的1只怪兽以表侧攻击表示特殊召唤到自身的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP044', '华丽巡场大师', '「惊异荷官」＋「惊异荷官」
【条件】可以支付600LP发动。
【效果】进行1次抛硬币。是正面的场合，自己抽2张。是反面的场合，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP045', '交食', '【条件】无
【效果】选自己场上的1只表侧表示怪兽，选拥有与那只怪兽相同的等级的对手场上的1只表侧表示怪兽。将选的2只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP046', '意乱情迷咩～歌☆羊～毛超级光线', '【条件】自己场上有表侧表示的「魔法羊女 咩～歌小妹」的场合，可以将手牌的2只通常怪兽（兽族）送入墓地发动。
【效果】将对手场上的表侧表示怪兽（等级8以下）全部破坏。这个回合，自己不能用怪兽（兽族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP047', '如若被雨拍打', '【条件】自己或者对手场上有表侧表示的场地魔法卡的场合可以发动。
【效果】对手场上的全部表侧表示的通常怪兽的攻击力直到回合结束时下降[对手场上的怪兽的数量]×300。那之后，可以选对手的魔法陷阱区的1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP048', '雨中大都市带', '【条件】这张卡在自己场上有2只以上的表侧表示怪兽（水族）的场合可以发动。
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（水族）的攻击力就上升200，双方场上的表侧表示怪兽（水族以外）的攻击力就下降200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP049', '泡沫王国', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示的通常怪兽（水族）的攻击力就上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP050', '汪分惊奇邪犬', '【条件】自己场上有2只以上的表侧表示怪兽（兽战士族）的场合可以发动。
【效果】从自己卡组上面将4张卡送入墓地。这个效果使4只怪兽（兽战士族）被送入墓地的场合，可以再选自己场上的1只表侧表示怪兽使其攻击力直到回合结束时上升1200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP051', '300光年红斗篷', '【条件】自己场上的表侧表示怪兽（爬虫类族）为3只的场合可以发动。
【效果】自己场上的全部表侧表示怪兽（爬虫类族）的攻击力直到回合结束时上升300。自己的LP比对手少3000以上的场合，可以再选对手场上的1只表侧表示的通常怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP052', '伯蜴参上', '【条件】可以使自己墓地的3只通常怪兽（等级3以下/爬虫类族）返回卡组发动。
【效果】选自己墓地的1只怪兽（爬虫类族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP053', '33区', '【条件】这张卡在自己场上有2只以上的表侧表示的通常怪兽（等级3以下/爬虫类族）的场合可以发动。
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示的通常怪兽（爬虫类族）的攻击力就上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP054', '海豚的宝箱', '【条件】可以将手牌的1只怪兽（水属性）送入墓地发动。
【效果】自己抽1张。对手场上有表侧表示怪兽（等级7）的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP055', '神秘之海', '【条件】无
【效果】将手牌的最多3只怪兽（等级4以下/水属性）以表侧表示特殊召唤到自己的场上。那之后，自己场上的表侧表示怪兽（水属性）为3只的场合，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP056', '八岐剑', '【条件】可以使自己墓地的1只怪兽（等级8）返回卡组发动。
【效果】自己抽1张。那之后，可以选自己场上的1只表侧表示怪兽（等级8）使其攻击力直到回合结束时上升800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP057', '妖虎东洋击', '【条件】可以使自己墓地的2只怪兽返回卡组发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下），其攻击力直到回合结束时下降[对手墓地的魔法陷阱卡的数量]×300。对手墓地的魔法卡的数量为5张以上的场合，可以再选对手场上的1只表侧表示怪兽（守备力1600以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP058', '强力震慑', '【条件】对手发动魔法卡后可以发动。
【效果】选自己场上的1只表侧表示怪兽，其攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP059', '分组筒', '【条件】自己的攻击表示怪兽（光属性）受到攻击的对手怪兽的攻击宣言时可以发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降[攻击过来的怪兽的等级]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP060', '河童放河冲走', '【条件】对手怪兽的攻击宣言时，可以使自己墓地的2只怪兽（水族）返回卡组发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降800。那之后，可以选对手场上的1只表侧表示的通常怪兽使其攻击力直到回合结束时下降800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP061', '河童晒甲壳', '【条件】对手以表侧表示召唤或特殊召唤怪兽（等级5以上）时可以发动。
【效果】选自己墓地的1只通常怪兽（等级4以下/水族）以里侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP062', '屁之河童', '【条件】自己的里侧表示怪兽受到攻击的对手怪兽的攻击宣言时可以发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP063', '月光3大不可思议', '【条件】自己场上有表侧表示的通常怪兽（等级3以下/爬虫类族）的场合，对手怪兽的攻击宣言时可以发动。
【效果】选自己场上的1只表侧表示怪兽（爬虫类族），其攻击力直到回合结束时上升[自己场上的表侧表示怪兽（爬虫类族）的数量]×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP064', '落盖', '【条件】对手从墓地将怪兽以表侧表示特殊召唤时可以发动。
【效果】选对手场上的最多2只表侧表示怪兽（等级8以下）变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP10-JP065', '助推救援', '【条件】对手将怪兽以表侧表示召唤或特殊召唤时可以发动。
【效果】自己抽2张。那之后，自己选1张手牌送入墓地。并且，可以再选自己场上最多2只的攻击表示怪兽变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP001', '超魔机神 超大王道王[L]', '【条件】极限模式：自己的LP比对手少的场合，可以将1张手牌送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[双方LP的差值]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP002', '超魔机神 超大王道王', '和「超魔机神 超大王道王[L]」「超魔机神 超大王道王[R]」集齐可以极限召唤。
【条件】极限模式
【永续效果】这张卡不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP003', '超魔机神 超大王道王[R]', '【条件】极限模式：可以将卡组最上面的卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，这张卡的攻击力直到回合结束时上升[选的怪兽的等级]×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP004', '机器栗子', '【条件】自己场上没有这张卡以外的怪兽的场合，可以支付500LP发动。
【效果】选自己墓地的1只「机器栗子」加入手牌。
', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP005', '三重机器栗子', '【条件】可以使自己墓地的3只「机器栗子」返回卡组发动。
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP006', '沉默学习', '【条件】自己墓地的怪兽（等级5以上）的种族为3种类以上的场合可以发动。
【效果】选对手的魔法与陷阱区的1张里侧表示的卡确认。那张卡是陷阱卡的场合，选自己墓地的1只怪兽（等级5以上）返回卡组下面，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP007', '干劲10足最大级!!!', '【条件】可以将手牌的1只怪兽送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽。这个回合，那只怪兽的攻击力上升400，其攻击会贯通。那只怪兽是等级10的场合，给予对手1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP008', '魔力四震击', '【条件】对手将怪兽（攻击力1500以上）以表侧表示特殊召唤时，可以使自己墓地的4只通常怪兽返回卡组发动。
【效果】选对手场上的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP009', '传开的耳语', '【条件】对手从手牌盖放怪兽时可以发动。
【效果】选双方墓地的合计最多5只怪兽返回持有者的卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP010', '天帝龙树 世界树龙[L]', '【条件】极限模式：可以从卡组上面将3张卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP011', '天帝龙树 世界树龙', '和「天帝龙树 世界树龙[L]」「天帝龙树 世界树龙[R]」集齐可以极限召唤。
【条件】极限模式
【永续效果】这张卡不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP012', '天帝龙树 世界树龙[R]', '【条件】极限模式：可以从卡组上面将3张卡送入墓地发动。
【效果】选对手场上的1只守备表示怪兽变为表侧攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP013', '皮米孔雀高等粒子机', '【条件】自己场上没有这张卡以外的怪兽，自己墓地有「飞米粒子机」的场合可以发动。
【效果】将自己场上的这张卡送入墓地，自己抽2张。那之后，从自己卡组上面将2张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP014', '飞米粒子机', '隐藏着万物摄理的龙树之源。朝着极微极大逼近，引导世界前往新领域。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP015', '阿米粒子机', '【条件】自己场上没有这张卡以外的怪兽，自己墓地有「飞米粒子机」的场合可以发动。
【效果】将自己场上的这张卡送入墓地，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP016', '仄米粒子机', '【条件】自己场上没有这张卡以外的怪兽，自己墓地有「飞米粒子机」和「阿米粒子机」的场合可以发动。
【效果】将自己场上的这张卡送入墓地，自己抽2张。那之后，自己选2张手牌按照喜欢的顺序返回卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP017', '幺米粒子机', '【条件】自己的墓地有「飞米粒子机」和「阿米粒子机」和「仄米粒子机」的场合，可以使那3只按照喜欢的顺序返回卡组下面发动。
【效果】将自己场上的这张卡送入墓地，自己抽3张。那之后，自己选3张手牌送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP018', '对生成', '【条件】可以将等级相同的手牌的2只怪兽（等级5以下/电子空间族）送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽，其攻击力直到回合结束时上升[被这个效果的条件送入墓地的1只怪兽的等级]×400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP019', '落穴', '【条件】对手召唤怪兽（攻击力1000以上）时可以发动。
【效果】将那只怪兽破坏。 ​​​', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP020', '量子洞', '【条件】自己的怪兽（电子界族）被对手怪兽的攻击破坏时可以发动。
【效果】自己抽2张。那之后，自己选2张手牌按照喜欢的顺序返回卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP021', '清洁贝雷帽 拖把大佐', '【条件】对手场上有表侧表示怪兽（等级7以上）的场合可以发动。
【效果】选自己墓地的1张「白激泡-漂白剂迫击炮」返回卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP022', '洗净的圣诞抹布老人', '【条件】这张卡召唤或特殊召唤的自己的主要阶段可以发动。
【效果】对手抽[自身场上的怪兽的数量]。那之后，自己恢复[因这个效果对手抽的数量]×300LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP023', '洗铳士 洗涤射手', '【条件】这张卡召唤的回合，对手场上有表侧表示怪兽（等级7以上）的场合可以发动。
【效果】选自己墓地的1张「白激泡-漂白剂迫击炮」返回卡组。那之后，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP024', '白激泡-漂白剂迫击炮', '【条件】无
【效果】选对手场上的1只表侧表示怪兽（等级7以上），其攻击力直到回合结束时下降500。给予对手500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP025', '异色眼双尾猫', '【条件】自己场上有表侧表示的「真红眼黑猫」和「蓝眼白猫」的场合可以发动。
【效果】选自己墓地的1张「迷途猫」加入手牌。
', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP026', '真红眼黑猫', '拥有红色眼睛的黑猫。似乎会为与它扯上关系的人带来灾祸或者不幸。
', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP027', '蓝眼白猫', '拥有蓝色眼睛的白猫。似乎好好对待它的话就会带来幸福。
', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP028', '猫之眼', '【条件】自己场上的表侧表示怪兽（兽族）为3只的场合可以发动。
【效果】对手宣言卡的种类（怪兽·魔法·陷阱），将自身卡组最上面的卡送入墓地。那张卡不是宣言的种类的卡的场合，自己场上的全部表侧表示怪兽在这个回合可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP029', '迷途猫', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】对手宣言卡的种类（怪兽·魔法·陷阱），将自身卡组最上面的卡送入墓地。那张卡不是宣言的种类的卡的场合，那次攻击无效，给予对手300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP030', '雷电节拍甲虫 架子鼓', '温柔值得信赖，在背后为大家付出了很多。
相信一定能与可以共鸣的伙伴邂逅，今天也在鸣叫发声。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP031', '雷电节拍甲虫 踩镲', '性格很多面的老大哥。
相信一定能与可以共鸣的伙伴邂逅，今天也在鸣叫发声。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP032', '节拍甲虫 响弦鼓', '个性独特且一直都很受欢迎。
相信一定能与可以共鸣的伙伴邂逅，今天也在鸣叫发声。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP033', '雷电节拍甲虫的赠礼', '【条件】自己场上有表侧表示怪兽（等级4以下/雷族）的场合可以发动。
【效果】给予对手[自己场上的表侧表示怪兽（雷族）的数量]×500伤害。这个回合，自己不能用怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP034', '呼风唤雨的雷电节拍甲虫', '【条件】自己场上的表侧表示怪兽（等级4以下/雷族）为3只的场合可以发动。
【效果】将对手场上的表侧表示的效果怪兽（等级8以下）全部破坏。用这个效果将怪兽破坏的场合，直到回合结束时自己不能召唤或特殊召唤怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP035', '雷电节拍甲虫增益', '【条件】自己场上有表侧表示怪兽（雷族）的场合，拥有比自己的LP高的攻击力的对手怪兽（等级8以下）的攻击宣言时可以发动。
【效果】选对手场上的1只表侧表示怪兽，自己的LP恢复[选的怪兽的攻击力]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP036', '暗黑之玉座', '【条件】自己墓地有8只以上的怪兽（攻击力0）的场合可以发动。
【效果】将手牌的1只怪兽（等级7以上/攻击力0）以攻击表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP037', '伊苏椅之冥王 达尤', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选这张卡以外的自己场上的1只表侧表示怪兽（攻击力0），这张卡的攻击力直到回合结束时上升[选的怪兽的等级]×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP038', '宿灵椅 齿轮式', '大量生产的简单机械椅子。失去了过去的活体椅子拥有的坐感。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP039', '宿灵椅 骨式', '据说是家具职人一族过去制作的活体椅子的原点。坐感很古怪。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP040', '宿灵椅 利剑式', '家具职人一族最为繁荣的时代制作的活体椅子杰作。坐感十分舒服。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP041', '倒塌的椅子', '【条件】自己场上的攻击表示怪兽（暗属性/攻击力0）被对手怪兽的攻击破坏时可以发动。
【效果】将双方场上的攻击表示怪兽（等级8以下）全部破坏。那之后，从双方的卡组上面按照[被这个效果破坏的怪兽的数量]将卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP042', '宇宙弦之面条女德鲁伊', '【条件】自己或者对手场上有表侧表示的「宇宙」的场合，可以将手牌的2只怪兽（炎族）送入墓地发动。
【效果】将双方场上的表侧表示怪兽（等级7以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP043', '银河之鱼板矮子精', '【条件】自己或者对手场上有表侧表示的「宇宙」的场合，可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP044', '银河白发葱', '在天河自由漂流的少女。她的身姿仿若流星一般。看到她出现就会对其许愿的人络绎不绝，但她都会用辛辣的语句回复他们自己的梦想就该自己努力实现。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP045', '大爆炸蛋人', '先有蛋还是先有宇宙。拥有爆发性思维的人物。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP046', '宇宙', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（等级4以下）的攻击力、守备力就下降300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP047', '叉烧流星', '【条件】对手以表侧表示召唤或特殊召唤怪兽（等级5以上）时可以发动。
【效果】选自己场上的1只表侧表示怪兽（炎族），自己恢复[选的怪兽的等级]×200LP。那之后，选的怪兽返回持有者的手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP048', '手牌抹杀', '【条件】无
【效果】有手牌的玩家将手牌全部送入墓地。那之后，双方抽[用这个效果自身送入墓地的卡的数量]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP049', '收缩虾', '【条件】可以将自己场上最多2只表侧表示怪兽（电子空间族）送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降[被这个效果的条件送入墓地的怪兽的数量]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX1-JP050', '天之加护', '【条件】无
【效果】选喜欢的数量的手牌的怪兽送入墓地。[被这个效果送入墓地的怪兽的等级合计]是10以上的场合，自己可以抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP001', '超魔旗舰 超大王道王[L]', '【条件】极限模式：可以使自己墓地的1只怪兽返回卡组发动。
【效果】选自己墓地的1只怪兽，给予对手[选的怪兽的等级]×100伤害。用这个效果给予对手伤害的场合，可以再将那只怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP002', '超魔旗舰 超大王道王', '和「超魔旗舰 超大王道王[L]」「超魔旗舰 超大王道王[R]」集齐可以极限召唤。
【条件】极限模式：可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】将手牌的最多2只怪兽以表侧表示特殊召唤到自己的场上。那之后，可以选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP003', '超魔旗舰 超大王道王[R]', '【条件】极限模式：可以从卡组上面将2张卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时下降1000。这个回合，这张卡不能直接攻击，可以对对手怪兽全部各作1次攻击，那些攻击会贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP004', '紧急归还', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】选自己场上的1只表侧表示怪兽（等级5以上）返回持有者的手牌。用这个效果使怪兽返回手牌的场合，使那次攻击无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP005', '大恐龙驾 联力恐龙车[L]', '【条件】极限模式
【永续效果】这张卡不会被与怪兽（等级7以下）所作的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP006', '大恐龙驾 联力恐龙车', '和「大恐龙驾 联力恐龙车[L]」「大恐龙驾 联力恐龙车[R]」集齐可以极限召唤。
【条件】极限模式：对手场上没有表侧表示怪兽（等级9以上）的场合，可以将手牌的1只怪兽送入墓地发动。
【效果】选对手场上的最多2只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP007', '大恐龙驾 联力恐龙车[R]', '【条件】极限模式
【永续效果】这张卡不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP008', '大喷嚏守财奴河马龙', '【条件】自己的LP比对手少的场合，可以使1张手牌返回卡组下面发动。
【效果】从双方卡组上面各将2张卡送入墓地。用这个效果将怪兽送入墓地的场合，再给予对手[被这个效果送入墓地的怪兽的数量]×400伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP009', '机械镰刀盗龙', '【条件】可以将手牌的1只怪兽（恐龙族）送入墓地发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP010', '成金恐龙王', '【条件】对手的手牌为0张的场合可以发动。
【效果】双方抽1张。用这个效果双方都有抽卡的场合，自己可以再选自己墓地的1张「成金哥布林」盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP011', '抑龙 严峻翼龙', '【条件】无
【效果】可以将自己卡组最上面的卡送入墓地。那之后，可以随机选1张对手的手牌返回卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP012', '野性盗龙', '善于奔跑的恐龙。用锐利的牙齿和爪攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP013', '名流雷龙', '名字小改之后获得爆运的暴发户恐龙。以前住在洞穴里。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP014', '白金小翼龙', '很喜欢收集闪亮东西的无齿翼龙。最喜欢的是头上的壳。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP015', '侏罗纪世界', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（恐龙族）的攻击力、守备力就上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP016', '奇迹的共进化', '【条件】可以将自己场上的1只表侧表示怪兽（恐龙族）送入墓地发动。
【效果】将手牌的1只怪兽（等级5以上/恐龙族）以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤的怪兽的攻击力直到回合结束时上升[这个效果的条件送入墓地的怪兽的原等级]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP017', '恐龙粉碎', '【条件】自己场上有表侧表示怪兽（等级7以上/恐龙族）的场合，可以将1张手牌送入墓地发动。
【效果】选对手场上的1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP018', '成金哥布林', '【条件】无
【效果】自己抽1张。那之后，对手恢复1000LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP019', '超越进化', '【条件】对手召唤怪兽（等级7以上）时可以发动。
【效果】选自己场上的1只表侧表示怪兽（等级7以上/恐龙族）。这个回合，那只怪兽的攻击力上升1500，不会被对手的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP020', '恐力重压', '【条件】对手怪兽的攻击宣言时，可以使自己墓地的3只怪兽（恐龙族）返回卡组发动。
【效果】对手场上的全部表侧表示怪兽的攻击力直到回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP021', '种子同步粒子机 布鲁塞尔机', '【条件】这张卡召唤的回合可以发动。
【效果】将自己卡组最上面的卡送入墓地。用这个效果将怪兽（电子空间族）送入墓地的场合，可以再选最多为[对手场上的表侧表示怪兽数量]的自己墓地的怪兽（电子空间族/守备力0）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP022', '隐秘回旋粒子机', '寄宿着万物摄理的龙树之础。超越限度限界，前往新的境地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP023', '对死者的供奉', '【条件】可以将1张手牌送入墓地发动。
【效果】选自己或者对手场上的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP024', '伊苏椅的镜王 达尤·深渊', '【条件】可以使喜欢的数量的自己墓地的怪兽（攻击力0）返回卡组发动。
【效果】选这张卡以外的自己或者对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降[这个效果的条件返回卡组的怪兽的数量]×300。这张卡的攻击力直到回合结束时上升[这个效果的条件返回卡组的怪兽的数量]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP025', '宿灵椅 消酸痛式', '【条件】可以将手牌的1只怪兽（攻击力0）送入墓地发动。
【效果】从自己卡组上面将2张卡送入墓地。那之中有怪兽（等级8以下/暗属性）的场合，再选自己墓地的1只怪兽（等级8以下/暗属性）加入手牌。对手恢复[选的怪兽的攻击力]的LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP026', '宿灵椅 鳞甲式', '【条件】自己场上没有这张卡以外的怪兽的场合，使自己墓地的2只怪兽（攻击力0）按照喜欢的顺序返回卡组下面发动。
【效果】选自己墓地的1只怪兽（等级5以上/攻击力0）以表侧攻击表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP027', '暗冥椅子仪式', '【条件】自己墓地有怪兽（暗属性）的场合，可以将自己场上的3只表侧表示怪兽（暗属性）送入墓地发动。
【效果】选自己墓地的1只怪兽（暗属性）以表侧表示特殊召唤到自己的场上。那之后，自己墓地有3只卡名相同的怪兽（暗属性）的场合，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP028', '联合的椅子', '【条件】自己场上的表侧表示怪兽（攻击力0）为3只的场合，对手召唤怪兽时可以发动。
【效果】选自己场上最多2只怪兽变为表侧守备表示。这个回合，自己场上有守备表示怪兽的场合，对手怪兽只能攻击守备表示怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP029', '幻刃破龙 破碎龙兽', '用特殊工具来武装全身的幻刃龙。据说拥有无论怎样的大型工地都能一瞬间拆除的力量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP030', '透幻乡的银岭', '【条件】这张卡在对手场上有表侧表示怪兽（等级7以上）的场合才可以发动。
【效果】只要这张卡在场地区表侧表示，双方要以攻击表示高等召唤怪兽（等级7以上/幻龙族）的场合，需要的解放变为1只。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP031', '幻刃奥义-突陷攻事', '【条件】无
【效果】自己场上的全部表侧表示的通常怪兽（等级7以上/幻龙族）的攻击力直到回合结束时上升600。那之后，可以使对手场上的全部表侧表示怪兽（攻击力3000以上）的攻击力直到回合结束时下降1200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP032', '大槌粉碎', '【条件】可以将1张手牌送入墓地发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP033', '幻刃复归', '【条件】自己怪兽（等级7以上/幻龙族）被对手的攻击破坏时可以发动。
【效果】选自己墓地的1只怪兽（等级7以上/幻龙族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP034', '警乐姬 单簧管棍棒', '合奏武队的万事屋。悠扬的旋律为攻击增添厚重感。一旦兴奋头部就会发光。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP035', '弧乐姬 圆号鸳鸯钺', '【条件】这张卡召唤的回合可以发动。
【效果】将自己卡组最上面的卡送入墓地。用这个效果将怪兽（战士族）送入墓地的场合，可以再选自己墓地的1只通常怪兽（战士族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP036', '一气贯通', '【条件】可以使自己墓地的5只怪兽（风属性/战士族）返回卡组发动。
【效果】选自己场上的1只表侧表示怪兽（等级7或8）。这个回合，那只怪兽的攻击力上升2000，其攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。 ​​​​', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP037', '乐姬的倍急风', '【条件】自己场上有表侧表示怪兽（等级5以上/风属性/战士族）的场合可以发动。
【效果】选对手场上的最多2只攻击表示怪兽变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP038', '乐姬奥义-三连虎', '【条件】对手召唤或特殊召唤怪兽时，对手场上的怪兽为3只的场合可以发动。
【效果】自己场上的全部表侧表示怪兽（风属性/战士族）的攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP039', '极上寿司天使 热茶姜百列', '【条件】可以将手牌的1只怪兽（天使族）送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽，其攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP040', '寿司天使 龙卷', '【条件】这张卡召唤的回合，可以使自己墓地的1只怪兽（天使族）返回卡组下面发动。
【效果】自己抽1张。这个回合，自己不能用怪兽（等级6以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP041', '寿司天使 虎卷', '【条件】无
【效果】选自己墓地的最多2只怪兽（等级8以下/天使族）加入手牌。这个效果发动后，直到回合结束时自己不能将手牌的怪兽召唤、盖放或特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP042', '寿司天使 猴卷', '天上寿司界在座众神都追捧的寿司卷。以与生俱来的海苔附和力与独特甜味来席卷全部大米。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP043', '寿司天使 蜘蛛卷', '天上寿司界在座众神都追捧的寿司卷。以与生俱来的海苔附和力与独特芳香来席卷全部大米。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP044', '寿司反卷', '【条件】自己场上有表侧表示怪兽（等级5以上/天使族）的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降500。自己的LP比对手少2000以上的场合，再使其攻击力直到回合结束时下降1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP045', '天使裁决', '【条件】自己场上有表侧表示怪兽（天使族）的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡返回持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP046', '摇卷万黏不灭', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】选自己场上的1只攻击表示怪兽（天使族）。这个回合，那只怪兽不会被战斗破坏。再使对手的LP恢复[选的怪兽的攻击力]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP047', '卷辣箭', '【条件】对手召唤或特殊召唤怪兽时可以发动。
【效果】给予对手500伤害。自己场上有表侧表示怪兽（天使族）的场合，可以再将手牌的1只怪兽（天使族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP048', '成银哥布林', '【条件】可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】将手牌的1只怪兽（等级6以下）以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤的怪兽的攻击力直到回合结束时上升500。自己墓地有「成金哥布林」的场合，再给予对手500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP049', '天之启示', '【条件】无
【效果】选自己场上的喜欢的数量的怪兽送入墓地。[这个效果送入墓地的怪兽的原等级合计]为等级10以上的场合，可以再选自己墓地的1只怪兽（等级8以下）以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤的怪兽的攻击力直到回合结束时上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MAX2-JP050', '折回射击', '【条件】对手在抽卡阶段通常抽卡时可以发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下）返回持有者的手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD0-JP001', '千年盾', '据说是从古埃及王家传下来的传说之盾。传闻说再怎么强的攻击也能防住。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD0-JP002', '血腥魔兽人', '做尽坏事，并以此为乐的魔兽人。手中的斧子常常沾满鲜血。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD0-JP003', '神圣精灵', '虽然是个柔弱的精灵，但是有神圣的力量守护着，守备力相当高。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD0-JP004', '死者苏生', '【条件】无
【效果】选自己或者对手的墓地的1只怪兽以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD0-JP005', '炸裂装甲', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】将攻击过来的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD1-JP009', '加速魔杖手 飞溅斯普拉', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（魔法师族）。这个回合，那只怪兽的等级上升2，攻击力上升200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD1-JP010', '加速魔杖手 闪焰芙蕾雅', '【条件】可以使自己墓地的1只怪兽返回卡组发动。
【效果】给予对手400伤害。用这个效果给予对手伤害的场合，可以再选自己场上的1只表侧表示怪兽使其种族直到回合结束时变为魔法师族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD1-JP013', '水色术士', '保有清廉洁白之精神的魔术师。他那清澈的眼瞳被认为能看透一切事理，但从某时期起开始用假面将其隐藏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD1-JP019', '惊异荷官', '【条件】自己墓地的怪兽为3只以下的场合，可以支付300LP发动。
【效果】选自己的3张手牌送去墓地。那之后，自己抽3张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD1-JP032', '谜之手铐', '【条件】对手召唤怪兽时可以发动。
【效果】选对手场上的1只表侧表示怪兽。这个回合，选的怪兽表侧表示期间，对手不能为了作高等召唤而将选的怪兽解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD2-JP003', '龙队岩神终结者', '【条件】对手场上有攻击表示怪兽（等级9以下）的场合，可以支付3000LP发动。
【效果】这张卡的攻击力直到回合结束时上升2000。对手墓地有8只以上的怪兽的场合，再在这个回合使这张卡不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD2-JP012', '风精龙', '司掌风的四大精龙的幼体。自由自在地操控大气守护那片土地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD2-JP022', '『守备』封印', '【条件】无
【效果】选对手场上的1只守备表示怪兽变为表侧攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD2-JP023', '龙队联结', '【条件】无
【效果】选自己手牌或者自己墓地的1只通常怪兽（等级5或6/龙族）以表侧表示特殊召唤到自己的场上。那之后，自己场上有表侧表示的「龙队关键守门员」的场合，可以选自己墓地的1只「龙队射手」或者「龙队后卫」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD2-JP030', '龙力失调', '【条件】对手召唤怪兽（等级7以上）时，可以将手牌的1只通常怪兽（龙族）送入墓地发动。
【效果】那些怪兽变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD3-JP006', '魔将分队 待组', '【条件】这张卡召唤的回合，可以将手牌的1只怪兽（战士族）送入墓地发动。
【效果】从自己墓地的「魔将气流」「魔将决斗斩」「魔将方圆舞」之中选1张盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD3-JP015', '当方英雄', '据说是从遥远的东方国家而来的武士。手里的切面包刀非常锋利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD3-JP027', '鞠躬公会', '【条件】对手在抽卡阶段通常抽卡时，可以支付1000LP发动。
【效果】选自己场上的最多2只攻击表示怪兽变为表侧守备表示。那之后，自己场上的守备表示怪兽为3只的场合，可以选对手墓地的最多5只怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD3-JP030', '魔将方圆舞', '【条件】自己场上的攻击表示怪兽（等级7以上/战士族）被对手的攻击或者对手的陷阱卡的效果破坏时可以发动。
【效果】从自己墓地的「魔将 夜目流罗」「魔将 鬼目流罗」「魔将 濑目流罗」之中选1只以表侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD4-JP003', '天才吉他手', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[这张卡以外的自己场上的表侧表示怪兽（念动力族）的数量]×400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD4-JP009', '和平维持者', '守护城市和平的年轻搜查官。为解决某起失踪事件而奋斗。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD4-JP012', '梦幻鼓手', '【条件】可以使自己墓地的1只怪兽（念动力族）返回卡组发动。
【效果】选对手墓地的1只怪兽返回卡组。自己场上有表侧表示的通常怪兽的场合，自己可以再恢复500LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD4-JP026', '念力的落穴', '【条件】自己场上有2只以上的表侧表示怪兽（念动力族）的场合，对手召唤怪兽（等级5以上）时可以发动。
【效果】将那些召唤的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD5-JP002', '星战骑 阿斯波罗斯', '【条件】可以使自己场上的1只攻击表示怪兽（等级5以上/恶魔族）变为表侧守备表示发动。
【效果】选自己或者对手场上的1只表侧表示怪兽，其攻击力直到回合结束时上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD5-JP004', '永冥之猫头鹰随从', '【条件】这张卡召唤的回合可以发动。
【效果】选自己墓地的1只通常怪兽（等级3/恶魔族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD5-JP009', '星战骑 涅索斯', '让恶星之力寄宿于身的一人。拜了星战骑 厄开耳克洛斯为师。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD5-JP026', '王之权利', '【条件】对手在抽卡阶段通常抽卡时可以发动。
【效果】选自己墓地的2～3只等级不同的通常怪兽（恶魔族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD6-JP004', '系统屠龙者 苏尔', '【条件】对手场上有表侧表示怪兽（等级5以上）的场合，可以向对手展示手牌的最多2只怪兽（电子空间族）发动。
【效果】给予对手[这个效果的条件展示的怪兽的数量]×300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD6-JP005', '扇区狂战士 玛尼', '【条件】可以使自己墓地的2只怪兽返回卡组发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降[自己场上的表侧表示怪兽（电子空间族）的数量]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD6-JP009', '接口犬', '在网络世界运送情报的电子兽。经过世代交替得到品种改良，性格变得表里如一不分正反。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD6-JP015', '粒子加速', '【条件】自己场上有表侧表示怪兽（电子空间族）的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD7-JP010', '幻刃斗士 搅拌龙', '【条件】这张卡召唤的回合，自己或者对手场上有表侧表示的场地魔法卡的场合可以发动。
【效果】将自己卡组最上面的卡送入墓地。用这个效果将通常怪兽（幻龙族）送入墓地的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD7-JP011', '荒废之蟠龙', '【条件】可以使自己场上的表侧表示的场地魔法卡返回持有者卡组发动。
【效果】给予对手600伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD7-JP017', '幻刃工兵 绘图大龙', '【条件】这张卡召唤的回合可以发动。
【效果】将自己卡组最上面的卡翻开，双方确认。那之后，自己使翻开的卡返回卡组上面或下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD7-JP021', '屏障犰狳', '会把靠近之物反弹，意外地强的犰狳。能运用履带灵活地挖掘。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBD7-JP027', '透幻乡的万绿', '【条件】这张卡在自己场上的表侧表示怪兽的等级合计为10以上的场合可以发动。
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（地属性以外）的攻击力、守备力就下降300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD01-JP001', '消隐偕日升龙', '【条件】自己手牌为2张以下的场合，可以使自己墓地的1只怪兽返回卡组发动。
【效果】这张卡的攻击力直到回合结束时上升200。自己或者对手场上有表侧表示的魔法卡的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD01-JP006', '宇宙极光升龙', '【条件】可以将手牌的1张魔法陷阱卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[对手场上的魔法陷阱卡的数量]×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD01-JPB01', '双管手枪龙', '【条件】这张卡召唤或特殊召唤的自己的主要阶段可以发动。
【效果】选对手场上的1张卡，抛2次硬币。那之中2次都是正面的场合，将那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD01-JPB02', '幻象龙', '【条件】无
【永续效果】对手在双方的战斗阶段不能发动陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD01-JPB03', '炎之支配者', '【条件】无
【永续效果】要将怪兽（炎属性）以攻击表示高等召唤的场合，表侧表示的这张卡可以作为2只的分量来解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD01-JPB04', '恶魔士兵', '在恶魔之中也是隶属精英云集的部队的战斗专家。以可以切实地完成被交托的任务而出名。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD01-JPB05', '激流葬', '【条件】自己或者对手召唤或特殊召唤怪兽时可以发动。
【效果】将双方场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP018', '虚空噬骸兵 流星兵', '【条件】自己场上有表侧表示怪兽（等级7以上/银河族）的场合，可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（等级6以下/光属性）破坏。那之后，给予对手300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP019', '流星幼虫', '【条件】无
【效果】从自己卡组上面将[自己场上的表侧表示怪兽（暗属性/银河族）的数量]的卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP020', '虚空噬骸兵 轻盾兵', '身上寄宿有新月之力的战士。用其大盾来挡开全部攻击。满月之夜时隐藏的力量会觉醒。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP021', '虚空回廊', '【条件】自己墓地有怪兽（暗属性/银河族）的场合，可以将1张手牌送入墓地发动。
【效果】选自己墓地的1只怪兽（暗属性/银河族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP028', '虚空拦截', '【条件】自己场上的表侧表示怪兽只有怪兽（暗属性/银河族）的场合，对手以表侧表示召唤或特殊召唤怪兽时可以发动。
【效果】随机选1张对手的手牌送入墓地。那之后，对手的手牌为2张以上的场合，对手可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP029', '虚空遮盖罩', '【条件】自己场上有表侧表示怪兽（暗属性/银河族）2只以上的场合，对手以表侧表示召唤或特殊召唤怪兽时可以发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下）变为里侧守备表示。自己场上有表侧表示怪兽（等级8/银河族）的场合，可以再选对手场上的1只守备表示怪兽返回持有者的手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP001', '虚空噬骸兵 极乐鹰巨人', '【条件】可以将1张手牌送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽变为里侧守备表示。这张卡的攻击力直到回合结束时上升500。这个效果的条件将怪兽送入墓地的场合，再在这个回合使这张卡不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP007', '虚空噬骸兵 百臂鹰巨人', '【条件】使攻击表示的这张卡变为表侧守备表示发动。
【效果】给予对手500伤害。自己场上有表侧表示怪兽（等级8）的场合，可以再选自己场上的1只表侧表示怪兽（银河族）变更表示形式（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP012', '虚空噬骸兵 苍白骑士', '那存在即是「死亡」本身，将生者的灵魂带往冥界。无法从其紫绀之刃下逃脱。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP013', '虚空噬骸兵 重装步兵', '从宇宙的混沌中涌出的邪神眷属。不祥的单眼在人们的心中铭刻下真正的恐惧。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP014', '次元异种', '打破长久的沉默，再度开始生命活动的宇宙肉食兽。一边徘徊在异次元一边不断发动侵略。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD05-JP015', '虚空噬骸兵 球状兵', '【条件】可以使自己墓地的3只怪兽（暗属性/银河族）返回卡组发动。
【效果】这个回合，要将怪兽（暗属性/银河族）以攻击表示高等召唤的场合，表侧表示的这张卡可以作为2只的分量来解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP001', '分析燃素灵', '【条件】可以将手牌的1张魔法陷阱卡送入墓地发动。
【效果】选自己墓地的3只等级合计与[对手场上的攻击表示怪兽（等级8以下）的等级合计]相同的怪兽（炎族）返回卡组。那之后，将对手场上的攻击表示怪兽（等级8以下）全部破坏。这个回合，自己只能用1只怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP008', '火焰地狱犬', '全身被火焰包围的魔兽。用地狱之火将对手处刑。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP010', '火焰杀手', '使用火焰之盾的剑士。那个盾无论怎样的攻击也能无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP013', '业火的结界像', '【条件】无
【永续效果】双方不能特殊召唤怪兽（炎属性以外）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP015', '红袍博士', '燃烧研究的专家。从引以为傲的手套里放出的火球会把一切东西烧成炭。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP016', '火焰探寻者', '「火力全满」队的副领队。最近对使用全部财产中标的超高火力喷火枪爱不释手。让我们开火吧！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP017', '灯之炎魔 甲醇灵', '【条件】这张卡召唤的回合可以发动。
【效果】选自己墓地的1只通常怪兽（等级4/炎族）加入手牌。这个回合，自己不能用怪兽（炎族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP018', '灯之炎魔 乙醇灵', '【条件】自己场上没有这张卡以外的怪兽的场合可以发动。
【效果】选自己墓地的1只「灯之炎魔 甲醇灵」以表侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP023', '超级助手 阿炽', '喜欢的实验是焰色试验！以燃烧的心情为原动力今天一天会好好加油！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP028', '炎之天秤', '【条件】可以使自己墓地的1只怪兽（炎族）返回卡组发动。
【效果】选自己场上的1只表侧表示怪兽（炎族），其攻击力直到回合结束时上升500。那之后，可以选对手场上的1只表侧表示怪兽使其攻击力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD04-JP032', '火降烧壁', '【条件】自己场上有表侧表示怪兽（等级7以上/炎族）的场合，对手怪兽（等级8以下）的攻击宣言时可以发动。
【效果】从自己卡组上面将3张卡送入墓地。那之后，对手场上的全部表侧表示怪兽（等级8以下）的攻击力直到回合结束时下降[用这个效果送入墓地的怪兽（炎族）的数量]×400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD03-JP001', '真红动击速龙', '【条件】无
【效果】选自己墓地的最多7只怪兽（龙族）。给予对手[选的怪兽的数量]×100伤害，这张卡的攻击力直到回合结束时上升[选的怪兽的数量]×100。那之后，选的怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD03-JP008', '双核羽蛇神', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升400。这个回合，这张卡不能直接攻击，可以对怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD03-JP011', 'β版燃龙', '【条件】这张卡召唤的回合，自己场上有这张卡以外的表侧表示怪兽（龙族）的场合可以发动。
【效果】给予对手[对手场上的怪兽的数量]×100伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD03-JP012', '应用蜥蜴', '从龙变生而成的龙人种。发挥很高的战略性和敏捷性，运用自如地操纵既可当剑又可当盾的平板电脑来攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD03-JP020', 'SSD龙兽', '【条件】对手场上有怪兽的场合，可以将手牌的1张魔法陷阱卡送入墓地发动。
【效果】选自己墓地的2只通常怪兽（等级4以下/龙族）以表侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD03-JP022', '网站龙', '网络世界中稀有的电子生命体。据说不喜欢斗争，靠吃漏洞来长大。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD03-JP024', 'α版燃龙兽', '隐藏着各种可能性的龙宝宝。对眼罩所创造的广阔VR世界抱有憧憬。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD03-JP029', '龙超天山', '【条件】自己墓地有怪兽（龙族）的场合可以发动。
【效果】选自己或者对手场上的1张表侧表示的场地魔法卡破坏。那之后，可以将手牌的1只怪兽（龙族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD03-JP032', 'RB智龙手机', '【条件】自己场上的表侧表示怪兽（龙族）被对手的攻击或者对手的效果破坏时可以发动。
【效果】从自己卡组上面将2张卡送入墓地。自己场上没有怪兽的场合，可以再选自己墓地的1只「碧牙爆速龙」或者「真红动击速龙」以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD02-JP001', '接合科技掷币三角龙', '【条件】这张卡是攻击表示的场合可以发动。
【效果】抛1次硬币。是正面的场合，这个回合，这张卡的攻击力上升1500，这张卡的攻击宣言时对手不能发动陷阱卡。是反面的场合，这张卡变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD02-JP009', '软木塞骑兵', '【条件】自己场上没有这张卡以外的怪兽，对手场上的魔法陷阱卡为2张以下的场合可以发动。
【效果】给予对手[对手场上的魔法陷阱卡的数量]×300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD02-JP010', '盆子扳手捕鸟蛛', '【条件】这张卡召唤的回合，对手场上有2张以上的魔法陷阱卡的场合可以发动。
【效果】选自己墓地的1只通常怪兽（等级4/机械族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD02-JP012', '陆战型战斗艇', '陆上战斗机器人。虽然现在不行，但以前好像可以在海上使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD02-JP014', '木工龙', '机动性和机能性优秀的量产型拆卸机器。结合部非常脆弱，手腕和双翼经常脱落。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD02-JP018', '叉子鹰', '【条件】自己场上的表侧表示怪兽（机械族）为3只的场合，可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选对手场上的1只里侧表示怪兽变为表侧攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD02-JP020', '手工矮人', '在孩子间很有人气的手工制作机器人。也作为游乐园吉祥物在活跃中。转动中间的手轮还会变形。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD02-JP021', '图钉尖钉刺猬', '【条件】无
【效果】将自己卡组最上面的卡送入墓地。用这个效果将怪兽送入墓地的场合，可以再选对手场上的1只表侧表示怪兽使其攻击力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD02-JP022', '螺丝犰狳', '【条件】可以将手牌的1只怪兽（机械族）送入墓地发动。
【效果】选对手场上的1只攻击表示怪兽（等级6以下）变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD02-JP030', '雷电火花', '【条件】自己墓地有怪兽（机械族或者雷族）的场合，对手怪兽的攻击宣言时可以发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP001', '黑魔导士', '在魔法师中，攻击力、守备力都是最高级别。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B001-JP001', '精灵剑士', '学过剑术的精灵。用敏捷的攻击愚弄敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B001-JP002', '机械猎鹰', '装备了喷气式引擎的鹰。能够用音速飞行。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B001-JP003', '死灵女仆 娜娜', '【条件】可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选自己墓地的1只怪兽（等级7）返回卡组下面，自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B001-JP004', '最古念力埋葬', '【条件】可以支付1000LP发动。
【效果】从自己卡组上面将2张卡送入墓地。对手场上的怪兽为3只的场合，可以再从自己卡组上面将1张卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B001-JP005', '水疗射击', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】选自己墓地的1只怪兽（水属性），自己恢复[选的怪兽的等级]×100LP，给予对手[选的怪兽的等级]×100伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B001-JP006', '悠悠', '完全不知道在想什么的天使中的出格者。偶尔生起气来会很可怕。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B001-JP007', '铁铲粉碎机', '要当心它那双手能破坏一切的大铲。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B001-JP008', '蟑螂球', '球形的蟑螂。不断滚动攻击。守备力意外地高。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B001-JP009', '天空龙', '有着四块翅膀、鸟的外形的龙。用刀刃那样的翅膀攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B001-JP010', '古代的望远镜', '【条件】无
【效果】对手从自身卡组上面翻开5张卡，双方确认。那之后，对手使翻开的卡按照原本的顺序返回卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AKG1-JP001', '七道魔导士', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[自己墓地的怪兽的属性的种类]×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B002-JP001', '治疗之神 迪安·凯特', '【条件】无
【效果】自己恢复1000LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B002-JP002', '花牙鬼之百合', '【条件】自己场上有表侧表示的通常怪兽（植物族）的场合可以发动。
【效果】将双方卡组最上面的卡送入墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B002-JP003', '星途之光', '【条件】可以将自己场上的1只表侧表示的通常怪兽送入墓地发动。
【效果】将手牌的1只怪兽（念动力族）以表侧表示特殊召唤到自己的场上。这个效果的条件将怪兽（等级2以下）送入墓地的场合，再使自己恢复1000LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B002-JP004', '幻刃剑匠', '【条件】自己或者对手的场上有表侧表示的场地魔法卡的场合可以发动。
【效果】选对手场上的1只守备表示怪兽变为表侧攻击表示。用这个效果变为表侧攻击表示的怪兽是通常怪兽的场合，自己可以再抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B002-JP005', '进军的喇叭', '【条件】自己的怪兽（战士族）被对手怪兽的攻击破坏时可以发动。
【效果】将手牌的1只怪兽（战士族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B002-JP006', '火山种老鼠', '灼热的火山地带生活的鼠类变种。拥有任何高温都能抵抗的身体。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B002-JP007', '剑背角龙', '悠闲地群居生活的恐龙。外表看起来粗犷，其实并不是很强。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B002-JP008', '台风炮', '从口中发射出炮弹远程攻击。在山上作出的炮击很强劲。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B002-JP009', '豌豆士兵', '使用剑和豆子攻过来的植物战士。意外地强力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B002-JP010', '红龙', '用火球把周边变为火海，深红色的龙。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B003-JP001', '炎之剑士', '「火焰操纵者」+「传说的剑豪 正树」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B003-JP002', '魔界的机械兵', '用黑暗之力制造出来的机械兵。像发狂一般破坏敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B003-JP003', '沉重磙子', '【条件】可以将手牌的1只怪兽（炎属性）送入墓地发动。
【效果】自己抽1张。自己或者对手的场上有表侧表示的场地魔法卡的场合，可以再使自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B003-JP004', '海', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（鱼族·海龙族·雷族·水族）的攻击力、守备力就上升200，双方场上的表侧表示怪兽（机械族·炎族）的攻击力、守备力就下降200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B003-JP006', '埴轮蜜糖华夫饼', '为了解救粮荒而开发的一道甜点。其甜美的俏脸和口味令人尖叫声四起。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B003-JP007', '火焰操纵者', '自由自在地制造火海或火墙攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B003-JP008', '独眼白虎', '对有些人来说是恐怖，对有些人来说是尊敬的对象，孤高的密林王者。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B003-JP009', '传说的剑豪 正树', '据说达成了百人斩的传说剑豪。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B003-JP010', '尖刺海龙', '用身体上的刺刺击对手，再放出电流攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B004-JP001', '乘龙的飞龙战士', '「宝贝龙」+「飞龙战士」
【条件】对手场上的表侧表示怪兽只有怪兽（地属性·水属性·炎属性）的场合可以发动。
【效果】这个回合，这张卡可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B004-JP006', '色变龙', '使身体的颜色改变，不管是在什么地方都能隐藏自己。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B004-JP007', '蓝目银僵尸', '据说从眼中射出的怪光线能把对手变成僵尸。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B004-JP008', '世界蛇', '神话世界中出现的蛇。非常长。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B004-JP009', '水陆的帝王', '从其大口向四面八方喷射火焰的爬虫类怪物。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B221-JP005', '强者的愉悦', '【条件】对手召唤怪兽时可以发动。
【效果】选自己场上的1只表侧表示的通常怪兽，其攻击力、守备力直到回合结束时上升[对手召唤的那只怪兽的等级]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B221-JP006', '迷恋瓢虫 粉画', '背上的心形为其特征，心地和善的瓢虫。据说只要触碰到就能实现恋情。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B221-JP007', '梦想瓢虫 彩虹', '背上的星星为其特征，情感丰富的瓢虫。画出虹之轨迹的同时今天也传递着幸福。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B221-JP008', '恶魔河狸', '有着恶魔的角和翼的河狸。投掷橡实攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B221-JP009', '东方英雄', '据说是从遥远的东方国家而来的武士。手里的刀非常锋利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B221-JP010', '杀人熊猫', '经常拿着一根大竹子，性格非常凶暴。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/21CC-JP001', '天比惠姑娘', '【条件】无
【效果】双方恢复300LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/G001-JP001', '最强战旗 王牌破坏者', '【条件】可以将手牌的2只怪兽送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/G001-JP002', '黑魔导士少女', '【条件】无
【永续效果】这张卡的攻击力上升双方墓地的「黑魔导士」的数量×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/G001-JP003', '强欲之壶', '【条件】无
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/P003-JP001', '七道男巫', '【条件】可以将手牌的1张陷阱卡送入墓地发动。
【效果】选自己墓地的1只怪兽（等级7以上/暗属性/魔法师族）加入手牌。用这个效果将「七道魔导士」加入手牌的场合，可以再选自己墓地的1只怪兽（等级6以上/魔法师族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/P003-JP002', '三联龙', '【条件】对手场上有表侧表示怪兽（等级7以上），自己场上的表侧表示怪兽（等级3以外/龙族）为2只的场合可以发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/P003-JP003', '死者转生', '【条件】可以将1张手牌送入墓地发动。
【效果】选自己墓地的1只怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP001', '王道魔导-爆发', '【条件】自己场上有表侧表示怪兽（等级7以上/魔法师族）的场合，可以将手牌的1只怪兽（炎属性）送入墓地发动。
【效果】给予对手[对手场上的卡的数量]×400伤害。 ​​​​', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP003', '王道魔导-逆流', '【条件】自己场上有表侧表示怪兽（等级7以上/魔法师族）的场合，可以将手牌的1只怪兽（水属性）送入墓地发动。
【效果】选对手场上的1只怪兽返回持有者的手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP005', '机动城的开启桥人', '【条件】这张卡召唤的回合，可以从卡组上面将3张卡送入墓地发动。
【效果】变更这张卡的表示形式变更（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。那之后，可以选自己墓地的1只通常怪兽（地属性）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP002', '正义龙', '【条件】可以使自己墓地的2只怪兽（龙族）返回卡组发动。
【效果】这个回合，要以攻击表示高等召唤怪兽（龙族）的场合，表侧表示的这张卡可以作为2只的分量来解放。 ​​​​', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP004', '皇家魔族 蓝调', '【条件】这张卡召唤的回合，可以将手牌的1张魔法陷阱卡送入墓地发动。
【效果】选自己墓地的1只怪兽（等级7以上/恶魔族）以表侧守备表示特殊召唤到自己的场上。这个回合，自己不能用怪兽（恶魔族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP006', '黄昏之勇者 莱达克罗斯', '【条件】可以使自己墓地的合计2只怪兽（战士族或者魔法师族）返回卡组发动。
【效果】将手牌的1只怪兽（等级6/战士族或者魔法师族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VP02-JP001', '大连击龙 德拉基亚斯·爆裂[L]', '【条件】极限模式：可以将卡组最上面的卡送入墓地发动。
【效果】这个回合，这张卡可以对怪兽作3次攻击。这个回合的结束阶段这张卡返回持有者的卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VP02-JP002', '大连击龙 德拉基亚斯·爆裂', '和「大连击龙 德拉基亚斯·爆裂[L]」「大连击龙 德拉基亚斯·爆裂[R]」集齐可以极限召唤。
【条件】极限模式
【永续效果】这张卡不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VP02-JP003', '大连击龙 德拉基亚斯·爆裂[R]', '【条件】极限模式：可以将3张手牌送入墓地发动。
【效果】这个回合，这张卡的攻击力上升1000，其攻击会贯通（攻击守备表示怪兽攻击时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/WJMP-JP001', '暗黑骑士盖亚', '骑着比风还快的马的骑士。小心它的突进攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VJMP-JP001', '真红眼黑龙', '拥有真红之眼的黑龙。愤怒的黑炎将映入眼里的一切东西烧尽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VJMP-JP002', '黑龙之雏', '【条件】可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】将手牌的1只「真红眼黑龙」以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VJMP-JP003', '黑炎弹', '【条件】自己场上有表侧表示的「真红眼黑龙」的场合可以发动。
【效果】给予对手2400伤害。这个回合，自己不能用「真红眼黑龙」攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/JB01-JP001', '进击火山龙', '火龙王国攻龙精锐部队的教练队长。喷射出的灼热火焰会将与王为敌的人一扫而空。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/JB01-JP002', '正统的爆裂龙息', '【条件】自己场上有表侧表示的通常怪兽（等级7以上/龙族）的场合可以发动。
【效果】将对手场上的表侧表示怪兽（等级6以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/JB01-JP003', '龙的执念', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】选自己墓地的1只怪兽（龙族），攻击过来的怪兽的攻击力直到回合结束时下降[选的怪兽的等级]×100。那之后，使选的怪兽返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/DD01-JP003', '神圣护罩 -镜之力-', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】将对手场上的攻击表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/DD01-JP002', '七道附魔师', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选自己或者对手场上的1只表侧表示怪兽（等级3以外/魔法师族）返回持有者的手牌。用这个效果使「七道魔导士」返回手牌的场合，可以再使自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/DD01-JP001', '蓝眼白龙', '拥有引以为傲的高攻击力的传说之龙。不管是怎样的对手都能粉碎，其破坏力无法估计。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/BD05-JP001', '月魔将 鬼目流奈', '【条件】无
【效果】选对手场上的最多2只怪兽变更表示形式（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。用这个效果将表示形式变更的场合，可以再选自己场上的1只表侧表示怪兽变更表示形式。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP001', '超魔辉兽 超大王道王[L]', '【条件】极限模式
【永续效果】这张卡的攻击力上升[对手场上的怪兽的数量]×500。自己的墓地有10只以上怪兽的场合，这张卡的攻击会贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP002', '超魔辉兽 超大王道王', '和「超魔辉兽 超大王道王[L]」「超魔辉兽 超大王道王[R]」集齐可以极限召唤。
【条件】极限模式
【永续效果】这张卡不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP003', '超魔辉兽 超大王道王[R]', '【条件】极限模式
【永续效果】对手以表侧表示特殊召唤怪兽（等级5以上）的回合，这张卡表侧表示期间，对手不能发动表侧表示怪兽（等级10以下）的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP004', '刚击龙 梅塔基亚斯之星F', '「钢击龙 梅塔基亚斯」+「THE☆天龙」
【条件】可以将卡组最上面的卡送入墓地发动。
【选择效果】●自己场上的全部表侧表示怪兽的攻击力直到回合结束时上升500，并且这个回合，这张卡可以对怪兽作2次攻击。●自己场上的全部表侧表示怪兽直到回合结束时不会被战斗和对手的陷阱卡的效果破坏，并且这个回合，这张卡可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP005', '暗七道之魔导士', '「七道魔导士」+「暗冥零盗贼」
【条件】无
【永续效果】这张卡的攻击力上升[自己墓地的怪兽（暗属性/魔法师族）的数量]×300。这张卡以外的自己的怪兽的战斗不会使自己受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP006', '暗冥零盗贼', '【条件】这张卡特殊召唤的自己的主要阶段，自己墓地有8只以上的怪兽（暗属性/魔法师族）的场合可以发动。
【效果】将对手场上的表侧表示怪兽（等级8以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP001', '黑魔导士少女', '【条件】无
【永续效果】这张卡的攻击力上升双方墓地的「黑魔导士」的数量×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP007', '暗冥预探者', '【条件】自己墓地有3只以上的等级不同的怪兽（暗属性/魔法师族）的场合可以发动。
【效果】从自己卡组上面将4张卡送入墓地。这个回合，自己只能用怪兽（暗属性/魔法师族）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP008', '暗冥盗贼', '【条件】这张卡召唤的回合，自己场上没有这张卡以外的怪兽的场合可以发动。
【效果】将手牌的1只怪兽（暗属性/魔法师族）以表侧表示特殊召唤到自己的场上。那之后，使自己场上的这张卡返回持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP018', '魔术的幕帘', '【条件】可以支付1000LP发动。
【效果】将手牌的1只怪兽（魔法师族）以表侧表示特殊召唤到自己的场上。这个回合，用这个效果特殊召唤的怪兽不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP019', '王道魔导-暗夜', '【条件】自己场上有表侧表示怪兽（等级7以上/魔法师族）的场合，可以将手牌的1只怪兽（暗属性）送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP020', '暗冥之道', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（等级5以上/暗属性/魔法师族）的攻击力就上升400，守备力就下降1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP021', '七道防护', '【条件】对手召唤怪兽时可以发动。
【效果】自己场上的全部表侧表示怪兽（暗属性/魔法师族）在这个回合不会被对手的效果破坏。自己墓地有「七道魔导士」的场合，可以使对手召唤的那只怪兽变为表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP023', '魔法火焰防御', '【条件】自己墓地有2只以上的怪兽（魔法师族）的场合，对手怪兽（等级8以下）的攻击宣言时可以发动。
【效果】选自己场上的1只攻击表示怪兽（魔法师族）。这个回合，那只怪兽不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP024', '彩光超 欧米伽吉他手', '「彩光之首席吉他手」+「业余花莉莉丝」
【条件】可以将卡组最上面的卡送入墓地发动。
【选择效果】●这张卡的攻击力直到回合结束时上升[对手场上的怪兽数量]×1000。这个回合，这张卡不会被对手的陷阱卡的效果破坏。●选对手场上的1张魔法陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP025', '彩光超 欧米伽公主', '「彩光之首席吉他手」+「业余花莉莉丝」
【条件】无
【选择效果】●变更自己场上的全部怪兽的表示形式变更。那之后，可以选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降[自己场上的怪兽的数量]×800。●选对手墓地的最多7张卡返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP027', '可能甜心：D 万能玩偶', '「可能甜心：D」+「AI可能甜甜熊」
【条件】无
【效果】选自己墓地的1只怪兽（等级6以下/念动力族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP029', '可能甜心-高速：D', '【条件】自己场上有这张卡以外的表侧表示怪兽（欧米伽念动力族或者念动力族）的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽。这个回合，那只怪兽的攻击力上升200，那只怪兽的攻击宣言时对手不能发动陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP035', '革新制壶陶艺家', '【条件】可以使自己墓地的5只怪兽返回卡组发动。
【效果】选对手墓地的最多2张卡返回卡组。那之后，自己可以抽出[自己墓地的「革新制壶陶艺家」「贪欲之壶」的卡名种类的数量]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP037', 'AI可能甜甜熊', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「可能甜心：D」或者「业余花莉莉丝」以表侧表示特殊召唤到自己的场上。这个回合，自己只能用怪兽（欧米伽念动力族或者念动力族）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP042', '业余花莉莉丝', '自由自在地奏出心声的女孩子。喜欢的心情永不褪色。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP044', '念动力欧米伽爆破', '【条件】对手场上有2只以上的表侧表示怪兽的场合，可以使自己墓地的4只怪兽（念动力族）返回卡组发动。
【效果】选对手场上的1只攻击力最低的表侧表示怪兽破坏。自己场上有表侧表示怪兽（欧米伽念动力族）的场合，再给予对手[用这个效果破坏的怪兽的原攻击力]的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP048', '与未知的邂逅', '【条件】自己场上有表侧表示怪兽（等级7以上/欧米伽念动力族·念动力族）的场合，对手怪兽（等级8以下）的攻击宣言时可以发动。
【效果】使攻击的怪兽返回持有者的手牌。自己场上有表侧表示的「多面手女郎」的场合，可以再选自己墓地的1只怪兽（等级3以下）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP049', '欧米伽客串', '【条件】对手特殊召唤怪兽时可以发动。
【效果】选自己场上的1只表侧表示怪兽（欧米伽念动力族或者念动力族），其攻击力直到回合结束时上升1200。选的怪兽是等级9的场合，再在这个回合使那只怪兽不会被战斗和对手的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP052', '厨房之神 迪安·凯特', '【条件】可以将1张手牌送入墓地发动。
【效果】从自己卡组上面将3张卡送入墓地。自己的LP为2000以下的场合，自己可以再恢复[被这个效果送入墓地的怪兽（水族）的数量]×1000LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP053', '肩电娘娘', '【条件】这张卡召唤的回合，可以使1张手牌返回卡组下面发动。
【效果】选对手场上的1只表侧表示怪兽，其攻击力直到回合结束时下降500。那之后，可以选自己墓地的1只怪兽（等级7以上/水族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP054', '高跟鞋女祭司', '【条件】这张卡召唤的回合，自己场上有表侧表示怪兽（等级7以上/水族）的场合可以发动。
【效果】自己抽1张。那之后，自己场上的全部表侧表示怪兽（等级7以上/水族）的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP056', '提拉米苏瓦尔基莉', '送上提拉米苏和热潮的天使店员。决不输给流行变迁和邪恶的心。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP059', '杀手意式奶冻熊猫', '凶暴的熊猫店员。点了意式奶冻会生气。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP062', '妈妈风暴', '【条件】自己场上有表侧表示怪兽（等级8以上/水族）的场合，可以将手牌的1只怪兽（水族）送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下）破坏。用这个效果将怪兽（机械族）破坏的场合，可以再将对手场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP065', '泡沫雷曼冲击！', '【条件】自己场上有表侧表示怪兽（等级8以上/水族）的场合可以发动。
【效果】自己受到[对手场上的表侧表示怪兽（等级8以下）的攻击力合计]的伤害。用这个效果使自己受到伤害的场合，再将对手场上的表侧表示怪兽（等级8以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP067', '兴高采烈回复', '【条件】自己的表侧表示怪兽（水族）受到攻击的对手怪兽的攻击宣言时可以发动。
【效果】自己的LP恢复[攻击的怪兽的攻击力]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP068', '神之治疗', '【条件】对手以表侧表示召唤或特殊召唤怪兽（等级7以上）时可以发动。
【效果】自己恢复1000LP。那之后，可以选自己场上的1只表侧表示怪兽（水族），其攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP071', '冥骸 死亡支配者', '【条件】可以将手牌的1只怪兽（不死族）送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升1000。自己墓地有怪兽（等级7/不死族）的场合，再给予对手700伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP073', '到处爬的半身', '【条件】这张卡召唤的回合可以发动。
【效果】选自己墓地的1只通常怪兽（不死族/攻击力0）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP074', '弗兰肯魔人·神社', '【条件】这张卡召唤的回合，自己墓地有通常怪兽（4星以下/不死族）的场合，将卡组最上面的卡送入墓地才能发动。
【效果】选自己墓地最多2只通常怪兽（4星以下/不死族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP075', '背后的花子小姐', '在地下男厕所里有时会突然感到背后有动静。可是呀，上完厕所之前绝对不能回过头去。如果，回过头看见了那怪兽的话……', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP076', '紫镜中的潜藏者', '各位……你们可知道紫镜这个词？如果知道这个词那就要当心了。要是到二十岁还记得这个词没忘掉的话……', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP077', '丑三时的阿菊人偶', '在后台里睡，是要被鬼压床的……在漆黑中定睛一看，枕边竟然是……', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP078', '桑巴舞僵尸 里约', '总是在不灵活地活动身体的僵尸。已经没了意识却仍未忘记其身体记住的桑巴舞节奏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP079', '干涩的敲门声', '【条件】对手场上有2张以上的魔法陷阱卡的场合可以发动。
【效果】选对手场上的1张魔法陷阱卡，将那张卡以外的对手场上的魔法陷阱卡全部破坏。这个回合，自己不能用怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP080', '诅咒的粉丝来信', '【条件】对手有手牌的场合，可以使自己场上的攻击表示的通常怪兽（不死族）全部变为表侧守备表示发动。
【效果】随机选最多为[自己场上的表侧守备表示怪兽（不死族）的数量]的对手的手牌送入墓地。那之后，给予对手[用这个效果送入墓地的卡的数量]×300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP081', '僵尸狂欢节', '【条件】无
【效果】只要这张卡在场地区表侧表示，双方场上的表侧表示怪兽（不死族）的攻击力、守备力上升[双方场上的表侧表示怪兽（不死族）的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP082', '僵尸烟花', '【条件】可以向对手展示手牌的1只怪兽（等级5以上/不死族）发动。
【效果】选自己墓地的最多2只怪兽（等级6以下/不死族）以表侧表示特殊召唤到自己的场上。那之后，自己选手牌的1只怪兽（等级5以上/不死族）送入墓地。这个回合，自己不能用怪兽（不死族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP083', '吓人僵尸大胜利', '【条件】自己场上有2只以上的表侧表示的通常怪兽（不死族）的场合可以发动。
【效果】选对手场上的最多3只怪兽变更表示形式。那之后，可以使自己场上的全部表侧表示怪兽（不死族）的攻击力直到回合结束时上升[自己墓地的通常怪兽（不死族）数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP084', '就在你后面！', '【条件】双方的抽卡阶段或者双方的主要阶段，对手受到伤害时可以发动。
【效果】选自己手牌或者自己墓地的1只「冥骸 死亡支配者」或者「邪影 黑暗潜伏者」以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤的怪兽的原攻击力、原守备力直到回合结束时交换。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP085', '步步逼近的足音', '【条件】自己场上有表侧表示怪兽（不死族）的场合，对手在抽卡阶段通常抽卡时可以发动。
【效果】确认对手的手牌。自己可以从那之中选最多3张魔法陷阱卡。选的场合，对手将那些卡盖放到自身的场上，对手受到[用这个效果盖放的卡的数量]×300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP086', '诅咒猫数盘', '【条件】自己场上有表侧表示怪兽（等级7以上/不死族）的场合，对手怪兽（等级9以下）的攻击宣言时可以发动。
【效果】使那次攻击无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP087', '诅咒的来电号码', '【条件】自己墓地有怪兽（不死族）的场合，对手在抽卡阶段通常抽卡时可以发动。
【效果】给予对手900伤害。这个回合，对手攻击表侧表示怪兽的场合，只能攻击自己场上的等级最低的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP088', '东方虎', '【条件】可以变更这张卡的表示形式发动（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。
【效果】给予对手[对手墓地的魔法陷阱卡的数量]×100伤害。对手墓地的魔法卡的数量为10张以上的场合，再给予对手1200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP089', '影之食尸鬼', '【条件】无
【永续效果】这张卡的攻击力上升[自己墓地的怪兽的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP090', '咒腐龙 魔灵纳迦', '【条件】自己场上有这张卡以外的表侧表示怪兽（不死族）的场合，可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选对手场上的1只表侧表示怪兽（等级5以上），其攻击力直到回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP091', '高峰窥探魔法师', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】双方从自身卡组上面将2张卡翻开，双方确认。那之后，双方将自身翻开的卡按照喜欢的顺序返回卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP092', '天终之怪依', '【条件】无
【效果】从自己卡组上面将3张卡翻开，双方确认。自己从翻开的卡之中选1张送入墓地。那之后，剩下的卡返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP093', '魔法幽灵', '向对手施展魔法，使其陷入恐怖和混乱再攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP094', '牺牲召唤', '【条件】可以将自己场上的1只表侧表示怪兽（攻击力1600以上）送入墓地发动。
【效果】将手牌的1只效果怪兽以表侧表示特殊召唤到自己的场上。用这个效果的条件将原等级为7以上的效果怪兽送入墓地的场合，用这个效果特殊召唤的怪兽在这个回合可以对怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP096', '折价交易', '【条件】可以将手牌的1只怪兽（等级8）送入墓地发动。
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP098', '燃尾之急', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】给予对手600伤害。对手场上有2只以上的表侧表示怪兽（等级7）的场合，可以再选对手场上的1只怪兽返回持有者的卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP099', '噩梦再临', '【条件】无
【效果】选自己墓地的2只怪兽（暗属性/守备力0）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP1-JP100', '贪欲之壶', '【条件】可以使自己墓地的5只怪兽返回卡组发动。
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/MRP2-JP088', '魔导士才华', '【条件】自己的墓地有3张以上的魔法卡的场合，对手召唤或特殊召唤怪兽时可以发动。
【效果】选自己墓地的「千把刀」「黑·魔·导」「黑·魔·导·响·弹」合计最多2张盖放到自己的魔法陷阱区。并且再在这个回合使自己不会因对手怪兽（等级9以下）的攻击受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B222-JP007', '邪犬拔刀 匕首吉娃娃', '用圆圆大眼睛来麻痹敌人博取好感的邪犬。
忠诚心算是平平墓奇。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B222-JP006', '迷你竖琴精灵', '在发表会上弹奏竖琴的精灵。
那音色使周围听众的心变得平静。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B222-JP001', '诅咒之龙', '邪恶之龙。
使用黑暗力量的攻击强而有力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B222-JP003', '美少女剑士 迦南', '以演剧部为主战场的女战士。
灵活使用剑与盾，像蝴蝶飞舞像蜜蜂跳舞。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B222-JP009', '河童说唱歌手', '经常押韵，鼓动那靠近水边的人们的河童。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B222-JP002', '沙场的魔女', '操纵水去凝固沙子的魔法师。
用满是泥巴的手来生成任何东西', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B222-JP008', '念力河童', '使用各种超能力，防住攻击伤害的河童。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/B222-JP010', '复仇的河童', '同伴被杀害，为复仇而把心卖给邪恶的河童。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/G002-JP003', '大风暴', '【条件】无
【效果】双方场上的魔法·陷阱卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/G002-JP001', '银线暴空想龙', '【条件】把自己场上1张这张卡以外的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升500。双方场上没有魔法·陷阱卡的场合，更在这个回合让这张卡可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/G002-JP002', '魔术女武神', '【条件】无
【永续效果】对方不能向这张卡以外的表侧表示怪兽（魔法师族）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBP1-JP001', '最强战旗 刚强攻击者', '连山也粉碎的无敌刚拳。
扬起的战旗如烈火灼心。
最强的战斗里没有败北。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBP1-JP002', '最强旗兽 先锋狼', '为战斗用开发的机械兽。
它的雄姿唤醒最强斗志。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CL01-JP001', '零击龙 齿车戒零龙', '【条件】把手卡1只怪兽（7星以上/龙族）送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下），那个原本攻击力直到回合结束时变成0。这个回合，这张卡向怪兽攻击过的战斗阶段中，这张卡只再1次可以向怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CL02-JP001', '装魂龙 齿车戒铠龙', '【条件】把1张手卡送去墓地才能发动。
【效果】自己场上的这张卡送去墓地。那之后，手卡1只怪兽（7星/龙族）在自己场上攻击表示特殊召唤。这个效果特殊召唤的怪兽的攻击力直到回合结束时上升1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CL03-JP001', '虚击龙 齿车戒铠零龙', '「零击龙 齿车戒零龙」＋「装魂龙 齿车戒铠龙」
【条件】
把卡组最上面的卡送去墓地才能发动。
【选择效果】
●选对方场上最多3只表侧表示怪兽，那些原本攻击力直到回合结束时变成0。这个回合，这张卡可以向怪兽作2次攻击。
●选对方场上1张魔法·陷阱卡破坏。那之后，可以选自己墓地1只怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/BD02-JP001', '宇宙弦之面条女德鲁伊', '【条件】
自己或者对方场上有表侧表示的「宇宙」的场合，把手卡2只怪兽（炎族）送去墓地才能发动。
【效果】
双方场上的表侧表示怪兽（7星以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/BD03-JP001', '幻刃龙 建造龙', '【条件】
自己或者对方场上有表侧表示的场地魔法卡的场合才能发动。
【效果】
选自己墓地1只通常怪兽（幻龙族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/BD04-JP001', '可能甜心：D', '隐藏有无限可能性，面带笑容的同时不断追逐着光辉梦想。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/BD06-JP001', '可能甜心：D 驱动现场演奏', '「可能甜心：D」＋「念力拾音人」
【条件】
对方场上有怪兽的场合才能发动。
【选择效果】
●自己受到2000伤害。那之后，可以让对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降3000。
●自己回复1000基本分。那之后，可以选自己墓地1只怪兽（7星以上/念动力族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/BD07-JP001', '七星道魔女', '【条件】
把1张手卡送去墓地才能发动。
【效果】
手卡1只怪兽（7星以上/暗属性/魔法师族）在自己场上表侧表示特殊召唤。这个效果把「七星道魔术师」特殊召唤的场合，这张卡的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/WJMP-JP002', '监狱之神 迪安·凯特', '【条件】
把1张手卡送去墓地才能发动。
【效果】
确认对方的手卡，从那之中选1张送去墓地。这个效果把怪兽（7星以上）送去墓地的场合，自己回复1000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VC22-JP001', '蓝宝石龙', '全身被蓝宝石覆盖，样子非常美丽的龙。
虽然并不喜欢斗争，却具备很高攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP001', '魔将 岂灭鲁拉', '【条件】
这张卡召唤的回合，对方场上没有攻击表示怪兽的场合，把卡组最上面的卡送去墓地才能发动。
【效果】
这个回合，这张卡可以直接攻击，自己不能用怪兽（战士族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP002', '魔将分队 埋组', '【条件】
自己或者对方场上有表侧守备表示怪兽的场合，把卡组最上面的卡送去墓地才能发动。
【效果】
选对方场上1只表侧表示怪兽，那个攻击力·守备力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP003', '忧路始抹仙女', '【条件】
把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】
选对方场上1只攻击表示怪兽变成表侧守备表示。这个效果变成表侧守备表示的怪兽的守备力直到回合结束时下降600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP004', '不许始末战士', '【条件】
让自己墓地1只怪兽（攻击力0）回到卡组才能发动。
【效果】
选自己场上1只表侧表示怪兽（战士族）。这个回合，那只怪兽的攻击宣言时对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP005', '苍鹰天狗', '冷酷无情的天狗。
面对那毫不留情的严厉指责根本无计可施。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP006', '忧赂缟仙人', '满是烦恼。
严于他人而宽于自己。
就是如此一个仙人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP007', '传说的侍将 正树', '说自己完成了百人斩的传说之侍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP008', '月泪之兔', '流逝的日月。
平淡的日常。
当年真好。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP009', '右手持盾左手持剑', '【条件】
无
【效果】
双方场上的全部表侧表示怪兽的原本的攻击力·守备力直到回合结束时交换。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP010', '行礼石膏绷带', '【条件】
把自己场上1只攻击表示怪兽（7星以上/战士族）变成表侧守备表示才能发动。
【效果】
自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP011', '『攻击』封禁', '【条件】
无
【效果】
选对方场上1只攻击表示的怪兽变成表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP012', '大贯通！！', '【条件】
把1张手卡送去墓地才能发动。
【效果】
选等级相同的自己场上2只表侧表示怪兽。这个回合，那些怪兽的攻击带有贯通（向守备表示怪兽攻击时，给与攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP013', '一同礼状', '【条件】
自己场上有表侧表示怪兽（5星以上）2只以上的场合，对方把怪兽召唤时才能发动。
【效果】
选自己场上1只怪兽回到持有者手卡。可以把自己场上的攻击表示怪兽全部变成表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP014', '仙人的神髓', '【条件】
由自己的表侧表示怪兽（攻击力0）承受攻击的对方怪兽的攻击宣言时才能发动。
【效果】
攻击的怪兽变成表侧守备表示。这个效果把怪兽变成表侧守备表示的场合，可以选自己墓地1只通常怪兽（攻击力0）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP015', '王家魔族·英伦入侵歌手', '【条件】
把2只怪兽（5星以上）解放来把这张卡召唤的回合才能发动。
【效果】
对方场上的表侧表示怪兽（4星以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP016', '王家魔族·死吼歌手', '【条件】
把怪兽（5星以上）解放来把这张卡召唤的回合，把卡组最上面的卡送去墓地才能发动。
【效果】
选对方场上1只表侧表示怪兽（8星以下），那个攻击力·守备力直到回合结束时下降［选的怪兽的等级］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP017', '王家魔族·扎胎朋克乐手', '【条件】
这张卡召唤的回合才能发动。
【效果】
选自己墓地1只怪兽（6星以上/恶魔族）加入手卡。这个回合，自己不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP018', '王家魔族·嘶吼歌手', '【条件】
对方场上有表侧表示怪兽（7星以上）的场合，把1张手卡送去墓地才能发动。
【效果】
对方手卡随机选最多2张送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP019', '宫殿的石像鬼', '【条件】
把1张手卡送去墓地才能发动。
【效果】
这张卡的等级直到回合结束时上升1。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP020', '聪冥之猫头鹰随从', '黑暗真理的探究者。
待在争霸大陆的王身边侍奉左右，其心里实际在想什么则不得而知。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP021', '孤狼 镓尔姆', '拒绝了神之加护的猛兽。
日子虽不安稳但拥有自由。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP022', '子守山羊', '魔界孩子的玩伴。
性格严肃但一看见有纸就会不小心跑去吃掉。
随着主人长大成人，自己也提高了魔力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP023', '王家魔族·骨肉皮', '不擅长看着对方的眼睛说话的女孩。
和同伴们一起追求着真实之爱。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP024', '国王的奖赏', '【条件】
让自己墓地1只通常怪兽（1星/恶魔族）回到卡组才能发动。
【效果】
选对方场上1只表侧表示怪兽（6星以下）破坏。这个效果把怪兽破坏的场合，对方抽1张。这个回合，自己不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP025', '魔人的热风', '【条件】
自己场上有表侧表示怪兽（恶魔族）的场合才能发动。
【效果】
选对方场上1张魔法·陷阱卡回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP026', '国王的威严', '【条件】
对方怪兽的攻击宣言时，让自己墓地1只通常怪兽（1星/恶魔族）回到卡组才能发动。
【效果】
那次攻击无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP027', '激唱魔族摇滚', '【条件】
对方把怪兽召唤时，把手卡2只怪兽（恶魔族）送去墓地才能发动。
【效果】
双方场上的表侧表示怪兽（8星以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP028', '梦弦之折叠式闪电吉他', '【条件】
自己基本分比对方少2000以上的场合才能发动。
【效果】
给与对方1500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP029', '极致贝司手', '【条件】
自己场上有这张卡以外的表侧表示怪兽（念动力族）的场合，支付500基本分才能发动。
【效果】
选自己墓地1只通常怪兽（2星/念动力族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP030', '传心特工', '【条件】
自己基本分比对方少1000以上的场合，让自己墓地1只怪兽（念动力族）回到卡组才能发动。
【效果】
这个回合，这张卡可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP031', '音痴表演者', '【条件】
支付800基本分才能发动。
【效果】
给与对方300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP032', '念能舞台保镖', '近年来超能力威胁日趋增多。
念动力歌后掌握着解决此类事件的关键，自身的命运则托付给能力出众的警卫队。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP033', '现场礼服创造者', '运用超能力创造出舞台服装的设计师。
性格固执不会接受不合己意的人委托。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP034', '神曲键盘手', '乐队里最年少的成员。
虽然老被摇滚话筒歌手等人捉弄，但不论是谁都对其实力给予肯定。
5人全员一起在大舞台举行现场演唱会是她的梦想。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP035', '啸叫鸟', '随风而至伴声而行的飞鸟。
据说其振翅声是反映了听众的内心，有的人听起来是优美歌声，有的人听起来是不祥之音。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP036', '电气念力扩音安瓶', '【条件】
无
【效果】
选自己场上最多2只表侧表示的通常怪兽（2星以下/念动力族），自己基本分回复［选的怪兽的攻击力合计］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP037', '念动力分歧', '【条件】
自己场上有表侧表示怪兽（念动力族）的场合，支付500基本分才能发动。
【效果】
选对方场上1张魔法·陷阱卡回到持有者卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP038', '高潮终场', '【条件】
支付［自己墓地的怪兽（念动力族）数量］×100基本分才能发动。
【效果】
选自己场上1只表侧表示怪兽（念动力族），那个攻击力直到回合结束时上升［自己墓地的怪兽（念动力族）数量］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP039', '念动力前奏', '【条件】
对方把怪兽召唤时才能发动。
【效果】
自己回复［自己场上的表侧表示怪兽（念动力族）数量］×500基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CP01-JP040', '断绝念力壁', '【条件】
由自己的表侧表示怪兽（念动力族）承受攻击的对方怪兽的攻击宣言时，让自己墓地1只怪兽（念动力族）回到卡组才能发动。
【效果】
受到攻击的怪兽的攻击力直到回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP001', '钢铁徽章之阿修罗明星', '「虚钢演机」＋「剑舞者」
【条件】
把卡组最上面的卡送去墓地才能发动。
【选择效果】
●选对方场上1张里侧表示的卡破坏。
●选自己场上1只表侧表示怪兽（电子人族），那个攻击力直到回合结束时上升［对方场上的表侧表示怪兽（战士族）的攻击力合计］', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP002', '钢铁徽章之弗栗多明星', '「虚钢演机」＋「蛇蜿龙」
【条件】
无
【选择效果】
●选对方场上1只怪兽变成表侧攻击表示或者里侧守备表示。
●对方场上的表侧表示怪兽（龙族）选最多有［自己场上的表侧表示怪兽（电子人族）数量］破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP003', '钢铁徽章之赫拉克勒斯明星', '「虚钢演机」＋「魔法杂耍人」
