●选对方场上最多2只表侧表示怪兽（魔法师族）回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP004', '钢铁徽章之拉冬明星', '「虚钢演机」＋「优雅恐龙」
【条件】
把1张手卡送去墓地才能发动。
【选择效果】
●选对方场上1只表侧表示怪兽，那个攻击力·守备力直到回合结束时下降1500。
●对方场上的全部表侧表示怪兽（恐龙族）的攻击力·守备力直到回合结束时下降2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP005', '火焰小丑', '【条件】
自己场上有表侧表示怪兽（5星以上/光属性）的场合，把卡组最上面的卡送去墓地才能发动。
