选对方场上1只表侧表示怪兽（8星以下），那个攻击力·守备力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP006', '虚钢演机', '没有除了笑以外的情感表现的机械人偶。
以观众的情感为能源。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP007', '优雅恐龙', '不喜欢争斗的和蔼恐龙。
总是温和地注视着观众。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP008', '蛇蜿龙', '住过清澈水潭的美丽之龙。
现在以马戏团吉祥物的身份在观众中博得人气。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP009', '剑舞者', '曾经侍奉大国的厉害剑士。
在观众注视下以准确无比的控制掷出飞剑。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP010', '魔法杂耍人', '对过去只字不提而充满谜团的男子。
如魔法一般操纵着魔棒来俘虏观众。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP011', '虚钢演机攻流', '【条件】
把1张手卡送去墓地才能发动。
【效果】
选自己场上1只表侧表示怪兽（9星/光属性）或者表侧表示的通常怪兽（光属性），那个攻击力直到回合结束时上升500。自己墓地有「虚钢演机」的场合，再让选的怪兽的攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP012', '虚钢演机塔', '【条件】
这张卡在自己墓地有通常怪兽（光属性/守备力500）的场合才能发动。
【效果】
只要这张卡在场地区域处于表侧表示，双方场上的表侧表示怪兽（光属性以外）的攻击力下降300，双方场上的表侧表示怪兽（9星/光属性）不会被陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP013', '虚钢演机乱流', '【条件】
自己墓地有通常怪兽（光属性/守备力500）的场合，对方把怪兽召唤·特殊召唤时才能发动。
【效果】
选自己场上1只攻击表示怪兽（8星以上/光属性）变成表侧守备表示。那之后，可以选持有和自己墓地的通常怪兽相同种族的对方场上1只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP014', '虚钢演机再动', '【条件】
自己的攻击表示怪兽（光属性）被对方的攻击破坏时才能发动。
【效果】
