选自己墓地1只「落单使魔」加入手卡。那之后，自己可以抽1张。这个效果抽卡的场合，这个回合，自己不能用怪兽（6星以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
