INSERT INTO "texts" VALUES ('RD/EXT1-JP047', '忠义的护卫刀', '【条件】
对方怪兽的攻击宣言时才能发动。
【效果】
选自己场上1只表侧表示的融合术怪兽。这个回合，那只怪兽不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP048', '战士生还', '【条件】
无
【效果】
选自己墓地1只怪兽（战士族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP049', '天使的施舍', '【条件】
无
【效果】
自己抽3张。那之后，自己选2张手卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/EXT1-JP050', '融合术', '【条件】
无
【效果】
自己场上的表侧表示怪兽作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP008', '最强战旗 黄金超速人', '【条件】
把手卡1只效果怪兽（机械族）送去墓地才能发动。
【效果】
选自己墓地1只通常怪兽（机械族）加入手卡。对方场上的攻击表示怪兽是3只的场合，可以再把手卡1只通常怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP009', '古代炎冰龙', '【条件】
把1张手卡送去墓地才能发动。
【效果】
选对方场上最多2只表侧表示怪兽，那些攻击力直到回合结束时下降400。那之后，可以选自己墓地的「明冰龙」「燃烧烈焰龙」各最多1只在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP010', '可能甜心-旋律：D', '【条件】
让这张卡以外的自己场上1只表侧表示怪兽（5星以上）回到持有者手卡才能发动。
【效果】
选对方场上1张里侧表示的卡回到持有者卡组。自己基本分比对方少的场合，可以再选自己墓地1只通常怪兽（1星/念动力族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP011', '天翔流那 岂灭铁拉斯', '「月魔将 岂灭鲁娜」＋「战天女 哈里基莉」
【条件】
无
【选择效果】
●选自己墓地1只怪兽（攻击力0）加入手卡。
●选对方场上最多2只守备表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP012', '王家魔族·硬摇滚歌手', '【条件】
把2只怪兽（7星以上/恶魔族）解放来把这张卡召唤的回合才能发动。
【效果】
选对方场上1只表侧表示怪兽（7星以上）。给与对方为［选的怪兽和这张卡的攻击力差］的伤害。这张卡的攻击力直到回合结束时上升［选的怪兽的攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP013', '排错擎天神·许德拉粒子机', '【条件】
自己墓地有怪兽（电子界族）3只以上的场合，把卡组最上面的卡送去墓地才能发动。
【效果】
这张卡的攻击力直到回合结束时上升［自己墓地的怪兽数量］×100。自己墓地有怪兽（电子界族）8只以上的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP014', '梦幻刃龙 建造梦幻亚龙', '「幻刃龙 建造龙」＋「幻刃姬 路锥白龙」
【条件】
把自己的场地区域1张卡送去墓地才能发动。
【效果】
选对方场上2只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP016', '真红眼黑龙', '拥有真红之眼的黑龙。
愤怒的黑炎将映入眼里的一切东西烧尽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP017', '地碎', '【条件】
无
【效果】
选对方场上1只守备力最高的表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP018', '火丽鸟 哈耳庇厄', '【条件】
无
【效果】
自己抽1张。那之后，自己选1张手卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP019', '大逆转之女神', '【条件】
自己墓地有「逆转之女神」的场合才能发动。
【效果】
自己抽1张，自己卡组最上面的卡送去墓地。这个效果让怪兽被送去墓地的场合，可以再选持有和那只怪兽相同种族的对方场上2只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP020', '星战骑 福鲁斯', '【条件】
让自己墓地3只相同种族的怪兽回到卡组才能发动。
【效果】
选自己墓地1只通常怪兽（5·6星）在自己场上表侧表示特殊召唤。那之后，可以让对方场上的全部表侧表示怪兽（5星以上）的等级直到回合结束时下降4星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP021', '水晶脑人', '【条件】
这张卡召唤的回合才能发动。
【效果】
把［自己场上的表侧表示怪兽（电子界族）数量］的卡从双方卡组上面送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP022', '以太寻得者', '【条件】
把手卡1张魔法·陷阱卡送去墓地才能发动。
【效果】
选自己场上1只表侧表示怪兽，那个攻击力直到回合结束时上升300。自己墓地有「融合术」的场合，可以再选自己墓地1只「以太探寻者」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP024', '潜入开始', '【条件】
无
【效果】
选自己手卡或者自己墓地1只通常怪兽（7星）在自己场上表侧表示特殊召唤。这个回合，这个效果特殊召唤的怪兽的攻击力上升700，不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP027', '黑·魔·导·响·弹', '【条件】
无
【效果】
选自己场上1只表侧表示怪兽（6星以上/暗属性/魔法师族），那个攻击力直到回合结束时上升1000。自己场上有表侧表示的「黑魔术师」或者「黑魔术少女」的场合，再让选的怪兽的攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP028', '毁灭之爆裂疾风弹', '【条件】
自己场上有表侧表示的「青眼白龙」的场合才能发动。
【效果】
对方场上的怪兽全部破坏。这个回合，自己不能用「青眼白龙」攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP029', '魔法石采掘', '【条件】
把2张手卡送去墓地才能发动。
【效果】
选自己墓地1张魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP030', '一时风锁', '【条件】
对方卡组的卡被送去墓地时才能发动。
【效果】
从自己卡组上面把4张卡送去墓地。那之后，可以让对方手卡随机选1张回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP031', '回手反击', '【条件】
自己场上的魔法·陷阱卡被对方的效果破坏时才能发动。
【效果】
选对方场上1只表侧表示的效果怪兽（攻击力2300以上）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP033', '天之冥福', '【条件】
自己场上的怪兽被对方的攻击或者对方的效果破坏时，自己场上没有其他怪兽的场合才能发动。
【效果】
选对方场上1只表侧表示怪兽变成里侧守备表示。破坏的怪兽是10星的场合，可以再选对方场上1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP034', '逆转之女神', '用神圣之力守护弱者，给予逆转之力的女神。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP035', '翼龙战士', '剑技出众的蜥蜴人。
可以音速舞剑。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP036', '路易斯', '身体虽小，在草原上的守备力却相当强。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP037', '幻刃姬 路锥白龙', '住在透幻乡的幻龙姬君。
很珍惜与同伴们的牵绊。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP038', '阴阳士 唐竹', '【条件】
自己场上有这张卡以外的表侧表示怪兽（战士族）的场合才能发动。
【效果】
给与对方为［对方场上的魔法·陷阱卡数量］×200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP039', '不成哥布林', '【条件】
把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】
选对方场上1只表侧表示怪兽（8星以下），那个攻击力直到回合结束时下降500。那之后，可以选自己墓地1张「成金哥布林」回到卡组上面。回去的场合，可以再选对方场上1只表侧表示怪兽（8星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP040', '正义的同伴 海马侠', '【条件】
把自己场上表侧表示的这张卡送去墓地才能发动。
【效果】
手卡的1只「青眼白龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRP1-JP045', '裂缝掉落', '【条件】
无
【效果】
双方的场地区域的卡全部破坏。这个效果把卡破坏的场合，可以再选对方场上1只表侧表示怪兽那个攻击力·守备力直到回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRC1-JP007', '鹰身女郎', '人形长着翅膀的猛兽。
既优美而华丽地飞舞，又猛锐地展开攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRC1-JP008', '守城的翼龙', '守护山上城寨的龙。
从天空俯冲下来攻击敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SST1-JP001', '穿越侍·线性海牛侍', '沃·图·征！
马尼亚克·尤·歹！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP002', '宇宙勇战机', '【条件】
把1张手卡送去墓地才能发动。
【效果】
选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降800。这个效果的条件把通常怪兽（银河族）送去墓地的场合，再让自己回复800基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP003', '宇宙泰坦', '用5个环来控制的侵略兵器。
将所到之处的文明踏为平地。
杜加伊·布·兹威！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP004', '银河舰健忘龙', '【条件】
让1张手卡回到卡组下面才能发动。
【效果】
选自己墓地2只通常怪兽（6星以下/银河族）在自己场上表侧表示特殊召唤。这个回合，自己不能用怪兽（银河族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP005', '循环轮回蛇', '【条件】
让自己墓地4只怪兽（银河族）回到卡组才能发动。
【效果】
自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP006', '天界星系天使龙', '被托付无秽群星意志的灵龙。
与纯洁之心共鸣来进行攻击。
恩戈尔杜·格艾！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP008', '陨石犀牛', '拥有柔软皮肤的神秘生命体。
为了从宇宙肉食兽那里保护自身而让陨石附在体表。
伊加伊·杜·乌维！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP011', '光明哨兵', '守护秩序的银河士兵。
同伴危机时伴随着闪光赶到。
米久伊·加兰·戈奈杜埃！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP012', '暗影哨兵', '不容邪恶的银河士兵。
强而有力的一击将常暗劈开。
希登里·瓦·亚梅迪埃！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP013', '旋涡射手', '投掷圆盘进行攻击的银河战士。
伊加伊·杜·兹威！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP014', '核球巨人', '与旋涡星系有相似构造的宇宙兵器。
用活动自如的触手来攻击。
瓦贾！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP015', '轨道滑板手', '宇宙中飞奔自如的银河少年。
最近在行星际街头和大人一起游荡。
伊珍杜埃莫·伊杜秀瓦！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP016', '宇宙噗呦', '【条件】
自己墓地有怪兽10只以上的场合才能发动。
【效果】
自己抽1张。那之后，自己选1张手卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP017', '穿越侍·裸海蝶侍', '【条件】
自己场上没有这张卡以外的怪兽的场合才能发动。
【效果】
选自己墓地1只通常怪兽（光属性/银河族）加入手卡。这个回合，自己不能用怪兽（银河族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP018', '星际史莱檬', '由星际物质气体构成的史莱姆。
隐隐散发着来檬的香味哦。
亚西久埃！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP019', '小行星地外生命', '操纵看起来像岩石的UFO在空间移动的宇宙生物。
朱比多格·希久梅！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP022', '银河舰之力', '【条件】
让自己墓地3只怪兽（银河族）回到卡组才能发动。
【效果】
自己场上的全部表侧表示的通常怪兽（银河族）的攻击力直到回合结束时上升［双方场上的表侧表示的通常怪兽数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP025', '宇宙风暴', '【条件】
自己场上有表侧表示怪兽（银河族）的场合才能发动。
【效果】
选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP026', '真空湮灭', '【条件】
自己场上有表侧表示的通常怪兽（7星以上/银河族）的场合，对方怪兽的攻击宣言时才能发动。
【效果】
对方场上的攻击表示怪兽选最多有［自己场上的表侧表示的通常怪兽（银河族）数量］破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP028', '穿越侍到来', '【条件】
自己场上的表侧表示怪兽（银河族）被对方的攻击或者对方的效果破坏时，自己场上没有其他怪兽的场合才能发动。
【效果】
选自己手卡或者自己墓地1只通常怪兽（银河族/攻击力1600以上）在自己场上表侧攻击表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP030', '星云力量', '【条件】
对方把怪兽召唤时才能发动。
【效果】
选自己场上1只表侧表示的通常怪兽（银河族），那个攻击力直到回合结束时上升［对方场上的怪兽数量］×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD2-JP028', '上级封锁', '【条件】
自己基本分比对方少的场合，对方把怪兽（5星以上）召唤时才能发动。
【效果】
那只怪兽变成表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD2-JP021', '夹子翼龙', '用鲜艳夺目的双翼在房间里滑翔的翼龙。
抓住了童心不放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD2-JP008', '报位线圈象', '用电磁波来告知位置的象。
使用长弹簧的绝活很有人气。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD2-JP010', '接合科技王牌', '擅长制作的自律型机器人。
接合部分隐藏着未知的力量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD2-JP030', '接合科技缓冲器', '【条件】
对方怪兽的直接攻击宣言时，让自己墓地3只通常怪兽（机械族）回到卡组才能发动。
【效果】
选对方场上最多3只攻击表示的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD2-JP012', '火炎巫师', '怀着如火热情的魔术师。
那份心情没多久就把他自己的心也燃烧殆尽了。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD2-JP023', '蛋球机器人', '碰巧召唤不球而遇的蛋球机器人。
走一步算一步吧！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD2-JP018', '闪电勇士', '【条件】
让自己墓地3只怪兽回到卡组才能发动。
【效果】
选对方场上1只里侧守备表示怪兽变成表侧守备表示。那之后，可以让对方场上的全部表侧表示怪兽的守备力直到回合结束时下降800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD2-JP006', '齿轮战士', '为战斗而制造的机械战士。
用不生锈金属制成。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD0-JP010', '古之规则', '【条件】
无
【效果】
手卡1只通常怪兽（5星以上）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD0-JP003', '暗之量产工厂', '【条件】
无
【效果】
选自己墓地2只通常怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD0-JP002', '外星人士兵', '神秘生命体外星人的上级战士。
虽然拥有较高的攻击力，另一方面特殊能力却没掌握。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD0-JP001', '漆黑的战士 狼人', '【条件】
无
【永续效果】
对方在双方的战斗阶段中不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD0-JP009', '牲祭人偶', '【条件】
把自己场上1只怪兽送去墓地才能发动。
【效果】
手卡1只怪兽（7星）在自己场上表侧表示特殊召唤。这个回合，这个效果特殊召唤的怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/RLP1-JP001', '加速魔杖手·卵石魔女', '【条件】
这张卡召唤的回合，自己场上没有这张卡以外的怪兽的场合才能发动。
【效果】
选自己墓地1只通常怪兽（魔法师族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP009', '骰子的天使', '【条件】把「天使的骰子」以外的1张手卡送去墓地才能发动。
【效果】选自己墓地1张「天使的骰子」加入手卡。对方场上有怪兽2只以上的场合，再掷1次骰子。6以外出现的场合，自己回复600基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP010', '骰子的恶魔', '【条件】把「恶魔的骰子」以外的1张手卡送去墓地才能发动。
【效果】选自己墓地1张「恶魔的骰子」加入手卡。对方场上有怪兽2只以上的场合，再掷1次骰子。1以外出现的场合，给与对方600伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP011', '骰子的大剑士', '【条件】无
【效果】掷1次骰子。这个回合，这张卡可以作出最多有［出现的数目数量］的攻击。3以下出现的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP012', '骰子的大天使', '【条件】无
【效果】掷1次骰子。自己场上的全部表侧表示怪兽的攻击力·守备力直到回合结束时上升［出现的数目］×100。自己墓地有「天使的骰子」的场合，作为代替而上升［出现的数目］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP013', '骰子的大恶魔', '【条件】无
【效果】掷1次骰子。对方场上的全部表侧表示怪兽的攻击力·守备力直到回合结束时下降［出现的数目］×100。自己墓地有「恶魔的骰子」的场合，作为代替而下降［出现的数目］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP050', '强欲的骰子', '【条件】自己卡组的卡是10张以上的场合，把手卡3张持有掷骰子效果的卡送去墓地才能发动。
【效果】掷1次骰子。自己抽出［出现数目的数量］。3以下出现的场合，可以再选自己墓地的「天使的骰子」「恶魔的骰子」合计最多2张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP000', '堕天使 杰拉特', '自己墓地有卡名不同的怪兽（暗属性）4只以上的场合，这张卡可以把1只怪兽（暗属性）解放攻击表示上级召唤。
【条件】把手卡1只怪兽（暗属性）送去墓地才能发动。
【效果】对方场上的怪兽全部破坏。这个回合的结束阶段这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP001', '小铲警官', '装备有多功能小铲的警官机器人。同时进行农活和警备工作。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP002', '艺术天使·守卫杜比', '从飞天收音机读出来信的新手天使。第一封是署名为烦恼仙人的听众来信。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP003', '艺术天使·图形均衡雷蛇', '从天上堕落的音乐兵器。放出的特殊音波如镭射光般锐利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP004', '艺术天使·CD防御芬达', '曾经活跃于天界的战音女。那虹光闪闪的圆盾无论怎样的攻击都会读取并反弹。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP005', '豌豆战士运动服士', '使用剑和豆子来攻击的运动服战士。想不到还挺强的。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP006', '混沌战士运动服士', '因混沌的运动服式而现身的超战士。用必杀的混沌尼龙剑斩断敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP007', '雪花牙 舞兰度舞兰', '纯真无垢的花精。温柔地回应那信任她的主人心意。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP008', '琴圈盗贼', '好奇心旺盛的见习冒险家。也常和探求祖先宝物的预言乐句盗贼等人共同行动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP009', '不插电盗贼', '有大姐头气质的情报贩子。助追求一族秘密的班卓琴盗贼等人一臂之力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP010', '航天士兵', '【条件】无
【永续效果】自己场上有把装备魔法卡装备的怪兽的场合，这张卡的攻击力上升700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP011', '银河舰空白龙', '【条件】把手卡1张魔法卡送去墓地才能发动。
【效果】选对方的魔法与陷阱区域1张卡回到持有者手卡。那之后，可以选对方场上1只表侧表示怪兽（7星以下/攻击力2500以上）那个攻击力直到回合结束时下降2500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP012', '灯之炎皇 醇灵', '【条件】支付500基本分才能发动。
【效果】选自己墓地1只「灯之炎魔 甲醇灵」或者「灯之炎魔 乙醇灵」在自己场上表侧表示特殊召唤。那之后，自己场上有表侧表示的「灯之炎魔 甲醇灵」和「灯之炎魔 乙醇灵」的场合，这张卡的攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP013', '艺术天使·钻石唱针乐手', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（暗属性/天使族）。这个回合，那只怪兽的攻击带有贯通（向守备表示怪兽攻击时，给与攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP014', '艺术天使·金属磁带乐手', '【条件】自己基本分比对方少的场合，把这张卡以外的自己场上1只表侧表示怪兽（暗属性/天使族）送去墓地才能发动。
【效果】选对方场上1只里侧表示怪兽变成表侧守备表示。那之后，给与对方为［选的怪兽的原本攻击力］的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP015', '企鹅士兵运动服士', '【条件】这张卡召唤的回合，把手卡1只怪兽（守备力500）送去墓地才能发动。
【效果】选对方场上最多2只表侧表示怪兽（4星以下）回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP016', '加农炮兵运动服士', '【条件】自己场上有这张卡以外的表侧表示怪兽（守备力500）的场合，把自己场上1只表侧表示怪兽（守备力500）送去墓地才能发动。
【效果】给与对方500伤害。那之后，可以选对方场上1只表侧表示怪兽（8星以下）那个攻击力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP017', '混沌战士运动服士 -干燥的使者-', '【条件】让自己墓地2只属性不同的怪兽（守备力500）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）回到持有者卡组下面。这个回合，这张卡不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP018', '希花牙 鸢尾', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1张「花牙缝」或者「花牙分身」在自己的魔法与陷阱区域盖放。那之后，自己卡组最下面的卡送去墓地。这个效果让通常怪兽（5星/植物族）被送去墓地的场合，可以再选自己墓地1只通常怪兽（植物族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP019', '莳卷之钢丝弹簧草', '【条件】这张卡召唤的回合，自己场上的表侧表示怪兽只有怪兽（植物族）的场合，让1张手卡回到卡组下面才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之中有怪兽（植物族）的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP020', '鼠小僧盗贼·梅尔', '【条件】自己卡组的卡是15张以上的场合才能发动。
【效果】手卡是0张的玩家抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP021', '乐队合演款待者', '【条件】这张卡召唤的回合，对方手卡是4张以下，自己场上的表侧表示怪兽（3星以外/念动力族）是2只的场合才能发动。
【效果】选对方墓地2只怪兽回到卡组。那之后，对方直到手卡变成5张为止抽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP022', '蓝草音乐偷窃者', '【条件】这张卡召唤的回合才能发动。
【效果】自己卡组最上面的卡送去墓地。这个效果让怪兽（念动力族）被送去墓地的场合，可以再选自己场上1只表侧表示怪兽（念动力族）。这个回合，怪兽（风属性/念动力族）攻击表示上级召唤的场合，选的怪兽可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP023', '高跟反派治疗师', '【条件】让自己墓地1张魔法卡回到卡组才能发动。
【效果】自己回复1000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP024', '风彩之预言乐句盗贼', '【条件】自己场上的表侧表示怪兽只有怪兽（风属性/念动力族）的场合，支付1000基本分才能发动。
【效果】有手卡的玩家把手卡全部送去墓地。那之后，给与对方为［这个效果送去墓地的卡数量］×200伤害。并且，可以再让对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降［这个效果给与对方的伤害］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP025', '风碎之消物哨管海盗', '【条件】自己墓地有怪兽（念动力族）3只以上的场合，支付1000基本分才能发动。
【效果】对方墓地的怪兽（4星以下）选最多有［对方场上的表侧表示怪兽数量］加入对方手卡。那之后，这张卡的攻击力直到回合结束时上升［双方手卡数量合计］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP026', '斗奏之班卓琴盗贼', '【条件】这张卡召唤的回合，支付1000基本分才能发动。
【效果】选自己墓地1只通常怪兽（2星以下/念动力族）加入手卡。那之后，这张卡的攻击力直到回合结束时上升［双方手卡数量合计］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP027', '兽机界 边车阔耳狐', '【条件】让自己墓地2只怪兽（兽战士族）回到卡组才能发动。
【效果】选自己场上1只表侧表示怪兽（兽战士族），那个攻击力直到回合结束时上升400。自己场上有表侧表示的魔法卡的场合，可以再选自己场上1只表侧表示怪兽那个攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP028', '新米寿司天使 沙利叶舍利', '【条件】这张卡召唤·特殊召唤的自己主要阶段，自己场上的表侧表示怪兽是3只的场合才能发动。
【效果】选自己墓地1张「蓄积醋酸的落穴」在自己的魔法与陷阱区域盖放。那之后，可以选自己墓地1只「特上寿司天使 加百列腌姜」或者「极上寿司天使 加百列热茶」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP029', '智能收获者', '【条件】对方场上有怪兽2只以上的场合，把手卡最多2只怪兽（天使族）送去墓地才能发动。
【效果】自己抽出［这个效果的条件送去墓地的怪兽的数量］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP030', '暗黑之炽天使', '【条件】自己场上有表侧表示怪兽（5星以上/暗属性）的场合，支付500基本分才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）变成表侧攻击表示或者里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP031', '拾金而昧侏儒兔', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选对方墓地1张魔法·陷阱卡回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP032', '暗影买主', '【条件】让自己墓地1只怪兽回到卡组才能发动。
【效果】这张卡的等级直到回合结束时上升［对方场上的表侧表示怪兽数量］。这个回合，自己不能用怪兽（恶魔族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP033', '幽灵恶徒', '【条件】自己场上有这张卡以外的表侧表示怪兽（5星/不死族）的场合，支付500基本分才能发动。
【效果】选自己场上1只表侧表示怪兽（5星/不死族）。这个回合，那只怪兽可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP034', '天启之监视者', '【条件】无
【永续效果】对方墓地有怪兽6只以上的场合，这张卡的攻击力上升500，不会被对方怪兽（8星以下）的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP035', '新种掠夺萝卜', '【条件】把卡组最下面的卡送去墓地才能发动。
【效果】这个回合，这张卡不会被对方的陷阱卡的效果破坏。这个效果的条件让怪兽（植物族）被送去墓地的场合，再让这张卡的攻击力直到回合结束时上升700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP036', '打捞狼鱼', '【条件】这张卡召唤·特殊召唤的自己主要阶段，让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（水属性/海龙族）加入手卡。这个效果把「海胆確認生物」加入手卡的场合，再让这张卡的攻击力直到回合结束时上升1400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP037', '花牙一轮 同心·开花', '「花牙美人 昙花」＋「花牙武者 光萼青兰」
【条件】从卡组上面把3张卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（植物族）。这个回合，那只怪兽可以直接攻击。并且，可以再选自己墓地1张「花牙踏」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP038', '花牙一突 邪部凛·道久须', '「花牙忍·我斗凛俱」＋「花牙武者 光萼青兰」
【条件】无
【效果】选对方场上1只表侧表示怪兽破坏。那之后，可以选自己墓地1张「花牙舞回」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP039', '阴阳极士 葛叶', '「阴阳士 刺突」＋「阴阳士 右薙」
【条件】让自己墓地1张魔法·陷阱卡回到卡组下面才能发动。
【效果】对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降［自己墓地的怪兽（攻击力1000/守备力1000）数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP040', '银河舰短剑', '【条件】对方场上有表侧表示怪兽（7·8星）的场合，可以给自己场上1只表侧表示怪兽（银河族）装备。
【效果】装备怪兽的攻击力上升［自己场上的表侧表示的通常怪兽数量］×300。装备怪兽是「银河舰忘却龙」的场合，再让攻击力上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP041', '接合科技超速角枪', '【条件】可以给自己场上1只表侧表示怪兽（机械族）装备。
【效果】装备怪兽的攻击力上升300，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP042', 'QWERTY键盘刃', '【条件】可以给自己场上1只表侧表示怪兽（龙族）装备。
【效果】装备怪兽的攻击力上升［自己场上的表侧表示的魔法卡数量］×200。装备怪兽是暗属性的场合，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP043', '化学化弹·红', '【条件】可以给自己场上1只表侧表示怪兽（炎族）装备。
【效果】装备怪兽的攻击力上升300，那只怪兽不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP044', '虚空噬骸兵斩裂剑', '【条件】可以给自己场上1只表侧表示怪兽（暗属性/银河族）装备。
【效果】装备怪兽的攻击力上升400，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP045', '自动翻带', '【条件】对方场上的怪兽是3只的场合才能发动。
【效果】对方场上的攻击表示怪兽全部变成里侧守备表示。那之后，可以选对方场上最多3只里侧表示怪兽变成表侧攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP046', '混沌的运动服式', '【条件】把自己场上2只怪兽送去墓地才能发动。
【效果】手卡1只怪兽（8星/守备力500）在自己场上表侧表示特殊召唤。这个回合，这个效果特殊召唤的怪兽的攻击力上升500，那攻击带有贯通，不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP047', '运动服式的准备', '【条件】支付500基本分才能发动。
【效果】选自己墓地1只怪兽（8星/守备力500）加入手卡。那之后，可以选自己墓地1张「混沌的运动服式」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP048', '花牙缝', '【条件】自己墓地有通常怪兽（植物族）的场合，从卡组上面把3张卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降［自己墓地的通常怪兽（植物族）数量］×100。自己墓地有通常怪兽（5星）的场合，可以再把对方场上的表侧表示的通常怪兽（7星以上）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP049', '花牙分身', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己场上1只表侧表示的通常怪兽（植物族）。选持有选的怪兽的等级以下的等级的自己墓地最多2只通常怪兽（植物族）在自己场上表侧表示特殊召唤。那之后，自己场上有表侧表示怪兽（5星）的场合，可以把对方场上的表侧表示的通常怪兽（7星以上）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP050', '大道武器-七魔导枪', '【条件】自己场上没有这张卡以外的表侧表示的「大道武器-七魔导枪」的场合，可以给自己场上1只表侧表示的「七星道魔术师」装备。
【效果】装备怪兽的攻击力上升［自己墓地的怪兽的属性种类］×400，那只怪兽不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP051', '炎装 琴品焰形剑', '【条件】可以给自己场上1只原本种族是念动力族的表侧表示怪兽装备。
【效果】装备怪兽的攻击力上升400。只要装备怪兽在自己场上处于表侧表示，对方不能向没有装备魔法卡装备的怪兽攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP052', '重装 双琴颈断钢剑', '【条件】可以把手卡1只怪兽（风属性/念动力族）送去墓地，给自己场上1只表侧表示怪兽（念动力族）装备。
【效果】装备怪兽1回合可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP053', '圣装 背带主教斯式琴', '【条件】可以给自己场上1只表侧表示怪兽（念动力族）装备。
【效果】装备怪兽的攻击力上升100，守备力上升1500，那只怪兽不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP054', '即兴果酱音跃：P校音！', '【条件】自己场上有包含通常怪兽的表侧表示怪兽（念动力族）2只以上的场合才能发动。
【效果】选对方场上最多2张里侧表示的魔法·陷阱卡确认，从那之中选1张破坏。自己场上有表侧表示的「可能甜心：D」的场合，再让自己可以回复1000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP055', '乐姬的前奏曲', '【条件】自己场上没有怪兽的场合才能发动。
【效果】手卡1只怪兽（风属性）在自己场上表侧表示特殊召唤。这个效果把怪兽（战士族）特殊召唤的场合，可以再选自己墓地1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP056', '吹过之风', '【条件】把手卡1只怪兽（风属性）送去墓地才能发动。
【效果】自己抽1张。自己场上有表侧表示怪兽（风属性/攻击力1800以上）2只以上的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP057', '扫神降临', '【条件】把手卡2只怪兽（天使族）给对方观看才能发动。
【效果】选自己墓地1只怪兽（7星以上/天使族）在自己场上表侧表示特殊召唤。这个效果把「扫风之阿扎雷斯」以外的怪兽特殊召唤的场合，再让自己选手卡2只怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP058', '兽剑 虎齿剑', '【条件】可以给自己场上1只表侧表示的通常怪兽（攻击力1400以下）装备。
【效果】装备怪兽的攻击力上升900。怪兽攻击表示上级召唤的场合，装备怪兽可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP059', '升阵的装备品', '【条件】可以给自己场上1只表侧表示怪兽装备。
【效果】装备怪兽的等级上升2星，攻击力·守备力上升200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP060', '网站预览', '【条件】对方把魔法卡发动后才能发动。
【效果】选自己墓地1只怪兽（4星以下）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP061', '蓝之牢狱', '【条件】对方把怪兽召唤·特殊召唤时，把自己场上1只怪兽送去墓地才能发动。
【效果】这个回合，双方不能从墓地把怪兽（7·8星）特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP062', '割削光环', '【条件】由自己的攻击表示怪兽（天使族）承受攻击的对方怪兽的攻击宣言时，支付500基本分才能发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP063', '放回充能运动服', '【条件】对方把怪兽（5星以上）表侧表示召唤·特殊召唤时，支付500基本分才能发动。
【效果】选自己场上1只表侧表示怪兽（守备力500），那个攻击力直到回合结束时上升500。那之后，可以选对方墓地最多5只怪兽回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP064', '火场盗贼怪力', '【条件】自己的魔法与陷阱区域的卡被对方的效果破坏时才能发动。
【效果】选自己墓地最多2张魔法·陷阱卡在自己的魔法与陷阱区域盖放。那之后，可以选自己场上最多3只表侧表示怪兽（7星以上/念动力族）。选的场合，这个回合，那些怪兽不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP11-JP065', '复仇极斧', '【条件】对方把怪兽表侧表示召唤·特殊召唤时才能发动。
【效果】选自己场上1张魔法·陷阱卡破坏。这个效果把装备魔法卡破坏的场合，可以再选那1只召唤·特殊召唤的怪兽（8星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP019', '电子终结龙', '「电子龙」＋「电子龙」＋「电子龙」
【条件】
无

【永续效果】
这张卡的攻击带有贯通（向守备表示怪兽攻击时，给与攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP020', '电子双生龙', '「电子龙」＋「电子龙」
【条件】
无

【永续效果】
这张卡1回合可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP021', '电子超速龙', '「电子龙」＋「电子龙」
【条件】
对方场上有怪兽的场合才能发动。

【效果】
自己直到手卡变成5张为止抽卡。那之后，自己选4张手卡送去墓地。并且，可以再把手卡1只怪兽（机械族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP022', '电子强袭龙', '这张卡可以把1只表侧表示的「电子龙」解放攻击表示上级召唤。

【条件】
让自己墓地1只「电子龙」回到卡组上面才能发动。

【效果】
选对方场上1只表侧表示怪兽（8星以下/攻击力2400以上）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP023', '电子隐形龙', '这张卡可以把1只表侧表示的「电子龙」解放攻击表示上级召唤。
【条件】
无

【永续效果】
自己墓地有「电子龙」的场合，这张卡的守备力上升2000，不会被对方怪兽的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP024', '电子龙', '只有对方场上才有怪兽的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】
无

【效果】
无', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP025', '电子狮鹫', '【条件】
把1张手卡送去墓地才能发动。

【效果】
选自己场上1只表侧表示怪兽（5星以上/机械族）。这个回合，那只怪兽不会被对方的陷阱卡的效果破坏。那只怪兽是光属性的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP026', '原始电子龙', '【条件】
无

【永续效果】
这张卡的卡名变成「电子龙」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP027', '电子巨蛇', '【条件】
自己场上有这张卡以外的表侧表示怪兽（光属性/机械族）的场合才能发动。

【效果】
从自己卡组上面把3张卡送去墓地。这个效果让怪兽（光属性/机械族）2只以上被送去墓地的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP028', '进化超速光焰', '【条件】
自己场上有表侧表示怪兽（5星以上/机械族）的场合，让自己墓地5只怪兽（光属性/机械族）回到卡组才能发动。


【效果】
选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP029', '电子突入', '【条件】
自己墓地有怪兽（光属性/机械族）3只以上的场合才能发动。


【效果】
选自己手卡或者自己墓地1只「电子龙」或者「原始电子龙」在自己场上表侧表示特殊召唤。这个回合，自己不用怪兽（光属性/机械族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP030', '复合转接装置', '【条件】
对方把怪兽召唤时，把自己场上1只表侧表示怪兽（5星以上/机械族）送去墓地才能发动。


【效果】
那只召唤的怪兽变成里侧守备表示。那之后，可以选自己墓地1只「电子强袭龙」或者「电子隐形龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP022', '电子搜索龙', '这张卡可以把1只表侧表示的「电子龙」解放攻击表示上级召唤。
【条件】
这张卡召唤·特殊召唤的自己主要阶段，让1张手卡回到卡组上面才能发动。

【效果】
选自己墓地1只「电子龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP044', '碧科技爆速霸王龙', '「碧牙爆速龙」+「接合科技霸王龙」
【条件】这张卡聚变召唤的自己主要阶段，可以使自己墓地的3只怪兽返回卡组发动。
【效果】选对手场上的最多3张里侧表示的卡破坏，这张卡的攻击力直到回合结束时上升[破坏的卡的数量]×500。那之后，可以使对手场上的全部表侧表示怪兽的攻击力直到回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP009', '化学宠物 鹦鹦', '【条件】自己场上没有这张卡以外的怪兽的场合，可以向对手展示手牌的1只怪兽（炎族·水族·雷族）发动。
【效果】从自己卡组上面将3张卡送入墓地。那之后，可以从那之中选1只拥有与[这个效果的条件展示的怪兽的等级]相同等级的怪兽（炎族·水族·雷族）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP018', '电子空间香料忍 肉豆蔻', '这张卡可以将1只怪兽（电子空间族）解放来以攻击表示高等召唤。
【条件】无
【效果】双方卡组最上面的卡送入墓地。那之后，自己可以从那之中选1张返回持有者卡组上面或下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP046', '电子空间香料忍 肉桂女王', '「电子空间香料忍 肉桂」+「电子空间香料忍炖锅」
【条件】可以使自己墓地的3只怪兽返回卡组发动。
【效果】双方从自身卡组上面将2张卡翻开，双方确认。那之后，给予对手[那之中的怪兽的等级合计]×100伤害。双方使自身翻开的卡返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP015', '电子空间香料忍 姜黄', '【条件】自己卡组的卡为10张以上，自己场上有这张卡以外的表侧表示怪兽（炎属性/电子空间族）的场合可以发动。
【效果】选对手的魔法陷阱区的1张里侧表示的卡确认。那张卡是陷阱卡的场合，再使自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP038', '暗物质皇帝龙', '「暗物质龙」＋「接触体·暗物质飞龙」
这张卡可以用接触融合术（自己场上的上记的表侧表示怪兽作为素材回到持有者卡组作融合术召唤）。
【条件】自己场上有里侧表示怪兽的场合才能发动。
【效果】选自己或者对方场上的里侧表示的卡合计2张破坏。这个回合，这张卡的攻击力上升2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP048', '暗物质谜团之母', '「暗物质迷雾」+「暗物质迷雾」
【条件】无
【永续效果】这张卡的攻击力上升[这张卡聚变召唤时作为素材的怪兽的原攻击力的合计]。自己场上有里侧表示怪兽的场合，这张卡不会被对手的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP029', '龙力魂灵', '【条件】自己墓地的怪兽只有多头龙族·龙族的场合，可以将自己场上的2只表侧表示的效果怪兽（等级4以下）送入墓地发动。
【效果】选自己墓地的1只怪兽（等级7/地属性·暗属性/攻击力2500）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP052', '混合驱动回归聚变', '【条件】可以使自己墓地的合计4只怪兽（龙族·机械族）返回卡组发动。
【效果】对手选自身墓地的1只怪兽以里侧守备表示特殊召唤到自身的场上。那之后，自己可以使自己墓地的怪兽（龙族）1只和怪兽（机械族）1只作为素材返回卡组来聚变召唤。这个效果发动后，直到回合结束时自己只能用聚变怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP006', '混合驱动螺丝起子龙', '【条件】可以使自己墓地的2只怪兽（龙族）和2只怪兽（机械族）按照喜欢的顺序返回卡组下面发动。
【效果】选自己或者对手场上的1只怪兽破坏。并且再直到下个对手回合结束时使双方不能将原卡名与用这个效果破坏的怪兽相同的怪兽以表侧表示召唤或特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP004', '青眼幻像龙', '自己场上有表侧表示怪兽（等级8以上/龙族）的场合，这张卡可以从手牌以表侧守备表示特殊召唤到自己的场上。
【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这个回合，这张卡的卡名变为「青眼白龙」，自己要融合召唤「青眼究极龙」的场合，表侧表示的这张卡可以作为2只的分量的素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP007', '落单使魔女', '【条件】自己场上没有这张卡以外的怪兽的场合可以发动。
【效果】选自己墓地的1只「七道魅力魔女」或者「七道魔女」以表侧表示特殊召唤到自己的场上。那之后，可以选自己墓地的1张「融合」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD01-JP011', '水母穿越侍', '【条件】自己场上有表侧表示怪兽（攻击力1600以上）的场合，可以将卡组最上面的卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（等级4/光属性/银河族）。这个回合，那只怪兽可以对怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP010', '焰魔神 蝇光蛇三魔[L]', '【条件】极限模式
【永续效果】这张卡不会被与通常怪兽所作的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP011', '焰魔神 蝇光蛇三魔', '和「焰魔神 蝇光蛇三魔[L]」「焰魔神 蝇光蛇三魔[R]」集齐可以极限召唤。
【条件】极限模式
【永续效果】这张卡的等级上升6，不会被对手的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP012', '焰魔神 蝇光蛇三魔[R]', '【条件】极限模式：可以将卡组最上面的卡送入墓地发动。
【效果】这个回合，这张卡的攻击力上升600，其攻击会贯通（攻击守备表示怪兽时，给予其攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GRD1-JP007', '银白赛弗特', '为寻求强者而浪迹银河的骑士。奎因杜拉角迈·久因杜莱吉迈！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP057', '机装星11-水瓶座', '【条件】对手场上有2只以上的表侧表示怪兽的场合可以发动。
【效果】从自己卡组上面翻开4张卡，双方确认。[翻开的卡之中的怪兽的等级合计]为11以上的场合，可以选对手场上的1只怪兽破坏。翻开的卡返回卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP007', '终焰魔神 绝望大炎魔[L]', '【条件】无
【永续效果】这张卡不会被对手的陷阱卡的效果破坏。这张卡是极限模式的场合，再使这张卡不会被对手的魔法卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP008', '终焰魔神 绝望大炎魔', '和「终焰魔神 绝望大炎魔[L]」「终焰魔神 绝望大炎魔[R]」集齐可以极限召唤。
【条件】可以将手牌的2只极限怪兽送入墓地发动。
【效果】选对手场上的1张卡破坏。这张卡是极限模式的场合，自己再抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP009', '终焰魔神 绝望大炎魔[R]', '【条件】无
【永续效果】双方不能从手牌或墓地特殊召唤怪兽（等级7）。这张卡是极限模式的场合，再使对手不能将手牌的怪兽盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP040', '幻坏熔龙 暗冥爆破龙王', '「幻坏龙 爆破龙王」+「暗冥幻影炸药龙」
【条件】无
【效果】从对手牌组上面将3张卡送入墓地。那之中有怪兽的场合，可以再选最多为[用这个效果送入墓地的怪兽的数量]的对手场上的里侧表示的卡破坏。那之后，给予对手[用这个效果破坏的卡的数量]×500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP041', '暗物质谜团隐雷兽·潜地', '「暗物质深潜獾」＋「暗物质秘雾法师」
【条件】这张卡是攻击表示的场合，把1张手卡送去墓地才能发动。
【效果】直到下次的对方回合结束时，这张卡的卡名变成「暗物质谜团之母」，这张卡在攻击表示的期间不会被战斗破坏。并且自己场上的里侧表示怪兽是2只的场合，这个回合，这张卡可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP007', '深空宇宙世界树龙', '「宇宙世界树龙」+「宇宙世界树龙」+「宇宙世界树龙」
【条件】无
【永续效果】这张卡不会被效果破坏，其攻击会贯通。对手场上的表侧表示怪兽（等级7以上）的攻击力下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP040', '暗物质噬兵 镇魂鹰巨人·欧米伽', '「虚空噬骸兵 镇魂鹰巨人」＋「接触体·暗物质欧米伽旅行者号」
这张卡可以用接触融合术（自己场上的上记的表侧表示怪兽作为素材回到持有者卡组作融合术召唤）。
【条件】这张卡特殊召唤的自己主要阶段才能发动。
【效果】选对方场上1张表侧表示的卡和1张里侧表示的卡破坏。这个回合，这张卡的攻击力上升1300，这张卡不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP039', '暗物质噬兵 镇魂鹰巨人', '「虚空噬骸兵 镇魂鹰巨人」＋「接触体·暗物质旅行者号」
这张卡可以用接触融合术（自己场上的上记的表侧表示怪兽作为素材回到持有者卡组作融合术召唤）。
【条件】这张卡特殊召唤的自己主要阶段才能发动。
【效果】选对方场上1只表侧表示怪兽变成里侧守备表示。这个回合，这张卡的攻击力上升1300，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP064', '龙力支配', '【条件】对手召唤或特殊召唤怪兽时可以发动。
【效果】给予对手400伤害。自己场上有表侧表示怪兽（等级7以上/龙族）的场合，可以再选对手场上的1只表侧表示的效果怪兽（等级8以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP028', '升腾之吉尔福德', '这张卡不能特殊召唤。
【条件】这张卡召唤的回合，可以使自己墓地的2只怪兽（战士族）返回卡组发动。
【效果】这个回合，这张卡可以对怪兽作3次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP011', '二咒葬之龙', '【条件】可以从卡组上面将2张卡送入墓地发动。
【效果】自己恢复200LP。那之后，可以选自己墓地的1张「龙之二咒葬」盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP060', '龙之二咒葬', '【条件】自己场上有表侧表示怪兽（多头龙族或者龙族）的场合，对手怪兽的攻击宣言时可以发动。
【效果】受到那次攻击的自己怪兽由自己重新选。自己场上有2只以上的同名的表侧表示怪兽的场合，可以再选对手场上的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP006', '传说的交点龙', '【条件】这张卡召唤的回合可以发动。
【效果】将自己卡组最上面的卡送入墓地。那之后，可以选自己墓地的1只「传说的原石」或者1张「传说的圣所」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP026', '人造人7.7号', '【条件】可以使自己墓地的1只怪兽返回卡组下面发动。
【效果】这个回合，这张卡可以直接攻击。并且，可以再选自己墓地的1张「机器检查员」或者「电脑加速器」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP050', '青眼激煌龙', '「青眼白龙」+怪兽（等级8/光属性/龙族）
【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到下个对手回合结束时上升500。自己墓地有「不可估量的破坏力」的场合，可以再选对手场上的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP057', '机器检查员', '【条件】无
【效果】双方从自身卡组上面翻开4张卡，双方确认。自己可以从那8张之中选合计最多2张怪兽（机械族）或者陷阱卡送入墓地。双方使自身的剩下的卡按照喜欢的顺序返回卡组下面。用这个效果将陷阱卡送入墓地的场合，再使自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP047', '疾风之龙骑士盖亚', '怪兽（战士族/守备力2100）+「诅咒之龙」
【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这个回合，这张卡的攻击会贯通。自己的手牌为0张的场合，可以再使自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP032', '永久磁石战士α', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的卡名在这个回合变为「磁石战士α」。那之后，可以将自己的手牌或场上的怪兽（岩石族）作为素材送入墓地来聚变召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP024', '磁石之翼 磁石武神', '「磁石战士α」+「磁石战士β」+「磁石战士γ」
【条件】可以使自己墓地的3只怪兽返回卡组发动。
【效果】这个回合，这张卡不会被效果破坏。并且，可以再选对手场上的1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP033', '永久磁石战士β', '【条件】将卡组最上面的卡送入墓地才能发动。
【效果】这张卡的卡名在这个回合变为「磁石战士β」。那之后，可以将自己的手牌或场上的怪兽（岩石族）作为素材送入墓地来聚变召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP030', '弹射宝贝龟', '【条件】可以将1张手牌送入墓地发动。
【效果】选对手墓地的2只怪兽返回卡组。那之后，可以选自己墓地的1只「龙骑士盖亚」或者怪兽（水族/守备力2000）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP035', '磁石充雷', '【条件】可以将手牌的1只怪兽（岩石族）送入墓地发动。
【效果】自己抽2张。自己场上有原攻击力为3500的表侧表示怪兽（岩石族）的场合，可以再选对手场上的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP036', '磁石回归', '【条件】可以将自己场上的1只表侧表示怪兽（等级4以下/岩石族）送入墓地发动。
【效果】选自己墓地的1只怪兽（等级7或8/岩石族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP034', '永久磁石战士γ', '【条件】将卡组最上面的卡送入墓地才能发动。
【效果】这张卡的卡名在这个回合变为「磁石战士γ」。那之后，可以将自己的手牌或场上的怪兽（岩石族）作为素材送入墓地来聚变召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP037', '电磁石双剑', '【条件】可以装备给自己场上的1只表侧表示怪兽（岩石族）。
【效果】装备怪兽的攻击力上升300。装备怪兽是「团结战士 磁石武神」的场合，装备怪兽1回合最多2次可以对怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP028', '磁石战士 磁石始神', '【条件】可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选自己墓地的最多2只通常怪兽（岩石族）加入手牌。那之后，可以将自己的手牌或场上的怪兽（岩石族）作为素材送入墓地来聚变召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP026', '磁石骑士α', '「磁石战士α」+怪兽（等级4以下/岩石族）
【条件】这张卡特殊召唤的自己的主要阶段可以发动。
【效果】选自己墓地的「电磁双剑」「斥力」各最多1张盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP038', '斥力', '【条件】对手召唤或特殊召唤怪兽时或者对手怪兽的攻击宣言时，可以使自己墓地的3只怪兽（岩石族）返回卡组发动。
【效果】选对手场上的1只表侧表示怪兽变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP025', '团结战士 磁石武神', '「磁石战士α」+「磁石战士β」+「磁石战士γ」
【条件】可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选自己墓地的「磁石战士α」「磁石战士β」「磁石战士γ」各1只以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP029', '念力震慑者·电脑增幅', '墓地的这张卡的卡名变为「人造人-念力震慑者-」。
【条件】可以将卡组最上面的卡送入墓地发动。
【效果】这个回合，这张卡不会被对手的陷阱卡的效果破坏。并且，可以再使这张卡的攻击力直到回合结束时上升[自己墓地的怪兽（机械族）的数量]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP056', '电脑加速器', '这张卡的效果不会被无效化。
【条件】可以装备给自己场上的1只表侧表示怪兽（机械族）装备。
【效果】装备怪兽的攻击力上升300。装备怪兽的原卡名是「人造人-念力震慑者-」的场合，其永续效果作为「对手不能将陷阱卡发动，对手的陷阱卡的效果无效化」适用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP025', '真红眼月龙', '手牌的这张卡的卡名变为「真红眼黑龙」。
【条件】无
【永续效果】要将这张卡作为聚变召唤的素材的场合，这张卡的卡名变为「真红眼黑龙」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP063', '流星光坠', '【条件】自己墓地有3只以上的怪兽（龙族）的场合，对手怪兽的攻击宣言时可以发动。
【效果】攻击过来的怪兽的攻击力直到回合结束时下降1000。那之后，可以选自己墓地的1张「流星炎聚变」盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP024', '陨石龙之雏', '【条件】这张卡召唤的回合可以发动。
【效果】选自己墓地的1只怪兽（地属性/龙族/攻击力1800）加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP058', '陨石龙之爪', '【条件】可以装备自己场上的1只表侧表示怪兽（地属性·炎属性·暗属性/龙族）。
【效果】装备怪兽的攻击力上升300。装备怪兽是效果怪兽以外的聚变怪兽的场合，再使其攻击力上升700，那只怪兽不会被对手的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP046', '流星群龙', '「流星之龙」+「流星之龙兽」
【条件】无
【效果】选自己墓地的1只怪兽（地属性/龙族/攻击力1800）以表侧守备表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP057', '流星炎聚变', '【条件】无
【效果】将包含「真红眼黑龙」「恶魔的召唤」「流星之龙」其中任意1种的自己的手牌或场上的2只怪兽作为素材送入墓地来聚变召唤。用这个效果将效果怪兽以外的怪兽特殊召唤的场合，可以再选对手场上的1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP028', '流星之龙兽', '自己场上没有怪兽的场合，这张卡可以从手牌以表侧表示特殊召唤到自己的场上。
【条件】无
【效果】从自己卡组上面翻开4张卡，双方确认。自己可以从翻开的卡之中选1只「流星之龙」或者1张「流星炎聚变」加入手牌。剩下的卡按照喜欢的顺序返回卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP047', '流星黑龙兽', '「真红眼黑龙」+「流星之龙兽」
【条件】自己墓地有「流星炎聚变」的场合，可以将卡组最上面的卡送入墓地发动。
【效果】这张卡直到下个对手回合结束时不会被对手的效果破坏。自己墓地有2张以上的「流星之龙」的场合，再给予对手500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP026', '飞龙黑骑士', '【条件】自己墓地有「飞龙战士」或者怪兽（暗属性/守备力1200）的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽（等级8以下）变为里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP048', '流星黑火星龙', '「真红眼黑龙」+「流星之龙」
【条件】自己墓地有「流星之龙」的场合，可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[自己墓地的怪兽的数量]×200，其攻击会贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP001', '色谱气斗士', '身体汽化熊熊燃烧。我斗志若不消我身躯必不灭。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP012', '妖鸟正装', '【条件】可以装备自己场上的1只表侧表示的「妖鸟女郎」或者「妖鸟三姐妹」。
【效果】装备怪兽的攻击力上升800，守备力上升400。自己场上的表侧表示怪兽为1只或者3只的场合，装备怪兽的攻击会贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP009', '妖鸟甜心', '【条件】无
【效果】选自己墓地的1张「妖鸟正装」盖放到自己的魔法陷阱区。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP001', '妖鸟三姐妹[L]', '墓地的这张卡的卡名变为「妖鸟三姐妹」。
【条件】无
【永续效果】这张卡的卡名变为「妖鸟三姐妹」，不会被对手的陷阱卡的效果破坏。这张卡是极限模式的场合，再使这张卡的等级上升5。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP002', '妖鸟三姐妹', '和「妖鸟三姐妹[L]」「妖鸟三姐妹[R]」集齐可以极限召唤。
【条件】可以使自己墓地的2只怪兽（风属性/鸟兽族）返回卡组发动。
【效果】选自己场上的1只表侧表示怪兽，其攻击力直到回合结束时上升500。这张卡是极限模式的场合，再给予对手500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP003', '妖鸟三姐妹[R]', '墓地的这张卡的卡名变为「妖鸟三姐妹」。
【条件】无
【永续效果】这张卡的卡名变为「妖鸟三姐妹」，不会被对手怪兽的效果破坏。这张卡是极限模式的场合，更使这张卡1回合可以对怪兽作3次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP008', '妖鸟女君王', '【条件】自己场上有这张卡以外的表侧表示怪兽（风属性/鸟兽族）的场合，可以将1张手牌送入墓地发动。
【效果】自己抽1张。自己场上有表侧表示的通常怪兽的场合，可以再选自己墓地的1只「妖鸟女郎」或者「妖鸟三姐妹」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP016', '妖鸟的羽毛风暴', '【条件】对手召唤怪兽时，可以使自己墓地合计2只的「妖鸟女郎」「妖鸟三姐妹」返回卡组发动。
【效果】那只召唤的怪兽破坏。这个效果的条件使通常怪兽返回卡组的场合，可以再选对手场上的1只怪兽变更表示形式（攻击表示变为表侧守备表示，守备表示变为表侧攻击表示）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP024', '深渊海兽 安渚', '【条件】可以将手牌的1只怪兽（海龙族）送入墓地发动。
【效果】自己抽1张。那之后，可以选自己墓地的1只怪兽（等级10/海龙族/攻击力2500）或者1张「深渊海兽究极战甲」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP025', '深渊海兽 凛梦', '【条件】可以将手牌的1只怪兽（守备力0）送入墓地发动。
【效果】选对手墓地的最多3只怪兽返回卡组。那之后，可以选自己墓地的1只怪兽（等级10/海龙族/攻击力2400）或者1张「深渊海兽阻挡壁」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP026', '深渊海兽 卡涟', '【条件】可以将手牌的1只怪兽（光属性）送入墓地发动。
【效果】从自己卡组上面将3张卡送入墓地。那之后，可以选自己墓地的1只怪兽（等级10/海龙族/攻击力2200）或者1张「深渊海兽守护」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP040', '深渊海兽奇迹少女组', '【条件】自己场上有这张卡以外的表侧表示怪兽（海龙族）的场合，可以将卡组最上面的卡送入墓地发动。
【效果】这张卡的攻击力直到下次对手回合结束时上升1600。自己墓地有「深渊海兽派对」的场合，再使这张卡直到下次的对手回合结束时不会被对手的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP052', '深渊海兽地图绘制', '墓地的这张卡的卡名变为「深渊海兽阻挡壁」。
【条件】无
【效果】自己恢复[自己场上的表侧表示怪兽（海龙族）的数量]×300LP。那之后，可以选自己墓地的1张「深渊海兽派对」加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP061', '深渊海兽单色光', '【条件】对手怪兽的攻击宣言时可以发动。
【效果】选双方墓地的合计3只怪兽（等级4以下/光属性·暗属性）返回持有者卡组。那之后，攻击的怪兽的攻击力直到回合结束时下降[被这个效果返回的怪兽的等级合计]×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP053', '深渊海兽派对', '【条件】无
【效果】将[自己场上的表侧表示怪兽（海龙族）的数量]的卡从双方卡组上面送入墓地。那之后，可以选原攻击力为800的自己场上的最多3只表侧表示怪兽（光属性/海龙族）使其攻击力直到下个对手回合结束时上升1600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VSP1-JP050', '深渊海兽守护', '【条件】对手将怪兽（等级5以上）以表侧表示召唤或特殊召唤时可以发动。
【效果】选自己场上的1只表侧表示怪兽（海龙族），其攻击力直到回合结束时上升1000。选的怪兽是极限怪兽的场合，再使那只怪兽这个回合不会被对手的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP055', '深渊海兽违逆光环', '墓地的这张卡的卡名变为「深渊海兽究极战甲」。
【条件】可以装备自己场上的1只表侧表示怪兽（海龙族）。
【效果】装备怪兽的攻击会贯通。自己场上有里侧表示的魔法陷阱卡的场合，自己不会因对手的效果受到伤害。自己场上有2张以上的里侧表示的魔法陷阱卡的场合，装备怪兽不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VSP1-JP049', '深渊海兽阻挡壁', '【条件】由自己的表侧表示怪兽（海龙族）承受攻击的对手怪兽的攻击宣言时可以发动。
【效果】受到攻击的怪兽不会被那次战斗破坏。受到攻击的怪兽是极限模式的场合，再使自己恢复1000LP。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VSP1-JP048', '深渊海兽究极战甲', '【条件】有卡被送入对手的墓地时，可以将这张卡以外的自己场上的1张魔法陷阱卡送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（海龙族），其攻击力直到回合结束时上升1000，自己恢复1000LP。那只怪兽是极限怪兽的场合，再使那只怪兽这个回合不会被战斗和对手的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP057', '线性海牛穿越侍-沃·图·征！', '【条件】自己场上有这张卡以外的表侧表示怪兽（光属性/攻击力1400以下）的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽（攻击力1500以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP058', '大力线性海牛穿越侍', '「线性海牛穿越侍」+怪兽（等级4/银河族）
【条件】让自己墓地2只怪兽返回卡组才能发动。
【效果】这个回合，这张卡的攻击力上升1000，这张卡不能直接攻击。这个效果的条件使「碟状幼体穿越侍」返回的场合，再在这个回合使这张卡的攻击力上升2600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CGR3-JP001', '变星之线性海牛穿越侍', '「线性海牛穿越侍」+怪兽（等级7/光属性/银河族）
【条件】可以使自己墓地的2只怪兽（银河族）返回卡组发动。
【效果】这张卡的攻击力直到回合结束时上升1400。这个效果的条件使2只效果怪兽（等级7）返回的场合，再在这个回合使这张卡不会被战斗和对手的陷阱卡的效果破坏，可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP039', '高天穿越侍 全铠甲新星', '「高天穿越侍·铠甲新星」+「线性海牛穿越侍」
【条件】无
【永续效果】这张卡的攻击力上升[双方墓地的怪兽的种族种类]×300。双方墓地的怪兽的种族为5种类以上的场合，这张卡不会被对手的效果破坏，10种类以上的场合，再使这张卡的攻击力上升3000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/CGR2-JP001', '线性海牛穿越侍·超越光', '【条件】可以将卡组最上面的卡送入墓地发动。
【效果】选自己或者对手场上的1只表侧表示怪兽（等级4以上），其等级直到回合结束时下降3。那之后，这张卡的攻击力直到回合结束时上升500。自己的墓地有「线性海牛穿越侍」的场合，再使这个回合这张卡的卡名变为「线性海牛穿越侍」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP008', '高天穿越侍·铠甲新星', '这张卡可以将1只或者3只怪兽解放来以攻击表示高等召唤。用这个方法将1只解放的场合，这张卡的原攻击力变为1800。
【条件】无
【永续效果】将3只怪兽解放来召唤的这张卡的攻击力上升[这张卡召唤时解放的怪兽的原等级的合计]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP041', '大传说的剑士', '手卡或者墓地的这张卡变为传说卡。
【条件】将手卡的1只「传说的剑士」或者1张传说卡给对手观看才能发动。
【效果】这个回合，这张卡的攻击力上升500，可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP042', '大传说的魔术师', '手卡或者墓地的这张卡变为传说卡。
【条件】将手卡的1只「传说的魔术师」或者1张传说卡给对手观看才能发动。
【效果】选对手场上的1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP043', '大传说的祭司', '手卡或者墓地的这张卡变为传说卡。
【条件】这张卡召唤·特殊召唤的自己主要阶段，将自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选对手场上的1只表侧表示怪兽（等级10以下）破坏。那之后，可以选自己的墓地的1只「传说的祭司」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP044', '传说的祭司', '手卡或者墓地的这张卡变为传说卡。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己的卡组上方将3张卡送去墓地。那之后，自己的墓地有传说卡的场合，可以选对手场上的1只表侧表示怪兽那个攻击力·守备力直到回合结束时下降600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP049', '传说的魔法师', '【条件】无
【效果】从自己卡组上面翻开3张卡，双方确认。自己可以从那之中选1只怪兽送入墓地。剩下的卡返回卡组。那之后，可以选自己墓地的1只传说通常怪兽加入手牌。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP057', '传说的一击', '【条件】支付300基本分才能发动。
【效果】选自己墓地1只怪兽（4星/攻击力1600以下）或者传说通常怪兽在自己场上表侧表示特殊召唤。这个效果把「传说的魔术师」或者传说通常怪兽特殊召唤的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP001', '元素英雄 火焰翼人', '「元素英雄 羽翼侠」＋「元素英雄 爆热女郎」
这张卡只能用聚变召唤来特殊召唤。
【条件】无
【永续效果】这张卡用战斗将怪兽破坏并送入墓地时，给予对手[那只怪兽的原攻击力]的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP004', '元素英雄 新宇侠', '从新宇宙来的新元素英雄。藉由与新空间侠接触融合，发挥未知的力量！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP005', '元素英雄 电光侠', '熟练使用各种武器，元素英雄中的光之战士。用神圣的光辉，电光一闪断绝恶人的退路。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP006', '元素英雄 黏土侠', '用黏土制造，拥有结实身体的元素英雄。挺身将元素英雄的同伴们守护到底。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP007', '元素英雄 爆热女郎', '操纵火焰的元素英雄中的一点红。用红莲之炎，爆裂之火将邪恶燃烧殆尽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP008', '元素英雄 羽翼侠', '操纵着风拥有翱翔天空翅膀的元素英雄。用来自天空的一击，羽毛碎断来制裁邪恶。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP009', '元素英雄 水泡侠', '【条件】这张卡召唤或特殊召唤的自己的主要阶段，自己的手牌、场上没有这张卡以外的卡的场合可以发动。
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP066', '元素英雄 火焰新宇侠', '「元素英雄 新宇侠」+「新空间侠·火焰甲虫」
这张卡可以接触融合（将自己场上的上述表侧表示怪兽作为素材返回持有者的卡组来融合召唤）。
【条件】可以从卡组上面将2张卡送入墓地发动。
【效果】这张卡的攻击力直到回合结束时上升[双方场上的卡的数量]×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP065', '元素英雄 水波新宇侠', '「元素英雄 新宇侠」+「新空间侠·水波海豚」
这张卡可以接触融合（将自己场上的上述表侧表示怪兽作为素材返回持有者的卡组来融合召唤）。
【条件】无
【效果】选对手场上的1只表侧表示怪兽（等级9以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP047', '虚空噬骸兵·默示鹰巨人', '「虚空噬骸兵·苍白骑士」＋「暗黑预言者」
【条件】
把1张手卡送去墓地才能发动。
【效果】
这个回合，这张卡的攻击力上升1000，不会被效果破坏。这张卡特殊召唤的自己主要阶段把这个效果发动的场合，可以再选自己墓地1张「黑洞」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP018', '鹰身女郎 宠物主人', '墓地的这张卡的卡名变成「鹰身女郎」。
【条件】
把卡组最上面的卡送去墓地才能发动。
【效果】
这张卡的卡名直到下次的对方回合结束时变成「鹰身女郎」。那之后，自己场上的表侧表示的「鹰身女郎」「鹰身三姐妹」是合计3只的场合，可以选对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP055', '梦中丝绸蚕', '这张卡可以把1只怪兽（光属性/昆虫族）解放攻击表示上级召唤。
【条件】无
【效果】把自己手卡·场上的怪兽作为素材送去墓地把怪兽（光属性/昆虫族）融合召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/DK01-JP005', '潜入开始', '【条件】
无
【效果】
选自己手卡或者自己墓地1只通常怪兽（7星）在自己场上表侧表示特殊召唤。这个回合，这个效果特殊召唤的怪兽的攻击力上升700，不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP074', '魔力动物领袖', '【条件】
无
【效果】
选自己墓地2只怪兽（4星以下/守备力900以下）在自己场上表侧表示特殊召唤。这个效果的发动后，直到回合结束时自己不能把怪兽（8星以下）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP050', '最强旗兽 引导独角兽', '【条件】自己墓地有3只以上的怪兽（光属性/机械族）的场合可以发动。
【效果】选对手场上的1只表侧表示怪兽（等级4以下）变为里侧守备表示。那之后，可以将手牌的1只怪兽（等级5/机械族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SBP1-JP003', '最强旗兽 瞄准鹰', '【条件】对手场上有表侧表示的怪兽（等级7以上）的场合，可以将自己场上的2只表侧表示怪兽（光属性）送入墓地发动。
【效果】将手牌的1只怪兽（机械族）以表侧表示特殊召唤到自己的场上。用这个效果特殊召唤的怪兽的攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/G001-JPB01', '最强旗兽 浪涌双角兽', '【条件】可以使自己墓地的3只怪兽（机械族）返回卡组发动。
【效果】这个回合，有怪兽（光属性/机械族）以攻击表示高等召唤的场合，表侧表示的这张卡可以作为2只的分量来解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP008', '最强旗兽 大炮犀牛', '【条件】可以将手牌的1只怪兽（光属性/机械族）送入墓地发动。
【效果】选自己场上的1只表侧表示怪兽（光属性/机械族）。这个回合，那只怪兽的攻击会贯通。自己场上有表侧表示的通常怪兽（机械族）的场合，再给予对手500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/S243-JP002', '死灵女仆 娜娜', '【条件】可以将自己场上的表侧表示的这张卡送入墓地发动。
【效果】选自己墓地的1只怪兽（等级7）返回卡组下面，自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP012', '死灵女仆·护卫', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的等级直到回合结束时上升3星。这个回合，怪兽（不死族）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP013', '死灵女仆·打火机', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1张「死灵女仆·缝衣」或者「死灵女仆·改衣」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP014', '死灵女仆·计时机', '【条件】这张卡召唤·特殊召唤的自己主要阶段，把自己场上2只原本等级是4星以下的表侧表示怪兽送去墓地才能发动。
【效果】选自己墓地1只「死灵女仆·南瓜马车」或者仪式术怪兽（光属性/不死族）在自己场上表侧表示特殊召唤。这个回合，自己不能用怪兽（不死族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP015', '死灵女仆·鸟嘴医生', '【条件】这张卡召唤·特殊召唤的自己主要阶段，把这张卡以外的自己场上1只表侧表示怪兽（不死族）送去墓地才能发动。
【效果】选自己墓地1张「冥土女仆的土产」或者「死灵女仆·诡计诊疗」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP016', '死灵女仆·清洁工', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之中有怪兽（不死族）的场合，可以自己选对方墓地1张魔法·陷阱卡。选了的场合，对方把那张卡在自身场上盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP017', '死灵女仆·厨师', '【条件】无
【效果】从自己卡组上面把5张卡翻开给双方确认。自己可以从那之中选1只怪兽（不死族）或者1张仪式魔法卡送去墓地。剩下的卡任意顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP018', '死灵女仆·南瓜马车', '【条件】无
【效果】把自己卡组最下面的卡送去墓地。这个效果把怪兽（不死族）送去墓地的场合，可以再把那只怪兽在自己场上表侧表示特殊召唤。特殊召唤的场合，这个回合，自己不能把「死灵女仆·南瓜马车」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP044', '死灵女仆·潜伏者', '墓地的这张卡的卡名变成「死灵女仆 娜娜」。
【条件】把自己墓地1只仪式术怪兽或者3只怪兽（不死族）回到卡组才能发动。
【效果】选对方场上1张卡破坏。那之后，可以给对方700伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP045', '死灵女仆·Re:D', '墓地的这张卡的卡名变成「死灵女仆 娜娜」。
【条件】把自己墓地1只仪式术怪兽或者3只怪兽（不死族）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP049', '死灵女仆·缝衣', '【条件】无
【效果】直到等级合计为7星以上为止，把自己场上的表侧表示怪兽作为素材送去墓地，把「死灵女仆·潜伏者」仪式术召唤（不能把多余怪兽作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP050', '死灵女仆·改衣', '【条件】无
【效果】直到等级合计为7星以上为止，把自己场上的表侧表示怪兽（不死族）作为素材送去墓地，把怪兽（7星/光属性/不死族）仪式术召唤（不能把多余怪兽作为素材）。这个回合，自己不能用怪兽（不死族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP051', '死灵女仆·订衣', '【条件】无
【效果】从自己卡组上面把4张卡翻开给双方确认。自己可以从那之中选1只效果怪兽（不死族/守备力700）或者1张仪式术魔法卡加入手卡。剩下的卡任意顺序回到卡组下面。这个回合，自己不能用怪兽（不死族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP063', '死灵女仆·诡计诊疗', '【条件】对方把怪兽召唤·特殊召唤时，把自己场上1只表侧表示怪兽（不死族）送去墓地才能发动。
【效果】选对方场上最多2只攻击表示怪兽变成表侧守备表示。这个回合，对方不能把选的怪兽为上级召唤而解放，不能作为仪式术召唤的素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/5TH1-JP001', '永劫之神导龙', '【条件】这张卡召唤或特殊召唤的自己主要阶段，可以支付500LP发动。
【效果】选对手场上的1张卡破坏。这个回合，自己不能再发动「永劫の神導龍／永劫之神导龙」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JPS00', '天导圣之守望人', '【条件】这张卡召唤或特殊召唤的自己的主要阶段，可以支付500LP发动。
【效果】选自己墓地的1只怪兽以表侧表示特殊召唤到自己的场上。这个回合，自己不能发动「天導聖の見継ぎ人／天导圣之守望人」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JPS00', '暗狱皇 亚巴顿', '【条件】这张卡召唤·特殊召唤的自己主要阶段，支付500基本分才能发动。
【效果】这个回合，这张卡可以攻击2次。这个回合，自己不能把「暗狱皇 亚巴顿」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JPS00', '壮严的火焰之影', '【条件】支付500基本分才能发动。
【效果】选自己场上2只表侧表示的效果怪兽（8星以下）。选的怪兽表侧表示的期间，攻击力上升500。这个回合，自己不能把「壮严的火焰之影」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP031', '究极完全态大飞蛾', '「大飞蛾」＋「进化之茧」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP033', '蛹化的幼虫', '「幼虫宝宝」＋怪兽（5星以下/昆虫族）
这张卡可以接触融合术。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「进化之茧」。那之后，可以把包含这张卡的自己手卡·场上的怪兽作为素材送去墓地，把怪兽（地属性/昆虫族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP038', '剪斗独角仙', '自己场上有表侧表示怪兽（地属性/昆虫族）的情况下，这张卡可以不用解放作召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己的卡组上方将3张卡翻开，给双方确认。自己可以从那之中选1只怪兽（等级3·8/地属性/昆虫族）加入手牌。剩余的卡按喜欢的顺序回到卡组下方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP018', '火星心激情少女', '【条件】把这张卡以外的自己手卡·场上1张卡送去墓地才能发动。
【效果】选对方场上1张卡破坏。那之后，自己墓地有「火星」和「火星幕帘」的场合，给予对方700伤害。这个回合，自己不能把「火星心激情少女」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP019', '火星心激情大姐休', '【条件】把这张卡以外的自己手卡·场上1张卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升800。那之后，可以让自己抽1张。这个回合，自己不能把「火星心激情大姐休」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP020', '火星心激情妈库玛', '【条件】无
【永续效果】自己的「火星」的给与的效果伤害变成700。自己场上的表侧表示的「火星心少女」的攻击力上升1300。对方场上的表侧表示怪兽的攻击力下降[自己墓地有的「火星」「火星幕帘」的卡名种类]×400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP021', '交给火星心吧！', '【条件】这张卡召唤的回合，自己卡组的卡是10张以上的场合才能发动。
【效果】从自己卡组上面把3张卡翻开给双方确认。自己可以从那之中选1张仪式魔法卡加入手卡。剩下的卡任意顺序回到卡组下面。自己墓地有「火星」或者「火星幕帘」的场合，这个效果翻开的张数变成6张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP022', '火星心 阿涅休', '自己墓地有「火星」或者「火星幕帘」的场合，可以把这张卡从手卡在自己场上表侧表示特殊召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以从那之中选1只怪兽（炎属性/魔法师族）加入手卡。这个回合，自己不能把「火星心 阿涅休」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP023', '火星心 玛库玛', '【条件】把自己墓地2只怪兽（炎属性/魔法师族）或者4只怪兽回到卡组才能发动。
【效果】选自己场上的表侧表示怪兽或者对方场上的怪兽合计最多2张表示形式变更。自己卡组的卡是10张以上的场合，可以再选自己墓地的「火星心少女」「火星」「火星幕帘」合计最多4张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP024', '近燐的派特', '【条件】这张卡召唤的回合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的等级直到回合结束时上升3星。那之后，可以选自己墓地1只「火星心少女」或者1张「我想要驱魔的圣水！」加入手卡。这个回合，自己只能用怪兽（炎属性/魔法师族）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP025', '近燐的费艾玛', '【条件】这张卡召唤的回合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的等级直到回合结束时上升3星。那之后，可以选自己墓地1只「火星心少女」或者1张「耕地被破坏了很困恼！」加入手卡。这个回合，自己只能用怪兽（炎属性/魔法师族）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP028', '耕地被破坏了很困恼！', '【条件】无
【效果】等级合计直到和祭式召唤的怪兽的等级以上为止，把自己场上的表侧表示怪兽（炎属性/魔法师族）作为素材送去墓地。把「火星心激情少女」或者「火星心激情妈库玛」祭式召唤（多余的怪兽不能作为素材）。那之后，可以选对方场上1只表侧表示怪兽（6星以下/兽族·鸟兽族）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP029', '我想要驱魔的圣水！', '【条件】无
【效果】等级合计直到和祭式召唤的怪兽的等级以上为止，把自己场上的表侧表示怪兽（炎属性/魔法师族）作为素材送去墓地， 把「火星心激情少女」或者「火星心激情大姐休」祭式召唤（多余的怪兽不能作为素材）。那之后，可以选对方场上1只表侧表示怪兽（6星以下/恶魔族·战士族）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP030', '火星心工房', '【条件】无
【效果】只要这张卡在场地区域表侧表示存在，双方场上的表侧表示怪兽（炎属性/魔法师族）不会被效果破坏。双方场上的表侧表示怪兽（6星以下/炎属性/魔法师族）的攻击力上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP018', '饥饿的奶昔', '【条件】这张卡召唤的回合，把1张手卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以选自己墓地1张「饥饿的优惠券」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP019', '饥饿的冰淇淋', '【条件】这张卡召唤的回合，把自己墓地2只怪兽（暗属性/战士族）回到卡组才能发动。
【效果】自己回复1000生命值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP020', '饥饿的贪婪甜甜圈', '【条件】这张卡召唤的回合，把手卡1张「汉堡的食谱」或者「饥饿的优惠券」给对方观看才能发动。
【效果】从自己卡组上面把4张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP021', '饥饿的炸鸡块', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1张「汉堡的食谱」或者「汉堡的头牌食谱」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP022', '饥饿的薯条', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只怪兽（暗属性/战士族/攻击力1200/守备力900）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP033', '饥饿的贪婪汉堡', '【条件】自己墓地有怪兽（暗属性/战士族）的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升[自己墓地的怪兽（暗属性/战士族）数量]×200。自己场上有表侧表示的「饥饿的汉堡」的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP047', '汉堡的食谱', '【条件】无
【效果】等级合计直到6星以上为止，把自己手卡·场上的怪兽作为素材送去墓地，把「饥饿的汉堡」祭式召唤（多余的怪兽不能作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP048', '汉堡的头牌食谱', '【条件】无
【效果】等级合计直到6星以上为止，把自己场上的表侧表示怪兽作为素材送去墓地，把「饥饿的汉堡」或者「饥饿的贪婪汉堡」祭式召唤（多余的怪兽不能作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP049', '饥饿的优惠券', '【条件】无
【效果】选自己场上最多2只表侧表示怪兽（3·6星/暗属性/战士族），那些攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP050', '饥饿的迎客', '【条件】自己没有从墓地把怪兽特殊召唤的回合才能发动。
【效果】选自己墓地把1只怪兽（6星/暗属性/战士族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP060', '打包袭击', '【条件】对方把怪兽召唤·特殊召唤时，把自己场上1只表侧表示的祭式怪兽送去墓地才能发动。
【效果】选对方场上1只怪兽破坏。那之后，可以选自己墓地1只「饥饿的汉堡」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP035', '寄星体 死藤', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。这个回合对方没有承受过效果伤害的场合，可以再给与对方700伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP035', '圣域天使 杰拉特', '【条件】自己墓地有「杰拉的战士」或者祭式怪兽（攻击力2800/守备力2300）的场合，把手卡1只怪兽送去墓地才能发动。
【效果】选对方场上1只怪兽（8星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP036', '巢窟恶魔 魔杰拉', '【条件】自己墓地有「杰拉的战士」或者祭式怪兽（攻击力2800/守备力2300）的场合，把自己墓地1只怪兽回到卡组下面才能发动。
【效果】这张卡的攻击力直到回合结束时上升500。那之后，可以随机选对方最多3张手卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP052', '杰拉的分歧点', '墓地的这张卡的卡名变成「杰拉的仪式」。
【条件】无
【效果】等级合计直到8星以上为止，把自己场上的表侧表示怪兽作为素材送去墓地，把「圣域天使 杰拉特」或者「巢窟恶魔 魔杰拉」祭式召唤（多余的怪兽不能作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP053', '饶有兴趣的蓄发', '【条件】无
【效果】等级合计直到2星以上为止，把自己手卡·场上的怪兽（光属性/水族）作为素材送去墓地，把「依然饶有兴趣的假名姬」或者「依然饶有兴趣的雏人偶姬」祭式召唤（多余的怪兽不能作为素材）。这个效果不能把手卡的效果怪兽作为素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SS01-JP001', '依然饶有兴趣的假名姬', '墓地的这张卡的卡名变成「饶有兴趣的假名姬」。
【条件】无
【永续效果】这张卡的卡名变成「饶有兴趣的假名姬」。自己场上的表侧表示怪兽（光属性/水族）的攻击力上升500，等级上升5星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SS01-JP002', '依然饶有兴趣的假名姬', '墓地的这张卡的卡名变成「饶有兴趣的假名姬」。
【条件】无
