INSERT INTO "texts" VALUES ('RD/SS01-JP012', '依然饶有兴趣的假名姬', '墓地的这张卡的卡名变成「饶有兴趣的假名姬」。
【条件】无
【永续效果】这张卡的卡名变成「饶有兴趣的假名姬」。自己场上的表侧表示怪兽（光属性/水族）的攻击力上升500，等级上升5星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP037', '昂光天使 埃塞尔', '【条件】自己没有把怪兽特殊召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。这个效果在后攻玩家的最初回合发动的场合，可以再选自己或者对方的墓地1只怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP065', '天之选别', '【条件】自己场上的表侧表示怪兽的等级合计是10星以上的场合才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。自己场上的表侧表示怪兽是1只的场合，可以再选对方场上1只表侧表示怪兽那个攻击力直到回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/VSP1-JP054', '天之招来', '【条件】无
【效果】从自己卡组上面把3张卡送去墓地。自己场上没有怪兽的场合，可以再选自己墓地1只怪兽（10星）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP056', '昂光的咒缚', '【条件】对方手卡是1张以下的场合才能发动。
【效果】选对方场上1只怪兽变成表侧攻击表示或者里侧守备表示。这个回合对方是已把陷阱卡发动的场合或者这个回合是后攻玩家的最初回合的场合，再让双方抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP066', '超级战狮', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP027', '狮子的依代', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把4张卡翻开给双方确认。自己可以从那之中选「狮子的仪式」「狮子的强袭」各最多1张加入手卡。剩下的卡任意顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP030', '翼之魔兽 加尔瓦斯', '【条件】无
【永续效果】自己场上的表侧表示怪兽（兽族）的攻击力上升[效果怪兽以外的自己场上的表侧表示怪兽（兽族）数量]×500。自己的「超级战狮」的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP028', '竹林的杀手熊猫', '【条件】把自己场上1只表侧表示的效果怪兽（兽族）送去墓地才能发动。
【效果】选自己墓地1只效果怪兽以外的怪兽（兽族）在自己场上表侧表示特殊召唤。这个效果把「超级战狮」特殊召唤的场合，可以再选对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP029', '金毛魔兽 狮子王', '自己场上有表侧表示怪兽（地属性/兽族）的场合，这张卡可以不用解放进行召唤。
【条件】无
【效果】选自己墓地1张「狮子的仪式」或者「狮子的强袭」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP038', '狐狸茶茶', '【条件】把自己场上表侧表示的这张卡送去墓地才能发动。
【效果】选自己或者对方墓地1张祭式魔法卡回到持有者卡组。那之后，可以选自己墓地1只祭式怪兽（7～9星）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP057', '狮子的仪式', '【条件】无
【效果】等级合计直到7星以上为止，把自己手卡·场上的怪兽作为素材送去墓地，把「超级战狮」祭式召唤（多余怪兽不能作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP058', '狮子的强袭', '【条件】无
【效果】等级合计直到7星以上为止，把自己场上的表侧表示怪兽（兽族）作为素材送去墓地，把「超级战狮」祭式召唤（多余怪兽不能作为素材）。这个效果特殊召唤的怪兽的攻击力直到回合结束时上升2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP059', '狮子的战域', '墓地的这张卡的卡名变成「狮子的强袭」。
【条件】自己场上有表侧表示的「超级战狮」的场合，把自己墓地1只怪兽回到卡组才能发动。
【效果】选自己场上最多3只表侧表示怪兽（兽族）那些攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP001', '超时空战斗机 V形蛇', '拥有后备仓库，能发挥各种能力的高性能战斗机。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP023', '子机', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只原本守备力是800的表侧表示怪兽（4星/光属性/机械族），这张卡的攻击力直到下次对方回合结束时上升[选的怪兽的原本攻击力]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP024', '倍机', '手卡或者墓地的这张卡的卡名变成「子机」。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「子机」。自己场上有原本卡名是「超时空战斗机 罗德不列颠号」的表侧表示怪兽的场合，可以再选对方场上1只怪兽表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP025', 'V型蛇 传播炸弹', '【条件】把这张卡以外的自己手卡·场上1只怪兽送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「超时空战斗机 V型蛇」。那之后，可以选对方场上1张魔法·陷阱卡破坏。这个回合，自己只能用原本守备力800的怪兽（机械族）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP026', 'V型蛇 起动', '【条件】支付100生命值才能发动。
【效果】这张卡的卡名在这个回合变成「超时空战斗机 V型蛇」。那之后，可以选这张卡以外的自己手卡·场上最多2只怪兽送去墓地。送去墓地的场合，可以再选自己墓地的[这个效果送去墓地的怪兽数量]张的「子机」在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP041', 'V型蛇 波纹镭射型', '「超时空战斗机 V型蛇」＋「子机」
这张卡可以接触结合。
【条件】无
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选对方场上最多2只表侧表示怪兽那个攻击力直到回合结束时下降800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP042', 'V形蛇 全定制型', '「超时空战斗机 V形蛇」＋「子机」＋「子机」
这张卡可以接触结合。
【条件】无
【永续效果】这张卡不会被效果破坏。这张卡的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP065', '超时空战斗机 罗德不列颠号', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「超时空战斗机 V型蛇」。那之后，可以选自己墓地1只「子机」在自己场上表侧表示特殊召唤。这个回合，自己只能用原本守备力800的怪兽（机械族）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP053', '超越速度', '【条件】无
【效果】把自己手卡·场上的怪兽作为素材送去墓地，把怪兽（4星/机械族/守备力800）结合召唤。自己墓地有「能量胶囊 红」的场合，这个效果特殊召唤的怪兽的攻击力直到回合结束时上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP054', '能量上升测量仪', '【条件】把自己场上1只表侧表示怪兽回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（光属性/机械族/守备力800）加入手卡。自己墓地有「能量胶囊 红」的场合，可以再把自己手卡·场上的怪兽作为素材送去墓地把怪兽（4星/机械族/守备力800）结合召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP055', '能量胶囊 蓝', '【条件】自己场上有表侧表示的「超时空战斗机 V形蛇」的场合才能发动。
【效果】等级合计直到8星以下为止，选对方场上最多3只表侧表示怪兽破坏。这个回合，自己只能用原本守备力800的怪兽（机械族）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP056', '能量胶囊 红', '【条件】无
【效果】从自己卡组上面把4张卡翻开给双方确认。自己可以从那之中选「超时空战斗机 V形蛇」和效果怪兽（光属性/机械族/守备力800）各最多1张加入手卡。剩下的卡任意顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP064', '重生模式', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时才能发动。
【效果】选自己墓地1只「超时空战斗机 V型蛇」或者结合怪兽（4星/机械族/守备力800）在自己场上表侧表示特殊召唤。那之后，可以选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP001', '混沌战士', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP015', '光缠龙-拉特斯', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「缠龙的探索者 斯特拉」或者怪兽（等级9/幻龙族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP016', '缠龙的探索者 斯特拉', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】自己卡组上面翻开4张卡，双方确认。自己可以从那之中选1只怪兽（等级7以上）加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP017', '缠龙的探索者 莎拉', '【条件】自己卡组的卡是10张以上的场合，自己墓地2只怪兽（幻龙族）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽变成里侧守备表示。那之后，自己卡组最上面的卡送去墓地。这个效果令怪兽（幻龙族/守备力2400）送去墓地的场合，再可以令那只怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP018', '缠龙的探索者 阿斯特尔', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】自己卡组上面2张卡送去墓地。那之后，可以选自己1张手卡送去墓地。手卡送去了墓地的场合，再可以选自己墓地1只怪兽（幻龙族/守备力2400）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP019', '灼缠龙-弗雷卡尔', '这张卡可以解放1只怪兽（幻龙族）攻击表示上级召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段，对方场上没有表侧表示怪兽的场合才能发动。
【效果】选对方场上1张里侧表示的卡破坏。这个回合，自己不能用怪兽（幻龙族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP020', '绿缠龙-古里雷', '【条件】卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升800。对方场上没有表侧表示怪兽的场合，再可以选对方场上1张里侧表示的卡回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP021', '魔缠龙-喰星的薇扎尔', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】对方场上表侧表示怪兽全部变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP025', '升华英雄 银R', '墓地这张卡的卡名变成「升华英雄 银」。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】自己卡组上面2张卡送去墓地。那之后，可以选自己墓地1张「升华·装备」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP026', '升华·装置', '这张卡可以解放1只怪兽（战士族）攻击表示上级召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只怪兽（等级3/光属性/战士族/守备力1000）加入手卡。这个回合，自己不用怪兽（光属性/战士族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP038', '天河星象·升华·忘却龙', '「天河星象·忘却龙」＋「幻灭·偕日升龙」
【条件】这张卡结合召唤的自己主要阶段才能发动。
【效果】对方场上的卡全部回到持有者卡组。这个回合，自己不用这张卡不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP039', '回生·偕日升龙', '「幻灭·偕日升龙」＋怪兽（等级4以下/光属性）
【条件】卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合，变成「幻灭·偕日升龙」。那之后，可以选自己墓地1只怪兽（等级7/银河族）在自己场上表侧表示特殊召唤。这个回合，自己不能发动「回生·偕日升龙」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP041', '光缠龙的卵', '「缠龙的探索者 斯特拉」＋怪兽（等级4以下/幻龙族）
这张卡可以接触结合。
【条件】无
【效果】手卡1只怪兽（等级7以上）在自己场上表侧表示特殊召唤。这个效果令原本种族是幻龙族的怪兽特殊召唤的场合，再在这个回合，那只怪兽的攻击力上升800，那个攻击会贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP042', '升华英雄 银O', '怪兽（战士族/守备力1000）＋「升华·装置」
【条件】自己没有特殊召唤过怪兽的回合，自己场上表侧表示的这张卡回到持有者额外卡组才能发动。
【效果】选对方场上1张卡破坏。那之后，可以令自己墓地的怪兽作为素材回到卡组结合召唤「升华英雄 银O」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP047', '天河星象·结合·空间', '【条件】无
【效果】这张卡在场地区域表侧表示为限，双方用「结合」的效果结合召唤效果怪兽（光属性·暗属性/银河族）的场合，自身手卡的怪兽（光属性·暗属性/银河族）也可以作为素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP051', '缠龙域的战利品', '【条件】手卡的怪兽（幻龙族）或者自己场上的表侧表示怪兽（幻龙族）1只送去墓地才能发动。
【效果】自己抽1张，双方确认。那张卡是怪兽（幻龙族）的场合，再可以令手卡1只怪兽（等级7以上/幻龙族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP052', '缠龙域的探索', '【条件】无
【效果】选自己墓地1只怪兽（等级5以下/幻龙族/守备力900），在自己场上表侧表示特殊召唤。这个回合，攻击表示上级召唤怪兽（幻龙族）的场合，这个效果特殊召唤的怪兽可以作为2只的份额解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP062', '升华·装备', '【条件】对方召唤·特殊召唤怪兽时才能发动。
【效果】自己场上·墓地的怪兽（光属性）作为素材回到持有者卡组，结合召唤「升华英雄 银O」或者「升华英雄 银F」。那之后，可以选对方场上1只表侧表示怪兽（等级8以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JPS00', '望丘的护尧神', '自己场上没有表侧表示的「聖丘的护尧神」的场合，支付500LP，这张卡可以从手卡往自己场上表侧守备表示特殊召唤。
【条件】无
【永续效果】这张卡不会被对方的效果破坏。自己不会受到对方的效果伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP007', '报道合战 独家新闻', '可以与「报道合战 独家新闻[L] 」「报道合战 独家新闻[R] 」集齐作极限召唤。
【条件】无
【效果】对方翻开自身卡组最上面的卡，双方确认并放回原处。那张卡是怪兽的场合，这张卡的攻击力直到回合结束时上升800。这张卡是极限模式的场合，再在这个回合，这张卡的攻击力上升1000，那个攻击会贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP008', '报道合战 独家新闻[L]', '【条件】宣言卡的种类（怪兽·魔法·陷阱）才能发动。
【效果】对方翻开自身卡组最上面的卡，双方确认并放回原处。那张卡是宣言种类卡的场合，自己回复400LP。这张卡是极限模式的场合，再可以选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP009', '报道合战 独家新闻[R]', '【条件】自己卡组的卡是10张以上的场合才能发动。
【效果】对方翻开自身卡组最上面的卡，双方确认并放回原处。那张卡是怪兽的场合，自己从自己卡组上面令3张卡送去墓地。这张卡是极限模式的场合，再可以选自己墓地最多2张「瓦版小报炸」用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP010', '报道记人 颠倒磁带录音机人', '【条件】这张卡召唤的回合，自己墓地有怪兽（地属性/机械族）2只以上的场合才能发动。
【效果】选自己墓地1只「报道狸 话筒」或者1张「结合」加入手卡。那之后，可以选对方墓地1张卡回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP011', '报道魔娘 主播凯瑟琳', '【条件】宣言卡的种类（怪兽·魔法·陷阱）才能发动。
【效果】对方翻开自身卡组最上面的卡，双方确认并放回原处。那张卡是宣言种类卡的场合，自己可以抽1张。抽了的场合，这个回合，自己不能发动「报道魔娘 主播凯瑟琳」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP012', '速摄机器 ENG', '【条件】宣言卡的种类（怪兽·魔法·陷阱）才能发动。
【效果】对方翻开自身卡组最上面的卡，双方确认并放回原处。那张卡是宣言种类卡的场合，可以选自己墓地1只怪兽（地属性/机械族）加入手卡。加入了的场合，这个回合，自己不能发动「速摄机器 ENG」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP013', '突击机器·头角式耳机', '【条件】自己场上1张里侧表示的卡送去墓地才能发动。
【效果】选对方场上1张里侧表示的卡确认，回到持有者卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP014', '超特报机器·强硬小报机人超速闪光', '墓地这张卡的卡名变成「特报机器·强硬小报机人」。
【条件】卡组最上面的卡送去墓地才能发动。
【效果】对方从自身卡组上面翻开3张卡，双方确认并放回原处。自己可以选自己墓地最多[那之中怪兽的数量]张「瓦版小报炸」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP029', '花牙点的紫阳花', '【条件】这张卡召唤的回合才能发动。
【效果】自己卡组上面5张卡翻开，双方确认。自己可以从那之中选怪兽（等级7/植物族）和「结合」各最多1张加入手卡。剩下的卡用喜欢的顺序回到卡组下面。这个效果有2张加入手卡的场合，再选自己1张手卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP048', '快乐报', '【条件】自己没有发动过「快乐报」的回合，自己场上有表侧表示怪兽（地属性/机械族）的场合，宣言卡的种类（怪兽·魔法·陷阱）才能发动。
【效果】对方从自身卡组上面翻开2张，双方确认并放回原处。自己抽[那之中宣言种类卡的数量]。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP049', '号外报炸', '墓地这张卡的卡名变成「瓦版小报炸」。
【条件】自己场上有表侧表示怪兽（地属性/机械族）的场合才能发动。
【效果】对方从自身卡组下面取出3张卡，双方确认。给与对方[那之中怪兽的数量]×400伤害。自己从确认的3张之中选2张用喜欢的顺序回到对方卡组上面，剩下的卡回到对方卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP058', '启程的三贤者', '【条件】自己没有发动过「启程的三贤者」的回合才能发动。
【效果】自己卡组上面3张卡送去墓地。那之后，可以从那之中选1只效果怪兽（等级4以下/光属性·暗属性·水属性/魔法师族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP060', '大事件！', '墓地这张卡的卡名变成「报道魂」。
【条件】对方主要阶段，卡送去对方墓地时才能发动。
【效果】选对方墓地最多2张卡用喜欢的顺序回到卡组上面。那之后，自己可以令手卡最多2只怪兽（地属性/机械族）在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP063', '歇斯底里的眼', '【条件】对方从手卡召唤·放置怪兽时，或者对方特殊召唤怪兽时才能发动。
【效果】选对方场上最多2只怪兽变更表示形式。这个效果变更表示形式的怪兽是咒仪怪兽的场合，这个回合，对方不能发动与那只咒仪怪兽原本卡名相同的怪兽的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP25-JP067', '神鹰·优雅女士', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「神鹰三姐妹」或者通常怪兽（鸟兽族/守备力1400）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP063', '协力车机人', '同名的怪兽（机械族）×2
【条件】无
【永续效果】这张卡可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP031', '绝望狂魔 块·核', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1张「绝望的仪」或者「绝望的根源」在自己的魔法与陷阱区域放置。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP055', '灵魂迅速翻动', '【条件】对方召唤效果怪兽（等级4以下/守备力1400以下）时才能发动。
【效果】那只怪兽变成里侧守备表示。自己墓地怪兽的属性为3种类以上的场合，再可以得到那只里侧守备表示怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP056', '高速·军官', '「高速·运输者」＋「高速·骑兵」
【条件】卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升500。这张卡结合召唤的自己主要阶段发动这个效果的场合，再可以选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP057', '高速·少校', '「高速·狙击兵」＋效果怪兽（战士族/守备力2000以下）
【条件】无
【永续效果】这张卡以外的自己场上表侧表示怪兽（风属性·地属性/战士族）的攻击力上升500。自己场上有原本攻击力为2600以上的表侧表示怪兽（风属性·地属性/战士族）的场合，再上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP058', '高速·司令', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】手卡1只效果怪兽（等级3~5/战士族）在自己场上表侧表示特殊召唤。那之后，可以选自己墓地1只怪兽（战士族/攻击力1400/守备力100）加入手卡。这个回合，自己不能发动「高速·司令」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP059', '高速·运输者', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只效果怪兽（等级3·4/风属性/战士族/攻击力1000以上），在自己场上表侧表示特殊召唤。那之后，可以选自己墓地1张「高速·提升」或者「高速·转向」加入手卡。这个回合，自己不能用怪兽（战士族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP060', '高速·狙击兵', '【条件】无
【效果】自己场上表侧表示的效果怪兽（战士族）作为素材回到持有者卡组，结合召唤怪兽（战士族/守备力2300）。这张卡特殊召唤的自己主要阶段发动这个效果的场合，自己墓地的效果怪兽（战士族）也可以作为素材。这个回合，自己不能用怪兽（战士族以外）攻击，不能发动「高速·狙击兵」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP061', '高速·骑兵', '【条件】卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升200。这张卡特殊召唤的自己主要阶段发动这个效果的场合，再可以令自己或者对方卡组最上面的卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP062', '高速·提升', '【条件】无
【效果】手卡1只怪兽（等级6以下/风属性/战士族）在自己场上表侧表示特殊召唤。那之后，自己场上的表侧表示怪兽（风属性/战士族）为2只以上的场合，可以选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP063', '高速·转圈', '【条件】自己没发动过「高速·转圈」的回合才能发动。
【效果】选自己墓地1只怪兽（战士族/攻击力1400/守备力100），在自己场上表侧表示特殊召唤。自己在这个主要阶段没有抽过卡的场合，再有自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP064', '高速·转向', '【条件】对方表侧表示召唤·特殊召唤怪兽（等级7以上）时才能发动。
【效果】选自己墓地最多2只怪兽（风属性/战士族/攻击力2000以下），在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP066', '龙破坏的引导', '【条件】自己没有发动过「龙破坏的引导」的回合才能发动。
【效果】手卡1只怪兽（战士族）在自己场上表侧守备表示特殊召唤。那之后，自己场上有「毁灭剑士」的场合，自己可以抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP071', '莓果清新·协作', '【条件】这张卡召唤的回合，这张卡以外的自己手卡·场上1张卡送去墓地才能发动。
【效果】选自己场上1只攻击表示怪兽变成表侧守备表示。这个效果的条件令怪兽（水属性/水族）送去墓地的场合，再可以选极限怪兽以外的对方场上1只表侧表示怪兽（等级10以下）破坏。这个回合，自己不能用怪兽（水族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP073', '恶着之布拉斯蒂斯', '【条件】这张卡召唤·特殊召唤的自己主要阶段，卡组最上面的卡送去墓地才能发动。
【效果】选极限怪兽以外的对方场上1只效果怪兽（攻击力100以上），这张卡的攻击力直到回合结束时，上升[选的怪兽的攻击力]。再有直到下次的对方回合结束时，这张卡的战斗不会令双方承受战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP062', '苦涩的选择', '【条件】无
【效果】自己卡组上面5张卡翻开，给双方确认。对方从那之中选1张，自己令那张卡加入手卡。剩下的卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP001', '地灵使 奥丝', '【条件】这张卡反转的自己主要阶段，或者自己场上有这张卡以外的表侧表示怪兽（魔法师族/守备力1500）的场合才能发动。
【效果】选极限怪兽以外的对方场上1只表侧表示怪兽（8星以下/地属性）得到那个控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP002', '水灵使 艾里雅', '【条件】这张卡反转的自己主要阶段，或者自己场上有这张卡以外的表侧表示怪兽（魔法师族/守备力1500）的场合才能发动。
【效果】选极限怪兽以外的对方场上1只表侧表示怪兽（8星以下/水属性）得到那个控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP003', '火灵使 希塔', '【条件】这张卡反转的自己主要阶段，或者自己场上有这张卡以外的表侧表示怪兽（魔法师族/守备力1500）的场合才能发动。
【效果】选极限怪兽以外的对方场上1只表侧表示怪兽（8星以下/炎属性）得到那个控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP004', '风灵使 薇茵', '【条件】这张卡反转的自己主要阶段，或者自己场上有这张卡以外的表侧表示怪兽（魔法师族/守备力1500）的场合才能发动。
【效果】选极限怪兽以外的对方场上1只表侧表示怪兽（8星以下/风属性）得到那个控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP009', '地灵术师 奥丝', '【条件】这张卡召唤·特殊召唤的自己主要阶段，自己手卡·场上1只怪兽送去墓地才能发动。
【效果】自己卡组最上面的卡送去墓地。那之后，可以选自己墓地1只怪兽（5星以下）在自己场上表侧表示特殊召唤。这个回合，自己不能发动「地灵术师 奥丝」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP010', '水灵术师 艾里雅', '【条件】这张卡召唤·特殊召唤的自己主要阶段，自己手卡·场上1只怪兽送去墓地才能发动。
【效果】选对方墓地1只怪兽回到卡组上面。再有直到下次的对方回合结束时，对方不能表侧表示召唤·特殊召唤与选的怪兽原本卡名相同的怪兽。这个回合，自己不能发动「水灵术师 艾里雅」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP011', '火灵术师 希塔', '【条件】这张卡召唤·特殊召唤的自己主要阶段，自己手卡·场上1只怪兽送去墓地才能发动。
【效果】给予对方500伤害。那之后，自己可以抽1张。这个回合，自己不能发动「火灵术师 希塔」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP012', '风灵术师 薇茵', '【条件】这张卡召唤·特殊召唤的自己主要阶段，自己手卡·场上1只怪兽送去墓地才能发动。
【效果】选极限怪兽以外的对方场上1只表侧表示效果怪兽回到持有者卡组下面。这个回合，自己不能发动「风灵术师 薇茵」的效果。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP013', '地灵术师的使役魔', '【条件】自己场上表侧表示的这张卡或者卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个属性直到回合结束时变成地属性。那之后，可以选自己场上1只里侧表示的「地灵使」变成表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP014', '水灵术师的使役魔', '【条件】自己场上表侧表示的这张卡或者卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个属性直到回合结束时变成水属性。那之后，可以选自己场上1只里侧表示的「水灵使」变成表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP015', '火灵术师的使役魔', '【条件】自己场上表侧表示的这张卡或者卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个属性直到回合结束时变成炎属性。那之后，可以选自己场上1只里侧表示的「火灵使」变成表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP016', '风灵术师的使役魔', '【条件】自己场上表侧表示的这张卡或者卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个属性直到回合结束时变成风属性。那之后，可以选自己场上1只里侧表示的「风灵使」变成表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP017', '灵术集结', '【条件】无
【效果】选自己手卡·墓地1只怪兽（魔法师族/攻击力500·1900/守备力1500）在自己场上表侧表示特殊召唤。这个回合，自己不能用怪兽（等级9以上）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP018', '灵术精炼', '【条件】手卡1只怪兽（魔法师族/攻击力500·1900/守备力1500）送去墓地才能发动。
【效果】自己抽2张。那之后，可以令手卡1只怪兽（5星/魔法师族）在自己场上表侧表示特殊召唤。这个回合，自己不能用怪兽（9星以上）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP019', '灵术之指南书', '【条件】自己没有发动「灵术之指南书」的回合才能发动。
【效果】自己卡组上面5张卡翻开，给双方观看。自己可以最多按那之中的怪兽（魔法师族/攻击力500·1900/守备力1500）每有2只取1张，选对方场上的卡破坏。翻开的卡用喜欢的顺序回到卡组下面。破坏了2张卡的场合，这个回合，自己不用1只怪兽不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP020', '灵体化的锻炼', '【条件】自己没有发动「灵体化的锻炼」的回合，手卡持有相同属性的2只怪兽给对方观看才能发动。
【效果】持有与这个效果的条件被观看的怪兽相同属性的、自己墓地怪兽（魔法师族/攻击力500·1900/守备力1500）和怪兽（4星/攻击力1500/守备力200）选各最多1只加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP021', '灵使的回归场所', '【条件】无
【效果】这张卡在场地区域表侧表示为限，双方原本守备力为1500的表侧表示怪兽（等级3~5/魔法师族）的攻击力上升500，双方召唤怪兽（等级5/魔法师族/守备力1500）的场合可以不作必要的解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP023', '绝望狂魔 锁核', '「绝望狂魔 死核」＋「绝望狂魔 死锁」
【条件】
【永续效果】这张卡不会被效果破坏。这张卡不能作为上级召唤的解放。自己场上的表侧表示怪兽（恶魔族以外）的攻击力下降2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP024', '绝望狂魔 热核', '「绝望狂魔 死核」＋「绝望狂魔 死热平局」
【条件】自己墓地4只怪兽回到卡组才能发动。
【效果】选对手墓地1只怪兽（等级9以下），在自己场上表侧表示特殊召唤。那之后，可以选自己墓地1只怪兽（恶魔族）在对方场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP028', '绝望狂魔 死锁', '【条件】无
【永续效果】这张卡不能作为怪兽攻击表示上级召唤的解放。自己场上表侧表示怪兽（恶魔族以外）的攻击力下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP029', '绝望狂魔 死热平局', '【条件】自己场上有表侧表示的「绝望狂魔 死核」的场合才能发动。
【效果】自己卡组上面3张卡送去墓地。那之后，可以从那之中选1只怪兽（暗属性/恶魔族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP033', '绝望的根源', '【条件】无
【效果】为使合计等级为3以上，手卡的怪兽（恶魔族）作为素材送去墓地，咒仪召唤「绝望狂魔 死核」。那之后，可以令自己卡组上面2张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP035', '与绝望的遭遇', '【条件】对方召唤·特殊召唤怪兽时才能发动。
【效果】选自己手卡·墓地1只怪兽（暗属性/恶魔族/守备力1200·2400），在对方场上表侧守备表示特殊召唤。那之后，可以选对方场上1只表侧表示怪兽（等级8以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP037', '苍救之光明 沙鲁托鲁', '「苍救参谋 库雷蒙托」＋「苍救天使 日」
【条件】这张卡特殊召唤的自己主要阶段，卡组最上面的卡送去墓地才能发动。
【选择效果】
●直到下次的对方回合结束时，这张卡表侧表示期间，双方不能表侧攻击表示特殊召唤效果怪兽（8星以下）。
●直到下次的对方回合结束时，这张卡表侧表示期间，对方不能放置手卡的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP038', '苍救之幽暗 奎拉德斯', '「苍救参谋 库雷蒙托」＋「苍救天使 月」1
【条件】无
【效果】自己回合期间，自己场上的表侧表示怪兽（天界战士族·战士族）的攻击力上升500，那些攻击宣言时对方不能发动陷阱卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP043', '苍救之煌辉 桑马鲁斯', '「苍救骑士 塞尔」＋「苍救天使 日」
【条件】这张卡以外的自己手卡·场上1张卡给双方确认，回到持有者卡组下面才能发动。
【选择效果】
●选对方场上1只表侧表示怪兽（9星以下）破坏。
●选自己墓地1只怪兽（1星/天使族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP046', '苍救参谋 克雷蒙特', '【条件】这张卡召唤的回合才能发动。
【效果】选自己场上1张卡送去墓地。那之后，可以选自己墓地1只怪兽（水属性/战士族/守备力1200以外）或者1张「苍救之祈祷」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP049', '苍救天使之魂', '【条件】无
【效果】自己卡组最上面的卡送去墓地。那之后，选自己墓地1只「苍救天使 日」或者「苍救天使 月」加入手卡。加入了的场合，再可以选自己场上1只怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP050', '苍救之祈誓', '手卡或者墓地这张卡的卡名变成「苍救之祈祷」。
【条件】无
【效果】自己手卡·场上的，1只怪兽（水属性/战士族）和1只以上效果怪兽（天使族）作为素材送去墓地，结合召唤怪兽（天界战士族）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP051', '苍救之宿愿', '【条件】传说卡以外的手卡1只怪兽（战士族·天使族）或者1张「结合」送去墓地才能发动。
【效果】自己抽2张。这个效果发动后，直到回合结束时自己不能从额外卡组特殊召唤怪兽（天界战士族以外），不能用怪兽（等级8以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP054', '苍救之防卫', '【条件】对方召唤·特殊召唤怪兽时，自己墓地2只怪兽（水属性/战士族）回到卡组才能发动。
【效果】选自己场上合计最多2只攻击表示怪兽（天界战士族·战士族）。这个回合，那些怪兽不会被战斗破坏。再有，可以选自己墓地1张「结合」在自己的魔法与陷阱区域放置。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP065', '奇迹之战士-毁灭剑士', '「毁灭剑士」＋怪兽（等级8以下/战士族）
【条件】这张卡特殊召唤的自己主要阶段，自己卡组的卡是10张以上的场合才能发动。
【效果】自己抽1张。那之后，可以令这张卡的攻击力直到回合结束时上升[双方墓地怪兽（龙族·战士族）的数量合计]×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP067', '手揉小龙', '【条件】自己的手卡有2张以上的场合，攻击表示的这张卡变成表侧守备表示才能发动。
【效果】对方回复100基本分。那之后，随机选自己1张手卡，给双方确认。那张卡是怪兽（龙族）的场合，再可以令那只怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP069', 'P·M 工具箱鲸海怪', '这张卡可以解放1只怪兽（8星以上）攻击表示上级召唤。
【条件】自己场上表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地2只怪兽（4星以下/雷族/守备力800），在自己场上表侧守备表示特殊召唤。那之后，可以选自己墓地1张「P·M 开封」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP074', '幻惑之光', '【条件】自己没有发动「幻惑之光」的回合，宣言自己场上表侧表示怪兽（魔法师族）的1种属性才能发动。
【效果】选对方场上1只表侧表示怪兽，那个属性直到回合结束时变成这个效果的条件宣言的属性。发动后这张卡可以不送去墓地就此放置。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP076', '超越超速·火山', '【条件】对方的效果怪兽（8星以下）的攻击宣言时，自己墓地攻击力不同的3只怪兽用喜欢的顺序回到卡组下面才能发动。
【效果】破坏攻击的怪兽。没能破坏的场合，给与对方1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP025', '绝望狂魔 死·核', '【条件】无
【效果】自己手卡·场上怪兽作为素材送去墓地，结合召唤怪兽（暗属性/恶魔族/守备力2400）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP032', '绝望之仪', '【条件】无
【效果】等级合计到3以上，自己场上表侧表示怪兽（恶魔族）作为素材送去墓地，咒仪召唤「绝望狂魔 死·核」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP036', '苍救之闪戟士 雷克斯席翁', '怪兽（水属性/战士族）＋「苍救天使 日」＋「苍救天使之魂」
【条件】卡组最上面的卡送去墓地才能发动。
【选择效果】
●这个回合，这张卡可以直接攻击。
●这张卡的攻击力·守备力直到回合结束时上升1500。
●这个回合，这张卡可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP045', '苍救之王姬 利姆丽丝', '这张卡可以只解放1只怪兽（水属性/战士族）或者怪兽（天使族）攻击表示上级召唤。
【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地的「苍救天使 日」「苍救天使 月」「结合」合计最多2张加入手卡。那之后，可以选自己场上1只怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SJMP-JP061', '强欲之瓶', '【条件】自己或者对方召唤怪兽时，或者自己回合自己抽卡时才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP000', '神兽王 巴巴罗斯', '这张卡可以不用解放或者把3只表侧表示怪兽（地属性）解放攻击表示召唤。不用解放的场合，这张卡的原本攻击力变成1900。
【条件】上记的方法把3只怪兽解放来把这张卡召唤的回合才能发动。
【效果】对方场上的表侧表示的卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP001', '虚空噬骸兵·鹳式东方号', '【条件】把1张手卡或者从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「接触体·暗物质旅行者号」。这个效果的条件把手卡送去墓地的场合，可以作为代替把这张卡的卡名在这个回合变成「虚空噬骸兵 镇魂鹰巨人」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP002', '虚空精灵·旅行水黾', '【条件】自己卡组的卡是10张以上的场合，把手卡1只怪兽（地属性·水属性·炎属性·风属性/银河族）送去墓地或让自己墓地4只怪兽（1星以外/银河族）回到卡组才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP003', '虚空精灵·斯特鲁维吉丁虫', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「虚空精灵·天宇七星瓢虫」。那之后，可以选自己墓地最多2张「微新星」加入手卡。这个效果的发动后，直到回合结束时自己不能把怪兽（银河族以外）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP004', '虚空精灵·星斗螳螂', '【条件】自己场上的表侧表示怪兽的属性是3种类的场合或者自己墓地有「微新星」的场合才能发动。
【效果】选自己墓地1只效果怪兽（4星以外/地属性·水属性·炎属性·风属性/银河族）加入手卡。那之后，可以选自己墓地1张「微新星」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP005', '虚空精灵·仙女蚂蚁', '自己墓地有怪兽（银河族）3只以上的场合，这张卡可以不用解放作召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这个回合，怪兽（银河族）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。并且，可以再选自己墓地1只「虚空精灵·天宇七星瓢虫」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP006', '虚空精灵·天宇七星瓢虫', '【条件】自己卡组的卡是10张以上的场合，让自己墓地1张卡回到卡组才能发动。
【效果】选自己1张手卡送去墓地。那之后，自己可以抽1张。抽卡的场合，可以再选自己墓地1张「微新星融合」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP007', '冥迹之纳河', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只怪兽（地属性/兽战士族/攻击力1000）加入手卡。这个回合，自己不用怪兽（地属性/兽战士族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP008', '伊西利亚的依代', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地的「伊西利亚的供物」「伊西利亚之棺」「伊西利亚的灵魂」的其中1张加入手卡。加入的场合，可以再选自己墓地1张「冥迹祭-伊西利亚的降灵-」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP009', '冥迹之卡迪', '自己场上有表侧表示的「冥跡のジュンディー」或者「伊西利亚的依代」的场合，这张卡可以从手卡往自己场上表侧守备表示特殊召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段，把卡组最上面的卡送去墓地才能发动。
【效果】下次的对方回合，对方只能有最多2次攻击宣言。并且，可以再选自己墓地3只怪兽（兽战士族）回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP010', '冥迹之埃米尔', '【条件】无
【永续效果】这张卡和自己场上的魔法·陷阱卡不会被对方的效果破坏。自己场上的表侧表示怪兽（地属性/兽战士族）的攻击力上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP011', '月力吱吱鸟', '【条件】自己卡组的卡是10张以上的场合，把这张卡以外的自己的手卡·场上最多2张卡给双方确认，用喜欢的顺序回到持有者卡组下面才能发动。
【效果】自己抽出［这个效果的条件回去的卡的数量］。这个效果的发动后，直到回合结束时自己不能把怪兽（地属性/银河族）以外的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP012', '月力吊雪貂', '【条件】自己墓地的怪兽是4只以下的场合才能发动。
【效果】从对方卡组上面把2张卡送去墓地。那之后，对方墓地有怪兽5只以上，自己在这次主要阶段没有抽卡的场合，自己可以抽2张。这个效果的发动后，直到回合结束时自己不能把怪兽（地属性/银河族）以外的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP013', '月力姑娘鼠', '【条件】自己墓地的怪兽是4只以下的场合才能发动。
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选怪兽（2星以外/地属性/银河族）和「悠久之乡-妖光圣殿-」各最多1张加入手卡。剩下的卡用喜欢的顺序回到卡组下面。这个回合，自己不用怪兽（地属性/银河族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP014', '月力睡刺猬', '【条件】把自己场上1只表侧表示怪兽的表示形式变更才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）。下次的对方回合，对方不能用那只怪兽攻击。并且，可以再选自己墓地1只怪兽回到卡组下面。回去的场合，这张卡的守备力直到下次的对方回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP015', '月力梳耳兔', '【条件】这张卡召唤的回合，自己卡组的卡是10张以上的场合，让1张手卡和自己墓地1只怪兽（地属性/银河族）用喜欢的顺序回到卡组下面才能发动。
【效果】自己抽2张。这个回合，自己不用怪兽（地属性/银河族）不能攻击，对方不会受到效果伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP016', '火面忍者 导火直面', '【条件】把1张手卡送去墓地才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1只通常怪兽（炎族）或者1张「火面味变化之术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP017', '特务万能调味查察官', '自己墓地有通常怪兽（炎族）的场合，这张卡可以不用解放作召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「万能調味査察官」。那之后，可以选自己墓地1张「フュージョン」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP018', '爱之兔', '【条件】自己卡组的卡是10张以上的场合，把手卡1只怪兽（天使族/攻击力0）给对方观看才能发动。
【效果】自己抽1张。那之后，选自己1张手卡送去墓地。自己场上有原本攻击力是0的表侧表示怪兽（暗属性/天使族）的场合，可以再选对方场上1只表侧表示怪兽那个攻击力直到回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP019', '爱之天仙', '【条件】把这张卡以外的自己的手卡·场上1张卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升1800。这张卡召唤的回合把这个效果发动的场合，可以再选自己墓地1只怪兽（7星以上/天使族/攻击力0）或者1张「ラヴ・クリーン」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP020', '饶有情趣的菓子犬', '【条件】自己场上有这张卡以外的表侧表示怪兽（光属性/水族）的场合，把卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力·守备力直到回合结束时下降500。自己场上有表侧表示的「饶有情趣的菓子假名姬」的场合，可以再选对方场上最多2只怪兽把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP021', '饶有情趣的菓子绘卷姬', '【条件】把1张手卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以选自己墓地1只通常怪兽（水族）或者怪兽（4星/光属性/水族）加入手卡。这个效果选「饶有情趣的菓子假名姬」的场合，可以再选自己墓地1张仪式术魔法卡在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP022', '饥饿的洋葱圈', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1张「打包袭击」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP023', '电子义体海豚', '【条件】自己场上有表侧表示的仪式术怪兽（7星以下/水属性/鱼族）的场合才能发动。
【效果】选对方场上1张卡回到持有者手卡。这个回合，自己不能用怪兽（鱼族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP024', '电子义体奈耳', '【条件】无
【永续效果】双方的战斗阶段内，自己场上的表侧表示怪兽（鱼族）的攻击力上升［自己场上的怪兽数量］×400。自己的「要塞鲸」可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP025', '梦中之虎甲', '【条件】把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】这个回合，怪兽（光属性/昆虫族）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。并且，可以再选对方场上1只表侧表示怪兽那个种族直到回合结束时变成昆虫族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP026', '猛兽剑士', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升600。那之后，可以选自己1张手卡送去墓地。这个效果送去墓地的场合，可以再选对方场上1只怪兽把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP027', '圣祠尖鼻神鱼', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1张仪式术魔法卡在自己的魔法与陷阱区域盖放。这个回合，自己不能用怪兽（鱼族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP028', '疯狂犯罪者·变色龙女', '【条件】这张卡召唤的回合，让自己墓地3只怪兽回到卡组才能发动。
【效果】选对方场上1只攻击表示的效果怪兽（3～8星）破坏。这个效果把原本等级是6星的怪兽破坏的场合，可以再给与对方600伤害。这个回合，自己不能用怪兽（6星以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP029', '电动刃虫', '【条件】无
【永续效果】这张卡战斗破坏怪兽送去墓地时，对方抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP030', '兽岩块 轰鸣砾石堆', '这张卡可以把1只怪兽（银河族）解放攻击表示上级召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP031', '虚空噬骸兵·彼端探测器', '「接触体·暗物质旅行者号」＋怪兽（4星以下/暗属性）
这张卡可以用接触融合术。
【条件】这张卡融合术召唤的自己主要阶段才能发动。
【效果】选对方的魔法与陷阱区域1张里侧表示的卡破坏。这个回合，自己不用怪兽（暗属性/银河族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP032', '永恒虚空噬骸兵·镇魂鹰巨人', '「虚空噬骸兵 镇魂鹰巨人」＋怪兽（暗属性/银河族）1只以上
【条件】无
【永续效果】对方回合内，这张卡不会因怪兽的效果回到手卡·卡组·额外卡组。怪兽3只以上为素材作融合术召唤的这张卡不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP033', '虚空精灵·星条瓢虫', '「虚空精灵·天宇七星瓢虫」＋怪兽（风属性）
【条件】这张卡融合术召唤的自己主要阶段，让自己墓地1只怪兽（7星以下/风属性）回到卡组下面才能发动。
【效果】这张卡的攻击力直到回合结束时上升［这个效果的条件回去的怪兽的等级］×500。这个回合，自己不用怪兽（银河族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP034', '虚空精灵·星宇蜉蝣', '「虚空精灵·天宇七星瓢虫」＋怪兽（水属性）
【条件】这张卡融合术召唤的自己主要阶段，让包含怪兽（水属性）的自己墓地3只怪兽（银河族）回到卡组才能发动。
【效果】选对方场上的表侧表示怪兽（8星以下）或者里侧表示怪兽合计最多3只回到持有者手卡。这个回合，自己只能用1只怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP035', '火面速忍 开售中华冷面', '「火面忍者 导火直面」＋「万能調味査察官」
【条件】让自己墓地3只怪兽（炎族）回到卡组才能发动。
【效果】这个回合，这张卡可以直接攻击。并且，可以再选对方场上1只攻击表示怪兽变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP036', '火面特忍 音爆极粗面·浓厚贰星', '「火面上忍 极粗面」＋「万能調味査察官」
【条件】这张卡融合术召唤的自己主要阶段才能发动。
【效果】选自己墓地1只怪兽（7星/炎族）在自己场上表侧表示特殊召唤。这个效果把「火面上忍 极粗面」特殊召唤的场合，可以再选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP037', '冥迹神 伊西利亚', '这张卡不用「冥迹祭-伊西利亚的降灵-」的效果不能特殊召唤。
【条件】无
【永续效果】这张卡不会被效果破坏。自己把怪兽（兽战士族）表侧表示召唤·特殊召唤时对方不能把陷阱卡发动。自己回合内，这张卡以外的自己场上的表侧表示怪兽（地属性/兽战士族）的攻击力上升3000，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP038', '太阴月力白狼犬', '【条件】这张卡特殊召唤的自己主要阶段，自己墓地的怪兽是5只以下的场合，把自己场上1只表侧表示怪兽的表示形式变更才能发动。
【效果】直到下次的对方回合结束时，这张卡是表侧表示的期间，对方不能从墓地把怪兽（5星以下）表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP039', '太阴月力年糕猫', '【条件】让这张卡以外的自己场上的表侧表示怪兽或者自己墓地的怪兽合计3只用喜欢的顺序回到持有者卡组下面才能发动。
【效果】选对方场上1只怪兽破坏。那之后，对方墓地有怪兽5只以上的场合，可以选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP040', '太阴月力仙灵龙', '【条件】对方墓地的怪兽数量比自己墓地的怪兽数量多的场合，让自己墓地1只怪兽回到卡组下面才能发动。
【效果】直到下次的对方回合结束时，这张卡的攻击力上升［双方墓地的怪兽数量差］×100，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP041', '要塞鲸', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP042', '影力爆发', '【条件】自己没有把「影力爆发」发动的回合，让1张手卡回到卡组上面或下面才能发动。
【效果】选自己墓地2只卡名不同的怪兽（8星以下/暗属性/银河族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP043', '虫虚空洞', '【条件】无
【效果】自己的手卡·场上的怪兽作为素材送去墓地，把有「虚空噬骸兵 镇魂鹰巨人」或者「接触体·暗物质旅行者号」的卡名作为素材记述的怪兽（9星以下/银河族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP044', '微新星', '【条件】把1张手卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽，那个攻击力直到回合结束时上升800。那之后，可以给与对方为［自己墓地的怪兽的属性种类］×100伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP045', '微新星融合', '【条件】无
【效果】自己的手卡·场上的原本种族是银河族的怪兽作为素材送去墓地，把有「虚空精灵·天宇七星瓢虫」的卡名作为素材记述的怪兽融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP046', '冥迹祭-伊西利亚的降灵-', '【条件】把手卡和自己场上的里侧表示的卡之内「伊西利亚的供物」「伊西利亚之棺」「伊西利亚的灵魂」各1张送去墓地才能发动。
【效果】等级合计直到4以上的自己场上的表侧表示的「伊西利亚的依代」作为素材送去墓地，把「冥迹神 伊西利亚」仪式术召唤（不能把多余怪兽作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP047', '伊西利亚的供物', '【条件】无
【效果】自己回复600基本分。那之后，可以选自己场上1只表侧表示怪兽（地属性/兽战士族）那个攻击力直到回合结束时上升600。这个回合，自己不用怪兽（地属性/兽战士族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP048', '伊西利亚之棺', '【条件】自己墓地有怪兽（7星/地属性/兽战士族）的场合，把自己场上1只怪兽送去墓地才能发动。
【效果】选自己墓地1只怪兽（7星/地属性/兽战士族）在自己场上表侧表示特殊召唤。这个回合，自己不用怪兽（地属性/兽战士族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP049', '冥迹祭的准备', '【条件】无
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选「伊西利亚的依代」「冥迹祭-伊西利亚的降灵-」「伊西利亚的供物」「伊西利亚之棺」「伊西利亚的灵魂」的其中1张加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP050', '心灵之友', '【条件】无
【效果】等级合计直到变成和仪式术召唤的怪兽相同为止，让自己场上的表侧表示怪兽（银河族）作为素材回到持有者卡组，把和作为素材的怪兽卡名不同的仪式术怪兽（地属性/银河族）仪式术召唤。那之后，可以从对方卡组上面把最多有［这个效果作为素材的怪兽数量］的卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP051', '向阳处的片刻', '【条件】自己没有把「向阳处的片刻」发动的回合才能发动。
【效果】从自己卡组上面把6张卡翻开，给双方确认。自己可以从那之中选1只怪兽（5星以下/地属性/银河族）在自己场上表侧表示特殊召唤。剩下的卡用喜欢的顺序回到卡组下面。这个回合，自己不用怪兽（地属性/银河族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP052', '悠久之乡-妖光圣殿-', '【条件】这张卡在自己墓地的怪兽是4只以下的场合才能发动。
【效果】只要这张卡在场地区域处于表侧表示，双方在「心灵之友」的效果仪式术召唤的场合，也能把自身墓地的怪兽（银河族）作为素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP053', '火面味变化之术', '【条件】自己没有把「火面味变化之术」发动的回合，把额外卡组1只融合术怪兽（炎属性/攻击力2900）给对方观看，宣言1个在那只怪兽有作为素材记述的卡名才能发动。
【效果】选自己场上1只表侧表示怪兽。那只怪兽的卡名在这个回合变成这个效果的条件宣言的卡名。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP054', '爱之联络', '【条件】无
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1只怪兽（暗属性/天使族/攻击力0）加入手卡。自己场上有原本的攻击力·守备力是0的表侧表示怪兽（光属性/天使族）的场合，可以再选对方场上1张里侧表示的卡回到持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP055', '饥饿的特别优惠券', '【条件】无
【效果】选对方场上1只表侧表示怪兽变成里侧守备表示。那之后，可以选自己场上1只表侧表示怪兽（6星以下/暗属性/战士族）。选的场合，这个回合，那只怪兽的等级上升3星，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP056', '刚沐宇后的宇宙姬', '【条件】自己没有把「刚沐宇后的宇宙姬」发动的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选融合术怪兽以外的自己的手卡·墓地1只怪兽（9星/银河族）在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP057', '要塞鲸的誓言', '【条件】无
【效果】等级合计直到7以上的自己的手卡·场上的怪兽作为素材送去墓地，把「要塞鲸」仪式术召唤（不能把多余怪兽作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP058', '过浅的墓穴', '【条件】对方场上的怪兽是2只以下，对方墓地有怪兽的场合才能发动。
【效果】选自己墓地1只怪兽在自己场上里侧守备表示特殊召唤。那之后，对方可以选自身墓地1只怪兽在自身场上里侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP059', '旋转绑架事件', '【条件】自己卡组的卡是10张以上的场合才能发动。
【效果】选自己墓地6只怪兽（暗属性/银河族）回到卡组。那之后，可以选自己墓地1只怪兽（7·8星/银河族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP060', '昆虫金牛环', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以让自己场上的全部表侧表示怪兽的攻击力直到回合结束时上升［自己墓地的怪兽（银河族）的属性种类］×100。并且，可以再选自己墓地1张「微新星」或者「微新星融合」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP061', '伊西利亚的灵魂', '【条件】对方回合对方把怪兽召唤·特殊召唤时才能发动。
【效果】选对方场上1只表侧表示的效果怪兽（8星以下）。这个回合，对方不能把选的怪兽的效果发动。并且，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP062', '冥迹的记录', '【条件】自己墓地有怪兽（地属性/兽战士族）的场合，对方怪兽的攻击宣言时才能发动。
【效果】那次攻击无效。那之后，可以选自己墓地1只怪兽（地属性/兽战士族）在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP063', '爱之洁净', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】选自己场上最多3只原本攻击力是0的表侧表示怪兽（天使族），那些攻击力直到回合结束时上升1000。自己场上有表侧表示的「全爱·女神」的场合，可以再选对方场上1只怪兽回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP064', '沙尘之大龙卷', '【条件】对方抽卡时、对方把魔法·陷阱卡盖放时或者对方怪兽的攻击宣言时才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，可以选自己手卡1张魔法·陷阱卡在自己场上盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP065', '元素英雄 金刃侠', '【条件】无
【永续效果】这张卡的攻击带有贯通。自己回合内，自己或者对方场上有表侧表示的「摩天楼」的场合，这张卡的攻击力上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JP066', '元素英雄 电离钳侠', '「元素英雄 电光侠」＋「元素英雄 金刃侠」
这张卡不用融合术召唤不能特殊召唤。
【条件】把1张手卡送去墓地才能发动。
【效果】选对方场上1只攻击表示怪兽破坏。并且再在这个回合让这张卡的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP24-JPS00', '宇宙膛室之欲望淘气鬼', '【条件】这张卡召唤·特殊召唤的自己主要阶段，支付500基本分才能发动。
【效果】自己抽3张。那之后，选自己2张手卡用喜欢的顺序回到卡组下面。这个回合，自己不能把「宇宙膛室之欲望淘气鬼」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP002', '传说的魔术师', '【条件】无
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从那之中选1只怪兽送去墓地。剩下的卡回到卡组。那之后，可以选自己墓地1只传说通常怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP003', '传说的祭司', '手卡或者墓地的这张卡变成传说卡。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，自己墓地有传说卡的场合，可以选对方场上1只表侧表示怪兽那个攻击力·守备力直到回合结束时下降600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP004', '超可爱执行者紧急出动！', '【条件】无
【效果】选自己的手卡·墓地1只怪兽（6星/守备力500）在自己场上表侧表示特殊召唤。这个回合，自己不能用怪兽（7星以上）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP005', '黑洞', '【条件】无
【效果】双方场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP006', '魔法羊女 咩～歌小妹', '咩咩旋律♪家畜咩～虐杀咩～！咩～歌小妹是羊界牧场的公主。吃到美味的纸和重要的信就情不自禁地喊出「真香咩～♪」！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP007', '大魔法羊女 咩～歌小妹·最大级羊毛［L］', '墓地的这张卡的卡名变成「魔法羊女 咩～歌小妹」。
【条件】把2张手卡送去墓地才能发动。
【效果】这个回合，这张卡的攻击带有贯通。并且这张卡是极大模式的场合，再在这个回合让这张卡的攻击力上升1000，不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP008', '大魔法羊女 咩～歌小妹·最大级羊毛', '可以和「大魔法羊女 咩～歌小妹·最大级羊毛［L］」「大魔法羊女 咩～歌小妹·最大级羊毛［R］」集齐作极大召唤。墓地的这张卡的卡名变成「魔法羊女 咩～歌小妹」。
【条件】把手卡1张「肉与贪欲见面会」或者「意乱情迷咩～歌☆羊～毛超级光线」送去墓地才能发动。
【效果】选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP009', '大魔法羊女 咩～歌小妹·最大级羊毛［R］', '墓地的这张卡的卡名变成「魔法羊女 咩～歌小妹」。
【条件】无
【效果】选自己墓地的通常怪兽（兽族）、「肉与贪欲见面会」、「意乱情迷咩～歌☆羊～毛超级光线」的其中1张加入手卡。这张卡是极大模式的场合，可以作为代替选合计最多3张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP010', '咩～界的王姬 咩～歌小妹', '「魔法羊女 咩～歌小妹」＋通常怪兽（兽族）×2', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP011', '咩～界 羊毛火妖', '「羊界 羊毛火妖」＋「羊界 羊毛火妖」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP012', '咩～界 羔羊雷妖', '「羊界 羔羊雷妖」＋「羊界 羔羊雷妖」
【条件】把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】选对方场上最多2张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP013', '咩～界 绵羊水妖', '「羊界 绵羊水妖」＋「羊界 绵羊水妖」
【条件】把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】选对方场上1只怪兽回到持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP014', '咩～界 羊皮地妖', '「羊界 羊皮地妖」＋「羊界 羊皮地妖」
【条件】无
【永续效果】这张卡不能攻击，守备表示的这张卡不会被战斗破坏。自己场上的表侧表示的「魔法羊女 咩～歌小妹」「咩～界的王姬 咩～歌小妹」的攻击力上升700，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP015', '羊界 羊肉夜妖', '羊界牧场的内向孩子。总是待在角落像大人那样稳静。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP016', '羊界 羊毛火妖', '羊界牧场的年长者。热血指导呛得周围都敬而远之。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP017', '羊界 玛丽影妖', '【条件】自己场上有表侧表示的通常怪兽（兽族）的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以选自己墓地1张「咩～界的入口」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP018', '羊界 牲畜绒妖', '【条件】自己墓地有「魔法羊女 咩～歌小妹」的场合，把1张手卡送去墓地才能发动。
【效果】选自己墓地1只「魔法羊女 咩～歌小妹」加入手卡或在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP019', '羊界 白羊气妖', '羊界牧场的风中浪子。周围的喧嚣也成耳边风。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP020', '羊界 羔羊雷妖', '羊界牧场的干将。亮起眼睛监视同伴的一举一动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP021', '羊界 母羊植妖', '【条件】自己场上有表侧表示的通常怪兽（兽族）的场合才能发动。
【效果】选自己墓地1张「肉与贪欲见面会」或者「羊界-墓地积怨念」在自己的魔法与陷阱区域盖放。自己场上有表侧表示的「魔法羊女 咩～歌小妹」的场合，再让自己可以回复600基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP022', '羊界 家羊浪妖', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】自己回复200基本分。自己墓地的通常怪兽（兽族）的属性是3种类以上的场合，可以再选自己墓地1只「魔法羊女 咩～歌小妹」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP023', '羊界 绵羊水妖', '羊界牧场的慢性子。不慌不忙地观望形势。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP024', '羊界 羊皮地妖', '羊界牧场的新面孔。不劳如地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP025', '咩～界的入口', '【条件】无
【效果】自己场上1只表侧表示怪兽（兽族）送去墓地。那之后，可以让自己的场上·墓地的怪兽（兽族）作为素材回到持有者卡组把怪兽（暗属性/兽族/守备力1600）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP026', '咩～歌小妹的粉丝咩～信', '【条件】把手卡1只通常怪兽（兽族）送去墓地才能发动。
【效果】自己抽2张。这个效果的条件让「魔法羊女 咩～歌小妹」被送去墓地的场合，可以再选自己墓地1只通常怪兽（4星以下/兽族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP027', '肉与贪欲见面会', '【条件】把2张手卡送去墓地才能发动。
【效果】选自己场上1只表侧表示的通常怪兽（兽族）。这个回合，那只怪兽可以向怪兽作3次攻击。并且自己场上有表侧表示的「魔法羊女 咩～歌小妹」的场合，可以再让对方场上的全部表侧表示的效果怪兽的攻击力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP028', '意乱情迷咩～歌☆羊～毛超级光线', '【条件】自己场上有表侧表示的「魔法羊女 咩～歌小妹」的场合，把手卡2只通常怪兽（兽族）送去墓地才能发动。
【效果】对方场上的表侧表示怪兽（8星以下）全部破坏。这个回合，自己不能用怪兽（兽族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP029', '羊界的睡个好觉', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以把对方场上的表侧表示怪兽选最多有［这个效果送去墓地的极大怪兽（兽族）和通常怪兽（兽族）数量合计］变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP030', '羊界与咩～界的逆转', '【条件】自己墓地有怪兽（兽族）15只以上的场合，对方抽卡时，把自己手卡全部送去墓地才能发动。
【效果】双方墓地的卡全部回到持有者卡组。那之后，自己可以抽1张。抽卡的场合，那张卡给双方确认。那张卡是怪兽（7星以上/兽族）的场合，可以再把那只怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP031', '羊界-墓地积怨念', '【条件】由自己的攻击表示的通常怪兽（兽族）承受攻击的对方怪兽的攻击宣言时，从卡组上面把4张卡送去墓地才能发动。
【效果】受到攻击的怪兽的攻击力直到回合结束时下降2000。那之后，自己可以选这个效果的条件送去墓地的最多4张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP032', '洗礼的暗黑骑士 盖亚', '手卡或者墓地的这张卡的卡名变成「暗黑骑士 盖亚」。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1张「混沌的仪式」加入手卡。那之后，可以让这张卡的等级直到回合结束时上升1星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP033', '混沌刀剑骑手', '【条件】把手卡1只怪兽（4星/攻击力500/守备力1000）给对方观看，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升1000。那之后，可以选自己场上1只表侧表示的仪式术怪兽（8星/战士族）那个攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP034', '混沌素材', '【条件】把手卡1只怪兽（4星/攻击力500/守备力1000）给对方观看，从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升1000。那之后，可以让这张卡的等级直到回合结束时上升4星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP035', '混沌祈祷师', '【条件】让自己墓地2只怪兽（4星/攻击力500/守备力1000）回到卡组才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升1000。那之后，可以选对方的魔法与陷阱区域1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP036', '混沌苏生者', '【条件】让自己墓地2只怪兽（4星/攻击力500/守备力1000）回到卡组才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升1000。那之后，可以选效果怪兽以外的自己墓地1只仪式术怪兽（8星/战士族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP037', '速击之骑士', '【条件】把1张手卡送去墓地或把手卡1只怪兽（4星/攻击力500/守备力1000）给对方观看才能发动。
【效果】自己卡组最上面的卡送去墓地。那之后，可以选自己墓地1张「混沌的仪式」或者「超战士的一击」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP038', '混沌的仪式', '【条件】无
【效果】等级合计直到8以上的自己的手卡·场上的怪兽作为素材送去墓地，把「混沌战士」仪式术召唤（不能把多余怪兽作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP039', '超战士的一击', '【条件】自己场上有表侧表示的「混沌战士」的场合才能发动。
【效果】选对方场上1只表侧表示怪兽回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP040', '混沌的祭具', '【条件】无
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以选1张那之中或者自己墓地的「混沌的仪式」加入手卡。剩下的翻开的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP041', '消除黑暗的剑', '【条件】对方场上有怪兽的场合才能发动。
【效果】选自己墓地1只怪兽（4星/光属性·暗属性/攻击力500/守备力1000）加入手卡。那之后，可以选对方场上1只怪兽变成表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP042', '超战士的闪光', '【条件】对方把怪兽召唤·特殊召唤时，让1张手卡回到卡组下面或把自己场上1只表侧表示的「混沌战士」的表示形式变更才能发动。
【效果】选对方场上1只表侧表示怪兽变成里侧守备表示。自己场上有表侧表示的「混沌战士」的场合，这个效果选的怪兽数量可以变成2只。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP043', '天地谐谑之宇宙姬', '「谐谑之宇宙姬」＋怪兽（银河族/攻击力900）×2只以上
【条件】这张卡特殊召唤的自己主要阶段才能发动。
【效果】选对方场上1张卡破坏。这张卡融合术召唤时作为素材的怪兽数量是9只以上的场合，作为代替把这张卡以外的双方场上的卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP044', '黑极精 秋英宇宙星', '怪兽（银河族/攻击力900）×2
【条件】无
【永续效果】这张卡的攻击带有贯通。自己回合内，对方场上的表侧表示怪兽的攻击力·守备力下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP045', '夕极精 秋英宇宙星', '怪兽（银河族/攻击力900）×3
【条件】这张卡融合术召唤的自己主要阶段才能发动。
【效果】选自己墓地1只融合术怪兽（银河族/守备力1900或者2600）在自己场上表侧表示特殊召唤。那之后，可以选自己墓地1张「宇宙姬的嬉戏」加入手卡。这个回合，自己不能把「夕极精 秋英宇宙星」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP046', '谐谑之宇宙姬', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己场上最多3只怪兽破坏。那之后，可以让自己墓地的怪兽（银河族）最多9只作为素材回到卡组把怪兽（银河族/守备力1900或者2600）融合术召唤。这个回合，自己不能把「谐谑之宇宙姬」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP047', '惑精 石蒜天王星', '把手卡1只「谐谑之宇宙姬」或者1张「宇宙姬的嬉戏」给对方观看，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】自己场上的卡被效果破坏的自己主要阶段才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP048', '惑精 母菊土星', '把手卡1只「谐谑之宇宙姬」或者1张「宇宙姬的嬉戏」给对方观看，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】自己场上的表侧表示怪兽（银河族）作为素材送去墓地，把怪兽（银河族/守备力1900或者2600）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP049', '惑精 木樨木星', '【条件】这张卡召唤的回合才能发动。
【效果】自己场上的这张卡破坏。那之后，可以选自己墓地1只怪兽（6星以上/银河族/攻击力900）在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP050', '惑精 福禄考火星', '【条件】这张卡召唤的回合才能发动。
【效果】选自己场上1张卡破坏。那之后，可以选对方场上1只怪兽把表示形式变更。这个效果的发动后，直到回合结束时自己不能把怪兽（银河族以外）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP051', '惑精 大戟地球', '【条件】这张卡召唤的回合，自己卡组的卡是10张以上的场合才能发动。
【效果】选这张卡以外的自己场上1张卡破坏。那之后，自己可以抽1张。这个效果的发动后，直到回合结束时自己不能把怪兽（银河族以外）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP052', '惑精 石斛金星', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以把自己场上的这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP053', '惑精 水仙水星', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选1只怪兽（6星以上/银河族/攻击力900）加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP054', '搅拌的宇宙姬', '【条件】自己墓地有怪兽（银河族）5只以上的场合，让1张手卡回到卡组下面才能发动。
【效果】自己的场上·墓地的怪兽（银河族）最多3只作为素材回到持有者卡组，把怪兽（银河族/守备力1900或者2600）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP055', '宇宙姬的天体观测', '【条件】自己没有把「宇宙姬的天体观测」发动的回合才能发动。
【效果】选自己墓地1只怪兽（5星以下/银河族/攻击力900）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP056', '宇宙姬的嬉戏', '【条件】把包含2只怪兽的3张手卡送去墓地才能发动。
【效果】选对方场上最多2张卡破坏。那之后，对方场上有卡2张以上的场合，自己可以抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP057', '宇宙姬的就寝', '【条件】自己或者对方把怪兽召唤时，把1张手卡送去墓地才能发动。
【效果】那只召唤的怪兽破坏。那之后，自己可以抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP058', '破界王帝 外宇宙界愿［L］', '墓地的这张卡的卡名变成「外宇宙」。
【条件】极大模式：把卡组最上面的卡送去墓地才能发动。
【效果】这个回合，这张卡不会被效果破坏。并且，可以再选对方场上最多3只表侧表示怪兽那些种族直到回合结束时变成天使族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP059', '破界王帝 外宇宙界愿', '可以和「破界王帝 外宇宙界愿［L］」「破界王帝 外宇宙界愿［R］」集齐作极大召唤。墓地的这张卡的卡名变成「外宇宙」。
【条件】极大模式
【永续效果】对方场上的表侧表示怪兽（银河族以外）的攻击力下降3000。自己回合内，这张卡的种族变成银河族，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP060', '破界王帝 外宇宙界愿［R］', '墓地的这张卡的卡名变成「外宇宙」。
【条件】极大模式
【永续效果】对方回合内，这张卡的攻击力上升［对方场上的表侧表示怪兽（银河族以外）数量］×3000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP061', '外宇宙 安琪利瓦天愿', '手卡的这张卡的卡名变成「破界王帝 外宇宙界愿［L］」，墓地的这张卡的卡名变成「外宇宙」。
【条件】这张卡不是极大模式的场合才能发动。
【效果】选自己墓地1只10星「外宇宙」加入手卡。那之后，可以把这张卡的种族直到回合结束时变成银河族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP062', '外宇宙 戴维尔加魔愿', '手卡的这张卡的卡名变成「破界王帝 外宇宙界愿［R］」，墓地的这张卡的卡名变成「外宇宙」。
【条件】这张卡不是极大模式的场合才能发动。
【效果】选自己墓地1只10星「外宇宙」加入手卡。那之后，可以把这张卡的种族直到回合结束时变成银河族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP063', '外宇宙 母体真菌', '「OTSバグファンガス」＋怪兽（光属性以外）
墓地的这张卡的卡名变成「外宇宙」。
【条件】让自己墓地2只「外宇宙」回到卡组才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。那之后，可以选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP064', '援奏之指挥盗贼', '【条件】让自己墓地2只怪兽（风属性/念动力族/攻击力1300以外）回到卡组才能发动。
【效果】这张卡的等级直到回合结束时上升3星。那之后，可以选自己墓地1张「无人衬词演唱猫盗贼」或者「传统税」在自己的魔法与陷阱区域盖放。盖放的场合，可以再选对方场上1只怪兽把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP065', '传说系谱的魔术师', '墓地的这张卡变成传说卡。
【条件】无
【永续效果】这张卡的攻击带有贯通。攻击表示的这张卡不会因对方的效果变成守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP066', '传说的死灵师', '手卡或者墓地的这张卡变成传说卡。
【条件】把手卡1只怪兽（光属性）送去墓地才能发动。
【效果】选自己墓地1张仪式术魔法卡在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP067', '年轻剑士之祖', '手卡或者墓地的这张卡变成传说卡。
【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只传说怪兽（7星/光属性/守备力300）加入手卡。这个回合，自己不能把「年轻剑士之祖」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP068', '英魂的凭依', '【条件】自己没有把「英魂の憑依」发动的回合才能发动。
【效果】等级合计直到10以上的自己的手卡·场上的怪兽作为素材送去墓地，把「传说系谱的魔术师」仪式术召唤（不能把多余怪兽作为素材）。这个效果不能让传说怪兽以外的手卡的怪兽作为素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP069', '超可爱执行者·细剑女 开拓', '「超可爱执行者·细剑女」＋「超可爱执行者·花草女」
这张卡可以用接触融合术。
【条件】这张卡融合术召唤的自己主要阶段才能发动。
【效果】自己抽1张。那之后，这张卡的攻击力直到回合结束时上升500。这个回合，自己不用怪兽（守备力500）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP070', '超可爱执行者飞马', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只「超可爱执行者·细剑女」或者1张「超可爱执行者骑乘！」加入手卡。这个效果选「超可爱执行者骑乘！」的场合，可以再选对方场上1只表侧表示怪兽那个攻击力直到回合结束时下降1800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP071', '牧牛医·爱心', '「牵引的牧牛医」＋怪兽（4星以下/风属性）
【条件】无
【永续效果】这张卡的战斗不会让双方受到战斗伤害。自己回合内，这张卡的攻击力上升200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP072', '百兽王 贝希摩斯', '这张卡可以把1只怪兽解放攻击表示上级召唤。那个场合，这张卡的原本攻击力变成2000。
【条件】这张卡召唤的回合才能发动。
【效果】自己墓地的怪兽（兽族）选［这张卡上级召唤时解放的怪兽数量］加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP073', '大巨角猛犸', '【条件】这张卡召唤的回合，把卡组最上面的卡送去墓地才能发动。
【效果】直到下次的对方回合结束时，这张卡是表侧表示的期间，双方不能把表侧表示怪兽（4星以下）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP074', '大嘴鼠', '【条件】自己场上没有这张卡以外的怪兽的场合，让自己墓地1只怪兽（兽族）回到卡组下面才能发动。
【效果】选自己墓地1只通常怪兽（兽族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP075', 'THE☆战斗撞击剑', '【条件】可以给自己场上1只表侧表示怪兽装备。
【效果】装备怪兽的攻击力上升200。只要装备怪兽在自己场上处于表侧表示，对方不能把装备魔法卡发动。装备怪兽和对方的守备表示怪兽进行战斗，那只对方怪兽没被破坏的场合，那只对方怪兽变成表侧攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP076', '宇宙风暴', '【条件】自己场上有表侧表示怪兽（银河族）的场合才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP077', '燃召暗黑流星弹', '【条件】让自己墓地2只怪兽回到卡组才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，可以选效果怪兽以外的自己墓地1只融合术怪兽（暗属性·炎属性）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP078', '野兽的激怒', '【条件】自己场上有表侧表示怪兽（兽族·兽战士族）合计2只以上的场合才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，可以选自己墓地1张场地魔法卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP079', '大行进前夜', '【条件】把手卡1只怪兽（7星以上/兽族）给对方观看才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从那之中选最多2只怪兽（4星以下/兽族）在自己场上里侧守备表示特殊召唤。剩下的卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP3-JP080', '破龙的咆钢', '【条件】自己场上有表侧表示的通常怪兽（7星以上）的场合，对方把怪兽（7星以上）召唤时才能发动。
【效果】那只召唤的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP017', '自由风跑车', '这张卡可以把1只怪兽（风属性/守备力1200）解放攻击表示上级召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只「多面手女郎」或者「多面手少女」加入手卡。自己墓地有陷阱卡2张以上的场合，可以再选对方场上1只怪兽把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP000', '多面手女郎', '下至寻猫上至要人护卫样样承包的多面手。最近总是去送午餐，但某天收到了发送人不明的信息。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP001', '外宇宙 酸黏浆怪', '墓地的这张卡的卡名变成「外宇宙」。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。自己墓地有「外宇宙」的场合，可以再选对方场上1只表侧表示怪兽那个攻击力·守备力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP002', '外宇宙 虫草真菌', '墓地的这张卡的卡名变成「外宇宙」。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。那之后，可以选对方场上1只里侧表示怪兽确认。自己墓地有「外宇宙」5只以上的场合，可以再把确认的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP003', '外宇宙 星斗阿努比斯', '墓地的这张卡的卡名变成「外宇宙」。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。那之后，可以选对方场上1只攻击表示怪兽变成表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP004', '外宇宙 雨刺', '墓地的这张卡的卡名变成「外宇宙」。
【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。那之后，可以把自己的手卡·场上的怪兽作为素材送去墓地把怪兽（地属性·水属性·炎属性·风属性）融合术召唤。这个回合，自己不能用怪兽（银河族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP005', '外宇宙 制针机', '墓地的这张卡的卡名变成「外宇宙」。
【条件】从卡组上面把3张卡送去墓地才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。并且再在这个回合在「外宇宙 爆裂忘却龙」攻击表示上级召唤的场合让表侧表示的这张卡可以作为2只的数量解放。这个回合，自己不能用怪兽（银河族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP006', '外宇宙 毕久瓦索', '自己墓地有「外宇宙」3只以上的场合，这张卡可以不用解放作召唤。墓地的这张卡的卡名变成「外宇宙」。
【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。那之后，可以选自己墓地1张「外宇宙多样性尖叫」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP007', '外宇宙 风精赛弗特', '墓地的这张卡的卡名变成「外宇宙」。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。那之后，可以选自己场上最多3只表侧表示怪兽那些攻击力直到回合结束时上升［自己场上的表侧表示怪兽的属性种类］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP008', '外宇宙 爆裂忘却龙', '墓地的这张卡的卡名变成「外宇宙」。
【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。那之后，可以选炎族以外的自己墓地1只「外宇宙」在自己场上表侧表示特殊召唤。这个回合，这个效果特殊召唤的怪兽的攻击力上升700，不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP009', '挥乐姬 指挥棒薙刀手', '手卡或者墓地的这张卡的卡名变成「挥乐姬 指挥棒棍手」。
【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「挥乐姬 指挥棒棍手」。那之后，可以选自己墓地1张「融合术」加入手卡。这个回合，自己不用怪兽（风属性/战士族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP010', '号令的成金恐龙王', '墓地的这张卡的卡名变成「号令的成金恐龙王」。
【条件】自己墓地的怪兽只有恐龙族，自己墓地有传说怪兽或者「成金哥布林」的场合才能发动。
【效果】选对方场上1只怪兽破坏。那之后，自己墓地有「成金哥布林」的场合，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP011', '深渊海兽·万花华莲', '这张卡可以把1只「深渊海兽 卡涟」解放攻击表示上级召唤。
【条件】让自己墓地最多3只怪兽回到卡组才能发动。
【效果】这张卡的攻击力直到回合结束时上升400。这个效果的条件让怪兽3只回去的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP012', '多面手少女', '【条件】这张卡召唤·特殊召唤的自己主要阶段，让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只「多面手女郎」加入手卡。自己场上没有表侧表示的融合术怪兽（8星）的场合，可以再把自己的手卡·场上的原本守备力是1200的怪兽（风属性）2只作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP013', '活泼大头机', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从那之中选怪兽（风属性/守备力1200）或者陷阱卡合计最多2张送去墓地。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP014', '幻影悬浮圈', '【条件】这张卡召唤的回合，自己墓地有陷阱卡的场合，让自己墓地2只怪兽（风属性/守备力1200）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降［自己墓地的陷阱卡数量］×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP015', '地下商人', '【条件】这张卡召唤的回合，自己卡组的卡是10张以上的场合，把手卡1只怪兽（风属性/守备力1200）送去墓地才能发动。
【效果】自己抽1张。自己墓地有陷阱卡2张以上的场合，可以再选自己墓地1只「活泼大头机」或者「幻影悬浮圈」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP016', '开朗女服务员', '【条件】无
【永续效果】自己场上的原本守备力是1200的表侧表示怪兽（7星以上/风属性）的攻击力上升400。这张卡的战斗不会让自己受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP023', '决出胜败的剑士', '墓地的这张卡的卡名变成「龙破坏之剑士」。
【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「龙破坏之剑士」。那之后，可以选自己墓地1张「融合」或者「奇迹之秘术」加入手卡。这个回合，这张卡不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP024', '真红眼冥飞龙', '手卡或者墓地的这张卡的卡名变成「真红眼黑龙」。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示的效果怪兽，那个攻击力直到回合结束时下降300。那之后，可以选自己墓地1只「真红眼冥龙」或者1张「燃召暗黑流星弹」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP025', '双焰魔的飞鼠', '【条件】这张卡召唤的回合，把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地的「双焰魔的祭壇」「焰魔之槛」各最多1张在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP026', '牵引的牧牛医', '【条件】把自己场上1只怪兽送去墓地才能发动。
【效果】自己回复300基本分。那之后，可以把自己的手卡·场上的怪兽（风属性）作为素材送去墓地把怪兽（风属性）融合术召唤。这个回合，自己不能用怪兽（风属性以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP027', '巧阵之玛巴拉斯', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把5张卡翻开，给双方确认。自己可以从那之中选1只怪兽（9星/恶魔族/守备力2000）加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP028', '外宇宙 毒黏浆怪', '「外宇宙 酸黏浆怪」＋怪兽（光属性以外）
墓地的这张卡的卡名变成「外宇宙」。
【条件】让自己墓地2只「外宇宙」回到卡组才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。那之后，可以选持有和原本攻击力不同攻击力的对方场上1只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP029', '外宇宙 无终厄运忘却龙', '「外宇宙 爆裂忘却龙」＋怪兽（光属性以外）×2
墓地的这张卡的卡名变成「外宇宙」。
【条件】让自己墓地5只「外宇宙」回到卡组才能发动。
【效果】这张卡的种族直到回合结束时变成银河族。并且这个回合，这张卡可以向对方怪兽全部各作1次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP030', '弯乐姬 调音短号短弯刀手', '「弯乐姬 短号短弯刀手」＋「挥乐姬 指挥棒棍手」
这张卡可以用接触融合术。
【条件】无
【永续效果】这张卡的攻击带有贯通。自己场上的表侧表示怪兽（风属性/战士族）不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP031', '断乐姬 调音奥菲克莱德阔剑手', '「断乐姬 奥菲克莱德阔剑手」＋「挥乐姬 指挥棒棍手」
这张卡可以用接触融合术。
【条件】无
【效果】选对方场上1只攻击表示怪兽变成里侧守备表示。那之后，可以选自己墓地1张「一気貫通」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP032', '多面手搭档', '「多面手女郎」＋「多面手少女」
【条件】这张卡融合术召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选那之中的陷阱卡1张或者自己墓地的「潜入開始」「任務完了」的其中1张在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP034', '等离子塑料模型 换装雷神俱-再构姬', '【条件】这张卡仪式术召唤的自己主要阶段，把仪式术怪兽以外的自己场上1只表侧表示怪兽送去墓地才能发动。
【效果】选自己墓地1只仪式术怪兽（雷族/守备力1600）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP037', '依然饶有情趣的菓子假名姬', '墓地的这张卡的卡名变成「依然饶有情趣的菓子假名姬」。
【条件】无
【永续效果】这张卡的卡名变成「依然饶有情趣的菓子假名姬」。自己场上的表侧表示怪兽（光属性/水族）的攻击力上升500，等级上升5星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP038', '依然饶有情趣的菓子雏姬', '【条件】这张卡特殊召唤的自己主要阶段，让自己墓地2只怪兽（光属性/水族）回到卡组才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，可以选自己墓地1只「依然饶有情趣的菓子假名姬」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP039', '珠宝祭司的象牙', '【条件】怪兽2只以上作为素材把这张卡仪式术召唤的自己主要阶段才能发动。
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP040', '外宇宙缭乱回收', '【条件】自己墓地有「外宇宙」的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以从那之中选「外宇宙」「外宇宙爆震融合」各最多1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP041', '外宇宙火焰流变', '【条件】自己墓地有「外宇宙」的场合，把1张手卡送去墓地才能发动。
【效果】选自己墓地1只「外宇宙」加入手卡。这个效果选怪兽（7星/炎族）的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP042', '外宇宙逆转领地', '【条件】这张卡在自己墓地的「外宇宙」的种族是5种类以上的场合才能发动。
【效果】只要这张卡在场地区域处于表侧表示，自己回合内，自己场上的表侧表示怪兽（光属性以外/银河族）的攻击力上升1500，对方回合内，自己场上的表侧表示怪兽的种族是3种类的场合，那些怪兽不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP043', '乐姬的代演', '【条件】把1张手卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，自己墓地的怪兽只有风属性的场合，可以选自己墓地1只怪兽（战士族）在自己场上表侧守备表示特殊召唤。这个回合，自己不用怪兽（风属性/战士族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP044', '名流罩衫·死亡单肩衫', '【条件】可以给自己场上1只表侧表示怪兽装备。
【效果】自己把装备怪兽作为融合术召唤的素材的场合，可以把那个卡名变成「名蔷薇巫师」。对方回合只要装备怪兽在自己场上处于表侧表示，装备怪兽不会因效果回到手卡·卡组·额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP045', '热腾腾送上门', '【条件】把这张卡以外的自己的手卡·场上1张卡送去墓地才能发动。
【效果】自己抽1张。那之后，可以选自己墓地1只「多面手少女」或者「开朗女服务员」在自己场上表侧表示特殊召唤。这个回合，自己不用原本守备力是1200的怪兽（风属性）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP046', '第一次寻猫', '【条件】自己卡组的卡是10张以上的场合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地的「潜入開始」「与未知的邂逅」「念之印刻」「任務完了」的其中1张加入手卡。这个回合，自己不用原本守备力是1200的怪兽（风属性）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP051', '等离子塑料模型换装对接', '【条件】无
【效果】等级合计直到8以上的自己场上的表侧表示怪兽（雷族）作为素材送去墓地，把「等离子塑料模型 换装雷神俱-再构姬」仪式术召唤（不能把多余怪兽作为素材）。这个回合，自己不能用怪兽（雷族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP054', '奇迹之秘术', '【条件】对方场上有攻击表示怪兽的场合才能发动。
【效果】自己场上的「黑魔术师」或者「龙破坏之剑士」1只和自己墓地的「黑魔术师」或者「龙破坏之剑士」1只作为素材回到持有者卡组作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP055', '火箭救助', '【条件】无
【效果】选自己墓地1只「真红眼黑龙」或者1张「流星炎融合」加入手卡。那之后，可以选自己墓地1只「陨石龙之雏」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP056', '宝牙的仪式', '【条件】自己没有把怪兽仪式术召唤的回合才能发动。
【效果】等级合计直到6以上的手卡的怪兽作为素材送去墓地，把「珠宝祭司的象牙」仪式术召唤（不能把多余怪兽作为素材）。这个效果把怪兽特殊召唤时对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP057', '外宇宙多样性尖叫', '【条件】自己墓地有「外宇宙」的场合，对方怪兽的攻击宣言时才能发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降1000。自己场上的表侧表示怪兽的属性是2种类以上的场合，可以再让对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP058', '外宇宙爆震融合', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时才能发动。
【效果】选自己墓地2～3只「外宇宙」加入手卡。那之后，可以让手卡的怪兽作为素材回到卡组把怪兽（地属性·水属性·炎属性·风属性）表侧攻击表示融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP059', '疑念的社交场', '【条件】对方在抽卡阶段通常抽卡时才能发动。
【效果】选自己墓地1只怪兽（风属性/守备力1200）加入手卡或在自己场上表侧表示特殊召唤。那之后，自己场上有表侧表示的「多面手女郎」的场合，可以把对方手卡随机选1张送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP061', '深渊海兽万花衣装', '【条件】对方把怪兽召唤·特殊召唤时，让自己墓地2只怪兽回到卡组才能发动。
【效果】选自己场上最多2只攻击表示怪兽（光属性/海龙族）。这个回合，那些怪兽的攻击力上升800，不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP062', '焰魔之槛', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】选自己场上最多2只表侧表示怪兽（恶魔族），那些攻击力·守备力直到回合结束时上升500。自己场上有表侧表示怪兽（10星）的场合，再在这个回合让选的怪兽不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP063', '进化结末闪光', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时才能发动。
【效果】选自己墓地1只融合术怪兽（机械族）在自己场上表侧表示特殊召唤。那之后，可以选对方场上1只怪兽变成表侧攻击表示或者里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP064', '圣塔的半坏', '【条件】对方把极大怪兽以外的效果怪兽表侧表示召唤·特殊召唤时，把1张手卡和自己场上1只怪兽送去墓地才能发动。
【效果】选那1只召唤·特殊召唤的怪兽破坏。没能破坏的场合，那只怪兽回到持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP065', '守护者·艾托斯', '自己墓地没有怪兽的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把自己场上1张表侧表示的装备魔法卡送去墓地才能发动。
【效果】选对方墓地最多3只怪兽回到卡组。那之后，这张卡的攻击力直到回合结束时上升［这个效果回去的怪兽数量］×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP22-JP066', '饥饿的汉堡', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP005', '苍救天使 苏蕾', '【条件】把手卡1只怪兽（战士族）给对方观看才能发动。
【效果】这张卡的卡名在这个回合变成「苍救天使 卢阿」。那之后，从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选1张「融合术」加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP006', '苍救天使 卢阿', '【条件】把手卡1只怪兽（战士族）给对方观看才能发动。
【效果】这张卡的卡名在这个回合变成「苍救天使 苏蕾」。那之后，从自己卡组上面把3张卡送去墓地。并且，可以再从那之中选1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP007', '强欲之壶', '【条件】无
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP008', '苍救的祈愿', '【条件】对方把怪兽召唤·特殊召唤时，让自己墓地1只怪兽（水属性/战士族）和1只怪兽（天使族）用喜欢的顺序回到卡组上面才能发动。
【效果】选对方场上1只怪兽回到持有者卡组下面。那之后，可以选自己墓地1张「苍救的照览」或者「融合术」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP022', '绝望狂魔神 大终魔', '「绝望狂魔 死局终魔」＋「绝望狂魔 恶果终魔」
【条件】让自己墓地6只怪兽回到卡组才能发动。
【效果】选对方场上最多2张卡破坏。那之后，可以选对方墓地1只怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP026', '绝望狂魔 死局终魔', '【条件】让自己墓地4只怪兽回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。那之后，自己墓地有持有相同属性的怪兽6只以上的场合，可以选对方墓地1只怪兽（7星以下）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP027', '绝望狂魔 恶果终魔', '【条件】让自己墓地4张魔法·陷阱卡回到卡组才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，自己墓地有持有相同属性的怪兽6只以上的场合，可以选对方墓地1只怪兽（7星以下）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP030', '绝望狂魔 死线魔', '【条件】这张卡召唤的回合，把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1只「绝望狂魔 死局终魔」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP034', '绝望与切望', '【条件】自己没有把「绝望与切望」发动的回合，从卡组上面把2张卡送去墓地才能发动。
【效果】手卡1只怪兽（3·8星/暗属性/恶魔族/守备力1200）在自己场上表侧表示特殊召唤。那之后，自己场上有「绝望狂魔 死核魔」的场合，可以选自己墓地1只怪兽（暗属性/恶魔族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP039', '苍救之一闪 德古雷斯', '「苍救骑士 邓库斯」＋「苍救天使 苏蕾」
【条件】把卡组最上面的卡送去墓地才能发动。
【选择效果】●这张卡的攻击力直到回合结束时上升［自己场上的表侧表示怪兽（天界战士族）数量］×1000。●这个回合，这张卡可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP040', '苍救之幻影 德卢库穆阿', '「苍救骑士 邓库斯」＋「苍救天使 卢阿」
【条件】无
【永续效果】自己场上的表侧表示的卡不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP041', '苍救之闪光 苏勒希埃勒', '「苍救骑士 西埃拉」＋「苍救天使 苏蕾」
【条件】把这张卡以外的自己场上1张卡给双方确认，回到持有者卡组下面才能发动。
【选择效果】●对方场上的魔法·陷阱卡选最多有［自己场上的表侧表示怪兽（天界战士族）数量］破坏。●选自己墓地1张「苍救之证」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP042', '苍救之泡影 阿卢蒂埃拉', '「苍救骑士 西埃拉」＋「苍救天使 卢阿」
【条件】无
【永续效果】对方不能把「融合术」以外的通常魔法卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP044', '苍救之光耀 加尔弗雷尔', '「苍救骑士 兰加」＋「苍救天使 苏蕾」
【条件】让1张手卡回到卡组下面才能发动。
【选择效果】●对方墓地的卡选最多有［自己场上的表侧表示怪兽（天界战士族）数量］×2张回到卡组。●选自己墓地1只怪兽（4星以下/光属性·暗属性）或者1张「苍救的祈愿」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP047', '苍救骑士 塞尔', '【条件】这张卡召唤的回合，把手卡1张「苍救的祈祷」或者「融合术」给对方观看才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP048', '苍救骑士 兰加', '【条件】这张卡召唤的回合，把手卡1张「苍救的祈祷」或者「融合术」给对方观看才能发动。
【效果】选自己墓地1只「苍救天使 苏蕾」或者「苍救天使 卢阿」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP052', '苍救的照览', '【条件】把手卡的怪兽（战士族·天使族）合计2只给对方观看才能发动。
【效果】从自己卡组上面把5张卡翻开，给双方确认。自己从那之中选1张加入手卡。剩下的卡用喜欢的顺序回到卡组下面。这个效果的发动后直到回合结束时，自己不能用怪兽（8星以下）攻击，对方不会受到效果伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP053', '日落逆转', '【条件】在对方回合对方抽卡时或者在自己场上的怪兽被对方的效果破坏时才能发动。
【效果】选自己的手卡·墓地1只怪兽在自己场上里侧守备表示特殊召唤。那之后，选这张卡以外的自己场上最多3张卡。这个回合，那些卡不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP068', '等离子塑料模型 换装雷神俱-混合姬', '【条件】无
【永续效果】对方场上的表侧表示怪兽的攻击力·守备力下降600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP070', '等离子塑料模型换装竞玩', '【条件】无
【效果】等级合计直到8以上的自己场上的表侧表示怪兽（雷族）作为素材送去墓地，把「等离子塑料模型 换装雷神俱-混合姬」或者「等离子塑料模型 雷神俱-再构姬」仪式术召唤（不能把多余怪兽作为素材）。这个回合，自己不能用怪兽（雷族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP072', '恶魔咒术师', '【条件】把手卡1只怪兽（暗属性/恶魔族）送去墓地才能发动。
【效果】自己抽1张。那之后，可以选对方场上1只表侧表示怪兽（3星以上）那个等级直到回合结束时下降2星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP075', '出发区', '【条件】这张卡在先攻第1回合以外从卡组上面把2张卡送去墓地才能发动。
【效果】只要这张卡在场地区域处于表侧表示，这张卡不会被效果破坏，自身的场地区域有卡的玩家在抽卡阶段作直到手卡变成5张为止通常抽卡的场合，作为代替而作直到手卡变成6张为止通常抽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP077', '苍救骑士 邓库斯', '【条件】把额外卡组最多5只卡名不同的怪兽（天界战士族）给对方观看才能发动。
【效果】这张卡的攻击力直到回合结束时上升［这个效果的条件给人观看的怪兽数量］×200。这个回合，这张卡不能直接攻击，自己不用怪兽（天界战士族·战士族·天使族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP078', '苍救骑士 西埃拉', '【条件】把额外卡组最多5只卡名不同的怪兽（天界战士族）给对方观看才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降［这个效果的条件给人观看的怪兽数量］×200。这个回合，自己不用怪兽（天界战士族·战士族·天使族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP079', '破坏剑士', '【条件】无
【永续效果】这张卡的攻击力上升［对方场上的表侧表示怪兽（龙族）数量和对方墓地的怪兽（龙族）数量的合计］×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP4-JP080', '暗黑释放', '【条件】对方怪兽的攻击宣言时，让自己墓地4只怪兽（魔法师族）回到卡组才能发动。
【效果】对方场上的攻击表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/GC26-JP001', '胜利的旗手 格拉迪尼斯', '—荣耀归于光明。
雄壮的蹄声，踏破残光，彰显霸主之道。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP000', '闪电之战士 吉尔福德', '这张卡可以把3只怪兽解放攻击表示上级召唤。
【条件】把3只怪兽解放来把这张卡召唤的回合才能发动。
【效果】对方场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP002', '零度龙', '栖息在寒冷地域的龙。在雪道上高速移动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP003', 'THE☆齿车戒龙', '7颗超新星释放伽马射线暴的龙。其名就叫THE☆齿车戒龙！THE☆齿车戒龙！！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP004', '银眼星猫', '拥有银色之眼的星猫。充满不可思议。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP005', '金眼星猫', '拥有金色之眼的星猫。十分惹人喜爱。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP006', '接合科技铁皮腕龙', '【条件】把1张手卡送去墓地才能发动。
【效果】选对方场上1只攻击表示怪兽变成表侧守备表示。那之后，那只怪兽的守备力直到回合结束时下降2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP007', '红色化学人', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1张「化学化弹·红」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP008', '虚空噬骸兵·铁甲骑兵', '【条件】这张卡召唤的回合，自己场上有这张卡以外的表侧表示怪兽（暗属性）的场合才能发动。
【效果】自己卡组最上面的卡送去墓地。这个效果让怪兽被送去墓地的场合，可以再选自己墓地1只怪兽（8星/银河族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP009', '虚空噬骸兵·黑矮星兵', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只通常怪兽（4星/暗属性/银河族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP010', '极奏之小提琴马赫毗奥', '【条件】无
【永续效果】这张卡的攻击力上升［这张卡装备的装备魔法卡数量和对方场上的表侧表示的通常怪兽数量的合计］×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP012', 'THE☆克隆', '【条件】自己墓地的怪兽只有多头龙族·龙族的场合，把1张手卡送去墓地才能发动。
【效果】自己抽1张。自己墓地有「THE☆复制」或者「回到THE☆融合术」的场合，再在这个回合让这张卡的卡名变成「THE☆齿车戒龙」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP013', '镜像翼龙', '【条件】这张卡召唤的回合，自己墓地的怪兽只有多头龙族·龙族的场合才能发动。
【效果】选自己墓地1只通常怪兽在自己场上表侧表示特殊召唤。并且再在这个回合让这张卡的卡名变成和这个效果特殊召唤的怪兽相同卡名。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP014', '紫眼星猫', '【条件】无
【效果】选自己墓地1张「野性防护罩 -流浪猫力-」在自己的魔法与陷阱区域盖放。那之后，可以选自己场上1只表侧表示怪兽（7星以上/守备力200）。选的场合，这个回合，那只怪兽可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP015', '绿眼星猫', '【条件】把手卡1只怪兽（兽族或者战士族/守备力200）送去墓地才能发动。
【效果】自己抽1张。这个效果的条件把通常怪兽送去墓地的场合，再在这个回合在怪兽（守备力200）攻击表示上级召唤的场合让表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP016', '猫爪少女', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（兽族/守备力200）在自己场上表侧表示特殊召唤。这个效果把通常怪兽特殊召唤的场合，可以再选自己墓地1张「融合术」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP017', '暗眼破星猫', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】这个回合，这张卡的攻击带有贯通。这张卡特殊召唤的自己主要阶段把这个效果发动的场合，可以再选对方场上1只表侧表示怪兽（7·8星）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP018', '电子羽蛇神', '【条件】自己场上没有这张卡以外的怪兽的场合才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从翻开的卡之中选1只怪兽（5星/机械族）在自己场上表侧表示特殊召唤。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP019', '超可爱执行者·救火女', '对方场上有表侧表示怪兽（6星以上）的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［双方场上的表侧表示怪兽（6星以上）数量］×600。这个回合，自己不用这张卡不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP020', '苍救天使 苏蕾', '【条件】把手卡1只怪兽（战士族）给对方观看才能发动。
【效果】这张卡的卡名在这个回合变成「苍救天使 卢阿」。那之后，从自己卡组上面把4张卡翻开，给双方确认。自己可以从翻开的卡之中选1张「融合术」加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP021', '苍救天使 卢阿', '【条件】把手卡1只怪兽（战士族）给对方观看才能发动。
【效果】这张卡的卡名在这个回合变成「苍救天使 苏蕾」。那之后，从自己卡组上面把3张卡送去墓地。并且再让自己可以从这个效果送去墓地的卡之中选1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP022', '苍救骑士 兰加', '【条件】这张卡召唤的回合，把手卡1张「苍救的祈祷」或者「融合术」给对方观看才能发动。
【效果】选自己墓地1只「苍救天使 苏蕾」或者「苍救天使 卢阿」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP023', '苍救骑士 塞尔', '【条件】这张卡召唤的回合，把手卡1张「苍救的祈祷」或者「融合术」给对方观看才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP024', '苍救骑士 西埃拉', '【条件】把额外卡组最多5只卡名不同的怪兽（天界战士族）给对方观看才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降［这个效果的条件给人观看的怪兽数量］×200。这个回合，自己不用怪兽（天界战士族·战士族·天使族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP025', '苍救骑士 邓库斯', '【条件】把额外卡组最多5只卡名不同的怪兽（天界战士族）给对方观看才能发动。
【效果】这张卡的攻击力直到回合结束时上升［这个效果的条件给人观看的怪兽数量］×200。这个回合，这张卡不能直接攻击，自己不用怪兽（天界战士族·战士族·天使族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP026', '天体生化龙兽', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1张「融合术」在自己的魔法与陷阱区域盖放。这个回合，自己不用融合术怪兽不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP027', '炎神的遗能者', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地最多2只「炎神的遗能者」在自己场上表侧表示特殊召唤。这个效果的发动后，直到回合结束时自己不能把怪兽（战士族以外）召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP029', '传说的战士 吉尔福德', '这张卡不能特殊召唤。
【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地最多3张装备魔法卡各给自己场上的表侧表示怪兽（战士族）装备。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP030', '穿越侍道·线性海牛侍', '「穿越侍·线性海牛侍」＋「七道魔导士」
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己墓地1只通常怪兽（银河族）在自己场上表侧表示特殊召唤。那之后，可以让自己场上的全部表侧表示怪兽（银河族）的攻击力直到回合结束时上升［双方墓地的怪兽的属性种类］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP031', '灯之炎丽 甲醇乙醇灵', '「灯之炎魔 甲醇灵」＋「灯之炎魔 乙醇灵」
【条件】无
【效果】自己抽1张，给双方确认。那张卡是怪兽（炎族）的场合，可以再选自己墓地1只怪兽（8星以下/炎族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP032', '炼金化学化炎精灵', '「化学化火精灵」＋「超级助手 阿炽」
【条件】这张卡特殊召唤的自己主要阶段才能发动。
【效果】双方场上的魔法·陷阱卡全部破坏。那之后，可以让对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降［这个效果破坏的魔法卡数量］×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP033', '虚空噬骸兵·原恒星兵', '「虚空噬骸兵 球状兵」＋「暗黑预言者」
【条件】无
【效果】选自己墓地1只怪兽（4星以下/银河族）加入手卡。自己墓地有「ブラック・ホール」的场合，可以再选自己墓地1只怪兽（8星）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP034', '二重零度龙队', '「零度龙」＋「零度龙」
【条件】自己墓地的怪兽只有多头龙族·龙族的场合，支付500基本分才能发动。
【选择效果】●选自己场上1只表侧表示的通常怪兽。这个回合，那只怪兽可以作2次攻击。●选自己墓地1张「融合术」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP035', 'THE☆星齿车戒龙', '「THE☆齿车戒龙」＋「THE☆齿车戒龙」
【条件】自己墓地有同名通常怪兽2只以上的场合，把1张手卡送去墓地才能发动。
【选择效果】●选自己场上2只同名的攻击表示怪兽。这个回合，那些怪兽各可以作2次攻击。●选自己墓地2只同名通常怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP036', '星猫攻击喵', '「猫爪少女」＋「银眼星猫」
【条件】把这张卡以外的自己场上1张卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力·守备力直到回合结束时下降2200。这个效果的条件把原本守备力是200的通常怪兽送去墓地的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP037', '星猫破坏喵', '「猫爪少女」＋「金眼星猫」
【条件】让自己墓地2只怪兽（守备力200）回到卡组才能发动。
【效果】选自己墓地2只等级相同的怪兽（守备力200）在自己场上表侧表示特殊召唤。这个效果把通常怪兽特殊召唤的场合，那些通常怪兽的攻击力直到回合结束时上升2200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP038', '苍救之闪光 苏勒希埃勒', '「苍救骑士 西埃拉」＋「苍救天使 苏蕾」
【条件】让这张卡以外的自己场上1张卡回到持有者卡组下面才能发动。
【选择效果】●对方场上的魔法·陷阱卡选最多有［自己场上的表侧表示怪兽（天界战士族）数量］破坏。●选自己墓地1张「蒼救の証」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP039', '苍救之泡影 阿卢蒂埃拉', '「苍救骑士 西埃拉」＋「苍救天使 卢阿」
【条件】无
【永续效果】对方不能把「融合术」以外的通常魔法卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP040', '苍救之一闪 德古雷斯', '「苍救骑士 邓库斯」＋「苍救天使 苏蕾」
【条件】把卡组最上面的卡送去墓地才能发动。
【选择效果】●这张卡的攻击力直到回合结束时上升［自己场上的表侧表示怪兽（天界战士族）数量］×1000。●这个回合，这张卡可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP041', '苍救之幻影 德卢库穆阿', '「苍救骑士 邓库斯」＋「苍救天使 卢阿」
【条件】无
【永续效果】自己场上的表侧表示的卡不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP042', '隐性营销魔法', '【条件】把1张手卡送去墓地才能发动。
【效果】自己抽1张。这个效果的条件把魔法卡送去墓地，自己基本分是1000以下的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP043', '破解爪', '【条件】可以给自己场上1只表侧表示怪兽（龙族）装备。
【效果】装备怪兽的攻击力上升［双方场上的表侧表示怪兽（龙族）数量］×200。装备怪兽向怪兽（7星以上）攻击时，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP044', '虚空噬骸兵方阵', '【条件】可以给自己场上1只表侧表示怪兽（银河族）装备。
【效果】装备怪兽的攻击力·守备力上升200。装备怪兽是暗属性的场合，那只怪兽不会被对方的陷阱卡的效果破坏，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP045', '大道武器-破刃剑', '【条件】自己场上没有这张卡以外的表侧表示的「大道武器-破刃剑」的场合，可以给自己场上1只表侧表示的「七道魔导士」装备。
【效果】装备怪兽的攻击力上升［双方场上的装备中的装备魔法卡数量］×1000，那只怪兽不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP046', 'THE☆复制', '【条件】对方场上有表侧表示怪兽（7星以上）的场合才能发动。
【效果】选在自己场上有同名的表侧表示怪兽的自己墓地1只通常怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP047', '回到THE☆融合术', '【条件】自己场上有同名的表侧表示怪兽2只以上的场合才能发动。
【效果】选自己墓地1张「融合术」加入手卡。自己墓地有同名通常怪兽2只以上的场合，可以再从那之中选1只加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP048', '倍斩刃', '【条件】自己场上有同名的表侧表示的通常怪兽（龙族）2只以上的场合，可以给那之中的1只装备。
【效果】装备怪兽的攻击力上升［那只怪兽的原本攻击力］。装备怪兽不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP049', '双倍美喵超速连发', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地的怪兽（兽族或者战士族/守备力200）合计最多2只在自己场上表侧守备表示特殊召唤。这个回合，自己不能用怪兽（守备力200以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP050', '天翔月煌华', '【条件】自己场上有表侧表示的融合术怪兽（天界战士族）或者表侧表示的「月魔将 鬼目流奈」的场合，把1张手卡送去墓地才能发动。
【效果】选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP051', '焰魔的强袭', '【条件】把手卡3只极大怪兽（炎属性）送去墓地才能发动。
【效果】对方场上的表侧表示怪兽全部回到持有者卡组。那之后，可以选自己场上1只表侧表示的极大怪兽那个攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP052', '苍救的祈祷', '【条件】把1张手卡送去墓地才能发动。
【效果】选自己墓地1只怪兽（光属性或者暗属性/天界战士族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP053', '苍救的照览', '【条件】把手卡的怪兽（战士族或者天使族）合计2只给对方观看才能发动。
【效果】从自己卡组上面把5张卡翻开，给双方确认。自己从翻开的卡之中选1张加入手卡。那之后，剩下的卡用喜欢的顺序回到卡组下面。这个回合，自己不能用怪兽（8星以下）攻击，对方不会受到效果伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP054', '苍救之证', '【条件】对方场上有表侧表示怪兽的场合，可以给自己场上1只表侧表示怪兽（天界战士族·战士族·天使族）装备。
【效果】装备怪兽的攻击力上升［那只怪兽的等级］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP055', '暴风轮', '【条件】让自己墓地2只怪兽回到卡组才能发动。
【效果】选对方墓地2～7只卡名不同的怪兽回到卡组。这个效果让怪兽6只以上回去的场合，可以再选对方场上1只表侧表示怪兽（8星以下）回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP056', '穿越侍电光', '【条件】由自己的表侧表示的通常怪兽（4星以下/银河族）承受攻击的对方怪兽的攻击宣言时才能发动。
【效果】受到攻击的怪兽在这个回合不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP057', '接合科技巨壁', '【条件】自己场上有表侧表示怪兽（7星以上/地属性/机械族）的场合，对方把怪兽（7星以上）表侧表示召唤·特殊召唤时才能发动。
【效果】选自己场上最多3只表侧表示怪兽（地属性/机械族）。这个回合，那些怪兽的攻击力上升300，不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP058', '上级屏蔽积木', '【条件】对方把怪兽（5星以上）召唤时才能发动。
【效果】选自己场上1只攻击表示怪兽（龙族或者机械族），那只召唤的怪兽和选的怪兽变成表侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP059', '暗星云', '【条件】自己怪兽（暗属性/银河族/攻击力1500以上）被对方的攻击破坏时才能发动。
【效果】选自己墓地1只怪兽（暗属性/银河族）在自己场上表侧攻击表示特殊召唤。这个效果特殊召唤的怪兽的攻击力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP061', '野性防护罩 -流浪猫力-', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降200。自己场上的表侧表示怪兽（兽族·兽战士族·战士族/守备力200）是合计3只的场合，可以再把对方场上的攻击表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP062', '以太逃脱', '【条件】对方把怪兽（7星以上）召唤时，让自己墓地的怪兽（战士族或者机械族）合计2只回到卡组才能发动。
【效果】那只召唤的怪兽变成里侧守备表示。自己场上有表侧表示的融合术怪兽的场合，可以再选对方场上1张里侧表示的卡回到持有者卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP063', '传统税', '【条件】双方的主要阶段对方抽卡时才能发动。
【效果】对方手卡随机选2张送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP064', '缓冲史莱姆', '【条件】对方怪兽（8星以下）的攻击宣言时才能发动。
【效果】自己卡组最上面的卡送去墓地。这个回合，自己不会受到战斗伤害。自己基本分是3000以上的场合，再让自己受到2000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP065', '幻影咆哮', '【条件】自己怪兽被对方的攻击破坏时，让自己墓地2只怪兽（5星以上）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。那之后，可以选对方场上1只表侧表示怪兽那个攻击力直到下次的自己回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP12-JP066（ORR）連撃竜ドラギアス（连击龙', '齿车戒龙', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这个回合，这张卡战斗破坏怪兽的战斗阶段中，这张卡只再1次可以攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP001', '青眼白龙', '以高攻击力著称的传说之龙。任何对手都能粉碎，其破坏力不可估量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP002', '银河舰忘却龙', '沃·图·征！奥撒姆·特鲁·古奈特！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP003', '七星道魔术师', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［自己墓地的怪兽的属性种类］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP004', '超魔机神 大霸道王［L］', '【条件】极大模式：自己基本分比对方少的场合，把1张手卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［双方基本分差］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP005', '超魔机神 大霸道王', '可以和「超魔机神 大霸道王［L］」「超魔机神 大霸道王［R］」集齐作极大召唤。
【条件】极大模式
【永续效果】这张卡不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP006', '超魔机神 大霸道王［R］', '【条件】极大模式：把卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，这张卡的攻击力直到回合结束时上升［选的怪兽的等级］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP013', '焰魔的导者', '【条件】自己场上没有这张卡以外的怪兽的场合才能发动。
【效果】选自己墓地1只极大怪兽（4星以下）在自己场上表侧表示特殊召唤。这个回合，自己不用极大怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP014', '焰魔的暴蛇', '【条件】对方场上有表侧表示怪兽（7星以上），自己场上没有这张卡以外的怪兽的场合才能发动。
【效果】选自己墓地1只极大怪兽（10星）在自己场上表侧守备表示特殊召唤。这个回合，自己不用极大怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP015', '焰魔的归还', '【条件】无
【效果】选自己场上最多2只表侧表示的极大怪兽（恶魔族）回到持有者手卡。这个回合，自己不用极大怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP016', '焰魔的侵食', '【条件】把自己场上1只表侧表示怪兽（4星以下/恶魔族）送去墓地才能发动。
【效果】选自己墓地1只极大怪兽（10星/恶魔族）加入手卡。这个回合，自己不用极大怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP017', '焰魔的再燃', '【条件】自己的极大怪兽（炎属性）被对方的攻击破坏时，支付600基本分才能发动。
【效果】选自己墓地最多2只极大怪兽（4星以下/炎属性）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP018', '终焰之绝望', '【条件】由自己的表侧表示的极大怪兽承受攻击的对方怪兽（8星以下）的攻击宣言时，支付600基本分才能发动。
【效果】攻击的怪兽回到持有者卡组。自己场上有极大模式的怪兽的场合，再给与对方600伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP031', '超可爱执行者·光天女', '自己场上没有怪兽的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【效果】选自己场上1只表侧表示怪兽（6星）和对方场上1只表侧表示怪兽（7·8星）回到持有者卡组。这个回合，自己不能用怪兽（7星以上）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP032', '超可爱执行者·细剑女', '自己场上有表侧表示怪兽（6星/守备力500）的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【永续效果】双方场上的表侧表示怪兽（7星以上）的攻击力·守备力下降300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP033', '超可爱执行者·浮游女', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只怪兽（水属性以外/6星/守备力500）加入手卡。这个回合，自己不能用怪兽（7星以上）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP034', '超可爱执行者·夜魔女', '自己场上有表侧表示怪兽（6星/守备力500）的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【永续效果】自己不能用怪兽（7星以上）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP035', '超可爱执行者·遥控女', '【条件】让自己墓地1只怪兽（6星/守备力500）回到卡组才能发动。
【效果】选对方场上1只怪兽把表示形式变更（攻击表示变成表侧守备表示，守备表示变成表侧攻击表示）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP036', '超可爱执行者·主存女', '【条件】把手卡1只怪兽（6星/守备力500）送去墓地才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。这个回合，自己不能用怪兽（7星以上）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP037', '超可爱执行者·花草女', '把这张卡以外的手卡1只怪兽（6星/守备力500）给对方观看，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】自己回复500基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP038', '超可爱执行者人才发掘！', '【条件】让自己墓地4只卡名不同的怪兽（6星/守备力500）回到卡组才能发动。
【效果】自己抽2张。这个回合，自己不能用怪兽（7星以上）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP039', '超可爱执行者紧急出动！', '【条件】无
【效果】选自己手卡或者自己墓地1只怪兽（6星/守备力500）在自己场上表侧表示特殊召唤。这个回合，自己不能用怪兽（7星以上）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP040', '超可爱执行者紧急事态！', '【条件】自己场上的表侧表示怪兽（6星）被对方的攻击或者对方的效果破坏时，自己场上没有其他怪兽的场合才能发动。
【效果】选自己墓地1只怪兽（6星/守备力500）在自己场上表侧表示特殊召唤。那之后，可以选对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP041', '超可爱执行者捕获！', '【条件】自己场上有表侧表示怪兽（6星/守备力500）的场合，对方把怪兽表侧表示召唤·特殊召唤时才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP042', '超可爱执行者茶休！', '【条件】对方怪兽的攻击宣言时，让自己场上1只表侧表示怪兽（6星/守备力500）回到持有者卡组上面或下面才能发动。
【效果】那次攻击无效。自己场上有表侧表示怪兽（6星/守备力500）的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP043', '银河冠临夏娃', '【条件】自己场上没有这张卡以外的怪兽的场合，把手卡1只怪兽（银河族/攻击力1600以上）送去墓地才能发动。
【效果】自己场上的这张卡送去墓地，自己抽1张。那之后，自己墓地的怪兽是3只以下的场合，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP044', '接合科技筒仓剑龙', '【条件】把手卡最多3只怪兽（地属性/机械族）送去墓地才能发动。
【效果】对方场上的表侧表示怪兽（守备力1600以下）选［这个效果的条件送去墓地的怪兽数量］破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP045', '百神硬盘龙', '【条件】无
【永续效果】自己在抽卡阶段作直到手卡变成5张为止通常抽卡的场合，作为代替而作直到手卡变成6张为止通常抽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP046', '最终化凤凰', '【条件】对方场上有表侧表示怪兽2只以上的场合，让自己墓地4只怪兽（炎族）回到卡组才能发动。
【效果】等级合计直到变成和［对方场上的表侧表示怪兽的等级合计］相同为止，选自己墓地最多2只效果怪兽（炎族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP048', '暗黑预言者', '【条件】这张卡召唤的回合，让自己墓地3只怪兽（暗属性/银河族）回到卡组才能发动。
【效果】选自己墓地1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP049', '破灭之龙魔导士', '【条件】让自己墓地的怪兽（魔法师族或者龙族）合计4只回到卡组才能发动。
【效果】选自己场上1只表侧表示怪兽。这个回合，那只怪兽不会被对方的陷阱卡的效果破坏。并且，可以再选自己墓地1张「黑暗启示」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP051', '二重双生龙', '【条件】让自己墓地3只怪兽回到卡组才能发动。
【效果】这个回合，怪兽（7星/龙族）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。这个回合，自己不用怪兽（多头龙族或者龙族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP052', '魔将 雅灭鲁拉-武枪', '【条件】无
【永续效果】自己场上的表侧表示怪兽（7星以上/天界战士族或者战士族）不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP053', '可能甜心-偶像：D', '【条件】自己墓地的怪兽只有欧米伽念动力族·念动力族的场合，把1张手卡送去墓地才能发动。
【效果】手卡1只怪兽（7星/念动力族）在自己场上表侧表示特殊召唤。自己墓地有「CAN：D」的场合，再让这张卡的攻击力直到回合结束时上升700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP054', '未来风师', '【条件】这张卡召唤的回合，让自己墓地2只怪兽（风属性）回到卡组才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，自己可以从这个效果送去墓地的卡之中选1张装备魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP055', '兽机界王 滑翔机狐', '【条件】把这张卡以外的自己场上1只表侧表示怪兽（兽战士族/攻击力1500以上）送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。这个回合，自己不能用怪兽（兽战士族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP056', '愤碎龙 凶怒甲龙', '【条件】自己场上有这张卡以外的表侧表示怪兽（恐龙族）的场合，把卡组最上面的卡送去墓地才能发动。
【效果】对方场上的攻击力最高的表侧表示怪兽全部的攻击力直到回合结束时下降［自己场上的守备力最高的表侧表示怪兽的守备力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP058', '魔镜青年', '【条件】这张卡召唤·特殊召唤的自己主要阶段，让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（4星/魔法师族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP059', '升雷神战士', '【条件】无
【效果】自己卡组最上面的卡送去墓地。那之后，可以选对方场上1只表侧表示怪兽（8星以下）。选的场合，下次的对方回合，对方不能用那只怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP060', '钴精寇伯', '【条件】把手卡1只怪兽（恶魔族）送去墓地才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP061', '梦中荧火虫', '【条件】对方场上有怪兽2只以上的场合，把自己场上的表侧表示的这张卡和手卡1只怪兽送去墓地才能发动。
【效果】选持有和这个效果的条件从手卡送去墓地的怪兽相同种族的对方场上1只表侧表示怪兽（5～8星）得到那个控制权（向自己场上移动，由自己使用）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP062', '爱天使', '【条件】无
【永续效果】这张卡不会被和怪兽（7·8星）的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP063', '女武神呼唤', '【条件】无
【效果】选自己墓地1只怪兽（4星/魔法师族）在自己场上表侧表示特殊召唤。那之后，可以选自己场上1只表侧表示的「魔术女武神」那个攻击力直到下次的对方回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP064', '土星力之宝珠', '【条件】自己场上有表侧表示怪兽（6星）的场合，把手卡1只怪兽送去墓地才能发动。
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP066', '女武神防御', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】选自己墓地1只怪兽（4星/魔法师族）在自己场上表侧攻击表示特殊召唤。那之后，可以选包含「魔术女武神」的自己场上最多3只攻击表示怪兽变成表侧守备表示。这个回合，这个效果变成守备表示的怪兽在表侧守备表示的期间不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP067', '工作的言语', '【条件】对方把怪兽（7星以上）召唤时或者对方把魔法卡发动后才能发动。
【效果】选对方墓地最多5只怪兽回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP068', '亚龙地狱', '【条件】对方把怪兽（8星以下）表侧表示召唤·特殊召唤时，把自己场上1只表侧表示怪兽（5星以上）送去墓地才能发动。
【效果】双方场上的表侧表示怪兽之内等级最高的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP069', '黑洞', '【条件】无
【效果】双方场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP1-JP070', '力量结合', '【条件】无
【效果】自己的手卡·场上的怪兽作为素材送去墓地，把怪兽（机械族）融合术召唤。那只怪兽的攻击力上升［那个原本攻击力］。这个回合的结束阶段让自己受到［这个效果上升的数值］的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP000', '七星道魔女', '【条件】把1张手卡送去墓地才能发动。
【效果】手卡1只怪兽（7星以上/暗属性/魔法师族）在自己场上表侧表示特殊召唤。这个效果把「七道魔导士」特殊召唤的场合，再让这张卡的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP001', '大地巫师', '心怀一族骄傲的魔术师。那天他像逃跑似的离开了故乡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP002', '大气巫师', '随风而行歌颂自由的魔术师。任性的行动终会束缚他的未来。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP003', '银河舰既视龙', '【条件】对方基本分是4000以上的场合，把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】自己卡组最上面的卡送去墓地。这个效果让通常怪兽（4星以下/光属性/银河族）被送去墓地的场合，可以再把那只怪兽在自己场上表侧表示特殊召唤。那之后，给与对方为［这个效果特殊召唤的怪兽的原本攻击力］的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP004', '增速飞龙', '【条件】这张卡召唤·特殊召唤的自己主要阶段，自己场上有表侧表示的「碧牙爆速龙」或者「真红动击速龙」的场合才能发动。
【效果】给与对方600伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP005', 'DBF重建龙', '【条件】这张卡召唤·特殊召唤的自己主要阶段，把手卡1只「碧牙爆速龙」或者「真红动击速龙」给对方观看才能发动。
【效果】选自己墓地1张「龙爆速融合」或者「龙击速融合」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP006', '虚空噬骸兵·垂怜鹰巨人', '【条件】把自己场上1只表侧表示怪兽（7星以下/银河族）送去墓地才能发动。
【效果】选自己墓地1只「虚空噬骸兵 镇魂鹰巨人」或者「虚空噬骸兵·金剑鹰巨人」加入手卡。那之后，可以选自己场上1张表侧表示的卡。选的场合，这个回合，那张卡不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP007', '虚空噬骸兵·后勤兵', '【条件】把手卡1只怪兽（7星以上/银河族）给对方观看才能发动。
【效果】选自己墓地1张「融合术」在自己的魔法与陷阱区域盖放。对方场上有表侧表示怪兽（7星以上）的场合，可以再选自己墓地1只怪兽（8星/银河族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP008', '虚空噬骸兵·金剑鹰巨人', '【条件】对方场上有怪兽2只以上的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之中有怪兽（暗属性/银河族）的场合，这个回合，这张卡可以作出最多有那个数量的攻击。并且是3只持有相同等级的怪兽（暗属性/银河族）的场合，可以再把对方场上的表侧表示怪兽（8星以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP009', '名蔷薇法师', '【条件】这张卡召唤的回合，自己墓地有「名蔷薇魔术师」或者装备魔法卡的场合才能发动。
【效果】选自己墓地1张「克里斯马魔杖 死亡魔杖」或者「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP010', '名蔷薇巫师', '【条件】把自己场上3只表侧表示怪兽（光属性/魔法师族）送去墓地才能发动。
【效果】选自己墓地1只怪兽（光属性/魔法师族/攻击力2500以下）在自己场上表侧表示特殊召唤。那之后，可以选自己墓地1张「克里斯马魔杖 死亡魔杖」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP011', '名蔷薇魔女', '【条件】自己墓地有「名蔷薇魔术师」的场合，把手卡1只怪兽（光属性/魔法师族）或者1张魔法卡送去墓地才能发动。
【效果】选自己墓地1只「名蔷薇魔术师」或者融合术怪兽（9星以下/魔法师族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP012', '名蔷薇魔术师', '【条件】把自己场上1张表侧表示的装备魔法卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。那之后，自己墓地有魔法卡3张以上的场合，这张卡的攻击力直到回合结束时上升700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP013', '魔装兽 齿车豹', '【条件】无
【永续效果】自己的魔法与陷阱区域有卡的场合，这张卡的攻击力上升200，再让攻击表示的这张卡在对方回合内不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP014', '贤帝家臣 楚泽', '【条件】这张卡召唤的回合，让自己墓地2只怪兽（守备力1000）回到卡组才能发动。
【效果】对方选自身墓地1张魔法卡在自身场上盖放。那之后，自己可以选自己墓地1只怪兽（5星以上/守备力1000）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP015', '星帝家臣 赫柏', '【条件】这张卡召唤的回合，让自己墓地2只怪兽（守备力1000）回到卡组才能发动。
【效果】对方选自身墓地1只效果怪兽（6星以下）在自身场上表侧守备表示特殊召唤。那之后，自己可以选自己墓地1只怪兽（5星以上/守备力1000）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP016', '贤帝 威廉', '【条件】这张卡攻击表示上级召唤的回合才能发动。
【效果】选对方场上1张里侧表示的魔法·陷阱卡确认。那张卡是魔法卡的场合，可以再把那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP017', '星帝 艾斯特罗姆', '【条件】这张卡攻击表示上级召唤的回合才能发动。
【效果】选对方场上1只表侧表示的效果怪兽（6星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP018', '才贤帝 威廉', '这张卡可以把1只表侧表示怪兽（5星以上/守备力1000）解放攻击表示上级召唤。
【条件】这张卡攻击表示上级召唤的回合才能发动。
【效果】对方选自身场上1张卡。自己把那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP019', '煌星帝 艾斯特罗姆', '这张卡可以把1只表侧表示怪兽（5星以上/守备力1000）解放攻击表示上级召唤。
【条件】这张卡攻击表示上级召唤的回合才能发动。
【效果】对方选自身场上1张卡。自己选那张卡以外的自己或者对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP020', '雷帝 扎博尔格', '【条件】这张卡攻击表示上级召唤的回合才能发动。
【效果】选自己或者对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP021', '电子处理机', '自己场上有表侧表示怪兽（机械族）的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把这张卡以外的自己场上1张卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「电子龙」。那之后，可以选自己墓地1只「电子龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP022', '替星龙', '【条件】自己场上没有这张卡以外的怪兽的场合，让自己场上的这张卡回到持有者手卡才能发动。
【效果】选自己墓地1只怪兽（4星以下）在自己场上里侧守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不能从自己的手卡·墓地把怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP023', '树海的首领 咕栗', '【条件】把自己场上3张魔法·陷阱卡送去墓地才能发动。
【效果】选对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP024', '辫子阅读者', '【条件】把手卡1只怪兽（光属性/魔法师族）或者1张魔法卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之中有怪兽（光属性/魔法师族）的场合，可以再选自己墓地1张装备魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP025', '空中传送机·最大式', '【条件】让自己墓地10只怪兽回到卡组才能发动。
【效果】选自己墓地2～3只极大怪兽用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP026', '乌贼合之众', '【条件】这张卡召唤的回合，把手卡最多2只怪兽（守备力0）给对方观看才能发动。
【效果】自己墓地的怪兽（守备力0）选［这个效果的条件给人观看的怪兽数量］在自己场上里侧守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不能把怪兽（9星以下）召唤，不能把手卡的怪兽盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP027', '分离镜像炎精', '【条件】让自己墓地2只怪兽（炎族）回到卡组才能发动。
【效果】选自己墓地1只怪兽（8星以下）。这张卡的卡名在这个回合变成和选的怪兽相同卡名。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP028', '雅之金鸟', '【条件】自己卡组的卡是10张以上的场合，把手卡1只怪兽（光属性/魔法师族）送去墓地才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP029', '石膏斥候', '【条件】无
【永续效果】对方主要阶段内，自己不会因对方的效果受到伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP030', '疯狂犯罪者·空鹰女', '【条件】对方场上有怪兽2只以上的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这个回合，这张卡可以作2次攻击。并且，可以再选对方场上1只表侧表示的效果怪兽（6星）破坏。这个效果把怪兽破坏的场合，再让这张卡的攻击力直到回合结束时上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP031', '额外探险者号', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升300。自己墓地有怪兽（银河族）5只以上的场合，可以再选自己墓地的通常怪兽（银河族）和「融合术」各最多1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP032', '显现术师 多尔特奥', '【条件】无
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以给与对方为［这个效果送去墓地的怪兽（魔法师族）数量］×300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP033', '附冰贯枪龙', '【条件】把这张卡的表示形式变更才能发动（攻击表示变成表侧守备表示，守备表示变成表侧攻击表示）。
【效果】选自己场上1只表侧表示怪兽。这个回合，那只怪兽的攻击力上升1000，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP034', '银河冠临融合夏娃', '「银河冠临夏娃」＋怪兽（光属性/银河族）
【条件】让自己墓地1张「融合术」回到卡组上面或下面才能发动。
【效果】自己抽1张。那之后，可以选自己墓地1只通常怪兽（银河族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP035', '永恒银河舰忘却龙', '「银河星忘却龙」＋怪兽（光属性/银河族）×2
【条件】让自己墓地5只怪兽（银河族）回到卡组才能发动。
【效果】从自己卡组上面把3张卡送去墓地。这个回合，这张卡不会被对方的陷阱卡的效果破坏。并且，可以再让这张卡的攻击力直到回合结束时上升［自己墓地的怪兽数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP036', '蛋球机器爆速龙', '「碧牙爆速龙」＋「碧牙爆速龙」
【条件】从卡组上面把［双方墓地的「碧牙爆速龙」数量合计］的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升1000。这个效果的条件让怪兽（攻击力1500以下）被送去墓地的场合，可以再选对方场上1只表侧表示怪兽（攻击力1500以上）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP037', '碧牙超越爆速龙', '「碧牙爆速龙」＋「增速飞龙」
【条件】把自己场上1只怪兽送去墓地才能发动。
【效果】选自己或者对方场上1张表侧表示的卡破坏。这个效果的条件把原本等级是7星以上的怪兽送去墓地的场合，可以再选自己墓地1只「碧牙爆速龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP038', '真红动超越击速龙', '「真红动击速龙」＋「增速飞龙」
【条件】无
【效果】选双方墓地的怪兽合计最多9只。给与对方为［选的怪兽数量］×200伤害，这张卡的攻击力直到回合结束时上升［选的怪兽数量］×200。那之后，选的怪兽回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP039', '虚空噬骸兵·神谱鹰巨人', '「虚空噬骸兵·金剑鹰巨人」＋「暗黑预言者」
【条件】这张卡特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只怪兽（8星/银河族）在自己场上表侧表示特殊召唤。这个效果特殊召唤的怪兽直到下次的对方回合结束时不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP040', '虚空噬骸兵·巨战鹰巨人', '「虚空噬骸兵 镇魂鹰巨人」＋「虚空噬骸兵·金剑鹰巨人」
【条件】把1张手卡送去墓地才能发动。
【效果】选自己或者对方场上1张魔法·陷阱卡破坏。并且再在这个回合让这张卡的攻击力上升500，可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP041', '名蔷薇绝妙魔术师', '「名蔷薇魔术师」＋「名蔷薇魔女」
【条件】把1张手卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽破坏。那之后，可以选自己墓地1张装备魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP042', '名蔷薇豪华魔术师姐妹', '「名蔷薇魔术师」＋「名蔷薇魔女」
【条件】无
【效果】选自己墓地1只怪兽（9星以下/光属性/魔法师族）在自己场上表侧守备表示特殊召唤。这张卡有装备魔法卡装备的场合，更在这个回合让这张卡可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP043', '魔导骑士-七魔导战车', '「七道魔导士」＋「魔装兽 齿车豹」
【条件】把卡组最上面的卡送去墓地才能发动。
【选择效果】●这张卡的攻击力直到回合结束时上升［双方的魔法与陷阱区域的卡数量］×500。●这个回合，这张卡不会被对方的效果破坏。并且可以再把对方场上的表侧表示的卡选最多有［自己的魔法与陷阱区域的卡数量］破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP044', '电子战术龙', '「电子强袭龙」＋「电子龙」
【条件】让自己墓地2只怪兽（光属性/机械族）回到卡组才能发动。
【效果】攻击力合计最多到这张卡的攻击力以下为止，选对方场上最多2只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP045', '太空融合-额外探险等离子体号', '「额外探险者号」＋怪兽（光属性/银河族）
【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】选对方的魔法与陷阱区域1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP046', '上级冲击', '【条件】自己场上没有怪兽的场合才能发动。
【效果】选对方场上1只表侧表示怪兽，等级合计直到变成和那只怪兽的等级相同为止自己把手卡的怪兽送去墓地。这个回合，自己把怪兽上级召唤的场合，可以作为自己场上1只怪兽的代替而把选的对方的表侧表示怪兽解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP047', '银河舰皮盾机关炮', '【条件】可以给自己场上1只表侧表示怪兽（银河族）装备。
【效果】装备怪兽的攻击力·守备力上升200，那只怪兽不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP048', '龙爆速融合', '【条件】无
【效果】自己场上的表侧表示怪兽（龙族）作为素材送去墓地作融合术召唤。这个效果把「碧牙爆速龙」送去墓地的场合，可以再选对方场上1只表侧表示怪兽那个攻击力直到回合结束时下降1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP049', '龙击速融合', '【条件】无
【效果】自己场上的表侧表示怪兽（龙族）作为素材送去墓地作融合术召唤。这个效果把「真红动击速龙」送去墓地的场合，可以再从自己卡组上面把7张卡送去墓地。从卡组把卡送去墓地的场合，可以再从对方卡组上面把7张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP050', '虚空噬骸兵金鬃獠牙', '【条件】可以给自己场上1只表侧表示怪兽（暗属性/银河族）装备。
【效果】装备怪兽不会被魔法卡的效果破坏，自己回合内，攻击力上升800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP051', '虚空噬骸兵裹尸布', '【条件】可以给自己场上1只表侧表示怪兽（银河族）装备。
【效果】装备怪兽的攻击力上升［自己场上的魔法·陷阱卡数量］×100。只要装备怪兽在自己场上处于表侧表示，自己场上的魔法·陷阱卡不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP052', '克里斯马魔法-优雅变化', '【条件】把手卡1只怪兽（光属性/魔法师族）或者1张装备魔法卡送去墓地才能发动。
【效果】自己抽1张。自己墓地有怪兽4只以上的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP053', '克里斯马魔杖 死亡魔杖', '【条件】可以给自己场上1只表侧表示怪兽（光属性/魔法师族）装备。
【效果】装备怪兽的攻击力上升400，那只怪兽不会被对方的效果破坏。装备怪兽是融合术怪兽的场合，再让攻击力上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP054', '七魔导奇妙融合', '【条件】无
【效果】包含「七道魔导士」的自己的场上·墓地的怪兽作为素材回到持有者卡组作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP055', '魔导枪 天惠枪', '【条件】可以给自己场上1只表侧表示怪兽（魔导骑士族或者魔法师族）装备。
【效果】装备怪兽的攻击力上升200，那攻击带有贯通。装备怪兽是魔导骑士族的场合，再让攻击力上升［装备怪兽的等级］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP056', '帝之领域', '【条件】这张卡从卡组上面把2张卡送去墓地才能发动。
【效果】只要这张卡在场地区域处于表侧表示，双方场上的原本守备力是1000的表侧表示怪兽（5星以上）的攻击力上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP057', '雅耳典娜的加护', '【条件】可以让自己墓地1只怪兽回到卡组，给自己场上1只表侧表示怪兽装备。
【效果】装备怪兽不会被对方的效果破坏。自己墓地有装备魔法卡的场合，再让装备怪兽的攻击力上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP058', '生死一线性海牛侍', '【条件】对方怪兽的直接攻击宣言时才能发动。
【效果】自己回复800基本分。那之后，自己抽1张，给双方确认。那张卡是通常怪兽（银河族/攻击力1600以上）的场合，再把那次攻击无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP059', '复合银河舰', '【条件】自己怪兽被对方的攻击破坏时才能发动。
【效果】选自己墓地1只通常怪兽（银河族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP060', '无人衬词演唱猫盗贼', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时才能发动。
【效果】自己抽3张。那之后，自己选手卡1张以上送去墓地。自己场上没有怪兽的场合，再在这个回合让自己不会因对方怪兽（8星以下）的攻击受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP061', '蔷薇锁链打捞', '【条件】自己场上有把装备魔法卡装备的怪兽（6星以上/魔法师族）的场合，对方把怪兽特殊召唤时才能发动。
【效果】选自己墓地1只怪兽在自己场上表侧表示特殊召唤。那之后，自己回复［这个效果特殊召唤的怪兽的原本等级］×100基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP062', '帝王的机才', '【条件】自己场上有表侧表示怪兽（5星以上/守备力1000）的场合，对方把怪兽召唤时才能发动。
【效果】那只召唤的怪兽变成里侧守备表示。那之后，可以选自己墓地1只怪兽（5星以上/守备力1000）加入手卡。

RD', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('/KP13-JP063', '帝王的煌诞', '【条件】对方把怪兽（8星以下）表侧表示召唤·特殊召唤时，把自己场上1只怪兽送去墓地才能发动。
【效果】手卡1只怪兽（5星以上/守备力1000）在自己场上表侧攻击表示特殊召唤。那之后，可以选对方召唤·特殊召唤的那1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP064', '相伴的心意', '【条件】对方把怪兽召唤时，让自己墓地2只怪兽（光属性）回到卡组才能发动。
【效果】选自己场上1只表侧表示怪兽（光属性）。这个回合，那只怪兽的攻击力上升［那只召唤的怪兽的攻击力］，不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP065', '破光之涡', '【条件】对方把怪兽（8星以下）表侧表示召唤·特殊召唤时，让自己墓地3只怪兽（光属性/魔法师族）回到卡组才能发动。
【效果】选那1只召唤·特殊召唤的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP13-JP066', '水稻梯田危机', '【条件】对方从手卡或者墓地把怪兽特殊召唤时才能发动。
【效果】等级合计最多到12星以下为止，选对方场上最多2只表侧表示怪兽变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP000', '暗黑骑士 盖亚', '乘坐跑得比风更快之马的骑士。要注意突进攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP001', '鳞虫', '一旦被那长长的身体卷住，就再也没有办法逃脱。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP002', '接合科技眼镜蛇', '【条件】自己场上没有这张卡以外的怪兽的场合才能发动。
【效果】从自己墓地的「接合科技电弧蝎」「接合科技大钉蜈蚣」「接合科技霸王龙」之中选1只在自己场上表侧守备表示特殊召唤。这个回合，自己不能把怪兽（机械族以外）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP003', '大接合科技要塞霸王龙［L］', '【条件】把手卡1只怪兽（地属性/机械族）送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时下降600。那之后，进行1次投掷硬币。表的场合，这个回合，这张卡可以作3次攻击。里的场合，这个回合，这张卡可以向怪兽作2次攻击，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP004', '大接合科技要塞霸王龙', '可以和「大接合科技要塞霸王龙［L］」「大接合科技要塞霸王龙［R］」集齐作极大召唤。
【条件】极大模式
【永续效果】这张卡的等级上升6星。自己墓地有怪兽（7星以上/机械族）的场合，再让这张卡不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP005', '大接合科技要塞霸王龙［R］', '【条件】无
【效果】双方各自选对方墓地3只怪兽回到持有者卡组。这张卡是极大模式的场合，再让这张卡的攻击力直到回合结束时上升［这个效果回去的怪兽（地属性/机械族）的等级合计］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP006', '接合科技电弧蝎', '【条件】把1只手卡的怪兽（机械族）或者自己场上的表侧表示怪兽（机械族）送去墓地才能发动。
【效果】选自己墓地1张「融合术」或者「力量结合」加入手卡。那之后，可以选自己墓地1只「接合科技大钉蜈蚣」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP007', '接合科技大钉蜈蚣', '【条件】让这张卡以外的自己场上1只表侧表示怪兽（5星以上/地属性/机械族）回到持有者手卡才能发动。
【效果】选对方场上1只怪兽破坏。这个回合，自己不能把怪兽（机械族以外）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP008', '接合科技英雄', '【条件】把「接合科技王牌」解放来把这张卡召唤的回合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升1500。那之后，可以选自己墓地1只怪兽（地属性/机械族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP009', '化学宠物·喵喵', '【条件】自己墓地有怪兽（炎族·水族·雷族）的其中任意种的场合，把卡组最上面的卡送去墓地才能发动。
【效果】自己回复400基本分。那之后，可以选自己墓地1只怪兽（炎族·水族·雷族）回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP010', '化学宠物·汪汪', '【条件】自己墓地的怪兽是10只以下的场合，把2张手卡送去墓地才能发动。
【效果】自己抽1张。这个效果的条件把怪兽（炎族·水族·雷族）2只送去墓地的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP011', '水溶精 熔灵', '【条件】把手卡1只怪兽（4星以下）送去墓地才能发动。
【效果】选自己墓地1只怪兽（7·10星/炎族·雷族）加入手卡。那之后，可以选自己墓地1张「化学化结构力」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP012', '电导精 电灵', '【条件】把手卡1只怪兽（4星以下）送去墓地才能发动。
【效果】选自己墓地1只怪兽（5·10星/炎族·水族）加入手卡。那之后，可以选自己墓地1张「化学化结构力」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP013', '火燃精 热灵', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把［自己场上的表侧表示怪兽的种族种类数量］的卡送去墓地。这个效果让怪兽（炎族）2只以上被送去墓地的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP014', '极超助手·阿炽', '【条件】对方场上有怪兽的场合，把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】手卡1只怪兽（7星以上/炎族）在自己场上表侧表示特殊召唤。自己墓地有「超级助手 阿炽」的场合，再让这个效果特殊召唤的怪兽的攻击力直到回合结束时上升800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP015', '火轰岚凰 化学火山化凤凰［L］', '【条件】让自己墓地1只怪兽（炎属性/雷族）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽（9星以下）破坏。这张卡是极大模式的场合，可以再选对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP016', '火轰岚凰 化学火山化凤凰', '可以和「火轰岚凰 化学火山化凤凰［L］」「火轰岚凰 化学火山化凤凰［R］」集齐作极大召唤。
【条件】极大模式：把手卡1只怪兽（炎属性或者炎族）送去墓地才能发动。
【效果】给与对方1000伤害。并且再在这个回合让这张卡不会被对方的陷阱卡的效果破坏，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP017', '火轰岚凰 化学火山化凤凰［R］', '【条件】让自己墓地1只怪兽（炎属性/水族）回到卡组才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。这张卡是极大模式的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP018', '秘密搜查官 误选小姐', '【条件】自己场上没有这张卡以外的怪兽的场合，支付300基本分才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之中有怪兽（爬虫类族）的场合，可以再选自己墓地1只怪兽（光属性/爬虫类族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP019', '秘密搜查官 错误小姐', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从翻开的卡之中选1只怪兽（3星以上/爬虫类族）加入手卡。剩下的卡用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP020', '秘密搜查官 误配小姐', '【条件】对方场上有表侧表示怪兽（7星以上）的场合，把手卡1只怪兽（3星以下/爬虫类族）送去墓地才能发动。
【效果】选自己墓地1只怪兽（7星/爬虫类族）在自己场上表侧攻击表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP021', '秘密搜查官 误导小姐', '【条件】自己场上有这张卡以外的表侧表示怪兽（爬虫类族）的场合，支付300基本分才能发动。
【效果】选自己或者对方场上1只里侧表示怪兽变成表侧攻击表示。那之后，这张卡的攻击力直到回合结束时下降1300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP022', '精英秘密搜查官 神秘小姐', '【条件】让这张卡以外的自己场上2只表侧表示怪兽（爬虫类族）和1张手卡回到持有者卡组才能发动。
【效果】这张卡的攻击力直到回合结束时上升300。那之后，可以选自己的手卡·墓地最多2只怪兽（7星以上/爬虫类族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP023', '深渊杀戮者·利维坦骑士', '【条件】无
【永续效果】这张卡的攻击力上升［自己墓地的怪兽（10星以上/海龙族）数量］×500。自己墓地有怪兽（10星以上/海龙族）3只以上的场合，再在对方回合内让这张卡不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP027', '幻刃走兵 拖行起重龙', '【条件】自己场上没有这张卡以外的怪兽的场合才能发动。
【效果】选自己墓地1只极大怪兽（地属性/幻龙族）加入手卡。那之后，自己墓地有怪兽（7星以上/幻龙族）的场合，可以选自己墓地1只极大怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP028', '变形史莱姆-龙骑士形态', '【条件】让融合术怪兽以外的自己墓地1只怪兽回到卡组才能发动。
【效果】自己的手卡·场上的怪兽（7星/战士族）1只和怪兽（5星/龙族）1只作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP029', '龙咒术魔道士', '【条件】自己墓地有魔法卡3张以上的场合，把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己手卡或者自己墓地1只「暗黑骑士 盖亚」或者通常怪兽（5星/龙族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP030', '射出的弹射龟', '自己场上没有攻击表示怪兽的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把自己场上1只表侧表示的融合术怪兽送去墓地才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，自己墓地有「龙骑士 盖亚」的场合，可以选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP031', '历战的诅咒之龙', '自己场上没有怪兽的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「历战的诅咒之龙」。那之后，可以让自己场上的这张卡和自己的场上·墓地的怪兽1只作为素材回到持有者卡组作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP032', '历战的暗黑骑士 盖亚', '这张卡可以把1只表侧表示怪兽（5星以上）解放攻击表示上级召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「暗黑骑士 盖亚」。那之后，可以让自己场上的这张卡和自己的场上·墓地的怪兽1只作为素材回到持有者卡组作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP033', '多边形蝴蝶', '【条件】自己墓地有怪兽（昆虫族）3只以上的场合，把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（8星以下/昆虫族）。这个回合，那只怪兽的攻击力上升200，可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP034', '无力化龙', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，自己墓地有「攻击无力化」的场合，可以选对方场上最多3只表侧表示怪兽那些攻击力直到下次的对方回合结束时下降2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP035', '天始之怪依', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只怪兽（不死族/攻击力1200/守备力0）在自己场上表侧守备表示特殊召唤。这个效果把「天终之怪依」特殊召唤的场合，可以再选对方墓地最多2张卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP036', '钢铁兵 鞅论倍赌兵', '【条件】无
【效果】进行1次投掷硬币。表的场合，自己场上的全部表侧表示怪兽的攻击力直到回合结束时上升500。里的场合，可以选对方场上1只表侧表示怪兽那个攻击力·守备力直到回合结束时下降800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP038', '银河材料矿石人', '【条件】自己墓地有怪兽（银河族）3只以上的场合，这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1张「银河舰短剑」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP039', '龙骸之角龙魂', '【条件】自己墓地有通常怪兽（恐龙族）的场合，从卡组上面把2张卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（恐龙族），那个攻击力直到回合结束时上升［自己墓地的通常怪兽（恐龙族）数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP040', '看破之哈维', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选对方场上1张里侧表示的卡确认。那张卡是怪兽卡（守备力1500以上）的场合，可以再把那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP041', '陆上运输车·最大式', '【条件】无
【效果】选自己场上1只怪兽送去墓地。那之后，可以选自己墓地1只极大怪兽（地属性/机械族）加入手卡。加入的场合，再进行2次投掷硬币。那之内2次都是表的场合，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP042', '清净之蛇姬', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降［自己场上的表侧表示怪兽（光属性）数量］×600。自己场上的表侧表示怪兽是3只的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP043', '接合科技斗士', '「接合科技王牌」＋「接合科技王牌」
【条件】无
【效果】选自己墓地1只怪兽（7星/地属性/机械族）加入手卡或在自己场上表侧表示特殊召唤。这个效果选「接合科技英雄」的场合，可以再选自己墓地1只「接合科技王牌」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP044', '接合科技杀人螫针蜂', '「接合科技电弧蝎」＋「接合科技大钉蜈蚣」
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降［对方场上的怪兽数量］×700。那之后，自己回复［对方场上的怪兽数量］×700基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP045', '接合科技爆速龙', '「接合科技霸王龙」＋「碧牙爆速龙」
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】对方场上的表侧表示怪兽（攻击力2500以下）全部破坏。并且，再让这张卡的攻击力直到回合结束时上升［这个效果破坏的怪兽数量］×500。那之后，可以选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP046', '百战的霸者 盖亚', '「暗黑骑士 盖亚」＋「历战的诅咒之龙」
【条件】这张卡特殊召唤的自己主要阶段，让自己墓地1只怪兽（魔导骑士族以外）回到卡组才能发动。
【选择效果】●这个回合，这张卡可以直接攻击。●选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP047', '接合科技挖出', '【条件】把手卡1只怪兽（地属性/机械族）送去墓地才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己从翻开的卡之中选1张加入手卡。剩下的卡用喜欢的顺序全部回到卡组上面或全部送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP048', '化学火山化化合物', '【条件】自己场上有表侧表示怪兽（炎属性）的场合，让自己墓地1只怪兽（炎族·水族·雷族）回到卡组才能发动。
【效果】自己抽1张。自己场上有极大模式的怪兽或者表侧表示的装备魔法卡的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP049', '化学化结构力', '【条件】可以给自己场上1只表侧表示怪兽（炎族·水族·雷族）装备。
【效果】装备怪兽的攻击力上升［双方场上的表侧表示怪兽的种族种类］×300。装备怪兽是极大怪兽的场合，再让那只怪兽不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP050', '黑洞装置', '【条件】把手卡3只怪兽（暗属性/银河族）送去墓地或自己场上有表侧表示的融合术怪兽（暗属性/银河族）的场合才能发动。
【效果】双方场上的怪兽全部破坏。那之后，可以选自己墓地1只怪兽（银河族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP051', '斗气破坏力', '【条件】可以给自己场上1只表侧表示怪兽（战士族）装备。
【效果】装备怪兽不会被对方的效果破坏。自己墓地有装备魔法卡的场合，再让装备怪兽的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP052', '怪兽招集', '【条件】把手卡1只怪兽送去墓地才能发动。
【效果】自己抽1张。那之后，可以选效果怪兽以外的自己墓地1只怪兽（攻击力2000或者守备力2100）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP053', '暗黑之格斗场', '【条件】无
【效果】只要这张卡在场地区域处于表侧表示，双方场上的原本守备力是2100的表侧表示怪兽的攻击力上升500，双方的「暗黑骑士 盖亚」「龙骑士 盖亚」的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP054', '光焰盘上', '【条件】无
【效果】选对方场上最多3只表侧表示的效果怪兽，那些攻击力·守备力直到回合结束时下降400。自己基本分比对方少的场合，可以再把手卡1只怪兽（7星）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP055', '三猫选择', '【条件】对方场上有怪兽的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，自己墓地的怪兽是3只以下的场合，可以选自己墓地1张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP056', '念之印刻', '【条件】自己场上有表侧表示怪兽（7星以上/风属性）的场合才能发动。
【效果】自己抽1张。自己场上有表侧表示的「多面手女郎」的场合，可以再把手卡1只怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP058', '接合科技点火', '【条件】由自己的表侧表示怪兽（地属性/机械族）承受攻击的对方怪兽的攻击宣言时才能发动。
【效果】受到攻击的怪兽不会被那次战斗破坏。自己场上有表侧表示怪兽（7星以上/地属性/机械族）的场合，可以再把攻击的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP059', '化学化蔑视', '【条件】由自己的表侧表示怪兽（炎族）承受攻击的对方怪兽的攻击宣言时才能发动。
【效果】那次攻击无效。受到攻击的怪兽的等级比攻击的怪兽高的场合，可以再把攻击的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP060', '秘密档案33-怨恨的散华', '【条件】对方怪兽的攻击宣言时，让自己墓地3只怪兽（3星以上/爬虫类族）回到卡组才能发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降3000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP061', '迎击的盖亚', '【条件】自己场上有表侧表示怪兽（7星/守备力2100）的场合，对方把怪兽召唤·特殊召唤时才能发动。
【效果】选对方场上1只表侧表示怪兽变成里侧守备表示。自己场上有表侧表示的「龙骑士 盖亚」的场合，可以再选对方场上1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP062', '龙战闪避', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时才能发动。
【效果】选自己墓地1只「龙骑士 盖亚」或者怪兽（5星以下/龙族）在自己场上表侧表示特殊召唤。这个回合，这个效果特殊召唤的怪兽不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP063', '音痴噪声烦恼', '【条件】对方主要阶段，卡被送去对方墓地时才能发动。
【效果】给与对方为［对方手卡数量］×300伤害。卡组的卡被送去对方墓地时把这张卡发动的场合，再把对方手卡随机选1张送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP064', '超可爱执行者骑乘！', '【条件】对方把效果怪兽表侧表示召唤·特殊召唤时才能发动。
【效果】选那只怪兽的攻击力以下的自己墓地1只怪兽在自己场上表侧攻击表示特殊召唤。那之后，可以选对方场上最多2只表侧表示怪兽那些攻击力直到回合结束时下降1800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP065', '攻击无力化', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】那次攻击无效。这个回合，对方不能攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP14-JP066', '自我回避', '【条件】对方在抽卡阶段通常抽卡时，自己手卡是2张以上的场合才能发动。
【效果】自己抽2张。那之后，可以把手卡最多3只怪兽在自己场上里侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP000', '碎光之超能电吉他打手', '【条件】自己基本分是1000以下的场合才能发动。
【效果】选对方场上最多2只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP001', '暗冥龙兽', '迷惑心灵的黑暗化身。侵蚀一切。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP002', '波导刀 吉光剑吻鲨', '受到波导刀的加护的传说中武人鱼。在深海中猛地一刺的剑戟没有能看破者。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP003', '暗冥矮星', '【条件】把这张卡以外的自己场上1只表侧表示怪兽（银河族）送去墓地才能发动。
【效果】包含这张卡的自己场上的表侧表示怪兽作为素材送去墓地，把怪兽（暗属性）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP004', '暗冥穿越侍·危机章鱼侍', '这张卡可以把持有相同属性的3只怪兽解放攻击表示上级召唤。
【条件】上记的方法把这张卡召唤的回合才能发动。
【效果】选对方场上1张卡破坏。那之后，可以让这张卡的攻击力直到回合结束时上升［这个效果破坏的怪兽的原本等级］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP005', '条带化飞龙', '【条件】从卡组上面把2张卡送去墓地，把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】手卡1只「碧牙爆速龙」或者「真红动击速龙」在自己场上表侧守备表示特殊召唤。那之后，可以选自己墓地1张「龙爆速融合」或者「龙击速融合」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP006', '襟翼翻转龙', '【条件】把手卡1只怪兽（龙族）送去墓地才能发动。
【效果】选对方场上1只里侧表示怪兽变成表侧攻击表示。自己场上的表侧表示怪兽只有怪兽（龙族）的场合，可以再选自己墓地1只「翻转襟翼龙」在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP007', '翻转襟翼龙', '【条件】把手卡1只怪兽（龙族）送去墓地才能发动。
【效果】选对方场上1只攻击表示怪兽变成里侧守备表示。自己场上的表侧表示怪兽只有怪兽（龙族）的场合，可以再选自己墓地1只「襟翼翻转龙」在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP008', '名蔷薇女巫', '【条件】这张卡召唤的回合，把手卡1只怪兽（光属性/魔法师族）或者1张装备魔法卡给对方观看才能发动。
【效果】从自己卡组上面把4张卡送去墓地。那之后，可以从这个效果送去墓地的卡之中选「名蔷薇魔术师」「名蔷薇魔女」「融合术」的其中1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP009', '暗冥狗仔队', '【条件】自己卡组的卡是10张以上，自己场上有表侧表示怪兽（5星以上/魔法师族）的场合，让自己墓地3只持有相同属性的怪兽（魔法师族）回到卡组才能发动。
【效果】自己抽出［对方场上的表侧表示怪兽（7星以上）的数量］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP010', '暗冥炸药幻龙', '【条件】让自己墓地2只怪兽（幻龙族）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽（9星以下）变成里侧守备表示。那之后，对方从自身卡组上面把3张卡翻开，给双方确认。对方让翻开的卡用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP011', '幻坏兵 楔式脚手架龙', '【条件】自己场上的怪兽是2只以下的场合才能发动。
【效果】从自己卡组上面把［自己场上的表侧表示怪兽（幻龙族）数量］×2张的卡送去墓地。那之中有怪兽2只以上的场合，再在这个回合在怪兽（幻龙族）攻击表示上级召唤的场合让表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP012', '提琴游吟诗人', '【条件】把手卡1只怪兽（风属性/念动力族）送去墓地才能发动。
【效果】选自己墓地1张「念力装备融合」或者装备魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP013', '振动盗贼', '【条件】对方场上有表侧表示怪兽（7星以上）的场合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之中有装备魔法卡的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP014', '曼陀林掠夺者', '【条件】支付100基本分才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从翻开的卡之中选「融合术」「念力装备融合」合计最多2张加入手卡。剩下的卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP015', '星台工作人员·女摄影师', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把2张卡送去墓地。自己场上有表侧表示的「碎光之超能电吉他打手」的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP016', '波导刀 种子岛金枪鱼', '【条件】自己墓地有怪兽（7星/鱼族）、「融合术」、「波涛融合」的其中任意种的场合，把1张手卡送去墓地才能发动。
【效果】从自己墓地的怪兽（7星/鱼族）、「融合术」、「波涛融合」之中选1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP017', '波导铳 小弹炮金枪鱼', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［自己场上的表侧表示怪兽（鱼族）的等级合计］×100。那之后，可以选自己墓地1只「波导炮 巨炮金枪鱼」加入手卡或在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP018', '突击印鱼', '【条件】把手卡1只怪兽（鱼族）送去墓地才能发动。
【效果】选自己墓地1张「鱼弹突击」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP019', '运输蝠鲼', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以从这个效果送去墓地的卡之中选1只「突击印鱼」或者1张「鱼弹突击」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP020', '电子鱼', '【条件】把手卡1只怪兽（水属性/鱼族）送去墓地才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP021', '电子鲨', '自己场上有表侧表示怪兽（水属性）的场合，这张卡可以不用解放作召唤。
【条件】无
【效果】无', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP022', '波导刀 鬼丸国纲金枪鱼', '【条件】无
【永续效果】自己场上的表侧表示怪兽（鱼族）不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP023', '地狱河童 奔河短跑者', '【条件】从手卡把「河童大帝 滑河骑手」「地狱河童 湿身减重者」「屁之河童」的其中1张送去墓地才能发动。
【效果】选对方场上1张卡破坏。那之后，自己墓地有怪兽（水族）3只以上的场合，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP027', '火箭卫星兵', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只「流星之龙」或者1张「流星炎融合」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP029', '种植妖精', '【条件】双方场上的全部表侧表示怪兽之中有相同属性的怪兽2只以上的场合才能发动。
【效果】选自己墓地1只通常怪兽（6星以下）或者1张「融合术」加入手卡。那之后，可以把手卡1只怪兽（地属性/植物族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP030', '纯爱天使', '【条件】无
【永续效果】这张卡不会被和怪兽（攻击力2500以上）的战斗破坏。这张卡和怪兽（9星以下）进行战斗的场合，自己不会受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP031', '频道猫头鹰', '【条件】对方场上有卡2张以上的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这个回合，自己不会因对方的陷阱卡的效果受到伤害。并且，可以再选自己墓地1只怪兽（鸟兽族/攻击力2200）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP032', '暗构体', '【条件】无
【永续效果】通常怪兽（暗属性）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP033', '绝望狂魔 死局魔', '【条件】让自己墓地4只怪兽回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。那之后，自己墓地有持有相同属性的怪兽6只以上的场合，可以选对方墓地1只怪兽（7星以下）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP034', '圣丽的冻士 格拉基耶斯', '【条件】把这张卡以外的自己的手卡·场上最多6张卡送去墓地才能发动。
【效果】直到下次的对方回合结束时，这张卡的等级上升1星，不会被对方的效果破坏。并且，可以再选这个效果的条件送去墓地的卡每3张最多1张的对方场上的里侧表示的卡回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP035', '暗冥厄运巨星', '「暗冥矮星」＋怪兽（光属性·暗属性/银河族）
【条件】无
【效果】选自己墓地1只怪兽（7·8星/银河族）或者1张「融合术」加入手卡。并且再在这个回合在怪兽（8星/银河族）攻击表示上级召唤的场合让表侧表示的这张卡可以作为2只的数量或者3只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP036', '暗冥银河舰忘却龙', '「银河星忘却龙」＋「暗冥矮星」
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只原本攻击力是100以上的表侧表示的效果怪兽，那个攻击力直到回合结束时下降［那个原本攻击力］。那之后，可以把选的怪兽的永续效果直到回合结束时无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP037', '重红动超越击速龙', '「真红动击速龙」＋「暗冥龙兽」
【条件】让自己墓地1只怪兽回到卡组才能发动。
【效果】选自己墓地最多3只怪兽（暗属性）。给与对方为［选的怪兽的等级合计］×100伤害，这张卡的攻击力直到回合结束时上升［选的怪兽的等级合计］×100。那之后，选的怪兽回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP038', '名蔷薇八卦魔女', '「名蔷薇魔女」＋「暗冥狗仔队」
【条件】无
【效果】选对方场上1张魔法·陷阱卡破坏。自己场上有表侧表示的魔法卡的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP039', '名蔷薇八卦魔术师', '「名蔷薇魔术师」＋「暗冥狗仔队」
【条件】无
【永续效果】这张卡的攻击力上升［自己墓地的装备魔法卡数量］×400。自己场上有表侧表示的魔法卡的场合，这张卡不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP041', '蓝草音乐强夺偷窃者', '「蓝草音乐偷窃者」＋「提琴游吟诗人」
【条件】自己场上有表侧表示的魔法卡的场合，把卡组最上面的卡送去墓地才能发动。
【效果】选自己或者对方场上1张魔法·陷阱卡回到持有者手卡。那之后，可以选自己墓地1只「提琴游吟诗人」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP042', '瞬苛斗奏之班卓琴歌后盗贼', '「斗奏之班卓琴盗贼」＋「提琴游吟诗人」
【条件】无
【效果】自己抽1张。那之后，这张卡的攻击力直到下次的对方回合结束时上升［双方手卡数量合计］×500。自己手卡是1张的场合，可以再选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP043', '旋紫斩奏之琴拨现演罪犯', '「斩奏之琴拨罪犯」＋「提琴游吟诗人」
【条件】把手卡最多2张魔法卡给对方观看才能发动。
【效果】自己墓地的怪兽（8星以下/风属性/念动力族）选［这个效果的条件给人观看的卡数量］在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP044', '暗黑波导炮 中子炮金枪鱼', '「波导炮 巨炮金枪鱼」＋「波导刀 种子岛金枪鱼」
【条件】无
【永续效果】自己场上的表侧表示怪兽只有融合术怪兽的场合，这张卡可以直接攻击。对方场上有表侧表示的极大怪兽的场合，对方不能把怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP045', '漆黑波导刀 鬼丸国纲金枪鱼', '「波导刀 鬼丸国纲金枪鱼」＋「波导铳 小弹炮金枪鱼」
【条件】无
【永续效果】这张卡的攻击带有贯通。自己场上的表侧表示怪兽（鱼族）不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP049', '苍救之光耀 加尔弗雷尔', '「苍救骑士 兰加」＋「苍救天使 苏蕾」
【条件】让1张手卡回到卡组下面才能发动。
【选择效果】●对方墓地的卡选最多有［自己场上的表侧表示怪兽（天界战士族）数量］×2张回到卡组。●选自己墓地1只怪兽（4星以下/光属性·暗属性）或者1张「苍救的祈愿」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP050', '龙力进度', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（1星/光属性·暗属性/龙族）加入手卡。那之后，可以选自己墓地1张「龙爆速融合」或者「龙击速融合」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP051', '念力装备融合', '【条件】无
【效果】自己场上的表侧表示怪兽（念动力族）作为素材送去墓地作融合术召唤。那之后，自己墓地有怪兽（风属性）的场合，可以选自己墓地1张装备魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP052', '奇迹匹克', '【条件】把手卡1只怪兽（7星/光属性·暗属性/念动力族/守备力0）给对方观看才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己从翻开的卡之中选1张加入手卡。剩下的卡送去墓地。这个回合，自己不用怪兽（欧米伽念动力族·念动力族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP053', '透幻乡的锦绣', '【条件】这张卡让自己墓地1只怪兽（幻龙族）回到卡组上面才能发动。
【效果】只要这张卡在场地区域处于表侧表示，双方场上的表侧表示怪兽（幻龙族）的攻击力上升300，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP054', '波涛融合', '【条件】自己墓地有怪兽（水属性/鱼族）5只以上的场合才能发动。
【效果】自己的场上·墓地的怪兽（水属性/鱼族）作为素材回到卡组，把怪兽（水属性/鱼族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP055', '荒波', '【条件】无
【效果】只要这张卡在场地区域处于表侧表示，自身场上的怪兽只有1只的玩家不用怪兽（鱼族·海龙族·雷族·水族）不能向怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP056', '海上打捞', '【条件】无
【效果】选自己墓地2只怪兽（水属性/攻击力1500以下）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP059', '朋友！', '【条件】自己场上有相同种族的表侧表示怪兽2只以上的场合才能发动。
【效果】自己抽1张。那之后，可以选自己场上2只相同属性的表侧表示怪兽那些攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP060', '女仆的恶作剧', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】选对方墓地最多2只怪兽回到卡组。那之后，自己可以抽出［这个效果回去的效果怪兽（7星）的数量］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP061', '和平与摇滚', '【条件】自己场上有表侧表示的「彩光之首席吉他手」或者「碎光之超能电吉他打手」的场合，对方把怪兽召唤·特殊召唤时才能发动。
【效果】选对方场上1只怪兽破坏。自己基本分是2000以下的场合，再在这个回合让自己不会受到战斗伤害，不会因对方的效果受到伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP062', '鱼弹突击', '【条件】对方把怪兽召唤·特殊召唤时或者对方把魔法卡发动后，把自己场上1只表侧表示怪兽（鱼族）送去墓地才能发动。
【效果】选对方场上1张卡破坏。那之后，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP064', '苍救的祈愿', '【条件】对方把怪兽召唤·特殊召唤时，让自己墓地1只怪兽（水属性/战士族）和1只怪兽（天使族）用喜欢的顺序回到卡组上面才能发动。
【效果】选对方场上1只怪兽回到持有者卡组下面。那之后，可以选自己墓地1张「蒼救の照覧」或者「融合术」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP065', '救惺望御', '【条件】对方回合对方抽卡时或者对方回合对方把怪兽召唤·特殊召唤时，把自己场上1只怪兽送去墓地才能发动。
【效果】这个回合，对方只能有1次攻击宣言。并且，可以再选对方场上1只原本攻击力是3000的表侧表示的融合术怪兽（9星以上/魔导骑士族）得到那个控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP15-JP066', '融合术解除', '【条件】自己或者对方的怪兽被战斗破坏时才能发动。
【效果】选自己或者对方场上1只表侧表示的融合术怪兽回到持有者的额外卡组。那之后，回去的怪兽的持有者可以从自身墓地选一组在那只怪兽有卡名作为素材记述的怪兽在自身场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP000', '暗黑魔龙', '「恶魔的召唤」＋「真红眼黑龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP001', '高天矮星', '【条件】无
【效果】选自己场上1只怪兽送去墓地。那之后，可以选自己墓地3只种族不同的怪兽（光属性）回到卡组。回去的场合，可以再从双方场上的表侧表示怪兽之中把怪兽（光属性）作为素材送去墓地把怪兽（光属性）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP002', '高天炸药幻龙', '【条件】让自己墓地2只怪兽（光属性）回到卡组才能发动。
【效果】选自己或者对方场上1只攻击表示怪兽（7星以上）变成里侧守备表示。那之后，双方从自身卡组上面把3张卡翻开，给双方确认。双方让自身翻开的卡用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP003', '星际高天莱檬', '【条件】自己墓地的怪兽只有光属性的场合，把手卡1只效果怪兽（7·8星）给对方观看才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以选自己墓地1只「穿越侍·高天海牛侍 铠天原新星」或者「穿越侍·线性海牛侍」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP004', '高天爪少女', '这张卡可以把1只怪兽解放攻击表示上级召唤。那个场合，这张卡的原本攻击力变成200。
【条件】让2张手卡用喜欢的顺序回到卡组下面才能发动。
【效果】选自己墓地1只通常怪兽（光属性）在自己场上表侧守备表示特殊召唤。那之后，可以选自己墓地1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP005', '高天拖拉虎', '这张卡可以把1只怪兽解放攻击表示上级召唤。那个场合，这张卡的原本攻击力变成1800。
【条件】把手卡1只怪兽送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽。这个回合，那只怪兽的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP006', '高天之班卓琴盗贼', '这张卡可以把1只怪兽解放攻击表示上级召唤。那个场合，这张卡的原本攻击力变成1800。
【条件】支付1000基本分才能发动。
【效果】选自己墓地1只通常怪兽（4星以下/光属性）或者1张「高天呼唤」加入手卡，这张卡的攻击力直到回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP007', '高天之神童 迪安·凯特', '这张卡可以把1只怪兽解放攻击表示上级召唤。那个场合，这张卡的原本攻击力变成1000。
【条件】把手卡1只怪兽送去墓地才能发动。
【效果】自己回复1000基本分，这张卡的攻击力直到回合结束时上升1000。那之后，可以选自己墓地1张「高天呼唤」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP014', '骰子小钥心·铠甲小奶糖', '【条件】无
【永续效果】只要自己场上有持有掷骰子效果的表侧表示怪兽（7星以上），对方在双方的战斗阶段中不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP015', '骰子小钥心·小全', '【条件】自己场上有持有掷骰子效果的表侧表示怪兽的场合，把卡组最上面的卡送去墓地才能发动。
【效果】自己场上的全部表侧表示怪兽的攻击力直到下次的对方回合结束时上升600。那之后，可以选自己墓地1只怪兽（天使族/攻击力300/守备力1200）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP016', '骰子炸药少女·小掷', '【条件】无
【效果】掷1次骰子。出现数目的效果直到回合结束时适用。
●1·2：这张卡的攻击力下降1000。
●3·4：这张卡的攻击力上升600。
●5·6：选对方场上1只表侧表示怪兽，这张卡的攻击力上升［选的怪兽的原本攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP017', '接合科技寄命蟹保安军', '【条件】让2张手卡回到卡组才能发动。
【效果】选自己墓地1只怪兽（7·8星/暗属性）在自己场上表侧表示特殊召唤。这个效果的发动后，直到回合结束时自己不是「接合科技三角恐龙基地」不能特殊召唤，自己不能把怪兽（暗属性）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP018', '暗冥接合科技机械暴君', '【条件】自己没有把怪兽的效果发动的回合才能发动。
【效果】选自己墓地2只种族不同的怪兽（7·8星/暗属性）加入手卡。那之后，这张卡的卡名在这个回合变成「接合科技寄命蟹保安军」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP019', '电狮子 起电范德', '【条件】自己场上的怪兽是2只以下的场合才能发动。
【效果】从自己卡组上面把［自己场上的表侧表示怪兽（炎族·水族·雷族）数量］×2张的卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP020', '蒸汽燕 引擎詹姆斯', '【条件】对方场上有怪兽的场合才能发动。
【效果】选自己墓地1只怪兽（2星以下/炎属性/雷族）在自己场上表侧守备表示特殊召唤。那之后，可以选自己墓地1张「融合术」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP021', '深渊杀戮者·提亚玛特女王', '【条件】让包含极大怪兽（海龙族）的自己墓地最多3只怪兽回到卡组才能发动。
【效果】自己抽1张。那之后，可以从自己卡组上面把5张卡翻开。翻开的场合，给双方确认。自己可以从那之中选最多3只怪兽（7星以上/海龙族）加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP022', '秘密搜查官 哑火小姐', '【条件】这张卡召唤的回合，支付300基本分才能发动。
【效果】给与对方为［自己场上的表侧表示怪兽（光属性/爬虫类族）数量］×300伤害。这个回合，自己不能用怪兽（爬虫类族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP023', '秘密基地守护神 打偏小姐', '【条件】让自己墓地3只怪兽（3星/光属性/爬虫类族）回到卡组才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升3000。把「精英秘密搜查官 神秘小姐」解放来把这张卡召唤的回合把这个效果发动的场合，可以再选对方场上最多3只表侧表示怪兽（8星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP024', '七星惧魔术师', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「七道魔导士」。那之后，可以选对方场上1只表侧表示怪兽那个攻击力直到回合结束时下降［自己墓地的怪兽的属性种类］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP025', '可能甜心-学习：D', '【条件】自己墓地的怪兽只有欧米伽念动力族·念动力族的场合，把1张手卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽回到持有者手卡。自己墓地有「可能甜心：D」的场合，再让自己回复700基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP027', '人造人-念力归来者', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地1只「人造人-念力震慑者」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP028', '威胁的人造人-念力震慑者', '自己或者对方的墓地有陷阱卡的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地1只「人造人-念力震慑者」在自己场上表侧表示特殊召唤。那之后，可以把对方的魔法与陷阱区域的里侧表示的卡全部确认。确认的场合，再把那之中的陷阱卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP031', '魔力动物魔女', '【条件】把手卡最多2只效果怪兽（7·8星/光属性）给对方观看才能发动。
【效果】自己抽出［这个效果的条件给人观看的怪兽的数量］。那之后，自己让手卡选［这个效果抽出的数量］回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP032', '翻弄敌人的精灵剑士', '【条件】无
【永续效果】这张卡不会被和怪兽（攻击力1900以上）的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP033', '潜行狙击手', '【条件】把手卡以喜欢的数量送去墓地才能发动。
【效果】骰子掷［这个效果的条件送去墓地的卡数量的次数］。选最多有［1·6以外出现的次数数量］的对方场上的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP034', '光鳞飞鱼', '【条件】把这张卡以外的自己场上1只表侧表示怪兽（鱼族）送去墓地才能发动。
【效果】选自己或者对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP035', '迷雾暗杀者', '【条件】把自己场上1只怪兽送去墓地才能发动。
【效果】选自己墓地的「融合术」「融合术解除」合计最多2张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP036', '七宝神-良财', '自己墓地有怪兽（守备力2700）或者「七宝船」的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【永续效果】自己场上的表侧表示怪兽（7星）和自己场上的里侧表示的魔法·陷阱卡不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP037', '高天贯通巨星', '「高天矮星」＋怪兽（8星以下/光属性）
【条件】无
【永续效果】自己怪兽（7星以上/光属性）的攻击带有贯通。对方回合内，自己场上的怪兽不能作为融合术召唤的素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP038', '高天猫攻击喵', '「高天爪少女」＋怪兽（光属性）
【条件】无
【永续效果】自己场上的表侧表示怪兽（7星以上/光属性）的攻击力上升200，不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP040', '穿越侍噬骸兵·线性海牛侍', '「穿越侍·线性海牛侍」＋「虚空噬骸兵 镇魂鹰巨人」
【条件】从卡组上面把3张卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升900。这个效果的条件让怪兽（光属性·暗属性）被送去墓地的场合，可以再让对方场上的全部表侧表示怪兽的攻击力直到下次的对方回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP041', '接合科技三角恐龙基地', '「接合科技寄命蟹保安军」＋怪兽（机械族以外）×2
【条件】无
【永续效果】这张卡的攻击带有贯通。原本卡名是「虚空噬骸兵 镇魂鹰巨人」「深渊杀戮者·利维坦骑士」的怪兽各作为素材送去墓地把这张卡融合术召唤的回合，这张卡可以作3次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP042', '超级谱气斗士·炽弓手', '「色谱气斗士」＋「超级助手 阿炽」
【条件】让自己墓地1只通常怪兽（7星/炎族）回到卡组上面才能发动。
【效果】这张卡的攻击力直到回合结束时上升2500。那之后，可以选对方场上1只表侧表示怪兽（9星以下）那个攻击力直到回合结束时下降1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP043', '华蝶风彩之预言乐句酷炫盗贼', '「风彩之预言乐句盗贼」＋「提琴游吟诗人」
【条件】无
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。那之后，可以让对方墓地的怪兽全部回到卡组。回去的场合，再让这张卡的攻击力直到回合结束时上升1200，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP044', '名蔷薇网红姐妹', '「名蔷薇附魔师」＋「名蔷薇女巫」
【条件】无
【效果】选对方墓地1只怪兽回到卡组下面，这张卡的攻击力直到回合结束时上升［这个效果回去的怪兽的等级］×200。这张卡有装备魔法卡装备的场合，再在这个回合让这张卡不会被效果破坏，可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP045', '花牙一波 梦凛·道久', '「花牙铠·小木通」＋「花牙武者之龙胆」
【条件】无
【效果】选自己场上1只表侧表示怪兽，那个攻击力直到回合结束时上升［自己场上的怪兽数量］×500。那之后，给与对方700伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP046', '苍救之晦冥 尼卢克利塔', '「苍救骑士 塞尔」＋「苍救天使 卢阿」
【条件】无
【永续效果】有装备魔法卡装备的自己怪兽（天界战士族·战士族·天使族）的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP048', '高天呼唤', '【条件】自己墓地的怪兽只有光属性的场合才能发动。
【效果】选自己墓地1只怪兽加入手卡。并且可以再选自己墓地1张「融合术」加入手卡。这个效果的发动后，直到回合结束时自己不能把「高天矮星」以外的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP049', '天使的骰子', '【条件】无
【效果】掷1次骰子。自己场上的全部表侧表示怪兽的攻击力·守备力直到回合结束时上升［出现的数目］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP051', '显现的秘仪', '【条件】把自己的手卡·场上最多2只怪兽送去墓地才能发动。
【效果】自己抽1张。那之后，可以选自己墓地1只怪兽（5星以上/光属性/魔法师族）在自己场上表侧表示特殊召唤。这个效果的发动后，直到回合结束时自己不能把怪兽（光属性/魔法师族）以外的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP053', '秘密三改', '【条件】把包含2只怪兽（光属性/爬虫类族）的3张手卡送去墓地才能发动。
【效果】自己抽3张。那之后，可以选对方场上1只表侧表示怪兽（8星以下）那个攻击力直到回合结束时下降1300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP054', '秘密搜查车 三电雷鸟', '【条件】可以给自己场上1只表侧表示怪兽（光属性/爬虫类族）装备。
【效果】装备怪兽的攻击力上升300，可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP055', '巡演魔王族王者归来', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽（3星以上），那个等级直到回合结束时下降2星。那之后，可以选自己墓地1只怪兽（7星以上/恶魔族/守备力0）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP058', '接合科技接合', '【条件】让自己墓地2只怪兽回到卡组才能发动。
【效果】选对方场上1只怪兽变成表侧攻击表示或者里侧守备表示。那之后，可以把自己的手卡·场上的怪兽作为素材送去墓地把怪兽（9星以下/地属性·暗属性/机械族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP059', '宇宙的威胁', '【条件】支付1000基本分才能发动。
【效果】自己卡组最上面的卡送去墓地。那之后，可以把那张卡在自己场上盖放（怪兽的场合，可以里侧守备表示特殊召唤）。这个效果把墓地的怪兽（2星）特殊召唤的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP060', '魔法除去', '【条件】无
【效果】选对方场上1张表侧表示的魔法卡或者里侧表示的魔法·陷阱卡。选的卡是表侧表示的场合，那张卡破坏。选的卡是里侧表示的场合，把那张卡确认。魔法卡的场合，再把那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP062', '恶魔的骰子', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】掷1次骰子。对方场上的全部表侧表示怪兽的攻击力·守备力直到回合结束时下降［出现的数目］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP063', '阿修罗的骰子', '【条件】对方把怪兽表侧表示召唤·特殊召唤时才能发动。
【效果】掷1次骰子。给与对方为［出现的数目］×100伤害，对方场上的全部表侧表示怪兽的攻击力·守备力直到回合结束时下降［出现的数目］×100。那之后，可以让自己场上的全部表侧表示怪兽的攻击力·守备力直到回合结束时上升［出现的数目］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP064', '融合防卫术', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】选自己墓地1张「融合术」或者「融合术解除」在自己的魔法与陷阱区域盖放。那之后，可以选自己场上1只表侧表示怪兽。选的场合，这个回合，选的怪兽不会被战斗和效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP065', '秘密档案3000-最终惨剧', '【条件】自己场上的表侧表示怪兽（光属性/爬虫类族）是3只的场合，对方怪兽的攻击宣言时，让自己墓地3只怪兽（光属性/爬虫类族）回到卡组才能发动。
【效果】对方场上的攻击表示怪兽全部破坏。那之后，给与对方3000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP16-JP066', '日落逆转', '【条件】在对方回合对方抽卡时或者在自己场上的怪兽被对方的效果破坏时才能发动。
【效果】选自己手卡或者自己墓地1只怪兽在自己场上里侧守备表示特殊召唤。那之后，选这张卡以外的自己场上最多3张卡。这个回合，选的卡不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP001', '杰拉', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP002', '邪恶的魔族 杰拉', '【条件】这张卡仪式术召唤的自己主要阶段，自己墓地有通常怪兽（攻击力1600）的场合才能发动。
【效果】选效果怪兽以外的自己墓地1只怪兽（恶魔族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP003', '杰拉的战士', '以能获得大天使之力的圣域为目标而四处探寻的战士。为了逃离邪恶的魔族诱惑，过着只身作战的孤独日子。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP004', '强化石像怪', '得到黑暗力量而被强化的石像怪。注意钩爪！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP005', '杰拉的流浪者', '这张卡可以把1只原本攻击力是1600的通常怪兽解放攻击表示上级召唤。
【条件】无
【效果】选自己墓地1张「杰拉的仪式」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP006', '暗魔界的凶鬼', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己1张手卡送去墓地。那之后，可以选自己墓地1只「杰拉的流浪者」在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP007', '凶头邪龙', '【条件】无
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1只「暗魔界的凶鬼」或者1张「杰拉之剑」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP008', '杰拉的仪式', '【条件】无
【效果】等级合计直到8以上的自己的手卡·场上的怪兽作为素材送去墓地，把「杰拉」仪式术召唤（不能把多余怪兽作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP009', '杰拉的降临', '【条件】无
【效果】等级合计直到8以上的自己场上的表侧表示怪兽作为素材送去墓地，把「杰拉」或者「邪恶的魔族 杰拉」仪式术召唤（不能把多余怪兽作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP010', '杰拉之剑', '【条件】可以给自己场上的表侧表示的「杰拉的战士」或者「杰拉」装备。
【效果】自己回合内，装备怪兽的攻击力上升1000，那攻击带有贯通（向守备表示怪兽攻击时，给与攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP011', '杰拉的探索', '【条件】无
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1只通常怪兽（4星/地属性·暗属性/攻击力1600）或者1张「杰拉的仪式」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP012', '魔族钩爪', '【条件】自己场上有表侧表示的「杰拉」的场合才能发动。
【效果】选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP013', '杰拉的魔炎弹', '【条件】自己场上有表侧表示的「杰拉」的场合，对方把怪兽召唤·特殊召唤时才能发动。
【效果】选对方场上1张卡破坏。那之后，可以给与对方1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP014', '依然饶有情趣的菓子舞姬', '【条件】这张卡特殊召唤的自己主要阶段，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡直到下次的对方回合结束时不会被对方的效果破坏。并且自己墓地有「饶有情趣的菓子假名姬」的场合，可以再选对方场上1只怪兽破坏。破坏的场合，这个回合，这张卡不能直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP015', '依然饶有情趣的菓子鞠姬', '【条件】这张卡特殊召唤的自己主要阶段，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升700。自己墓地有「饶有情趣的菓子假名姬」的场合，更在这个回合让这张卡可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP016', '饶有情趣的菓子舞姬', '饶有情趣的菓子姐妹的长女。特别喜欢假名姬。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP017', '饶有情趣的菓子假名姬', '啊～嗯。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP018', '饶有情趣的菓子香姬', '把手卡1只通常怪兽（光属性/水族/守备力1400）给对方观看，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把1张手卡送去墓地才能发动。
【效果】自己回复500基本分。那之后，可以选自己墓地1只「饶有情趣的菓子假名姬」或者1张「饶有情趣的菓子袴着」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP019', '饶有情趣的菓子鞠姬', '把手卡1只通常怪兽（光属性/水族/守备力1400）给对方观看，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升600。那之后，可以选自己墓地1只「饶有情趣的菓子假名姬」或者1张「饶有情趣的菓子袴着」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP020', '饶有情趣的菓子雏姬', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只「饶有情趣的菓子假名姬」或者通常怪兽（7星/光属性/水族）在自己场上表侧守备表示特殊召唤。这个效果选「饶有情趣的菓子假名姬」的场合，可以再选自己墓地1张仪式术魔法卡在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP021', '饶有情趣的菓子鸟', '【条件】自己卡组的卡是10张以上的场合，把手卡1只怪兽（光属性/水族）送去墓地才能发动。
【效果】自己抽1张。那之后，可以选自己墓地1只「饶有情趣的菓子假名姬」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP022', '饶有情趣的菓子猫', '【条件】把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】从自己卡组上面把6张卡翻开，给双方确认。自己可以从那之中选1只「饶有情趣的菓子假名姬」加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP023', '饶有情趣的菓子袴着', '【条件】无
【效果】等级合计直到9以上的自己的手卡·场上的怪兽（光属性/水族）作为素材送去墓地，把「依然饶有情趣的菓子舞姬」或者「依然饶有情趣的菓子鞠姬」仪式术召唤（不能把多余怪兽作为素材）。这个效果不能让手卡的效果怪兽作为素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP024', '饶有情趣的菓子幸福日记', '【条件】自己墓地有怪兽（光属性/水族）3只以上的场合才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从那之中选1只怪兽（光属性/水族）或者1张仪式术魔法卡加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP025', '终焰魔神 绝望大炎魔［L］', '【条件】无
【永续效果】这张卡不会被对方的陷阱卡的效果破坏。这张卡是极大模式的场合，这张卡不会被对方的魔法卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP026', '终焰魔神 绝望大炎魔', '可以和「终焰魔神 绝望大炎魔［L］」「终焰魔神 绝望大炎魔［R］」集齐作极大召唤。
【条件】把手卡2只极大怪兽送去墓地才能发动。
【效果】选对方场上1张卡破坏。这张卡是极大模式的场合，再让自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP027', '终焰魔神 绝望大炎魔［R］', '【条件】无
【永续效果】双方不能从手卡·墓地把怪兽（7星）特殊召唤。这张卡是极大模式的场合，对方不能把手卡的怪兽盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP028', '焰魔神 蝇光蛇三魔［L］', '【条件】极大模式
【永续效果】这张卡不会被和通常怪兽的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP029', '焰魔神 蝇光蛇三魔', '可以和「焰魔神 蝇光蛇三魔［L］」「焰魔神 蝇光蛇三魔［R］」集齐作极大召唤。
【条件】极大模式
【永续效果】这张卡的等级上升6星，不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP030', '焰魔神 蝇光蛇三魔［R］', '【条件】极大模式：把卡组最上面的卡送去墓地才能发动。
【效果】这个回合，这张卡的攻击力上升600，那攻击带有贯通（向守备表示怪兽攻击时，给与攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP031', '双焰魔天 黑日天魔', '【条件】自己墓地有极大怪兽（炎属性）的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［自己墓地的极大怪兽（炎属性）数量］×300。自己墓地的极大怪兽是3只以上的场合，再在这个回合让这张卡的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP032', '双焰魔天 夜月天魔', '【条件】无
【永续效果】自己场上有这张卡以外的表侧表示怪兽（10星/炎属性）的场合，对方场上的表侧表示怪兽的攻击力·守备力下降1000。自己墓地的极大怪兽是3只以上的场合，自己怪兽（10星/炎属性）的攻击宣言时对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP033', '焰魔神 蝇魔', '把这张卡以外的2张手卡送去墓地，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只怪兽（10星/炎属性/恶魔族/攻击力2400以外）在自己场上表侧守备表示特殊召唤。那之后，可以选自己场上1只表侧表示的仪式术怪兽把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP034', '焰魔神 光魔', '这张卡可以把1只极大怪兽解放攻击表示上级召唤。
【条件】自己墓地有怪兽（恶魔族）3只以上的场合才能发动。
【效果】选自己墓地1只极大怪兽（炎属性）加入手卡或在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP035', '焰魔的劾狗', '【条件】把手卡1只怪兽（炎属性/恶魔族）送去墓地才能发动。
【效果】从自己卡组上面把4张卡送去墓地。那之后，可以从那之中选1只怪兽（炎属性/恶魔族/攻击力900以外）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP036', '双焰魔的祭坛', '【条件】无
【效果】等级合计直到10的自己的手卡·场上的怪兽（恶魔族）作为素材送去墓地，把「双焰魔天 黑日天魔」或者「双焰魔天 夜月天魔」仪式术召唤。这个效果把极大模式的怪兽送去墓地的场合，再让这个效果特殊召唤的怪兽只要处于表侧表示，攻击力·守备力上升2000，不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP037', '名蔷薇豪华魔术师姐妹', '「名蔷薇魔术师」＋「名蔷薇魔女」
【条件】无
【效果】选自己墓地1只怪兽（9星以下/光属性/魔法师族）在自己场上表侧守备表示特殊召唤。这张卡有装备魔法卡装备的场合，更在这个回合让这张卡可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP038', '名蔷薇绝妙魔术师', '「名蔷薇魔术师」＋「名蔷薇魔女」
【条件】把1张手卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽破坏。那之后，可以选自己墓地1张装备魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP039', '名蔷薇匿名魔术师', '「名蔷薇魔术师」＋「名蔷薇魔女」
这张卡可以用接触融合术。
【条件】这张卡融合术召唤的自己主要阶段才能发动。
【效果】选自己场上1只怪兽送去墓地。那之后，可以选对方场上1只表侧表示怪兽那个攻击力直到回合结束时下降［这个效果送去墓地的怪兽的原本攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP040', '名蔷薇富有魔术师姐妹', '「名蔷薇巫师」＋「名蔷薇法师」
【条件】这张卡特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地的装备魔法卡、「融合术」、「名流释放」合计最多2张在自己的魔法与陷阱区域盖放。那之后，可以选对方场上1张魔法·陷阱卡破坏。这个效果的发动后，直到回合结束时自己不能把融合术怪兽（7星）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP041', '名蔷薇网红姐妹', '「名蔷薇巫师」＋「名蔷薇女巫」
【条件】无
【效果】选对方墓地1只怪兽回到卡组下面，这张卡的攻击力直到回合结束时上升［这个效果回去的怪兽的等级］×200。这张卡有装备魔法卡装备的场合，再在这个回合让这张卡不会被效果破坏，可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP042', '名蔷薇八卦魔术师', '「名蔷薇魔术师」＋「暗冥狗仔队」
【条件】无
【永续效果】这张卡的攻击力上升［自己墓地的装备魔法卡数量］×400。自己场上有表侧表示的魔法卡的场合，这张卡不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP043', '名蔷薇八卦魔女', '「名蔷薇魔女」＋「暗冥狗仔队」
【条件】无
【效果】选对方场上1张魔法·陷阱卡破坏。自己场上有表侧表示的魔法卡的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP044', '名蔷薇魔术师', '【条件】把自己场上1张表侧表示的装备魔法卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。那之后，自己墓地有魔法卡3张以上的场合，这张卡的攻击力直到回合结束时上升700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP045', '名蔷薇魔女', '【条件】自己墓地有「名蔷薇魔术师」的场合，把手卡1只怪兽（光属性/魔法师族）或者1张魔法卡送去墓地才能发动。
【效果】选自己墓地1只「名蔷薇魔术师」或者融合术怪兽（9星以下/魔法师族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP046', '名蔷薇术士', '【条件】把自己场上最多2只表侧表示怪兽（5星以下）送去墓地才能发动。
【效果】选自己墓地1只怪兽（7星以上/光属性/魔法师族）在自己场上表侧表示特殊召唤。这个效果把「名蔷薇魔术师」特殊召唤的场合，可以再选自己墓地1只「名蔷薇魔女」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP047', '名蔷薇巫师', '【条件】把自己场上3只表侧表示怪兽（光属性/魔法师族）送去墓地才能发动。
【效果】选自己墓地1只怪兽（光属性/魔法师族/攻击力2500以下）在自己场上表侧表示特殊召唤。那之后，可以选自己墓地1张「克里斯马魔杖 死亡魔杖」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP048', '名蔷薇附魔师', '【条件】让2张手卡回到卡组才能发动。
【效果】选自己墓地1只怪兽（光属性/魔法师族）在自己场上表侧守备表示特殊召唤。这个效果把怪兽（5星以上）特殊召唤的场合，可以再选自己墓地1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP049', '名蔷薇法师', '【条件】这张卡召唤的回合，自己墓地有「名蔷薇魔术师」或者装备魔法卡的场合才能发动。
【效果】选自己墓地1张「克里斯马魔杖 死亡魔杖」或者「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP050', '名蔷薇女巫', '【条件】这张卡召唤的回合，把手卡1只怪兽（光属性/魔法师族）或者1张装备魔法卡给对方观看才能发动。
【效果】从自己卡组上面把4张卡送去墓地。那之后，可以从那之中选「名蔷薇魔术师」「名蔷薇魔女」「融合术」的其中1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP051', '辫子阅读者', '【条件】把手卡1只怪兽（光属性/魔法师族）或者1张魔法卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之中有怪兽（光属性/魔法师族）的场合，可以再选自己墓地1张装备魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP052', '亮光女郎', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选有装备魔法卡装备的自己场上1只怪兽（光属性/魔法师族）。这个回合，那只怪兽可以直接攻击。那只怪兽是7星以上的场合，再让那个攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP053', '暗冥狗仔队', '【条件】自己卡组的卡是10张以上，自己场上有表侧表示怪兽（5星以上/魔法师族）的场合，让自己墓地3只持有相同属性的怪兽（魔法师族）回到卡组才能发动。
【效果】自己抽出［对方场上的表侧表示怪兽（7星以上）的数量］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP054', '克里斯马魔杖 死亡魔杖', '【条件】可以给自己场上1只表侧表示怪兽（光属性/魔法师族）装备。
【效果】装备怪兽的攻击力上升400，那只怪兽不会被对方的效果破坏。装备怪兽是融合术怪兽的场合，那个攻击力上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP055', '克里斯马魔法-优雅变化', '【条件】把手卡1只怪兽（光属性/魔法师族）或者1张装备魔法卡送去墓地才能发动。
【效果】自己抽1张。自己墓地有怪兽4只以上的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP056', '名流释放', '【条件】自己场上有表侧表示怪兽（光属性/魔法师族）的场合，对方怪兽的攻击宣言时，让自己场上1张表侧表示的装备魔法卡或者自己墓地4只怪兽（光属性/魔法师族）回到持有者卡组才能发动。
【效果】选对方场上最多3只攻击表示怪兽回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP057', '环幻乐鬼神 小号大管枪贯神息虎吸人', '「神乐鬼 大管神指人」＋「挥乐姬 指挥棒棍手」
【条件】把最多3张手卡送去墓地才能发动。
【效果】这个回合，这张卡不会被对方的陷阱卡的效果破坏，那攻击带有贯通。这张卡特殊召唤的自己主要阶段把这个效果发动的场合，可以再让这张卡的攻击力直到回合结束时上升［这个效果的条件送去墓地的怪兽数量］×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP058', '环幻乐鬼 全编制管弦乐团舞斗家', '「重乐鬼 合奏武斗家」＋「挥乐姬 指挥棒棍手」
【条件】把1张手卡送去墓地才能发动。
【效果】对方的魔法与陷阱区域的里侧表示的卡全部破坏。那之后，这张卡的攻击力直到回合结束时上升［这个效果破坏的卡数量］×600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP059', '环幻乐姬 旋律动作斧手', '「振乐姬 大号月刃斧手」＋「挥乐姬 指挥棒棍手」
【条件】让自己墓地1张魔法卡回到卡组上面或下面才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力·守备力直到下次的对方回合结束时下降2000。这个效果的条件让「一気貫通」或者「融合术」回去的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP060', '斧乐姬 调音长笛战斧手', '「斧乐姬 长笛战斧手」＋「挥乐姬 指挥棒棍手」
这张卡可以用接触融合术。
【条件】无
【效果】从自己卡组上面把4张卡送去墓地。那之后，可以选自己墓地1只怪兽（7星以上/风属性/战士族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP061', '斧乐姬 长笛战斧手', '合奏武队的冲锋陷阵队长。发出的斧声有着华丽的音色。虽然疑似隐藏暗器，但其实是单纯怕冷。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP062', '挥乐姬 指挥棒棍手', '合奏武队的统一者。用轻快的挥棒技巧来指挥个性丰富的同伴。只要眼镜受人指摘就会闹别扭。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP063', '神乐鬼 大管神指人', '【条件】对方场上有守备表示怪兽的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［对方场上的守备表示怪兽数量］×800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP064', '重乐鬼 合奏武斗家', '【条件】把1张手卡送去墓地才能发动。
【效果】这个回合，这张卡是表侧表示的期间，自己怪兽（风属性/战士族）的攻击宣言时对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP065', '振乐姬 大号月刃斧手', '【条件】这张卡召唤的回合，自己场上有这张卡以外的表侧表示怪兽（战士族）的场合才能发动。
【效果】选自己墓地的怪兽（7星以上/风属性）和通常怪兽（战士族）各1只加入手卡。这个效果的发动后，直到回合结束时自己不能把怪兽（风属性/战士族·兽族）以外的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP066', '弯乐姬 短号短弯刀手', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把5张卡翻开，给双方确认。自己可以从那之中选1只通常怪兽（风属性/战士族）或者1张「融合术」加入手卡。剩下的卡用喜欢的顺序回到卡组下面。这个回合，自己不用怪兽（风属性/战士族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP067', '冠狙乐姬 长号弩手', '【条件】从卡组上面把2张卡送去墓地，把手卡1只怪兽（风属性/战士族）送去墓地才能发动。
【效果】自己抽1张。自己墓地有通常怪兽的场合，可以再选自己或者对方场上1只怪兽把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP068', '乐姬的演舞', '【条件】自己墓地有怪兽（风属性/战士族）5只以上的场合才能发动。
【效果】自己的手卡·墓地的怪兽作为素材回到卡组，把怪兽（风属性/战士族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP069', '可能甜心：D', '隐藏有无限可能性，面带笑容的同时不断追逐着光辉梦想。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP070', '多面手女郎', '下至寻猫上至要人护卫样样承包的多面手。最近总是去送午餐，但某天收到了发送人不明的信息。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP071', '平流层军锤·雷神锤', '自己场上没有怪兽的场合，这张卡可以不用解放作召唤。
【条件】把这张卡以外的自己场上1张卡或者从卡组上面把2张卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽，那个等级直到回合结束时上升4星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP072', '希望之占仪巫妖', '【条件】这张卡召唤的回合，自己卡组的卡是10张以上的场合，让自己墓地1只怪兽回到卡组下面才能发动。
【效果】从自己卡组上面把3张卡送去墓地。这个效果的条件让仪式术怪兽回去的场合，再让自己可以从这个效果送去墓地的卡之中选1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP073', '神魔兽 加泽特', '这张卡可以把3只效果怪兽解放攻击表示上级召唤。
【条件】无
【永续效果】这张卡的攻击力上升［这张卡攻击表示上级召唤时解放的效果怪兽的原本攻击力合计］。把3只怪兽解放作召唤的这张卡的攻击力上升800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP074', '伟大魔兽 加泽特', '【条件】无
【永续效果】这张卡的攻击力上升［这张卡攻击表示上级召唤时解放的1只怪兽的原本攻击力］×2。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP075', '巡演魔王族·分立放大精英', '【条件】自己墓地有怪兽（恶魔族）3只以上的场合或者自己墓地有「国王的贪欲」的场合才能发动。
【效果】选自己墓地1只怪兽（5星以上/恶魔族/守备力0或者2000）加入手卡。这个回合，自己不能用怪兽（恶魔族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP076', '肩电娘娘', '【条件】这张卡召唤的回合，让1张手卡回到卡组下面才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降500。那之后，可以选自己墓地1只怪兽（7星以上/水族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP077', '高跟鞋女祭司', '【条件】这张卡召唤的回合，自己场上有表侧表示怪兽（7星以上/水族）的场合才能发动。
【效果】自己抽1张。那之后，自己场上的全部表侧表示怪兽（7星以上/水族）的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP078', '电子处理机', '自己场上有表侧表示怪兽（机械族）的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把这张卡以外的自己场上1张卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「电子龙」。那之后，可以选自己墓地1只「电子龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP079', '电子巨蛇', '【条件】自己场上有这张卡以外的表侧表示怪兽（光属性/机械族）的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之中有怪兽（光属性/机械族）2只以上的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP080', '龙之支配者-龙之绝对者-', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选怪兽（8星/光属性/龙族）和「究极的青眼传说」各最多1张加入手卡。剩下的卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP081', '英雄少年', '【条件】自己墓地有「融合术」或者「摩天楼」的场合才能发动。
【效果】选自己墓地的通常怪兽（战士族）或者「融合术」合计最多2张加入手卡。那之后，选自己场上1只怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP082', '元素英雄 火焰翼侠', '「元素英雄 羽翼侠」＋「元素英雄 爆热女郎」
这张卡不用融合术召唤不能特殊召唤。
【条件】无
【永续效果】这张卡战斗破坏怪兽送去墓地时，给与对方为［那只怪兽的原本攻击力］的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP083', '元素英雄 爆热翼侠', '「元素英雄 羽翼侠」＋「元素英雄 爆热女郎」
这张卡不用融合术召唤不能特殊召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（战士族），那个攻击力直到下次的对方回合结束时上升1000。那之后，可以选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP084', '乘潮蓝鳍号', '【条件】这张卡仪式术召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之中有怪兽（鱼族）或者魔法卡的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP085', '蓝鳍号的誓言', '【条件】自己没有把怪兽特殊召唤的回合才能发动。
【效果】等级合计直到4以上的自己场上的表侧表示怪兽作为素材送去墓地，把「乘潮蓝鳍号」仪式术召唤（不能把多余怪兽作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP086', '团结之力', '【条件】可以给自己场上1只表侧表示怪兽装备。
【效果】装备怪兽的攻击力·守备力上升［自己场上的表侧表示怪兽数量］×800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP087', '显现的秘仪', '【条件】把自己的手卡·场上最多2只怪兽送去墓地才能发动。
【效果】自己抽1张。那之后，可以选自己墓地1只怪兽（5星以上/光属性/魔法师族）在自己场上表侧表示特殊召唤。这个效果的发动后，直到回合结束时自己不能把怪兽（光属性/魔法师族）以外的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP088', '天使的玉米', '【条件】自己场上有表侧表示怪兽（水族），自己墓地有怪兽（水族）的场合才能发动。
【效果】自己抽2张。那之后，自己选1张手卡回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP089', '念之印刻', '【条件】自己场上有表侧表示怪兽（7星以上/风属性）的场合才能发动。
【效果】自己抽1张。自己场上有表侧表示的「多面手女郎」的场合，可以再把手卡1只怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP090', '融合术', '【条件】无
【效果】自己场上的表侧表示怪兽作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP091', '深渊海兽单色光', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】选双方墓地的怪兽（4星以下/光属性·暗属性）合计3只回到持有者卡组。那之后，攻击的怪兽的攻击力直到回合结束时下降［这个效果回去的怪兽的等级合计］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP092', '与未知的邂逅', '【条件】自己场上有表侧表示怪兽（7星以上/欧米伽念动力族·念动力族）的其中任意种的场合，对方怪兽（8星以下）的攻击宣言时才能发动。
【效果】攻击的怪兽回到持有者手卡。自己场上有表侧表示的「多面手女郎」的场合，可以再选自己墓地1只怪兽（3星以下）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP093', '历战的暗黑骑士 盖亚', '这张卡可以把1只表侧表示怪兽（5星以上）解放攻击表示上级召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「暗黑骑士盖亚」。那之后，可以让包含这张卡的自己的场上·墓地的怪兽2只作为素材回到持有者卡组作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP094', '历战的诅咒之龙', '自己场上没有怪兽的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「诅咒之龙」。那之后，可以让包含这张卡的自己的场上·墓地的怪兽2只作为素材回到持有者卡组作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP095', '青眼究极龙', '「青眼白龙」＋「青眼白龙」＋「青眼白龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP096', '摩天楼', '【条件】无
【效果】只要这张卡在场地区域处于表侧表示，回合玩家的场上的表侧表示的「元素英雄 羽翼侠」、「元素英雄 爆热女郎」、「元素英雄 黏土侠」、「元素英雄 电光侠」、「元素英雄 水泡侠」、「元素英雄 新宇侠」、融合术怪兽（5～8星/战士族）的攻击力上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP097', '碧牙超越爆速龙', '「碧牙爆速龙」＋「增速飞龙」
【条件】把自己场上1只怪兽送去墓地才能发动。
【效果】选自己或者对方场上1张表侧表示的卡破坏。这个效果的条件把原本等级是7星以上的怪兽送去墓地的场合，可以再选自己墓地1只「碧牙爆速龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP098', '真红动超越击速龙', '「真红动击速龙」＋「增速飞龙」
【条件】无
【效果】选双方墓地的怪兽合计最多9只。给与对方为［选的怪兽数量］×200伤害，这张卡的攻击力直到回合结束时上升［选的怪兽数量］×200。那之后，选的怪兽回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP099', '龙骑士 盖亚', '「暗黑骑士盖亚」＋「诅咒之龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP01-JP100', '潜入开始', '【条件】无
【效果】选自己的手卡·墓地1只通常怪兽（7星）在自己场上表侧表示特殊召唤。这个回合，这个效果特殊召唤的怪兽的攻击力上升700，不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP002', '巡演魔王族·重金属歌手', '【条件】把怪兽（5星以上）解放来把这张卡召唤的回合才能发动。
【效果】选对方场上1只等级最低的表侧表示怪兽（8星以下），这张卡的攻击力直到回合结束时上升［选的怪兽的攻击力］。选的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP003', '超级助手·阿炽', '喜欢的实验是焰色试验！以燃烧的心情为原动力今天也会好好加油！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP004', '可能甜心-旋律：D', '【条件】让这张卡以外的自己场上1只表侧表示怪兽（5星以上）回到持有者手卡才能发动。
【效果】选对方场上1张里侧表示的卡回到持有者卡组。自己基本分比对方少的场合，可以再选自己墓地1只通常怪兽（1星/念动力族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP005', '超可爱执行者·救火女', '对方场上有表侧表示怪兽（6星以上）的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［双方场上的表侧表示怪兽（6星以上）数量］×600。这个回合，自己不用这张卡不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP006', '超可爱执行者·花草女', '把这张卡以外的手卡1只怪兽（6星/守备力500）给对方观看，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】自己回复500基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP007', '七星道巫师', '【条件】把自己场上3只表侧表示怪兽送去墓地才能发动。
【效果】选自己墓地1只怪兽（7星以下/魔法师族）在自己场上表侧表示特殊召唤。这个效果把「七道魔导士」特殊召唤的场合，可以再选自己墓地1只「七道魔女」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP008', '魔导龙骑士-七魔导齿车戒骑士', '「七道魔导士」＋「連撃竜ドラギアス」
【条件】对方场上有表侧表示怪兽（7星以上）的场合，把卡组最上面的卡送去墓地才能发动。
【选择效果】●这个回合，这张卡的攻击力上升［自己墓地的怪兽的种族种类］×700，并且可以向怪兽作2次攻击。●双方场上的表侧表示的卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP009', '花牙一轮 同心·开花', '「花牙美人之昙花」＋「花牙武者之龙胆」
【条件】从卡组上面把3张卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（植物族）。这个回合，那只怪兽可以直接攻击。并且，可以再选自己墓地1张「花牙踏み」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP010', '幽灵旋风', '【条件】自己场上没有怪兽的场合才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，自己墓地的怪兽是3只以下的场合，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP011', '黑炎弹', '【条件】自己场上有表侧表示的「真红眼黑龙」的场合才能发动。
【效果】给与对方2400伤害。这个回合，自己不能用「真红眼黑龙」攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP012', '黑·魔·导·响·弹', '【条件】无
【效果】选自己场上1只表侧表示怪兽（6星以上/暗属性/魔法师族），那个攻击力直到回合结束时上升1000。自己场上有表侧表示的「黑魔术师」或者「黑魔导士少女」的场合，再让选的怪兽的攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP013', '毁灭之爆裂疾风弹', '【条件】自己场上有表侧表示的「青眼白龙」的场合才能发动。
【效果】对方场上的怪兽全部破坏。这个回合，自己不能用「青眼白龙」攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP014', '克里斯马魔杖 死亡魔杖', '【条件】可以给自己场上1只表侧表示怪兽（光属性/魔法师族）装备。
【效果】装备怪兽的攻击力上升400，那只怪兽不会被对方的效果破坏。装备怪兽是融合术怪兽的场合，再让那个攻击力上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP015', '魔导枪 天惠枪', '【条件】可以给自己场上1只表侧表示怪兽（魔导骑士族·魔法师族）装备。
【效果】装备怪兽的攻击力上升200，那攻击带有贯通。装备怪兽是魔导骑士族的场合，再让那个攻击力上升［装备怪兽的等级］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP016', '超可爱执行者捕获！', '【条件】自己场上有表侧表示怪兽（6星/守备力500）的场合，对方把怪兽表侧表示召唤·特殊召唤时才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP017', '巡演魔王族·前卫摇滚乐手', '【条件】把怪兽（5星以上）解放来把这张卡召唤的回合才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，可以选对方场上1张里侧表示的卡破坏。这个回合，自己不能用怪兽（恶魔族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP019', '虚空噬骸兵·混沌战鹰巨人', '「虚空噬骸兵 镇魂鹰巨人」＋怪兽（8星以上/暗属性）
【条件】让自己墓地2只种族不同的怪兽（暗属性）回到卡组才能发动。
【效果】选对方场上最多2张表侧表示的卡回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP020', '暗黑龙魔', '「恶魔的召唤」＋「真红眼黑龙」
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】自己场上的全部表侧表示怪兽的攻击力直到回合结束时上升500。那之后，可以把对方场上的表侧表示怪兽（攻击力3100以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP021', '不可估量的破坏力', '【条件】自己场上有表侧表示的「青眼白龙」的场合才能发动。
【效果】选自己墓地1只怪兽（8星/光属性/龙族）加入手卡。这个效果选「青眼の煌龍」的场合，可以再选自己墓地1张「究极的青眼传说」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP022', '名流释放', '【条件】自己场上有表侧表示怪兽（光属性/魔法师族）的场合，对方怪兽的攻击宣言时，让自己场上1张表侧表示的装备魔法卡或者自己墓地4只怪兽（光属性/魔法师族）回到持有者卡组才能发动。
【效果】选对方场上最多3只攻击表示怪兽回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP023', '决战的骸骨恶魔', '手卡或者墓地的这张卡的卡名变成「恶魔的召唤」。
【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「恶魔的召唤」。那之后，可以选自己墓地1只通常怪兽（7星以下）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP024', '真红动击速龙', '【条件】无
【效果】选自己墓地最多7只怪兽（龙族）。给与对方为［选的怪兽数量］×100伤害，这张卡的攻击力直到回合结束时上升［选的怪兽数量］×100。那之后，选的怪兽回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP025', '节奏表演者', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】对方把自身卡组最上面的卡送去墓地。这个效果让魔法·陷阱卡被送去墓地的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP026', '银河舰未视龙', '【条件】这张卡召唤的回合，自己场上没有这张卡以外的怪兽的场合，让自己墓地2张魔法卡回到卡组才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP027', '引力冠视小爱', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把5张卡翻开，给双方确认。自己从那之中让怪兽（光属性/银河族）全部用喜欢的顺序回到卡组上面。剩下的卡用喜欢的顺序回到卡组下面。这个效果让卡4张以上回到卡组上面的场合，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP028', '魔力报应', '【条件】自己场上的卡被对方的攻击或者对方的效果破坏时，支付800基本分才能发动。
【效果】选对方场上1只表侧表示的效果怪兽（8星以下）或者1张里侧表示的卡破坏。那之后，可以选自己墓地1只怪兽（6星/暗属性/魔法师族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP029', '双生精灵', '交替发动攻击的精灵双子姐妹。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP030', '人造人-念力震慑者', '【条件】无
【永续效果】双方不能把陷阱卡发动，双方的陷阱卡的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP031', '七星道附魔师', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己或者对方场上1只表侧表示怪兽（3星以外/魔法师族）回到持有者手卡。这个效果回到手卡的卡的原本卡名是「七道魔导士」的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP032', '强制脱出装置', '【条件】自己或者对方把怪兽召唤·特殊召唤时或者对方把魔法卡发动后才能发动。
【效果】选自己或者对方场上1只怪兽回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP033', '神圣防护罩 -反射镜力-', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】对方场上的攻击表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP034', '魔法筒', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】那次攻击无效，给与对方为［那只怪兽的攻击力］的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP035', '黑魔导遂行者', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「黑魔术师」。那之后，可以选自己墓地10张魔法卡回到卡组。回去的场合，可以再选对方场上1只表侧表示怪兽（8星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP036', '焰魔神 光魔', '这张卡可以把1只极大怪兽解放攻击表示上级召唤。
【条件】自己墓地有怪兽（恶魔族）3只以上的场合才能发动。
【效果】选自己墓地1只极大怪兽（炎属性）加入手卡或在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP037', '超银河王 道皆通银河舰［L］', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只原本攻击力是4000以上的表侧表示怪兽（银河族·魔法师族·机械族·龙族/攻击力4000以上），那个攻击力直到回合结束时下降4000。那之后，可以选对方场上最多4张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP038', '超银河王 道皆通银河舰', '可以和「超银河王 道皆通银河舰［L］」「超银河王 道皆通银河舰［R］」集齐作极大召唤。
【条件】把通常怪兽（银河族）解放来把这张卡召唤的回合才能发动。
【效果】选自己墓地2只怪兽（10星）加入手卡。那之后，这张卡回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP039', '超银河王 道皆通银河舰［R］', '【条件】极大模式
【效果】选对方场上1只表侧表示怪兽，等级合计直到变成和那只怪兽的等级相同为止自己把手卡的通常怪兽送去墓地。那之后，可以让这张卡的攻击力直到回合结束时上升［选的表侧表示怪兽的攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP041', '花牙封 绘都兰世', '墓地的这张卡的卡名变成「花牙女忍 异邦兰」。
【条件】让自己墓地1只怪兽（植物族）回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（植物族）。这张卡的卡名在这个回合变成和选的怪兽相同卡名。那之后，可以选自己墓地1张「融合术」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP042', '传导士 炼金化学人·水雷', '怪兽（水族）＋怪兽（雷族）
【条件】把包含怪兽的最多3张手卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升［这个效果的条件送去墓地的怪兽的等级合计］×100。这个效果的条件把种族不同的怪兽3只送去墓地的场合，再让这张卡直到下次的对方回合结束时不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP043', '诅咒之龙', '邪恶之龙。使用黑暗力量的攻击强而有力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP044', '创世神', '这张卡不能从墓地特殊召唤。
【条件】有自己手卡的场合才能发动。
【效果】选自己墓地1只怪兽在自己场上表侧表示特殊召唤。那之后，自己选1张手卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP045', '斩奏之琴拨罪犯', '【条件】这张卡召唤的回合，支付1000基本分才能发动。
【效果】选自己墓地1张装备魔法卡加入手卡。那之后，这张卡的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP046', '名蔷薇术士', '【条件】把自己场上最多2只表侧表示怪兽（5星以下）送去墓地才能发动。
【效果】选自己墓地1只怪兽（7星以上/光属性/魔法师族）在自己场上表侧表示特殊召唤。这个效果把「名蔷薇魔术师」特殊召唤的场合，可以再选自己墓地1只「名蔷薇魔女」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP047', '卫星飞马', '【条件】这张卡召唤的回合才能发动。
【效果】自己卡组最上面的卡送去墓地。那之后，自己墓地的怪兽是1只以下的场合，可以选对方场上1只表侧表示怪兽（8星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP048', '巡演魔王族·分立放大精英', '【条件】自己墓地有怪兽（恶魔族）3只以上的场合或者自己墓地有「国王的贪欲」的场合才能发动。
【效果】选自己墓地1只怪兽（5星以上/恶魔族/守备力0或者2000）加入手卡。这个回合，自己不能用怪兽（恶魔族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP050', '名蔷薇附魔师', '【条件】让2张手卡回到卡组才能发动。
【效果】选自己墓地1只怪兽（光属性/魔法师族）在自己场上表侧守备表示特殊召唤。这个效果把怪兽（5星以上）特殊召唤的场合，可以再选自己墓地1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP051', '言语妖精', '【条件】这张卡召唤的回合，对方场上有怪兽的场合，让自己墓地3只怪兽回到卡组才能发动。
【效果】选对方墓地3只怪兽回到卡组。自己场上的表侧表示怪兽（1星以外/魔法师族）是2只的场合，可以再选对方墓地3只怪兽回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP052', '龙骑士 盖亚', '「暗黑骑士盖亚」＋「诅咒之龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP054', '三角神迷火花', '【条件】自己场上有表侧表示的「鹰身三姐妹」的场合才能发动。
【效果】选自己场上最多3只表侧表示怪兽（风属性），那些攻击力直到回合结束时上升600。这个回合，对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP056', '鹰身女妖的正装', '【条件】可以给自己场上1只表侧表示的「鹰身女郎」或者「鹰身三姐妹」装备。
【效果】装备怪兽的攻击力上升800，守备力上升400。自己场上的表侧表示怪兽是1只或者3只的场合，装备怪兽的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP057', '基调强节奏', '【条件】让自己墓地2只怪兽回到卡组才能发动。
【效果】选对方墓地2～7只相同种族的怪兽回到卡组。这个效果让怪兽4只以上回去的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP058', '槌击', '【条件】无
【效果】选双方场上的攻击表示怪兽之内攻击力最高的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP059', '精灵剑士', '学会了剑术的精灵。以快速的攻击作弄敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP060', '加农炮兵', '【条件】把自己场上1只怪兽送去墓地才能发动。
【效果】给与对方500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP061', '穿越侍·乌贼侍', '【条件】把1张手卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（光属性/银河族）。这个回合，那只怪兽的攻击带有贯通。自己场上有表侧表示的「穿越侍·线性海牛侍」的场合，可以再选对方场上1只表侧表示怪兽把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP062', '成银哥布林', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】手卡1只怪兽（6星以下）在自己场上表侧表示特殊召唤。这个效果特殊召唤的怪兽的攻击力直到回合结束时上升500。自己墓地有「成金哥布林」的场合，再给与对方500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP063', '敏捷表演者', '【条件】对方场上有怪兽的场合，把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽，那个攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP064', '超级助手·冰娅', '【条件】自己卡组的卡是10张以上的场合，把手卡1只效果怪兽（炎属性）送去墓地才能发动。
【效果】自己抽1张。那之后，可以让自己墓地的「超级助手·阿炽」全部用喜欢的顺序回到卡组下面。回去的场合，再让自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP065', '超级助手·霹丽', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只怪兽（炎属性）回到卡组上面。那之后，自己墓地有「超级助手·阿炽」的场合，可以选自己墓地2只怪兽（炎属性）用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP066', '超可爱执行者联合！', '【条件】无
【效果】选自己场上2只种族不同的表侧表示怪兽。这个回合，怪兽攻击表示上级召唤的场合，选的怪兽可以作为2只的数量解放。自己场上有表侧表示怪兽（6星/守备力500）的场合，给与对方800伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP067', '花牙兰舞', '【条件】自己场上有怪兽的场合，让自己墓地3只怪兽（植物族）回到卡组才能发动。
【效果】自己抽1张。那之后，可以选对方场上最多3只表侧表示怪兽（植物族以外）那些攻击力·守备力直到回合结束时下降300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP068', '平行宇宙之门', '【条件】无
【效果】自己卡组最上面的卡送去墓地。自己手卡是0张的场合，可以再选自己墓地最多2只通常怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP069', '豪胆防御任务', '【条件】原本攻击力是2500以上的对方怪兽（8星以下）的攻击宣言时才能发动。
【效果】攻击的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP070', '华丽爪牙斩', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时，让自己墓地1只「鹰身女郎」或者「鹰身三姐妹」回到卡组上面或下面才能发动。
【效果】选对方场上1张卡回到持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP071', '巡演魔王族·死亡厄运歌手', '【条件】把2只怪兽（7星以上/恶魔族）解放来把这张卡召唤的回合才能发动。
【效果】对方场上的表侧表示怪兽全部破坏。那之后，给与对方为［这个效果破坏的怪兽的原本等级合计］×100伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP072', '花牙铠·小木通', '【条件】这张卡召唤的回合，自己基本分是对方基本分以上的场合，把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】直到下次的对方回合结束时，自己基本分是对方基本分以上的期间，这张卡不会被战斗破坏。自己墓地有怪兽3只以上的场合，可以再选自己墓地1只怪兽（植物族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP073', '焰魔的永狼', '【条件】把手卡1只怪兽（恶魔族）送去墓地才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。这个效果的条件把怪兽（10星）送去墓地的场合，可以再选自己墓地1只怪兽（4星/恶魔族/攻击力0）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP074', '巡演魔王族·垃圾摇滚乐手', '【条件】自己卡组的卡是10张以上的场合，把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】给与对方500伤害。自己场上有表侧守备表示怪兽（7星以上/恶魔族）的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP075', '双冷星', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的等级直到回合结束时上升2星。这个效果的条件让怪兽（光属性/银河族）被送去墓地的场合，再在这个回合在怪兽（光属性/银河族）攻击表示上级召唤的场合让表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP076', '银河材料采集员', '【条件】把手卡1只怪兽（8星以下/银河族）送去墓地才能发动。
【效果】选自己墓地1只极大怪兽（10星/银河族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP077', '灵魂骑士', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「灵魂骑士」或者「灵魂龙兽」在自己场上表侧守备表示特殊召唤。这个回合，自己不能用怪兽（7星以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP078', '巡演魔王族守护者', '【条件】对方场上有表侧表示怪兽（7星以上）的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这个回合，怪兽（恶魔族）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。对方场上有怪兽2只以上的场合，再让这张卡的等级直到回合结束时上升1星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP079', '海龙骑士', '【条件】让自己墓地2只怪兽回到卡组才能发动。
【效果】选对方场上1张里侧表示的魔法·陷阱卡确认。和那张卡同名的卡在对方墓地的场合，可以再把选的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP080', '成金恐龙王', '【条件】对方手卡是0张的场合才能发动。
【效果】双方抽1张。这个效果让双方抽卡的场合，再让自己可以选自己墓地1张「成金哥布林」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP081', '深渊刺海龟', '【条件】自己场上没有这张卡以外的怪兽的场合才能发动。
【效果】选自己墓地1只怪兽（海龙族/攻击力800/守备力0）加入手卡。这个回合，自己不能用怪兽（海龙族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP082', '亮光女郎', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选有装备魔法卡装备的自己场上1只怪兽（光属性/魔法师族）。这个回合，那只怪兽可以直接攻击。那只怪兽是7星以上的场合，再让那个攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP083', '国王的贪欲', '【条件】把手卡1只怪兽（5星以上/光属性/恶魔族）送去墓地或让自己墓地3只怪兽（7星以上/光属性/恶魔族）回到卡组才能发动。
【效果】选自己场上1只攻击表示怪兽（光属性/恶魔族）变成表侧守备表示。那之后，自己可以抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP084', '魔力火风暴', '【条件】无
【效果】对方场上的原本等级是6星以下的表侧表示怪兽选最多有［自己场上的表侧表示怪兽（魔法师族）数量］破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP085', '虚空噬骸兵晨星锤', '【条件】对方场上有里侧表示怪兽的场合，可以给自己场上1只表侧表示怪兽（7星以上/暗属性/银河族）装备。
【效果】装备怪兽1回合可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP086', '名流剑·死亡狂野剑', '【条件】可以给自己场上1只表侧表示怪兽（光属性/魔法师族）装备。
【效果】装备怪兽的攻击力上升400，那攻击带有贯通。自己墓地有「名蔷薇魔女」，自己把装备怪兽作为融合术召唤的素材的场合，可以把那个卡名变成「名蔷薇魔女」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP087', '名流礼服·死亡缠绕服', '【条件】可以给自己场上1只表侧表示怪兽（光属性/魔法师族）装备。
【效果】装备怪兽的攻击力上升400，那只怪兽不会被对方的效果破坏。自己墓地有「名蔷薇魔术师」，自己把装备怪兽作为融合术召唤的素材的场合，可以把那个卡名变成「名蔷薇魔术师」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/HC01-JP088', '国王的权威', '【条件】对方回合，对方把怪兽召唤·特殊召唤时才能发动。
【效果】对方场上的表侧表示的效果怪兽（4星以上）选最多有［自己场上的表侧表示怪兽（5星以上/光属性/恶魔族）数量］。这个回合，对方不能把那些怪兽的效果发动，对方不能把那些怪兽为上级召唤而解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP001', '青眼究极龙', '「青眼白龙」＋「青眼白龙」＋「青眼白龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP002', '青眼白龙', '以高攻击力著称的传说之龙。任何对手都能粉碎，其破坏力不可估量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP003', '青眼煌龙', '手卡的这张卡的卡名变成「青眼白龙」。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这个回合，这张卡的卡名变成「青眼白龙」，攻击力上升500。自己场上有表侧表示的传说通常怪兽的场合，可以再选对方场上1只表侧表示怪兽（8星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP005', '龙之支配者-龙之绝对者-', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从翻开的卡之中选怪兽（8星/光属性/龙族）和「究极的青眼传说」各最多1张加入手卡。剩下的卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP007', '灵魂龙兽', '【条件】这张卡召唤·特殊召唤的自己主要阶段，把自己场上2只表侧表示的效果怪兽（4星以下）送去墓地才能发动。
【效果】选自己墓地1只怪兽（8星/光属性/龙族）在自己场上表侧表示特殊召唤。这个回合，自己不能用怪兽（7星以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP008', '凤凰龙骑士', '【条件】自己卡组的卡是10张以上的场合，把手卡1只怪兽送去墓地才能发动。
【效果】自己回复300基本分。自己墓地有怪兽（8星）的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP009', '钻石龙', '全身由钻石构成的龙。用耀眼的光来蒙蔽敌人的双眼。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP010', '古代冰炎龙', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升600。那之后，可以选自己墓地的「明冰龙」「燃烧烈焰龙」各1只回到卡组。回去的场合，可以再选对方场上1只表侧表示怪兽（守备力1500以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP011', '古代炎冰龙', '【条件】把1张手卡送去墓地才能发动。
【效果】选对方场上最多2只表侧表示怪兽，那些攻击力直到回合结束时下降400。那之后，可以选自己墓地的「明冰龙」「燃烧烈焰龙」各最多1只在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP012', '明冰龙', '【条件】让自己墓地1只怪兽（5星以下/龙族）回到卡组下面才能发动。
【效果】选对方墓地最多2只怪兽回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP013', '燃烧烈焰龙', '【条件】让自己墓地1只怪兽（5星以下/龙族）回到卡组下面才能发动。
【效果】对方场上的表侧表示的场地魔法卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP014', '圣构体', '【条件】无
【永续效果】通常怪兽（光属性）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP015', '辉岩龙', '起源于地下矿脉的龙。靠未知矿石产生的能量作为动力源持续作战。超硬度的打击可是威力超群！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP016', '赤烈火龙', '全身被赤烈火覆盖，样子非常美丽的龙。虽然并不喜欢斗争，却具备很高攻击力。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP017', '风力精龙', '掌管风的四大精龙的幼体。将大气操纵自如并且守护那片土地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP018', '妖精龙', '在妖精之中出乎意料地强，非常美丽的龙之妖精。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP019', '午睡斗牛士', '【条件】让自己墓地3只怪兽回到卡组才能发动。
【效果】选对方场上1只攻击表示怪兽（8星以下）变成里侧守备表示。那之后，可以选自己墓地1张「强制午休」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP020', '财宝龙', '【条件】这张卡从手卡或者墓地特殊召唤的自己主要阶段，自己墓地有怪兽（龙族）4只以上的场合才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP021', '三联龙', '【条件】对方场上有表侧表示怪兽（7星以上），自己场上的表侧表示怪兽（3星以外/龙族）是2只的场合才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP022', '正义的同伴 海马侠', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】手卡1只「青眼白龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP023', '凤凰龙', '【条件】把1张手卡送去墓地才能发动。
【效果】选自己墓地1只怪兽（5星以上/龙族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP024', '守护的龙魔导士', '【条件】把手卡1只怪兽（魔法师族·龙族）送去墓地才能发动。
【效果】选自己场上1只怪兽。这个回合，那只怪兽不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP025', '二咒葬之龙', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】自己回复200基本分。那之后，可以选自己墓地1张「龙之二咒葬」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP026', '死者苏生', '【条件】无
【效果】选自己或者对方的墓地1只怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP027', '究极的青眼传说', '【条件】无
【效果】自己的手卡·场上的怪兽（龙族）最多3只作为素材送去墓地，把怪兽（10星以上/龙族）融合术召唤。这个回合，这个效果特殊召唤的怪兽不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP028', '传说的圣所', '【条件】无
【效果】只要这张卡在场地区域处于表侧表示，双方场上的表侧表示怪兽（8星以上/龙族）的攻击力上升500，双方场上的表侧表示的传说怪兽（龙族）不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP029', '毁灭之爆裂疾风弹', '【条件】自己场上有表侧表示的「青眼白龙」的场合才能发动。
【效果】对方场上的怪兽全部破坏。这个回合，自己不能用「青眼白龙」攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP030', '火龙的热闪', '【条件】自己场上有表侧表示怪兽（龙族）的场合才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP031', '龙力重压', '【条件】把手卡3只怪兽（龙族）送去墓地才能发动。
【效果】双方场上的怪兽全部破坏。那之后，可以选自己墓地1只怪兽（4星以下/龙族）在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP032', '抵价购物', '【条件】把手卡1只怪兽（8星）送去墓地才能发动。
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP033', '沉默的死者', '【条件】无
【效果】选自己墓地1只通常怪兽在自己场上表侧守备表示特殊召唤。这个效果特殊召唤的怪兽在表侧表示的期间不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP034', '落穴', '【条件】对方把怪兽（攻击力1000以上）召唤时才能发动。
【效果】那只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP035', '青色眼睛的秘宝', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时才能发动。
【效果】选自己墓地1只怪兽（8星以上/光属性/龙族）在自己场上表侧表示特殊召唤。那之后，自己场上有表侧表示的「青眼白龙」的场合，可以选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP036', '永久冻结', '【条件】对方把怪兽（攻击力2500以上）召唤时，把自己场上1只怪兽送去墓地才能发动。
【效果】那只召唤的怪兽回到持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0A-JP037', '龙之二咒葬', '【条件】自己场上有表侧表示怪兽（多头龙族·龙族）的场合，对方怪兽的攻击宣言时才能发动。
【效果】受到那次攻击的自己怪兽由自己重新选。自己场上有同名的表侧表示怪兽2只以上的场合，可以再选对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP000', '五神龙', '怪兽（龙族）×5
这张卡不用融合术召唤不能特殊召唤。
【条件】无
【永续效果】这张卡不会被和怪兽（暗属性·地属性·水属性·炎属性·风属性）的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP001', '岩石战车 砂石战车', '以出色的平衡来向前进行的古老战车。用一点突破来使敌阵的平衡崩溃。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP002', '巨金青铜龙', '发放出厚重光辉的巨龙。那鳞片据说会实现获得者的愿望。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP003', '混合驱动鳞甲蜥', '【条件】自己墓地有怪兽（光属性/龙族）和怪兽（地属性/机械族）的场合才能发动。
【效果】自己卡组最上面的卡送去墓地。并且再在这个回合在怪兽（龙族·机械族）攻击表示上级召唤的场合让表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP004', '混合驱动牙刀龙', '【条件】把1张手卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以选自己墓地1只「混合驱动螺丝起子龙」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP005', '混合驱动蜥蜴', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「混合驱动鳞甲蜥」或者「混合驱动牙刀龙」在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP008', '百合解放杀手', '【条件】这张卡召唤的回合才能发动。
【效果】自己卡组最上面的卡送去墓地。这个效果让怪兽（魔法师族）被送去墓地的场合，再在这个回合在怪兽（暗属性/魔法师族）攻击表示上级召唤的场合让表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP010', '骰子小钥心·小翻', '【条件】把1张手卡送去墓地才能发动。
【效果】从自己卡组上面把6张卡翻开，给双方确认。自己可以从那之中选1只「骰子小钥心·小缎带」或者持有掷骰子效果的怪兽（光属性）加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP011', '骰子小钥心·小呼', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「骰子小钥心·小睡」加入手卡。那之后，掷1次骰子。6出现的场合，可以选对方场上1只表侧守备表示怪兽回到持有者卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP012', '骰子小钥心·小缎带', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地1只「骰子小钥心·小翻」或者持有掷骰子效果的怪兽（光属性）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP013', '电子界香料忍炖锅', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只怪兽（7星以上/炎属性/电子界族）或者1张「香料忍布交织混合」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP014', '电子界香料忍·肉桂', '【条件】无
【效果】对方把自身卡组最上面的卡翻开，给双方确认。那张卡是怪兽（5星以上）的场合，再让自己可以把手卡1只怪兽在自己场上表侧表示特殊召唤。对方让翻开的卡回到原状。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP016', '电子界香料忍·孜然', '【条件】无
【效果】对方把自身卡组最上面的卡翻开，给双方确认。那张卡是怪兽的场合，给与对方为［那个等级］×100伤害。对方让翻开的卡回到原状。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP017', '小麦布料得墨忒耳', '【条件】自己没有从墓地把怪兽特殊召唤的回合才能发动。
【效果】对方从自身卡组上面把2张卡翻开，给双方确认。自己可以选持有［那之中的怪兽的等级合计］以下的等级的自己墓地1只怪兽在自己场上表侧表示特殊召唤。对方让翻开的卡用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP019', '电子界香料忍·葛拉姆马萨拉', '【条件】对方场上有表侧表示怪兽的场合才能发动。
【效果】对方从自身卡组上面把3张卡翻开，给双方确认。自己选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降［翻开的卡之中的怪兽的等级合计］×300。对方让翻开的卡用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP020', '暗物质死局声援天使', '【条件】这张卡召唤的回合才能发动。
【效果】选自己场上1只怪兽送去墓地。那之后，可以选自己墓地1只怪兽（5星/银河族/守备力1300）在自己场上表侧攻击表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP021', '暗物质岩偶', '【条件】把手卡1只怪兽（暗属性/银河族/守备力1300）送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「暗物质秘雾法师」。那之后，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP022', '暗物质水母', '【条件】自己场上有这张卡以外的表侧表示怪兽（暗属性/银河族）的场合，把自己场上1只里侧表示怪兽送去墓地才能发动。
【效果】这个回合，对方在战斗阶段中不能把陷阱卡发动。并且，再把这张卡变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP023', '暗物质土偶', '【条件】支付500基本分才能发动。
【效果】这张卡的卡名在这个回合变成「暗物质秘雾法师」。那之后，可以选自己墓地1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP024', '暗物质线团', '【条件】把手卡1只怪兽（5星以下/暗属性/银河族/守备力1300）给对方观看才能发动。
【效果】这个效果的条件给人观看的怪兽在自己场上表侧攻击表示或者里侧守备表示特殊召唤。那之后，这张卡的攻击力直到下次的对方回合结束时上升700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP025', '暗物质骑士', '【条件】无
【永续效果】这张卡的攻击力上升［自己场上的表侧表示的融合术怪兽数量和自己场上的里侧表示怪兽数量的合计］×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP026', '暗物质危害人偶', '【条件】这张卡召唤·特殊召唤的自己主要阶段，从卡组上面把3张卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「暗物质秘雾法师」。那之后，可以选自己墓地1只「暗物质土偶」或者「暗物质岩偶」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP027', '暗物质加油芙蕾雅', '【条件】把这张卡的表示形式变更才能发动。
【效果】选自己场上1只表侧表示怪兽（暗属性/银河族）。这个回合，那只怪兽的攻击带有贯通。并且，可以再选自己或者对方场上1只表侧表示怪兽变成表侧守备表示或者里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP028', '岩石魔神 瓦砾王', '【条件】自己场上的表侧表示的通常怪兽（岩石族）是2只的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升1400。自己场上的等级不同的表侧表示怪兽（5～7星）是3只的场合，可以再把对方场上的表侧表示怪兽（7星以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP030', '双刃幻龙', '【条件】自己墓地的怪兽只有多头龙族·龙族的场合，把这张卡的表示形式变更才能发动。
【效果】选自己场上1只表侧表示怪兽（7星/暗属性/龙族/攻击力2500）。这个回合，那只怪兽的攻击力上升500，可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP031', '贤帝近卫兵', '【条件】自己卡组的卡是10张以上的场合，让自己墓地4只怪兽（攻击力1200以外/守备力1000）回到卡组才能发动。
【效果】自己抽1张。那之后，这张卡的等级直到回合结束时上升2星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP032', '上级形躯', '【条件】把自己场上最多2张卡送去墓地才能发动。
【效果】对方墓地的怪兽选［这个效果的条件送去墓地的卡数量］回到卡组。那之后，可以选自己墓地1张「上级冲击」或者「帝之领域」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP033', '地帝 格兰玛格', '【条件】这张卡攻击表示上级召唤的回合才能发动。
【效果】选自己或者对方场上1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP034', '水镜蛇', '【条件】自己墓地的怪兽只有多头龙族·龙族的场合，让融合术怪兽以外的自己墓地2只怪兽回到卡组才能发动。
【效果】自己的手卡·场上的怪兽（7星/水属性·地属性/龙族）1只和怪兽（龙族）2只以上送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP035', '龙类拆除员', '【条件】这张卡召唤的回合，把自己场上1只表侧表示怪兽（7星以上/龙族）的表示形式变更才能发动。
【效果】选对方的魔法与陷阱区域1张里侧表示的卡确认。那张卡是陷阱卡的场合，再把选的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP036', '融合族翼龙', '【条件】自己墓地的怪兽只有多头龙族·龙族的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的等级直到回合结束时上升4星。那之后，可以选自己墓地1只「水镜蛇」或者1张「龙族融合」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP037', '纯真之魔龙小丑', '【条件】这张卡召唤的回合，自己在这次主要阶段没有抽卡的场合才能发动。
【效果】双方抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP038', '数据吞噬者', '【条件】把手卡1只怪兽（地属性）和1只怪兽（地属性以外）给对方观看才能发动。
【效果】选对方墓地2张卡回到卡组。那之后，可以选自己场上1只表侧表示怪兽那个攻击力直到回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP039', '解压除冻骑兵改', '【条件】这张卡召唤的回合才能发动。
【效果】给与对方200伤害。自己墓地有怪兽（3星/炎属性/电子界族）或者装备魔法卡的场合，可以再选对方场上1只表侧表示怪兽那个攻击力·守备力直到回合结束时下降600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP040', '加骷髅', '【条件】把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】选自己场上1只原本的攻击力·守备力是0的表侧表示怪兽（暗属性/恶魔族）。这个回合，那只怪兽的攻击力上升1000，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP041', '倍骷髅', '【条件】无
【永续效果】效果怪兽（暗属性/恶魔族/攻击力0/守备力0）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP042', '七宝神-米大', '自己墓地有怪兽（守备力2700）或者「七宝船」的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选对方场上1只表侧表示怪兽那个攻击力·守备力直到下次的对方回合结束时下降700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP043', '神魔兽 加泽特', '这张卡可以把3只效果怪兽解放攻击表示上级召唤。
【条件】无
【永续效果】这张卡的攻击力上升［这张卡攻击表示上级召唤时解放的效果怪兽的原本攻击力合计］。把3只怪兽解放作召唤的这张卡的攻击力上升800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP045', '七星道终极咒魔女', '「七道魔女」＋融合术怪兽（魔导骑士族·魔法师族）
【条件】无
【效果】选对方墓地1张魔法卡回到卡组。那之后，可以选自己墓地1张魔法卡加入手卡。加入的场合，这个效果的发动后，直到回合结束时自己只能有1张通常魔法卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP047', '电子界香料忍·咖梨面包布匹潘多拉', '「电子界香料忍·葛拉姆马萨拉」＋「小麦布料得墨忒耳」
【条件】无
【效果】对方从自身卡组上面把4张卡翻开，给双方确认。那之中有魔法·陷阱卡的场合，可以把对方场上的魔法·陷阱卡全部破坏。对方让翻开的卡用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP049', '暗物质谜团骑士·胜威', '「暗物质骑士」＋「暗物质秘雾法师」
【条件】无
【永续效果】这张卡不会被对方的效果破坏。对方场上的全部表侧表示怪兽（7～9星）的攻击力下降［自己场上的里侧表示怪兽数量］×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP051', '三合族铜镜龙', '怪兽（7星/地属性/龙族）＋怪兽（龙族）×2
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽。这个回合，那只怪兽不会被效果破坏，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP053', '混合驱动重构', '【条件】让自己墓地2只怪兽（光属性/龙族）用喜欢的顺序回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（地属性/机械族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP054', '碧牙重连', '【条件】无
【效果】选自己墓地2只怪兽（光属性/龙族）回到卡组。那之后，可以选自己墓地1只「碧牙爆速龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP055', '香料忍布交织混合', '【条件】无
【效果】自己的手卡·场上的怪兽（炎属性/电子界族）作为素材送去墓地作融合术召唤。那之后，可以选对方墓地1张卡回到卡组上面或下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP056', '暗物质风暴', '【条件】把自己场上2只里侧表示怪兽送去墓地才能发动。
【效果】对方场上的魔法·陷阱卡全部破坏。这个回合，自己不用效果怪兽（暗属性/银河族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP057', '暗物质之力', '【条件】无
【效果】选自己场上1只表侧表示的「暗物质谜团机偶」或者「暗物质谜团骑士·胜威」，那个攻击力直到回合结束时上升［对方场上的原本攻击力最高的表侧表示怪兽的原本攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP058', '宇宙姬的嬉戏', '【条件】把包含2只怪兽的3张手卡送去墓地才能发动。
【效果】选对方场上最多2张卡破坏。那之后，对方场上有卡2张以上的场合，自己可以抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP059', '混合驱动缓冲罩', '【条件】对方怪兽的攻击宣言时，让自己墓地的怪兽（龙族·机械族）合计4只回到卡组才能发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降1600。这个效果的条件回去的怪兽的种族是2种类的场合，可以再选对方场上1只表侧表示怪兽（9星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP060', '香料忍布秘密食谱', '【条件】对方把怪兽召唤·特殊召唤时，让自己墓地2只怪兽（电子界族）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽（9星以下）变成里侧守备表示。那之后，可以选对方墓地1张卡回到卡组上面或下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP061', '香料忍布黑胡椒', '【条件】自己墓地有卡名不同的怪兽（炎属性/电子界族）3只以上的场合，对方卡组的卡被送去墓地时才能发动。
【效果】自己选包含2只怪兽（4星以下）的对方墓地5张卡。对方让那些卡用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP062', '暗物质暗杀', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】选自己或者对方场上1张里侧表示的卡，给双方确认。那张卡是怪兽卡（守备力1300）的场合，可以再选对方场上1只表侧表示怪兽（8星以下）或者1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP063', '即兴果酱音跃：P抓取！', '【条件】对方怪兽的攻击宣言时，让自己墓地2～4只怪兽（念动力族）回到卡组才能发动。
【效果】攻击的怪兽变成表侧守备表示。自己墓地有通常怪兽（念动力族）的场合，再让自己可以直到手卡变成6张为止抽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP065', '神疑之光来', '【条件】对方场上的怪兽被送去墓地时才能发动。
【效果】自己抽2张。那之后，可以把对方手卡随机选1张送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP17-JP066', '梦中的引诱', '【条件】对方把怪兽召唤·特殊召唤时，让自己场上1只怪兽和1张手卡用喜欢的顺序回到持有者卡组下面才能发动。
【效果】选极大怪兽以外的对方场上1只表侧表示怪兽（8星以下）得到那个控制权。这个效果得到控制权的怪兽只要在场上处于表侧表示，不能攻击并不能把效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP002', '超可爱执行者·夜魔女', '自己场上有表侧表示怪兽（6星/守备力500）的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【永续效果】自己不能用怪兽（7星以上）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP003', '风帝 莱扎', '【条件】这张卡攻击表示上级召唤的回合才能发动。
【效果】选自己或者对方场上1张卡回到持有者卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP004', '天帝龙树 世界树龙［L］', '【条件】极大模式：从卡组上面把3张卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP005', '天帝龙树 世界树龙', '可以和「天帝龙树 世界树龙［L］」「天帝龙树 世界树龙［R］」集齐作极大召唤。
【条件】极大模式
【永续效果】这张卡不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP006', '天帝龙树 世界树龙［R］', '【条件】极大模式：从卡组上面把3张卡送去墓地才能发动。
【效果】选对方场上1只守备表示怪兽变成表侧攻击表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP008', '二重宇宙世界树龙', '「宇宙世界树龙」＋「宇宙世界树龙」
【条件】无
【效果】自己墓地的怪兽选［对方场上的怪兽数量］回到卡组。这个回合，这张卡可以向怪兽作出最多有［这个效果回去的怪兽数量］的攻击。这个效果让怪兽3只回去的场合，再在这个回合让这张卡的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP009', '宇宙世界树龙', '【条件】把自己场上1张卡送去墓地才能发动。
【效果】手卡1只怪兽（电子界族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP010', '多元宇宙世界树龙', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「宇宙世界树龙」。那之后，可以选自己墓地1只怪兽（8星以外/电子界族/守备力0）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP011', '皮米孔雀高等粒子机', '【条件】自己墓地有「飞米粒子机」，自己场上没有这张卡以外的怪兽的场合才能发动。
【效果】自己场上的这张卡送去墓地，自己抽2张。那之后，从自己卡组上面把2张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP012', '混沌飞米粒子机', '【条件】自己墓地的怪兽只有电子界族的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以从那之中选1只怪兽（电子界族/守备力0）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP013', '飞米粒子机', '隐藏着万物摄理的龙树之源。朝着极微极大逼近，引导世界通往新领域。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP014', '电子界守护者', '【条件】把自己场上1只怪兽送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（电子界族）。这个回合，那只怪兽的攻击力上升300，不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP015', '宇宙利用芽', '【条件】自己场上有表侧表示怪兽（7星以上/电子界族）的场合，把卡组最上面的卡送去墓地才能发动。
【效果】给与对方500伤害。那之后，可以选自己墓地1张「深空警告融合」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP016', '宇宙驱动种', '【条件】自己场上有表侧表示怪兽（7星以上），自己墓地的怪兽只有电子界族的场合才能发动。
【效果】选自己墓地1只怪兽（2星以上/光属性·暗属性/守备力0）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP017', '奇怪吸引子', '【条件】把手卡1只怪兽（电子界族）送去墓地或让自己墓地5只等级不同的怪兽（电子界族）回到卡组才能发动。
【效果】自己抽2张。这个效果的发动后，直到回合结束时自己不能把怪兽（电子界族以外）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP018', '宇宙呼唤', '【条件】把手卡1只怪兽（电子界族）给对方观看才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以从那之中选1只怪兽（7星以上/电子界族）在自己场上表侧表示特殊召唤。这个效果选「宇宙世界树龙」的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP019', '宇宙共振', '【条件】自己墓地有怪兽（7星以上/光属性·暗属性/电子界族）的场合才能发动。
【效果】手卡1只怪兽（电子界族）在自己场上表侧表示特殊召唤。这个效果把怪兽（7星）特殊召唤的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP020', '深空警告融合', '【条件】无
【效果】只把自己手卡的怪兽或者只把自己场上的表侧表示怪兽作为素材送去墓地，把怪兽（光属性·暗属性/电子界族）融合术召唤。这个效果把原本卡名是「宇宙世界树龙」的怪兽送去墓地的场合，可以再选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP021', '不合理的虚孔', '【条件】由自己的攻击表示怪兽（电子界族）承受攻击的对方怪兽的攻击宣言时才能发动。
【效果】这个回合，对方不能攻击宣言，自己怪兽不会被战斗破坏。自己可以回复［受到攻击的怪兽和攻击的怪兽的攻击力差］×2的基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP022', '临界服务', '【条件】自己怪兽被对方的攻击破坏时才能发动。
【效果】选自己墓地1只怪兽（电子界族）在自己场上表侧表示特殊召唤。那之后，自己可以选手卡1只怪兽（7·8星）送去墓地。那之后，给与对方为［这个效果送去墓地的怪兽的等级］×200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP023', '深空宇宙冲击', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】选自己墓地的怪兽（电子界族）、「融合术」、「深空警告融合」合计3～6张用喜欢的顺序回到卡组上面。自己场上有表侧表示的融合术怪兽的场合，可以再选对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP027', '磁力要塞壶', '这张卡可以把3只怪兽（岩石族）解放攻击表示上级召唤。
【条件】上记的方法把这张卡召唤的回合才能发动。
【效果】选对方场上1张卡破坏。那之后，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP029', '磁石战士α', '用α、β、γ来变形合体。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP030', '磁石战士β', '用α、β、γ来变形合体。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP031', '磁石战士γ', '用α、β、γ来变形合体。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP039', '全爱之女神', '自己场上有原本攻击力是0的表侧表示怪兽的场合，这张卡可以不用解放作召唤。
【条件】无
【永续效果】这张卡的攻击力上升［自己场上的原本攻击力是0的表侧表示怪兽数量］×1000。自己怪兽（攻击力0）的战斗不会让自己受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP040', '和平爱之天女', '这张卡可以把1只怪兽（攻击力0）解放攻击表示上级召唤。
【条件】让自己墓地1只怪兽（攻击力0）回到卡组才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升2500。那之后，可以选自己墓地1张「爱之射箭」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP041', '爱之天女', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升1000。自己墓地有怪兽，那个攻击力合计是0的场合，可以再让对方场上的全部表侧表示怪兽的攻击力·守备力直到回合结束时下降1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP042', '可爱之天童', '【条件】把1张手卡送去墓地才能发动。
【效果】选自己场上最多3只原本攻击力是0的表侧表示怪兽，那些攻击力直到回合结束时上升600。自己墓地有怪兽，那个攻击力合计是0的场合，可以再选对方场上1张魔法·陷阱卡回到持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP043', '爱之天童', '【条件】自己卡组的卡是10张以上的场合，让自己墓地3只怪兽（4星以外/攻击力0）回到卡组才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP044', '纯爱之天使', '【条件】无
【永续效果】这张卡不会被和怪兽（攻击力2500以上）的战斗破坏。这张卡和怪兽（9星以下）进行战斗的场合，自己不会受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP045', '爱之天使', '【条件】无
【永续效果】这张卡不会被和怪兽（7·8星）的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP046', '爱之狼', '【条件】这张卡召唤的回合，把手卡1只怪兽（天使族/攻击力0）给对方观看才能发动。
【效果】选1只自己场上的表侧表示怪兽或者对方场上的怪兽把表示形式变更。那之后，可以选自己墓地1张「爱之保护」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP047', '爱之鸽', '【条件】这张卡召唤的回合，把手卡1只怪兽（天使族/攻击力0）给对方观看才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以选自己墓地1只「爱之天使」或者1张「爱之安全」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP048', '爱之射箭', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只原本攻击力是0的表侧表示怪兽（天使族）。这个回合，那只怪兽的攻击力上升100，可以直接攻击。这个回合，自己只能用1只怪兽直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP049', '爱之学习', '【条件】自己墓地有怪兽6只以上，那个攻击力合计是0的场合才能发动。
【效果】选对方场上1张卡回到持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP050', '爱之书信', '【条件】自己墓地有怪兽3只以上，那个攻击力合计是0的场合才能发动。
【效果】选自己墓地1只怪兽（天使族/攻击力0）加入手卡。那之后，可以选自己墓地1张「爱之回忆」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP051', '爱之安全', '【条件】可以给自己场上1只原本的攻击力·守备力是0的表侧表示怪兽（天使族）装备。
【效果】装备怪兽和自己的魔法与陷阱区域的里侧表示的卡不会被对方的效果破坏。只要装备怪兽在自己场上处于表侧表示，对方不能向没有装备魔法卡装备的怪兽攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP052', '爱之保护', '【条件】自己场上有原本攻击力是0的表侧表示怪兽（天使族）的场合，对方把怪兽召唤·特殊召唤时才能发动。
【效果】选对方场上1只怪兽把表示形式变更。这个回合，对方不能把这个效果选的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP053', '爱之百万', '【条件】由原本攻击力是0的自己的表侧表示怪兽（天使族）承受攻击的对方怪兽的攻击宣言时才能发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降100万。自己场上有表侧表示怪兽（守备力0）的场合，再让受到攻击的怪兽的攻击力直到回合结束时上升100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP054', '爱之回忆', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时才能发动。
【效果】选自己墓地1只怪兽（天使族/攻击力0）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP055', '爱之回复', '【条件】自己场上有原本的攻击力·守备力是0的表侧表示怪兽（天使族）的场合，自己在抽卡阶段通常抽卡时才能发动。
【效果】双方场上的表侧表示怪兽之内原本攻击力最高的怪兽全部回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP056', '穿越侍·线性海牛侍', '沃·图·征！马尼亚克·尤·歹！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP059', '接合科技霸王龙', '【条件】这张卡召唤的回合，让自己墓地3只怪兽回到卡组才能发动。
【效果】选对方的魔法与陷阱区域1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP060', '碧牙爆速龙', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】对方场上的表侧表示怪兽（攻击力1500以下）全部破坏。那之后，这张卡的攻击力直到回合结束时上升［这个效果破坏的怪兽数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP061', '光波技术龙', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】选对方场上最多3只表侧表示怪兽，那些攻击力在这次主要阶段内下降1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP062', '七星道魅力魔女', '「七道魔女」＋怪兽（1星/地属性/魔法师族）
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只怪兽把表示形式变更。并且再在这个回合让这张卡的攻击带有贯通。自己墓地有「七道魔导士」的场合，再在这个回合让这张卡不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP063', '超级谱气斗士·汽枪兵', '「色谱气斗士」＋「超级助手·冰娅」
【条件】对方场上有表侧表示的卡的场合，把1张手卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，对方让自身场上的表侧表示的卡尽可能选最多有［这个效果送去墓地的怪兽（炎属性）的种族种类数量］回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP064', '美食之神童 迪安·凯特', '【条件】自己或者对方场上有魔法·陷阱卡的场合，把1张手卡送去墓地才能发动。
【效果】自己回复1000基本分。那之后，可以让这张卡的攻击力直到回合结束时上升［双方场上的表侧表示的魔法卡数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP065', '洁净之神童 迪安·凯特', '【条件】自己基本分比对方少的场合，把1张手卡送去墓地才能发动。
【效果】自己回复1000基本分。那之后，这张卡的攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP066', 'THE☆齿车戒龙', '7颗超新星释放伽马射线暴的龙。其名就叫THE☆齿车戒龙！THE☆齿车戒龙！！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP067', '骰子炸药少女·小双骰', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】掷2次骰子。出现数目合计的效果适用。
●7·11：选对方场上1张卡回到持有者卡组下面。
●2·3·12：选自己场上1只怪兽把表示形式变更。
●那以外：这张卡的攻击力直到下次的对方回合结束时上升［出现的数目合计］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP068', '骰子小钥心·小睡', '【条件】自己场上有持有掷骰子效果的表侧表示怪兽的场合才能发动。
【效果】选对方场上1只怪兽把表示形式变更（攻击表示变成表侧守备表示，守备表示变成表侧攻击表示）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP069', '超魔机人 燃霸道王', '自己场上有表侧表示的极大怪兽（机械族）的场合，这张卡可以不用解放作召唤。
【条件】自己墓地有极大怪兽（暗属性/机械族）3只以上的场合，支付500基本分才能发动。
【效果】直到下次的对方回合结束时，这张卡的攻击力上升1200，不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP070', '冲击彗星', '【条件】自己卡组的卡是10张以上的场合，把手卡1只怪兽（岩石族）送去墓地才能发动。
【效果】自己抽1张。自己场上的表侧表示怪兽（岩石族）是3只的场合，可以再选自己墓地1只怪兽（6～8星/岩石族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP071', '冠狙乐姬 长号弩手', '【条件】从卡组上面把2张卡送去墓地，把手卡1只怪兽（风属性/战士族）送去墓地才能发动。
【效果】自己抽1张。自己墓地有通常怪兽的场合，可以再选自己或者对方场上1只怪兽把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP072', '宿灵椅·代码式', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地的极大怪兽（电子界族）或者怪兽（暗属性/恶魔族/攻击力0/守备力2400以上）合计最多2只加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP073', '帝王的贡祭', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示的效果怪兽（3～8星），那个等级直到回合结束时下降2星。那之后，可以选自己墓地1只怪兽（8星/攻击力2400/守备力1000）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP075', '东方雕像', '【条件】无
【效果】给与对方为［对方墓地的魔法卡数量］×100伤害。这个效果给与1000以上的伤害的场合，可以再选自己墓地的「东方虎」「妖虎东洋击」合计最多2张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP076', '天使的玉米', '【条件】自己场上有表侧表示怪兽（水族），自己墓地有怪兽（水族）的场合才能发动。
【效果】自己抽2张。那之后，自己选1张手卡回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP077', '超越超速风暴', '【条件】让自己墓地2只怪兽用喜欢的顺序回到卡组下面才能发动。
【效果】选对方场上1张魔法·陷阱卡回到持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP078', '龙族融合', '【条件】自己场上有表侧表示怪兽（7星以上/龙族）的场合才能发动。
【效果】自己场上的表侧表示的通常怪兽（龙族）1只和自己墓地的怪兽（龙族）1只以上作为素材回到持有者卡组作融合术召唤。这个回合，自己不用融合术怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP079', '星辉心灰', '【条件】对方回合对方把怪兽召唤·特殊召唤时，把1张手卡送去墓地才能发动。
【效果】选自己或者对方场上的表侧表示的效果怪兽合计最多2只变成里侧守备表示。这个效果选对方场上的原本攻击力是2600以上的怪兽的场合，再让自己回复1500基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP080', '迷宫壁', '使场上出现墙壁，创造没有出口的迷宫。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP081', '流星黑龙', '「真红眼黑龙」＋「流星之龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/ORP2-JP082', '暗黑魔龙', '「恶魔的召唤」＋「真红眼黑龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP000', '元素英雄 闪光火焰翼侠', '「元素英雄 火焰翼侠」＋「元素英雄 电光侠」
这张卡不用融合术召唤不能特殊召唤。
【条件】无
【永续效果】这张卡的攻击力上升［自己墓地的怪兽（战士族）数量］×300。这张卡战斗破坏怪兽送去墓地时，给与对方为［那只怪兽的原本攻击力］的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP001', '接触体·暗物质旅行者号', '从暗黑尽头出现的探测卫星。隐藏有超越因果的黑暗力量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP002', '接触体·暗物质欧米伽旅行者号', '自己墓地有「接触体·暗物质旅行者号」的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地最多2只「接触体·暗物质旅行者号」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP003', '接触体·暗物质飞龙', '【条件】把里侧表示怪兽解放来把这张卡召唤的回合才能发动。
【效果】选自己1张手卡送去墓地。那之后，可以选自己墓地1只「暗物质龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP004', '暗物质深潜獾', '自己墓地有怪兽（暗属性/银河族）5只以上的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【永续效果】自己场上有里侧表示怪兽的场合，自己场上的攻击表示怪兽（暗属性/银河族）不会被对方的攻击破坏，那些攻击力上升［自己手卡数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP005', '暗物质秘雾法师', '自己场上有表侧表示的「暗物质龙」的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】支付500基本分才能发动。
【效果】选自己场上1只表侧表示怪兽（暗属性/银河族）。那只怪兽的卡名在这个回合变成「暗物质秘雾法师」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP006', '暗物质龙', '【条件】这张卡召唤·特殊召唤的自己主要阶段，把卡组最上面的卡送去墓地才能发动。
【效果】对方场上的表侧表示怪兽（8星以下）选最多有［自己场上的里侧表示怪兽数量］破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP007', '混合驱动推进宝珠龙', '【条件】自己墓地有怪兽（机械族）的场合，把手卡1只怪兽（7·8星/龙族）给对方观看才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从那之中选持有和［这个效果的条件给人观看的怪兽的等级］相同等级的1只怪兽在自己场上表侧表示特殊召唤。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP008', '混合驱动防护罩尾龙', '自己场上有表侧表示的「混合驱动螺丝起子龙」的场合，这张卡可以不用解放作召唤。
【条件】无
【永续效果】这张卡的攻击带有贯通。自己场上有表侧表示怪兽（龙族）的场合，自己场上的表侧表示怪兽（龙族·机械族）不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP009', '极超助手·冰娅', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地1只通常怪兽（3星以下/炎族）加入手卡。这个效果选「超级助手·阿炽」的场合，可以再选自己墓地1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP010', '虹眼星猫', '【条件】这张卡召唤的回合，自己场上有这张卡以外的表侧表示怪兽（守备力200）的场合才能发动。
【效果】从自己卡组上面把［双方场上的表侧表示怪兽（7星以上）数量］的卡送去墓地。那之中有怪兽的场合，可以再选自己墓地最多2只怪兽（7星/守备力200）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP011', '邪犬武斗神 高天湿婆柴犬', '这张卡可以把1只怪兽解放攻击表示上级召唤。那个场合，这张卡的原本攻击力变成1800。
【条件】自己的场地区域有卡的场合才能发动。
【效果】自己卡组最上面的卡送去墓地。这个回合自己没有把怪兽特殊召唤的场合，可以再选自己墓地1只怪兽（4星以下）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP012', '幻坏兵 派遣楔钉龙', '【条件】对方手卡是1张以下的场合才能发动。
【效果】自己场上的这张卡送去墓地，双方抽2张。这个效果的发动后，直到回合结束时自己不能把怪兽（幻龙族以外）表侧表示召唤·特殊召唤，只能用1只怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP013', '幻坏兵 食堂龙', '【条件】让自己墓地1只怪兽（幻龙族）回到卡组上面或下面才能发动。
【效果】选自己场上1只表侧表示怪兽，那个攻击力直到回合结束时上升100。那之后，可以选自己墓地1只「幻坏兵 安全帽龙」或者通常怪兽（幻龙族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP014', '幻刃兵站 办公桌泰拉斯奎', '【条件】把1张手卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以选自己墓地1张「融合术」或者场地魔法卡加入手卡。这个回合，自己不能用怪兽（幻龙族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP015', '梦幻重骑 建造龙骑士', '这张卡可以把1只极大怪兽解放攻击表示上级召唤。
【条件】自己卡组的卡是10张以上，自己墓地的怪兽只有幻龙族的场合才能发动。
【效果】自己抽1张。那之后，可以把自己的手卡·场上的怪兽（幻龙族）作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP016', '交叉装载员', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只怪兽（7星/战士族/攻击力2500/守备力2000）在自己场上表侧表示特殊召唤。这个回合，自己不能用怪兽（战士族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP017', '新宇宙侠·水波海豚', '【条件】把1张手卡送去墓地才能发动。
【效果】把对方手卡确认。自己可以从那之中选持有［自己场上的攻击力最高的表侧表示怪兽的攻击力］以下的攻击力的1只怪兽送去墓地。这个效果把怪兽送去墓地的场合，再给与对方500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP018', '新宇宙侠·火焰甲虫', '【条件】无
【永续效果】这张卡的攻击力上升［对方场上的魔法·陷阱卡数量］×400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP019', '冒牌新宇侠', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「元素英雄 新宇侠」。这个回合，自己不能用怪兽（战士族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP020', '锐进英雄 钛甲女郎', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只「锐进英雄 银甲侠」或者「锐进英雄 钽甲侠」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP021', '锐进英雄 钽甲侠', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升400。自己场上有表侧表示的融合术怪兽（战士族）的场合，可以再选对方场上1只表侧表示怪兽（8星以下）回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP022', '莓果新人·幸福小莓 收获', '【条件】这张卡召唤·特殊召唤的自己主要阶段，把这张卡以外的自己的手卡·场上最多2张卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升［这个效果的条件送去墓地的卡数量］×1500。自己墓地有怪兽（水族）5只以上的场合，再让这张卡直到下次的对方回合结束时不会被对方的魔法·陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP023', '莓果新人·欢乐小莓', '【条件】把这张卡以外的自己的手卡·场上1张卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升1500。这个效果的条件把原本攻击力是100的怪兽送去墓地的场合，可以再选对方场上1只怪兽变成表侧攻击表示或者里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP024', '莓果新人·聪明小莓', '【条件】把这张卡以外的自己的手卡·场上1张卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升1500。那之后，可以选自己墓地1张「莓果新人果园」或者「一莓之别」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP025', '莓果新人·治疗小莓', '【条件】把这张卡以外的自己的手卡·场上1张卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升1500。那之后，可以选自己墓地1张「莓果新人果园」或者「莓果新人游泳」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP026', '莓果新人·天真小莓', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只「莓果新人·幸福小莓」或者「莓果新人·幸福小莓 收获」加入手卡。这个效果选「莓果新人·幸福小莓 收获」的场合，再把自己场上的这张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP027', '莓果新人·富饶小莓', '【条件】这张卡召唤的回合，自己卡组的卡是10张以上的场合，把这张卡以外的自己的手卡·场上2张卡送去墓地才能发动。
【效果】自己抽1张。这个效果的条件把原本攻击力是100的怪兽（水族）送去墓地的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP028', '莓果新人·羞怯小莓', '【条件】无
【永续效果】自己场上有这张卡以外的原本攻击力是100的表侧表示怪兽（水族）的场合，对方场上的表侧表示怪兽的攻击力·守备力下降1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP029', '叛骨之梅尼', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】选自己场上1只表侧表示的「叛骨之盖加斯特」或者「叛骨之苏芙蕾思」。直到下次的对方回合结束时，那只怪兽的攻击力上升700，不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP030', '叛骨之苏芙蕾思', '【条件】把手卡1只怪兽送去墓地才能发动。
【效果】选对方场上1只怪兽把表示形式变更。自己墓地的怪兽是5只以上的场合，可以再选自己墓地1只「叛骨之盖加斯特」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP031', '叛骨之盖加斯特', '【条件】自己墓地的怪兽是5只以上的场合，把手卡1只怪兽送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。这个回合，自己不能把表侧表示的这张卡为上级召唤而解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP032', '好好黏液灵', '【条件】对方场上有怪兽2只以上的场合，把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽（7星以上），那个攻击力·守备力直到回合结束时下降1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP033', '虚假之日', '【条件】让自己墓地3只怪兽（银河族）回到卡组才能发动。
【效果】选对方场上1只怪兽变成表侧攻击表示或者里侧守备表示。那之后，可以选自己墓地1只「虚假之月」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP034', '虚假之月', '【条件】这张卡召唤的回合，自己墓地有怪兽（银河族/守备力1300）2只以上的场合才能发动。
【效果】选自己墓地1只怪兽（银河族/守备力1300）在自己场上里侧守备表示特殊召唤。那之后，可以把这张卡变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP036', '海牛头人', '【条件】无
【永续效果】自己怪兽（鱼族·海龙族·水族）的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP037', '突发爆裂兔', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己或者对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降600。这个效果选这张卡的场合，再在这个回合让这张卡可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP042', '曼陀林掠夺者·时髦', '「曼陀林掠夺者」＋「提琴游吟诗人」
【条件】无
【永续效果】自己用「融合术」「念力装备融合」的效果把怪兽（8星以上）融合术召唤的场合，也能把自己墓地的怪兽（念动力族）作为素材。那个场合，素材从场上·墓地回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP043', '星猫王牌喵破星', '「猫爪少女」＋「闇眼の破星猫」
【条件】无
【永续效果】这张卡的攻击力上升［对方场上的守备表示怪兽数量］×800，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP044', '电子界香料忍·姜黄女王', '「电子空间香料忍 姜黄」＋「电子界香料忍炖锅」
【条件】无
【效果】对方从自身卡组上面把3张卡翻开，给双方确认。那之中有怪兽2只以上的场合，这个回合，这张卡可以作2次攻击。对方让翻开的卡用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP045', '幻坏帝 爆破坏帝龙王', '「幻坏兵 安全帽龙」＋怪兽（幻龙族）
【条件】把手卡1只怪兽（幻龙族）送去墓地才能发动。
【效果】选对方墓地最多3张卡回到卡组。这个效果的条件把怪兽（8星以上）送去墓地的场合，再让这张卡的攻击力直到回合结束时上升［这个效果回去的卡数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP046', '斧乐姬 调音长笛战斧手', '「斧乐姬 长笛战斧手」＋「挥乐姬 指挥棒棍手」
这张卡可以用接触融合术（自己场上的上记的表侧表示怪兽作为素材回到持有者卡组作融合术召唤）。
【条件】无
【效果】从自己卡组上面把4张卡送去墓地。那之后，可以选自己墓地1只怪兽（7星以上/风属性/战士族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP047', '流星群突入龙', '「流星之龙兽」＋怪兽（6星以上/地属性·暗属性）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP048', '超可爱执行者·光天女 开拓', '「超可爱执行者·光天女」＋「超可爱执行者·夜魔女」
这张卡可以用接触融合术（自己场上的上记的表侧表示怪兽作为素材回到持有者卡组作融合术召唤）。
【条件】这张卡融合术召唤的自己主要阶段才能发动。
【效果】选对方场上1只表侧表示怪兽回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP049', '天堂始终之面妖姬', '「天始之怪依」＋「天终之怪依」
这张卡可以用接触融合术（自己场上的上记的表侧表示怪兽作为素材回到持有者卡组作融合术召唤）。
【条件】无
【永续效果】这张卡可以直接攻击。这张卡的战斗不会让自己受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP050', '电子邓氏鱼', '「电子鲨」＋「电子鲨」
【条件】无
【永续效果】自己回合内，对方场上的表侧表示怪兽的攻击力·守备力下降600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP051', '双海潮流', '【条件】把手卡1只怪兽（7星以上/鱼族·海龙族）给对方观看并回到卡组才能发动。
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP052', '念力装备返始', '【条件】无
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1张「融合术」或者「念力装备融合」回到卡组上面或下面。回去的场合，可以再从自己墓地的怪兽（风属性/念动力族）、「融合术」、「念力装备融合」之中选1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP053', '幻坏融门 废铁之门', '【条件】这张卡把自己场上1只表侧表示怪兽（7星以上/幻龙族）送去墓地才能发动。
【效果】只要这张卡在场地区域处于表侧表示，双方在「融合术」的效果融合术召唤的场合，也能只让自身墓地的怪兽（幻龙族）回到卡组作为素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP054', '幻之三角比例尺', '【条件】把手卡1只怪兽（幻龙族）送去墓地才能发动。
【效果】自己抽2张。这个效果的发动后，直到回合结束时自己不能把怪兽（幻龙族以外）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP055', '幻刃攻厂 鳞虫工厂', '【条件】无
【效果】只要这张卡在场地区域处于表侧表示，双方场上的表侧表示的「幻刃龙 建造龙」和怪兽（10星/幻龙族）的攻击力上升600，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP056', '英雄降落', '【条件】无
【效果】等级合计最多到7星以下为止，从自己墓地的「新宇宙侠·水波海豚」、「新宇宙侠·火焰甲虫」、通常怪兽（战士族）之中选合计最多2只在自己场上表侧守备表示特殊召唤。这个回合，自己不能用怪兽（战士族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP057', '莓果新人果园', '【条件】无
【效果】只要这张卡在场地区域处于表侧表示，回合玩家的场上的原本守备力是500的表侧表示怪兽（水族）的攻击力上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP058', '一莓一会', '【条件】无
【效果】选自己或者对方场上1只表侧表示怪兽（攻击力1500以下）破坏。那之后，可以选自己墓地1只怪兽（水族/攻击力100）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP059', '鱼弹发射器', '【条件】把自己场上1只表侧表示怪兽（鱼族）送去墓地才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP060', '绊脚岩', '【条件】对方把怪兽召唤时，对方场上有怪兽2只以上的场合才能发动。
【效果】选对方场上最多3只攻击表示怪兽变成表侧守备表示。这个回合，选的怪兽是表侧表示的期间，对方不能把选的怪兽为上级召唤而解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP061', '燃烧之风', '【条件】由自己怪兽承受攻击的对方怪兽（5星以上）的攻击宣言时才能发动。
【效果】选自己场上1只表侧表示怪兽（战士族），那个攻击力直到回合结束时上升1000。那之后，可以让受到那次攻击的自己怪兽由自己重新选。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP062', '一莓之别', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时，自己墓地有怪兽（水族/攻击力100）5只以上的场合才能发动。
【效果】选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP063', '莓果新人游泳', '【条件】自己场上有原本攻击力是100的表侧表示怪兽（水族）的场合，对方把怪兽（攻击力1500以下）表侧表示召唤·特殊召唤时才能发动。
【效果】双方场上的原本守备力是500以外的表侧表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP18-JP064', '被谋划的两败俱伤', '【条件】由自己的攻击表示怪兽承受攻击的对方怪兽的攻击宣言时才能发动。
【效果】受到攻击的怪兽和攻击的怪兽回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP004', '鹰身女郎1', '墓地的这张卡的卡名变成「鹰身女郎」。
【条件】无
【永续效果】这张卡的卡名变成「鹰身女郎」，双方场上的表侧表示怪兽（风属性）的攻击力上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP005', '鹰身女郎2', '墓地的这张卡的卡名变成「鹰身女郎」。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】直到下次的对方回合结束时，这张卡的卡名变成「鹰身女郎」，这张卡的攻击宣言时对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP006', '鹰身女郎3', '墓地的这张卡的卡名变成「鹰身女郎」。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名直到下次的对方回合结束时变成「鹰身女郎」。那之后，可以选对方场上1只表侧表示怪兽（8星以下）。选的场合，下次的对方回合，对方不能用那只怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP007', '鹰身女郎', '人形长着翅膀的猛兽。既优美而华丽地飞舞，又猛锐地展开攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP010', '鹰身女妖的宠物龙', '【条件】无
【永续效果】这张卡的攻击力上升［双方场上的表侧表示的「鹰身女郎」数量］×300，上升［双方场上的表侧表示的「鹰身三姐妹」数量］×900。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP011', '戏法鸽', '【条件】把手卡1张魔法·陷阱卡送去墓地才能发动。
【效果】选自己墓地1只怪兽（鸟兽族/攻击力1500以上）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP013', '三角神迷火花', '【条件】自己场上有表侧表示的「鹰身三姐妹」的场合才能发动。
【效果】选自己场上最多3只表侧表示怪兽（风属性），那些攻击力直到回合结束时上升600。这个回合，对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP014', '万华镜-华丽的分身-', '【条件】自己场上有表侧表示的「鹰身女郎」或者「鹰身三姐妹」的场合才能发动。
【效果】选自己墓地的「鹰身女郎」「鹰身三姐妹」合计最多2只在自己场上表侧表示特殊召唤。这个回合，自己不能向攻击表示怪兽（攻击力1200以下）攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP015', '鸟咒战术', '【条件】自己场上有表侧表示怪兽（战士族·鸟兽族）合计2只以上的场合才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，可以选自己墓地1只怪兽（8星以下/战士族·鸟兽族）回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP017', '咕蛊鸽心碎瞪', '【条件】自己场上有表侧表示怪兽（鸟兽族）的场合，对方把怪兽（5星以上）表侧表示召唤·特殊召唤时才能发动。
【效果】选对方场上1只攻击表示怪兽变成表侧守备表示。那之后，给与对方500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP018', '环幻乐鬼神 小号大管枪贯神息虎吸人', '「神乐鬼 大管神指人」＋「挥乐姬 指挥棒棍手」
【条件】把最多3张手卡送去墓地才能发动。
【效果】这个回合，这张卡不会被对方的陷阱卡的效果破坏，那攻击带有贯通。这张卡特殊召唤的自己主要阶段把这个效果发动的场合，可以再让这张卡的攻击力直到回合结束时上升［这个效果的条件送去墓地的怪兽数量］×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP019', '环幻乐鬼 全编制管弦乐团舞斗家', '「重乐鬼 合奏武斗家」＋「挥乐姬 指挥棒棍手」
【条件】把1张手卡送去墓地才能发动。
【效果】对方的魔法与陷阱区域的里侧表示的卡全部破坏。那之后，这张卡的攻击力直到回合结束时上升［这个效果破坏的卡数量］×600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP020', '环幻乐姬 旋律动作斧手', '「振乐姬 大号月刃斧手」＋「挥乐姬 指挥棒棍手」
【条件】让自己墓地1张魔法卡回到卡组上面或下面才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力·守备力直到下次的对方回合结束时下降2000。这个效果的条件让「一気貫通」或者「融合术」回去的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP021', '神乐鬼 大管神指人', '【条件】对方场上有守备表示怪兽的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［对方场上的守备表示怪兽数量］×800。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP022', '兽乐鬼 小号宠物虎', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升300。那之后，可以把手卡1只怪兽（8星以下/风属性/战士族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP023', '重乐鬼 合奏武斗家', '【条件】把1张手卡送去墓地才能发动。
【效果】这个回合，这张卡是表侧表示的期间，自己怪兽（风属性/战士族）的攻击宣言时对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP024', '连乐鬼 低音大管三节棍手', '【条件】自己卡组的卡是10张以上，自己场上没有这张卡以外的怪兽的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。对方场上有表侧表示怪兽（攻击力3000以上）的场合，再让自己可以抽3张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP025', '振乐姬 大号月刃斧手', '【条件】这张卡召唤的回合，自己场上有这张卡以外的表侧表示怪兽（战士族）的场合才能发动。
【效果】选自己墓地的怪兽（7星以上/风属性）和通常怪兽（战士族）各1只加入手卡。这个回合，自己不能把怪兽（风属性/战士族·兽族）以外的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP026', '弧乐姬 圆号鸳鸯钺手', '【条件】这张卡召唤的回合才能发动。
【效果】自己卡组最上面的卡送去墓地。这个效果让怪兽（战士族）被送去墓地的场合，可以再选自己墓地1只通常怪兽（战士族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP027', '断乐姬 奥菲克莱德阔剑手', '合奏武队的最老成员。用强而有力的声响来鼓舞同伴。对后辈大号月刃斧手的成长感到可靠放心。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP028', '斧乐姬 长笛战斧手', '合奏武队的冲锋陷阵队长。发出的斧声有着华丽的音色。虽然疑似隐藏暗器，但其实是单纯怕冷。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP029', '拳乐姬 萨克斯拳环手', '合奏武队的气氛营造者。强有力的音色使其能够单独战斗。左手的武器只靠一个人戴不上去。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP030', '警乐姬 单簧管棍棒手', '合奏武队的多面手。温柔的旋律为攻击增添厚重感。兴奋起来就头顶发光。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP031', '挥乐姬 指挥棒棍手', '合奏武队的统一者。用轻快的挥棒技巧来指挥个性丰富的同伴。只要眼镜受人指摘就会闹别扭。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP032', '一气贯通', '【条件】让自己墓地5只怪兽（风属性/战士族）回到卡组才能发动。
【效果】选自己场上1只表侧表示怪兽（7·8星）。这个回合，那只怪兽的攻击力上升2000，那攻击带有贯通（向守备表示怪兽攻击时，给与攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP033', '乐姬的演舞', '【条件】自己墓地有怪兽（风属性/战士族）5只以上的场合才能发动。
【效果】自己的手卡·墓地的怪兽作为素材回到卡组，把怪兽（风属性/战士族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP034', '乐姬的葬奏曲', '【条件】由自己的攻击表示怪兽（7星以上/风属性/战士族·兽族）承受攻击的对方怪兽的攻击宣言时才能发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降［攻击的怪兽的等级］×600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP035', '虎死眈眈', '【条件】自己场上有表侧表示怪兽（7星以上/风属性/战士族·兽族）的场合，对方怪兽的攻击宣言时才能发动。
【效果】攻击的怪兽变成表侧守备表示。自己基本分是对方基本分以下的场合，可以再选对方场上1只攻击表示怪兽破坏。那之后，给与对方为［这个效果破坏的怪兽的原本攻击力］的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP036', '三千破界', '【条件】对方怪兽的攻击宣言时，支付3000基本分才能发动。
【效果】攻击的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP037', '大激虎', '【条件】对方怪兽的攻击宣言时，让自己场上1只表侧表示怪兽（7星以上/风属性）回到持有者手卡才能发动。
【效果】攻击的怪兽变成表侧守备表示。那之后，给与对方1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP038', '幻坏爆龙 危险爆破龙王', '「幻坏龙 爆破龙王」＋「幻坏兵 安全帽龙」
【条件】无
【效果】选自己场上1张表侧表示的卡和对方场上1～2只怪兽。选的卡破坏。那之后，给与对方为［这个效果破坏的对方场上的怪兽数量］×500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP039', '幻坏爆僚 警告起重工龙', '「幻坏兵 高空工龙」＋「幻坏兵 安全帽龙」
【条件】无
【效果】选自己墓地的怪兽（8星以上/幻龙族）和「融合术」各最多1张加入手卡。那之后，选自己场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP040', '幻坏龙 爆破龙王', '【条件】自己或者对方的场地区域有卡的场合，把包含怪兽（幻龙族）的2张手卡送去墓地才能发动。
【效果】对方场上的表侧表示怪兽（8星以下）全部破坏。那之后，给与对方为［这个效果破坏的怪兽数量］×300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP041', '幻坏兵 临时小卖部龙', '【条件】支付500基本分才能发动。
【效果】自己卡组最上面的卡送去墓地。这个效果让怪兽（幻龙族）被送去墓地的场合，可以再选自己墓地1只「幻坏兵 安全帽龙」或者怪兽（8星/幻龙族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP042', '幻刃步哨 拉铲龙', '【条件】让自己墓地3只怪兽（幻龙族）回到卡组才能发动。
【效果】选自己墓地1只怪兽（8星/幻龙族）在自己场上表侧表示特殊召唤。这个效果把「幻刃龙 建造龙」特殊召唤的场合，可以再选自己墓地1只怪兽（幻龙族/守备力0）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP043', '幻坏兵 安全帽龙', '【条件】把「融合术」以外的1张手卡送去墓地，支付500基本分才能发动。
【效果】选自己墓地1张「融合术」加入手卡。那之后，可以选自己墓地1张场地魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP044', '幻刃龙 建造龙', '【条件】自己或者对方场上有表侧表示的场地魔法卡的场合才能发动。
【效果】选自己墓地1只通常怪兽（幻龙族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP045', '幻刃妖精 镐头龙', '【条件】把手卡1只怪兽（幻龙族）送去墓地才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP046', '幻坏兵 高空工龙', '以高处为目标的幻坏兵。为了到达理想乡，重复着破坏和创造。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP047', '幻坏兵 泥瓦匠龙', '反复钻研的幻坏兵。为了建立理想乡，重复着破坏和创造。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP048', '幻坏兵 管道工龙', '贯彻信念的幻坏兵。寻求通往理想乡之道，重复着破坏和创造。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP049', '幻刃破龙 破碎龙兽', '用特殊工具来武装全身的幻刃龙。据说拥有无论怎样的大型工地都能一瞬间拆除的力量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP050', '幻刃战士 铲子龙', '年轻的幻刃战士。将热情灌注到铲子上，今天也去开掘工地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP051', '幻坏剑 建筑五指剑', '【条件】可以给自己场上1只表侧表示怪兽（幻龙族）装备。
【效果】装备怪兽的攻击力上升500。自己墓地有怪兽（幻龙族）5只以上的场合，再让攻击力上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP052', '幻坏大铠户', '【条件】可以给自己场上1只表侧表示怪兽（幻龙族）装备。
【效果】装备怪兽只要处于攻击表示，不会被战斗破坏。自己或者对方的场地区域有卡的场合，装备怪兽和这张卡不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP053', '幻坏调查', '【条件】无
【效果】从自己卡组上面把［自己场上的表侧表示怪兽（幻龙族）数量］的卡送去墓地。那之后，可以选自己墓地1只「幻坏兵 安全帽龙」或者1张场地魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP054', '透幻乡的崄峻', '【条件】无
【效果】只要这张卡在场地区域处于表侧表示，双方场上的表侧表示怪兽（幻龙族）的攻击力上升400，守备力下降400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP055', '透幻乡的银岭', '【条件】这张卡在对方场上有表侧表示怪兽（7星以上）的场合才能发动。
【效果】只要这张卡在场地区域处于表侧表示，双方在怪兽（7星以上/幻龙族）攻击表示上级召唤的场合，需要的解放变成1只。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP056', '始幻的咆哮', '【条件】自己场上有表侧表示怪兽（幻龙族）的场合才能发动。
【效果】选对方场上1张魔法·陷阱卡回到持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP057', '幻坏壁砾', '【条件】自己场上有表侧表示怪兽（7星以上/幻龙族）的场合，对方怪兽（8星以下）的攻击宣言时才能发动。
【效果】那次攻击无效。这个回合，对方不能用怪兽（7星以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP058', '幻坏奥义-一式攻事', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】选自己墓地最多6只怪兽（幻龙族）回到卡组。［这个效果回去的怪兽的等级合计］是16星以上的场合，可以再把对方场上的攻击表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP059', '淘金超速潮', '【条件】对方把怪兽（7星以上）表侧表示召唤·特殊召唤时，把自己场上的怪兽全部送去墓地才能发动。
【效果】自己抽3张，给双方确认。那之中有怪兽（7星以上）的场合，再让自己可以把那些怪兽（7星以上）以喜欢的数量在自己场上里侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP060', '以太探寻者', '【条件】把手卡1张魔法·陷阱卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降300。自己墓地有「融合术」的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP061', '救惺之巫女', '【条件】让自己墓地1张「融合术」回到卡组才能发动。
【效果】自己抽1张。自己场上有表侧表示怪兽（9星）的场合，再让自己场上的全部表侧表示怪兽的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP062', '融合术', '【条件】无
【效果】自己场上的表侧表示怪兽作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP063', '幻煌龙 螺旋', '经历了炽烈战涡的猛龙。其负伤之躯接触古老光芒，最终完成自身的浸涡。不久，巨龙展开自己的双翅，变为称霸天涡的煌者。那位新生的煌，究竟是梦是真还是幻。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP064', '风帝 莱扎', '【条件】这张卡攻击表示上级召唤的回合才能发动。
【效果】选自己或者对方场上1张卡回到持有者卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB01-JP065', '神鸟攻击', '【条件】对方把怪兽召唤·特殊召唤时或者对方把魔法卡发动后，把自己场上1只表侧表示怪兽（鸟兽族）送去墓地才能发动。
【效果】选对方场上最多2张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP002', '元素英雄 爆热翼侠', '「元素英雄 羽翼侠」＋「元素英雄 爆热女郎」
这张卡不用融合术召唤不能特殊召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（战士族），那个攻击力直到下次的对方回合结束时上升1000。那之后，可以选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP003', '元素英雄 雷霆巨人', '「元素英雄 电光侠」＋「元素英雄 黏土侠」
这张卡不用融合术召唤不能特殊召唤。
【条件】把1张手卡送去墓地才能发动。
【效果】选持有比这张卡的攻击力低的原本攻击力的自己或者对方场上1只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP010', '锐进英雄 银甲侠', '【条件】把额外卡组1只融合术怪兽（6·7星/战士族）给对方观看才能发动。
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选最多2只在这个效果的条件给人观看的怪兽有卡名作为素材记述的通常怪兽加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP011', '支援龙', '自己场上有表侧表示的通常怪兽（战士族）的场合，这张卡可以从手卡往自己场上表侧守备表示特殊召唤。
【条件】无
【效果】从自己卡组上面把4张卡送去墓地。那之后，可以选自己墓地1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP012', '英雄少年', '【条件】自己墓地有「融合术」或者「摩天楼」的场合才能发动。
【效果】选自己墓地的通常怪兽（战士族）或者「融合术」合计最多2张加入手卡。那之后，选自己场上1只怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP013', '流浪勇者 弗里德', '【条件】让自己墓地2只怪兽（光属性）用喜欢的顺序回到卡组下面才能发动。
【效果】选持有比这张卡的攻击力高的攻击力的自己或者对方场上1只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP014', '天终之怪依', '【条件】无
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己从那之中选1张送去墓地。那之后，剩下的卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP015', '魔将 雅灭鲁拉-武枪', '【条件】无
【永续效果】自己场上的表侧表示怪兽（7星以上/天界战士族·战士族）不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP016', '升腾之战士 吉尔福德', '这张卡不能特殊召唤。
【条件】这张卡召唤的回合，让自己墓地2只怪兽（战士族）回到卡组才能发动。
【效果】这个回合，这张卡可以向怪兽作3次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP017', '极斧袭击者', '持斧的战士。把自己逼至极限，彻底锻炼好肉体。挥舞两把斧头的攻击相当强劲。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP018', '暗黑骑士 盖亚', '乘坐跑得比风更快之马的骑士。要注意突进攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP019', '断乐姬 奥菲克莱德阔剑手', '合奏武队的最老成员。用强而有力的声响来鼓舞同伴。对后辈大号月刃斧手的成长感到可靠放心。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP020', '贯贵益荒男', '【条件】自己场上的表侧表示怪兽是3只的场合，把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（战士族）。这个回合，那只怪兽的攻击带有贯通（向守备表示怪兽攻击时，给与攻击力超过那个守备力的数值的战斗伤害）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP021', '阴阳士 唐竹', '【条件】自己场上有这张卡以外的表侧表示怪兽（战士族）的场合才能发动。
【效果】给与对方为［对方场上的魔法·陷阱卡数量］×200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP022', '阴阳士 刺突', '【条件】自己场上的表侧表示怪兽只有怪兽（战士族）的场合，让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（战士族/攻击力1000/守备力1000）在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP023', '阴阳士 逆风', '【条件】自己场上有这张卡以外的表侧表示怪兽（战士族）的场合才能发动。
【效果】对方墓地的怪兽选最多有［对方场上的魔法·陷阱卡数量］回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP024', '阴阳士 右薙', '【条件】自己场上有这张卡以外的表侧表示怪兽（攻击力1000/守备力1000）的场合，让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（8星/攻击力2500）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP025', '午睡斗牛士', '【条件】让自己墓地3只怪兽回到卡组才能发动。
【效果】选对方场上1只攻击表示怪兽（8星以下）变成里侧守备表示。那之后，可以选自己墓地1张「斗牛士午睡锁」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP026', '弧乐姬 圆号鸳鸯钺手', '【条件】这张卡召唤的回合才能发动。
【效果】自己卡组最上面的卡送去墓地。这个效果让怪兽（战士族）被送去墓地的场合，可以再选自己墓地1只通常怪兽（战士族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP027', '鬼将 美咤美', '【条件】这张卡召唤的回合，对方场上有表侧表示怪兽（攻击力2500以上）的场合才能发动。
【效果】选自己墓地1只怪兽（7星以上/战士族）加入手卡。这个回合，自己不能用怪兽（守备力1900以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP028', '强欲之壶', '【条件】无
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP029', '七宝船', '【条件】把手卡1只怪兽送去墓地才能发动。
【效果】自己抽1张。这个效果的条件把怪兽（7星）送去墓地的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP030', '元素循环', '【条件】把额外卡组1只融合术怪兽（6·7星/战士族）给对方观看，把1只在那只怪兽有卡名作为素材记述的手卡的怪兽（战士族）送去墓地才能发动。
【效果】自己抽3张。那之后，自己选1张手卡送去墓地。这个效果的发动后，直到回合结束时自己不能把怪兽（战士族以外）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP031', '奇迹融合', '【条件】无
【效果】自己的场上·墓地的怪兽作为素材用喜欢的顺序回到持有者卡组下面，把不用融合术召唤不能特殊召唤的怪兽（战士族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP032', '摩天楼', '【条件】无
【效果】只要这张卡在场地区域处于表侧表示，回合玩家的场上的表侧表示的「元素英雄 羽翼侠」、「元素英雄 爆热女郎」、「元素英雄 黏土侠」、「元素英雄 电光侠」、「元素英雄 水泡侠」、「元素英雄 新宇侠」、融合术怪兽（5～8星/战士族）的攻击力上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP033', '幽灵旋风', '【条件】自己场上没有怪兽的场合才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，自己墓地的怪兽是3只以下的场合，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP034', '潜入开始', '【条件】无
【效果】选自己手卡或者自己墓地1只通常怪兽（7星）在自己场上表侧表示特殊召唤。这个回合，这个效果特殊召唤的怪兽的攻击力上升700，不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP035', '平行宇宙之门', '【条件】无
【效果】自己卡组最上面的卡送去墓地。自己手卡是0张的场合，可以再选自己墓地最多2只通常怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP036', '融合术', '【条件】无
【效果】自己场上的表侧表示怪兽作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP037', '魔法石采掘', '【条件】自己墓地有魔法卡的场合，把2张手卡送去墓地才能发动。
【效果】选自己墓地1张魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP038', '沙尘防护罩 -尘埃之力-', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】对方场上的表侧表示怪兽全部变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP039', '亚龙地狱', '【条件】对方把怪兽（8星以下）表侧表示召唤·特殊召唤时，把自己场上1只表侧表示怪兽（5星以上）送去墓地才能发动。
【效果】双方场上的表侧表示怪兽之内等级最高的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/SD0B-JP040', '斗牛士午睡锁', '【条件】对方把怪兽（4星以下）召唤时，对方场上没有那只怪兽以外的怪兽的场合才能发动。
【效果】那只怪兽变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP000', '注射天使 莉莉', '【条件】支付2000基本分才能发动。
【效果】这张卡的攻击力直到回合结束时上升3000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP001', '公正空中飞人', '自由自在飞翔于空中的杂技演员。和妹妹邪恶耍球人一起为演出节目增添华彩。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP002', '三色化学人', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1张「极大炎融合」或者「化学化弹·翼」加入手卡。那之后，可以选自己墓地1只「化学化火精灵」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP003', '极超助手·霹丽', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，自己墓地有「超级助手·阿炽」的场合，可以选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP004', '化学火山化火巨灵', '【条件】无
【永续效果】这张卡的攻击力上升［这张卡攻击表示上级召唤时解放的1只怪兽（炎属性/炎族·水族·雷族）的原本等级］×400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP005', '骰子小钥心·小一', '【条件】自己卡组的卡是10张以上，自己场上有表侧表示的「骰子小钥心·小八」的场合，把卡组洗切才能发动。
【效果】自己卡组最上面的卡送去墓地。这个效果让持有掷骰子效果的怪兽（7星）被送去墓地的场合，再给与对方700伤害。给与伤害的场合，可以再选自己或者对方场上的卡合计最多7张破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP006', '骰子小钥心·小八', '【条件】无
【永续效果】这张卡和自己场上的表侧表示的「骰子小钥心·小一」不能为上级召唤而解放。攻击表示的这张卡不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP007', '骰子小钥心·小合', '【条件】无
【效果】掷1次骰子。出现数目的效果适用。
●1：选自己场上1张卡破坏。
●2～6：自己场上的怪兽（天使族）作为素材送去墓地作融合术召唤。出现的数目是5·6的场合，再在这个回合让这个效果特殊召唤的怪兽不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP008', '骰子小钥心·小撤', '【条件】把手卡1只怪兽送去墓地才能发动。
【效果】选自己墓地1张持有掷骰子效果的陷阱卡加入手卡。那之后，可以选自己场上1张表侧表示的卡。选的场合，这个回合，那张卡不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP009', '骰子小钥心·小莉莉丝', '【条件】把1张手卡送去墓地才能发动。
【效果】掷1次骰子。出现数目的效果适用。
●1～3：这个回合，怪兽（天使族）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。
●4～6：手卡1只怪兽（天使族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP010', '道星魔剑士', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「道星剑士」。那之后，可以选自己墓地1只「七星惧魔术师」在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP011', '全息宇宙世界树龙', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「宇宙世界树龙」。自己墓地有「宇宙世界树龙」的场合，再在这个回合在自己把「深空宇宙世界树龙」融合术召唤的场合让表侧表示的这张卡可以作为2只数量的素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP012', '黄色零件', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「绿色零件」加入手卡。这个回合，自己不能把「黄色零件」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP013', '绿色零件', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「红色零件」加入手卡。这个回合，自己不能把「绿色零件」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP014', '红色零件', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「黄色零件」加入手卡。这个回合，自己不能把「红色零件」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP015', '机动城 极大零件［L］', '墓地的这张卡的卡名变成「黄色零件」。
【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP016', '机动城 极大零件', '可以和「机动城 极大零件［L］」「机动城 极大零件［R］」集齐作极大召唤。墓地的这张卡的卡名变成「绿色零件」。
【条件】极大模式
【永续效果】这张卡的攻击带有贯通。自己场上的卡不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP017', '机动城 极大零件［R］', '墓地的这张卡的卡名变成「红色零件」。
【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP018', '古代的机械蝎尾兽', '【条件】让自己墓地的「绿色零件」「红色零件」「黄色零件」的其中1只回到卡组才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。这个回合，自己不用怪兽（地属性/机械族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP019', '古代的机械双头龙', '【条件】无
【永续效果】这张卡的攻击宣言时对方不能把陷阱卡发动。自己墓地有「绿色零件」「红色零件」「黄色零件」的其中任意种的场合，这张卡的攻击力上升300，不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP020', '锐气机动车 协合拖拉机', '【条件】自己场上有表侧表示的「锐进英雄 银甲侠」或者融合术怪兽（7星/战士族）的场合，把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP021', '新宇宙侠·天空蜂鸟', '【条件】自己基本分是4000以下的场合才能发动。
【效果】自己回复［对方手卡数量］×500基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP022', '兽医 莉莉', '【条件】这张卡召唤的回合，支付500基本分才能发动。
【效果】选自己墓地1只怪兽（地属性/攻击力400/守备力1500）在自己场上表侧表示特殊召唤。那之后，可以选自己场上1只表侧表示怪兽那个攻击力直到下次的对方回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP023', '惠雷之鸭儿', '【条件】这张卡召唤的回合，让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只「惠雷之精灵」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP024', '惠雷之狗儿', '【条件】这张卡召唤的回合，自己墓地有「惠雷之精灵」的场合才能发动。
【效果】选对方场上1只怪兽把表示形式变更。那之后，可以选自己墓地1张「恵雷のかかし」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP025', '舞踊的惠雷之精灵', '墓地的这张卡的卡名变成「惠雷之精灵」。
【条件】这张卡召唤的回合，自己卡组的卡是10张以上的场合才能发动。
【效果】选双方墓地的卡各1张回到持有者卡组。那之后，对方墓地的卡是5张以下的场合，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP026', '爱之天人', '【条件】这张卡召唤的回合，支付500基本分才能发动。
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选1只怪兽（4星以外/天使族/攻击力0）加入手卡。剩下的卡用喜欢的顺序回到卡组下面。这个效果选怪兽（光属性）的场合，可以再让自己回复1000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP027', '邪爱之天人', '这张卡可以把1只怪兽（攻击力0）解放攻击表示上级召唤。
【条件】无
【永续效果】这张卡的攻击力上升2200，那攻击带有贯通。自己场上的原本攻击力是0的表侧表示怪兽不会被对方的怪兽·魔法卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP028', '莓果新人·骄傲小莓', '【条件】把这张卡以外的自己的手卡·场上1张卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升1500。自己墓地有怪兽（水族/攻击力100）5只以上的场合，可以再选对方场上1只里侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP029', '龙水之神子', '【条件】让自己墓地1只「龙水之神子」或者4只怪兽回到卡组才能发动。
【效果】选对方的魔法与陷阱区域1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP030', '骷髅花', '【条件】自己卡组的卡是10张以上的场合，让自己墓地3只怪兽（4星以外/不死族）回到卡组才能发动。
【效果】选自己墓地1只怪兽（1星/不死族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP031', '电击狮鹫', '【条件】自己卡组的卡是10张以上的场合，把手卡1只怪兽（雷族）送去墓地才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP032', '支援单位-熊耳', '【条件】无
【永续效果】自己场上的表侧表示怪兽（地属性/机械族）的攻击力上升500，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP033', '诡术师', '把这张卡以外的1张手卡送去墓地，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【效果】无', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP034', '月之女战士', '【条件】无
【永续效果】双方的战斗阶段中，对方场上有表侧表示怪兽（光属性）的场合，这张卡的攻击力上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP035', '穿越侍·强袭线性海牛侍', '「穿越侍·线性海牛侍」＋效果怪兽（7星以外/银河族）
【条件】这张卡的等级是4星以上的场合，让自己墓地2只怪兽回到卡组才能发动。
【效果】这张卡的等级直到回合结束时下降3星。这个效果的条件让「トランザム・ライカー」回去的场合，再在这个回合让这张卡的攻击带有贯通，贯通时给与对方的战斗伤害变成2倍。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP036', '穿越侍·破坏线性海牛侍', '「穿越侍·线性海牛侍」＋效果怪兽（7·8星/银河族）×2
【条件】无
【效果】选对方场上1张里侧表示的卡破坏。这张卡融合术召唤的自己主要阶段把这个效果发动的场合，再让这张卡的攻击力直到回合结束时上升2600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP037', '炼金化学化宝珠', '怪兽（炎属性/炎族）＋怪兽（水族·雷族）
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽。这个回合，那只怪兽的攻击带有贯通。并且，可以再选对方场上1张魔法·陷阱卡回到持有者卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP038', '超级谱气斗士·等离子剑士', '「色谱气斗士」＋「超级助手·霹丽」
【条件】无
【永续效果】这张卡的攻击力上升［对方场上的表侧表示怪兽（7星以上）的等级合计］×200。自己墓地有极大怪兽（炎族·水族·雷族）合计3只以上的场合，双方不能从手卡把怪兽（炎属性以外）表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP039', '化学火山现行化火精神灵', '「化学化火精灵」＋极大怪兽（炎族·水族·雷族）
【条件】让自己墓地3只极大怪兽用喜欢的顺序全部回到卡组上面或用喜欢的顺序全部回到卡组下面才能发动。
【效果】对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降3000。极大模式的怪兽作为素材把这张卡融合术召唤的回合发动的场合，更在这个回合让这张卡可以作3次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP040', '骰子炸药美腿女郎·翻倍小掷', '「骰子炸药少女·小掷」＋「骰子小钥心·小合」
【条件】这张卡特殊召唤的自己主要阶段才能发动。
【效果】掷2次骰子。可以选持有［出现的数目合计］以下的等级的自己或者对方的墓地1只怪兽（光属性）在自己场上表侧表示特殊召唤。那之后，可以让这张卡的攻击力直到回合结束时上升［这个效果特殊召唤的怪兽的原本攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP041', '名蔷薇匿名魔术师', '「名蔷薇魔术师」＋「名蔷薇魔女」
这张卡可以用接触融合术。
【条件】这张卡融合术召唤的自己主要阶段才能发动。
【效果】选自己场上1只怪兽送去墓地。那之后，可以选对方场上1只表侧表示怪兽那个攻击力直到回合结束时下降［这个效果送去墓地的怪兽的原本攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP042', '道星魔导剑斗士', '「七道魔导士」＋「道星剑士」
这张卡可以用接触融合术。
【条件】把卡组最上面的卡送去墓地才能发动。
【选择效果】●选对方场上1只表侧表示怪兽，那个攻击力·守备力直到回合结束时下降［自己墓地的怪兽（暗属性/魔法师族）的等级种类］×400。●这个回合，这张卡的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP043', '暗物质噬兵 极乐鹰巨人', '「虚空噬骸兵 极乐鹰巨人」＋「接触体·暗物质旅行者号」
这张卡可以用接触融合术。
【条件】无
【永续效果】攻击表示的这张卡不会被战斗破坏，这张卡的攻击力上升［双方场上的里侧表示怪兽数量］×1000。自己基本分是2500以下的场合，这张卡的攻击力上升2500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP044', '暗物质超越龙', '「暗物质龙」＋「接触体·暗物质飞龙」＋通常怪兽
这张卡可以用接触融合术。
【条件】这张卡特殊召唤的自己主要阶段才能发动。
【效果】从双方卡组上面把卡各3张送去墓地。这个回合，这张卡可以向怪兽作3次攻击，那攻击带有贯通。并且，可以再选对方墓地最多3只怪兽（5星以上）在对方场上里侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP045', '暗物质银河龙', '「暗物质皇帝龙」＋「接触体·暗物质飞龙」
这张卡可以用接触融合术。
【条件】无
【永续效果】这张卡的攻击力上升［对方场上的怪兽数量］×1000。自己场上有里侧表示怪兽的场合，攻击表示的这张卡不会被战斗和效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP046', '钢铁徽章之阿梅勒斯明星', '「虚钢演机」＋「公正空中飞人」
【条件】把这张卡的表示形式变更才能发动。
【选择效果】●对方场上的里侧表示的卡全部确认。那之后，可以把那之中的魔法卡全部破坏。●选极大怪兽以外的对方场上1只表侧表示怪兽（天使族）得到那个控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP047', '元素英雄 水手侠', '「元素英雄 水泡侠」＋「元素英雄 羽翼侠」
这张卡不用融合术召唤不能特殊召唤。
【条件】自己的魔法与陷阱区域有里侧表示的卡的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这个回合，这张卡可以直接攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP048', '穿越侍星云融合', '【条件】无
【效果】自己手卡1只怪兽（银河族）送去墓地。那之后，可以让自己场上的怪兽1只和自己墓地的怪兽（银河族）1只以上作为素材回到持有者卡组把有「穿越侍·线性海牛侍」的卡名作为素材记述的怪兽融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP049', '极大炎融合', '【条件】无
【效果】包含极大怪兽（炎属性）的自己的手卡·场上的怪兽作为素材送去墓地，把怪兽（炎属性）融合术召唤。这个效果把极大模式的怪兽送去墓地的场合，再让这个效果特殊召唤的怪兽只要处于表侧表示不会被对方的效果破坏，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP050', '化学化火山盾', '【条件】可以给自己场上1只表侧表示怪兽（炎族·水族·雷族）装备。
【效果】装备怪兽不会被对方的效果破坏。装备怪兽的攻击力上升［自己墓地的极大怪兽（炎属性/炎族·水族·雷族）数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP051', '机动碎击 齿轮粉碎拳', '【条件】把手卡1只怪兽（4星/地属性/机械族）送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）或者1张里侧表示的卡破坏。这个回合，自己不用怪兽（地属性/机械族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP052', '机动配备 齿轮起动', '【条件】支付1000基本分才能发动。
【效果】选自己墓地最多2只极大怪兽（4星/地属性/机械族）加入手卡。这个回合，自己不用极大模式的怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP053', '莉莉的注射器', '【条件】对方场上有怪兽的场合才能发动。
【效果】选自己墓地1只怪兽（地属性/攻击力400/守备力1500）加入手卡。并且再在这个回合在自己把「注射天使 莉莉」的效果发动的场合让效果的条件支付的基本分可以改成100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP054', '传述的英雄谭', '【条件】自己卡组的卡是10张以上的场合，让自己墓地2只怪兽回到卡组才能发动。
【效果】从自己卡组上面把4张卡送去墓地。那之后，可以从那之中选传说怪兽和传说陷阱卡各最多1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP055', '死地高扬', '【条件】把1张手卡和自己场上1只表侧表示怪兽（不死族）送去墓地才能发动。
【效果】选对方场上1张卡破坏。那之后，自己墓地有怪兽（不死族）4只以上的场合，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP057', '化学化弹·翼', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时，让自己墓地2只怪兽（炎属性）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。那之后，可以选自己墓地1只「化学化火精灵」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP058', '时间机械', '【条件】只让怪兽1只被战斗破坏时才能发动。
【效果】那只怪兽在那只怪兽被破坏时的控制者场上以相同表示形式从墓地特殊召唤（那只怪兽是极大模式的场合，那些全部集齐以极大模式特殊召唤）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP059', '起动指令 齿轮武力', '【条件】自己场上的怪兽只有表侧表示怪兽（4星以上/地属性/机械族）的场合，对方怪兽的攻击宣言时才能发动。
【效果】对方场上的攻击表示怪兽（8星以下）选最多有［自己场上的怪兽数量］破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP060', '惠雷之稻草人', '【条件】对方怪兽的攻击宣言时，让自己墓地1只怪兽（4星以下/雷族）回到卡组下面才能发动。
【效果】那次攻击无效。那之后，可以选对方墓地最多3张卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP061', '天使的注射', '【条件】在对方回合对方抽卡时或者在对方把怪兽召唤时才能发动。
【效果】选自己场上1只怪兽送去墓地。那之后，自己墓地有怪兽（地属性/攻击力400/守备力1500）的场合，可以选对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP062', '骸群', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】那只怪兽的攻击力直到回合结束时下降［自己墓地的「白骨」数量］×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP063', '狡猾的落穴', '【条件】自己墓地没有陷阱卡的场合，对方把怪兽召唤·特殊召唤时才能发动。
【效果】选自己或者对方场上的怪兽合计2只破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP064', '第六感', '【条件】自己卡组的卡是6张以上的场合，对方把怪兽召唤·特殊召唤时才能发动。
【效果】自己从1～6的数字之中选2个，对方掷1次骰子。选的数字数目出现的场合，自己抽出［出现数目的数量］。没出现的场合，自己从自己卡组上面把［出现的数目数量］的卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP065', '元素英雄 棱镜侠', '【条件】把额外卡组1只融合术怪兽给对方观看，宣言1个在那只怪兽有作为素材记述的卡名才能发动。
【效果】这张卡的卡名在这个回合变成这个效果的条件宣言的卡名。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP19-JP066', '元素英雄 长空新宇侠', '「元素英雄 新宇侠」＋「新空间侠·天空蜂鸟」
这张卡可以用接触融合术（自己场上的上记的表侧表示怪兽作为素材回到持有者卡组作融合术召唤）。
【条件】双方基本分不同的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这个回合，这张卡可以向怪兽作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP000', '龙骑士 黑魔术师', '「黑魔术师」＋怪兽（龙族）
墓地的这张卡的卡名变成「黑魔术师」。
【条件】无
【永续效果】这张卡的卡名变成「黑魔术师」。自己场上的魔法·陷阱卡不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP001', '花牙消 向日葵', '潜入阴暗处，总在守护主人的草之一派。以电光石火之速完成忍务，如烟雾一般消失。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP002', '魔法爆罚者', '【条件】这张卡召唤的回合，把1张手卡送去墓地才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1只「七道魔女」或者「七道高级魔导士」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP003', '解咒术弓手', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「解咒术弓手」。自己墓地有通常怪兽（魔法师族）的场合，可以再选对方场上1只怪兽把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP004', '歼灭之暗黑巫师', '【条件】这张卡召唤的回合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「黑暗术士」。那之后，可以选自己墓地1张「魔法七星融合」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP005', '加速魔杖手·暗黑魔女', '【条件】把额外卡组1只融合术怪兽（暗属性/魔法师族/守备力2100）给对方观看，宣言1个在那只怪兽有作为素材记述的卡名才能发动。
【效果】这张卡的卡名在这个回合变成这个效果的条件宣言的卡名。这个回合，自己不能用怪兽（魔法师族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP006', '重建龙兽', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地1只「碧牙爆速龙」或者「真红动击速龙」在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP007', '机械蛋球机器人', '墓地的这张卡的卡名变成「蛋球机器人」。
【条件】无
【永续效果】这张卡的卡名变成「蛋球机器人」。自己把「蛋球机器人国王巨人」融合术召唤的场合，这张卡可以作为2只数量的素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP008', '妈妈球机器人', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「蛋球机器人」加入手卡。这个回合，怪兽（地属性/机械族）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP009', '蛤蟆球机器人', '【条件】把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】从自己卡组上面把6张卡翻开，给双方确认。自己可以从那之中选「蛋球机器人」「蛋球结合」合计最多2张加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP010', '国王蛋球机器人', '【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「蛋球机器人」。那之后，可以选自己墓地最多2只「蛋球机器人」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP011', '蛋球坦克Mk-2', '【条件】这张卡召唤的回合，把自己场上1只表侧表示的「蛋球机器人」送去墓地才能发动。
【效果】选对方场上1张表侧表示的卡破坏。那之后，可以选对方场上1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP012', '花牙疾走之女忍·绘都兰世', '墓地的这张卡的卡名变成「花牙女忍 异邦兰」。
【条件】从卡组上面把3张卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「花牙女忍 异邦兰」。这张卡召唤·特殊召唤的自己主要阶段把这个效果发动的场合，可以再选自己墓地最多2只通常怪兽（地属性/植物族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP013', '花牙女忍·凛花宁祥', '【条件】无
【永续效果】对方回合内，自己场上没有魔法·陷阱卡的场合，这张卡的攻击力上升［自己场上的原本攻击力最高的表侧表示怪兽的原本攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP014', '幻坏兵 灯裤龙', '【条件】把手卡1只怪兽（幻龙族）给对方观看才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之中有怪兽（炎属性/幻龙族）的场合，可以再选自己墓地1只「幻坏兵 笼裤龙」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP015', '幻坏兵 笼裤龙', '【条件】自己场上有表侧表示的「幻坏兵 灯裤龙」的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之中有怪兽（炎属性/幻龙族）的场合，可以再选自己墓地的场地魔法卡和装备魔法卡各最多1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP016', '等离子塑料模型 胶水龟', '【条件】把1张手卡送去墓地才能发动。
【效果】选自己场上最多2只表侧表示怪兽（雷族），那些等级直到回合结束时上升4星。这个回合，自己不能用怪兽（雷族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP017', '等离子塑料模型 斜口钳兔', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只「等离子塑料模型 胶水龟」或者1张「等离子塑料模型保养」加入手卡。这个回合，自己不能用怪兽（雷族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP018', '等离子塑料模型 音速马', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地的「等离子塑料模型 改造姬」「等离子塑料模型对接」各最多1张加入手卡。这个回合，自己不能用怪兽（雷族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP019', '等离子塑料模型 智能猫头鹰', '【条件】这张卡召唤的回合，让自己墓地2只怪兽（4星/雷族/守备力800）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽变成里侧守备表示。那之后，可以选自己墓地1张「等离子塑料模型竞玩」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP020', '等离子塑料模型 宇宙滑翔机', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1张「等离子塑料模型竞玩」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP021', '等离子塑料模型 改造姬', '【条件】这张卡召唤的回合，把1张手卡送去墓地才能发动。
【效果】这张卡的等级直到回合结束时上升4星。自己在这次主要阶段没有抽卡的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP022', '等离子塑料模型 再构姬', '【条件】把这张卡以外的自己场上1只怪兽送去墓地才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。这个回合，自己不能用怪兽（雷族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP023', '等离子塑料模型 混合姬', '【条件】让自己墓地1只仪式术怪兽（雷族/守备力1600）回到额外卡组才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。这个回合，自己不能用怪兽（雷族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP024', '磁石增速器', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（岩石族/守备力2100）或者通常怪兽（岩石族）加入手卡。那之后，可以把自己的手卡·场上的怪兽（岩石族）作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP025', '洗礼的诅咒之龙', '墓地的这张卡的卡名变成「诅咒之龙」。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选1张仪式术魔法卡加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP026', '洗礼的始神', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1张仪式术魔法卡在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP027', '摩耳摩', '【条件】无
【效果】选自己场上1只表侧表示怪兽（地属性）。选的怪兽和持有［那只怪兽的攻击力］以下的守备力的双方场上的表侧表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP028', '永远之体光摄手', '【条件】这张卡召唤的回合才能发动。
【效果】选对方墓地1张卡回到卡组下面。那之后，从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选1只怪兽（9星/地属性/魔法师族）加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP029', '炸弹杂耍人', '【条件】这张卡召唤的回合，把自己场上1只表侧表示的仪式术怪兽送去墓地才能发动。
【效果】给与对方1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP030', '继承的魔战士', '【条件】让自己墓地2只怪兽回到卡组才能发动。
【效果】选攻击力或者守备力是2600的自己墓地1只怪兽（战士族·魔法师族）。这张卡的卡名在这个回合变成和选的怪兽相同卡名。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP031', '不逊之常春藤小鬼', '【条件】让自己墓地2只怪兽回到卡组才能发动。
【效果】选对方场上1只攻击表示的效果怪兽变成里侧守备表示。自己场上的表侧表示怪兽（植物族）是3只的场合，再在这个回合让那些怪兽的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP032', '大道使徒·射手', '「解咒术弓手」＋怪兽（暗属性/魔法师族）
【条件】这张卡融合术召唤的自己主要阶段才能发动。
【效果】自己墓地的怪兽作为素材回到卡组，把「七道高级魔导士」融合术召唤。这个回合，自己不能用怪兽（魔法师族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP033', '大道使徒·法师', '「黑暗术士」＋怪兽（暗属性/魔法师族）
【条件】无
【永续效果】自己场上的表侧表示怪兽（魔法师族）的攻击力上升200。对方回合内，自己场上的怪兽不会因效果回到手卡·卡组·额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP034', '七星道最权威魔术师', '「七道高级魔导士」＋「七道附魔师」
【条件】无
【效果】选对方场上1张卡破坏。那之后，自己墓地有「七道高级魔导士」的场合，可以选对方场上1张卡回到持有者卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP035', '暗黑之邪龙骑士', '「暗黑龙骑士」＋「暗黑之邪龙」
【条件】支付500基本分才能发动。
【选择效果】●这张卡的攻击力直到回合结束时上升［自己墓地的通常怪兽数量］×400。●只要这张卡处于表侧表示，这张卡的攻击力上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP036', '光波技术巨龙', '「光波技术龙」＋「增速飞龙」
【条件】无
【效果】从自己卡组上面把4张卡送去墓地。那之后，可以选自己的手卡·墓地1只「碧牙爆速龙」或者「真红动击速龙」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP037', '紫鳞弹超越爆击速龙', '「碧牙爆速龙」＋「真红动击速龙」
【条件】无
【永续效果】自己回合内，这张卡的攻击力上升［对方场上的原本攻击力最高的表侧表示怪兽的原本攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP038', '蛋球机器击速龙', '「真红动击速龙」＋「蛋球机器人」
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升1000。那之后，可以给与对方为［自己墓地的「蛋球机器人」数量］×300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP039', '蛋球机器人国王巨人', '「蛋球机器人」＋「蛋球机器人」＋「蛋球机器人」
【条件】让自己墓地1只「蛋球机器人」回到卡组上面才能发动。
【效果】选自己场上最多3只怪兽。那些怪兽直到下次的对方回合结束时不会被效果破坏。这张卡融合术召唤的自己主要阶段把这个效果发动的场合，再让自己可以回复2000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP040', '花牙华艳 名花·绘都兰世', '「花牙女忍 异邦兰」＋「花牙消 向日葵」
【条件】无
【永续效果】自己场上的表侧表示怪兽的攻击力上升500，不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP041', '育养之钢丝弹簧草', '「莳卷之钢丝弹簧草」＋怪兽（植物族）
【条件】从卡组上面把3张卡送去墓地才能发动。
【效果】自己回复600基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP042', '幻坏双姬 半长裤双龙', '「幻坏兵 灯裤龙」＋「幻坏兵 笼裤龙」
【条件】无
【永续效果】对方回合内，自己场上的魔法·陷阱卡不会因效果回到手卡·卡组·额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP043', '电子监视龙', '「电子搜索龙」＋「电子龙」
【条件】把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】自己的场上·墓地的「电子龙」3只以上作为素材回到持有者卡组，把怪兽（10星/机械族）融合术召唤。这个回合，这个效果特殊召唤的怪兽的攻击力上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP044', '鹰身女郎3·1', '「鹰身女郎3」＋怪兽（4星以下/鸟兽族）
这张卡可以用接触融合术。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「鹰身女郎」。下次的对方回合，对方只能有最多2次攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP045', '超颈龙 动力薄片龙', '怪兽（4星以下/恐龙族）×2
【条件】无
【永续效果】这张卡不会被效果破坏。自己墓地有效果怪兽以外的融合术怪兽（恐龙族）的场合，这张卡的攻击力上升1200，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP046', '等离子塑料模型 雷神俱-改造姬', '【条件】无
【永续效果】自己回合内，这张卡的攻击力上升［这张卡的等级］×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP047', '等离子塑料模型 雷神俱-再构姬', '【条件】这张卡特殊召唤的自己主要阶段，让自己墓地2只怪兽回到卡组才能发动。
【效果】选对方场上1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP048', '等离子塑料模型 雷神俱-混合姬', '【条件】无
【永续效果】自己场上的里侧表示的魔法·陷阱卡不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP049', '传说系谱的剑士', '墓地的这张卡变成传说卡。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升500。自己墓地有怪兽（7星/守备力300）3只以上的场合，可以再选自己墓地1只怪兽（7星/守备力300）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP050', '魔法七星融合', '【条件】无
【效果】自己的手卡·场上的怪兽（魔法师族）作为素材送去墓地，把怪兽（暗属性/魔法师族/守备力2100以下）融合术召唤。这个回合，自己不能用怪兽（魔法师族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP051', '全中蛋球投球', '【条件】无
【效果】选自己场上1只表侧表示的「蛋球机器人」和对方场上1只表侧表示怪兽（攻击力100以上）。这个回合，选的自己怪兽的攻击力上升［选的对方怪兽的攻击力］，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP052', '蛋球火箭炮', '【条件】把自己场上1只表侧表示怪兽（地属性/机械族）送去墓地才能发动。
【效果】自己抽1张。这个效果的条件让怪兽（1星/攻击力200/守备力0）被送去墓地的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP053', '蛋球结合', '【条件】自己场上有表侧表示怪兽（地属性）的场合才能发动。
【效果】自己场上的表侧表示怪兽作为素材送去墓地，把怪兽（龙族·机械族）融合术召唤。那只怪兽的攻击力上升200。这个效果把怪兽（7星/地属性/机械族）作为素材的场合，可以把那些卡名变成「碧牙爆速龙」或者「真红动击速龙」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP054', '真花牙分身', '【条件】自己场上有表侧表示怪兽（7星/地属性/植物族）的场合，让2张手卡用喜欢的顺序回到卡组下面才能发动。
【效果】选自己墓地最多2只怪兽（7星/地属性/植物族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP055', '等离子塑料模型开封', '【条件】无
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选1只怪兽（4星以下/雷族/守备力800）或者1张「等离子塑料模型保养」加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP056', '等离子塑料模型保养', '【条件】可以给自己场上1只表侧表示怪兽（光属性/雷族）装备。
【效果】装备怪兽的攻击力上升500，等级上升4星。装备怪兽是仪式术怪兽的场合，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP057', '等离子塑料模型对接', '【条件】无
【效果】等级合计直到8以上的自己场上的表侧表示怪兽（雷族）作为素材送去墓地，把「等离子塑料模型 雷神俱-改造姬」仪式术召唤（不能把多余怪兽作为素材）。这个回合，自己不能用怪兽（雷族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP058', '等离子塑料模型竞玩', '【条件】无
【效果】等级合计直到8以上的自己场上的表侧表示怪兽（雷族）作为素材送去墓地，把「等离子塑料模型 雷神俱-再构姬」或者「等离子塑料模型 雷神俱-混合姬」仪式术召唤（不能把多余怪兽作为素材）。这个回合，自己不能用怪兽（雷族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP059', '英魂的降临', '【条件】无
【效果】等级合计直到10以上的自己场上的表侧表示怪兽作为素材送去墓地，把「传说系谱的剑士」仪式术召唤（不能把多余怪兽作为素材）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP060', '触发龙雷斗', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】选自己场上1只表侧表示的效果怪兽。这个回合，那只怪兽的攻击力上升300，那攻击带有贯通。双方手卡是0张的场合，可以从自己墓地选1只「雷闘騎トリガードラゴ」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP061', '美狄亚的秘药', '【条件】自己墓地有怪兽（9星/地属性/魔法师族）的场合，把自己场上2只怪兽送去墓地才能发动。
【效果】选自己墓地1只怪兽（9星/地属性/魔法师族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP062', '闪存融合', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时才能发动。
【效果】自己墓地的怪兽作为素材回到卡组，把有「碧牙爆速龙」或者「真红动击速龙」的卡名作为素材记述的怪兽融合术召唤。自己回合把这张卡发动的场合，再让对方可以从自身墓地选1只怪兽在自身场上表侧攻击表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP063', '不球而遇砰砰爆诞', '【条件】自己场上的怪兽被对方的攻击或者对方的效果破坏时才能发动。
【效果】自己卡组最上面的卡送去墓地。那之后，可以选自己墓地最多3只「蛋球机器人」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP064', '花牙眩', '【条件】对方把怪兽召唤时，让自己墓地1只怪兽（地属性/植物族）回到卡组下面才能发动。
【效果】那只召唤的怪兽变成里侧守备表示。那之后，可以选自己墓地1只怪兽（植物族/守备力1000）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP065', '蒂迈欧之眼', '【条件】自己没有把「蒂迈欧之眼」发动的回合才能发动。
【效果】宣言1个「黑魔术师」或者「黑魔导士少女」的卡名，只用宣言的卡名的自己场上的表侧表示怪兽1只作为素材送去墓地，把有那个卡名作为素材记述的怪兽融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP21-JP066', '黑魔族复活之棺', '【条件】对方把怪兽（8星以下）表侧表示召唤·特殊召唤时，把自己场上1只表侧表示怪兽（魔法师族）送去墓地才能发动。
【效果】选那1只召唤·特殊召唤的怪兽破坏。那之后，可以选自己墓地1只怪兽（7星以下/暗属性/魔法师族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP000', '真红眼暗钢龙', '让自己场上1只表侧表示怪兽（龙族）回到卡组下面，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【效果】选自己的手卡·墓地1只怪兽（龙族）在自己场上表侧表示特殊召唤。这个回合，自己不能把「真红眼暗钢龙」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP002', 'THE☆小龙', '【条件】这张卡召唤的回合，把1张手卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「THE☆天龙」。自己墓地的怪兽只有多头龙族·龙族的场合，可以再让自己的手卡·场上的怪兽作为素材回到持有者卡组把怪兽（多头龙族/守备力2000）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP003', '手治小龙', '【条件】把自己场上的攻击表示怪兽（多头龙族·龙族）合计2只变成表侧守备表示才能发动。
【效果】自己回复200基本分。那之后，可以选对方场上最多2只怪兽把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP004', '手伤小龙', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只「背上小龙」或者1张「反攻的龙击」加入手卡。下次的对方回合，自己把「反攻的龙击」发动的场合，效果的条件送去墓地的手卡变成不需要。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP005', '手摘小龙', '【条件】这张卡召唤·特殊召唤的自己主要阶段，把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1只通常怪兽（攻击力0）或者1张「小龙手和平弹」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP006', '手扔小龙', '【条件】把手卡1只怪兽（龙族/攻击力0/守备力1400）送去墓地才能发动。
【效果】自己抽1张。自己墓地有「小巧玲龙」的场合，可以再选对方的魔法与陷阱区域1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP007', '七凤龙', '【条件】这张卡召唤的回合，自己场上有这张卡以外的表侧表示怪兽（多头龙族·龙族）的其中任意种的场合才能发动。
【效果】选自己墓地1只「钢击龙 梅塔基亚斯」或者「幻击龙 米拉基亚斯」加入手卡。那之后，可以选自己墓地1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP008', '稀辉岩龙', '【条件】把额外卡组1只融合术怪兽（光属性/多头龙族）给对方观看，宣言1个在那只怪兽有作为素材记述的卡名才能发动。
【效果】这张卡的卡名在这个回合变成这个效果的条件宣言的卡名。这个回合，自己不用怪兽（多头龙族·龙族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP009', '黑之龙骑士', '墓地的这张卡的卡名变成「暗黑龙骑士」。
【条件】自己墓地有怪兽（5星/龙族）的场合，支付500基本分才能发动。
【效果】选对方场上1只表侧表示怪兽（6星以下）破坏。那之后，可以选自己墓地1只5星「暗黑龙骑士」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP010', '背上小龙', '【条件】无
【永续效果】这张卡的攻击力上升［自己墓地的怪兽（龙族/攻击力0/守备力1400）数量］×500。这张卡的战斗不会让自己受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP011', '无邪孩气龙', '【条件】把这张卡以外的自己场上1张卡送去墓地才能发动。
【效果】自己场上的这张卡回到持有者手卡。那之后，可以选自己墓地1只怪兽（7星/龙族）在自己场上表侧表示特殊召唤。这个回合，自己不能把「无邪孩气龙」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP019', '最强的战旗', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地的怪兽（光属性/机械族/攻击力2500/守备力1600）或者「王牌剑一斩」各最多1张加入手卡。那之后，可以把手卡1只「最强战旗 王牌破坏者」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP020', '暴风眼', '【条件】这张卡召唤的回合才能发动。
【效果】自己的场上·墓地的怪兽（6星以下）2只作为素材回到持有者卡组，把「旋风之魔导师托纳」融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP021', '宇宙吸食者', '【条件】自己基本分比对方少的场合才能发动。
【效果】自己回复300基本分。自己在这次主要阶段没有抽卡的场合，再让自己抽1张。对方场上的表侧表示怪兽的原本等级合计是30星以上的场合，再让自己可以回复3000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP022', '强力震慑电子人', '【条件】这张卡召唤的回合，把卡组最上面的卡送去墓地才能发动。
【效果】选自己或者对方场上1只表侧表示怪兽（机械族），那个攻击力直到回合结束时上升1000。这个效果选的怪兽在这个回合的结束阶段破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP031', '涌军机 应炎', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地1只效果怪兽（7星以上/炎属性/机械族/守备力800）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP032', '涌军机 海炎', '把手卡1只怪兽（7星以外/炎属性/机械族）给对方观看，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】自己卡组的卡是10张以上的场合，让自己场上1只表侧表示怪兽回到持有者卡组下面才能发动。
【效果】选自己的手卡·墓地1只效果怪兽（9星/炎属性/机械族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP033', '涌军机 陆炎', '把手卡1只怪兽（8星以外/炎属性/机械族）给对方观看，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【永续效果】自己场上的表侧表示怪兽（机械族）不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP034', '邪心之魔龙小丑', '【条件】这个回合对方是已抽卡的场合，把自己场上1只怪兽送去墓地才能发动。
【效果】选极大怪兽以外的对方场上1只表侧表示怪兽（8星以下）得到那个控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP035', '集约之魔导师', '【条件】这张卡召唤的回合，从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［自己场上的魔法·陷阱卡数量］×500。自己墓地有「魔导师之力」的场合，再让这张卡的攻击力直到回合结束时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP036', '炎灵 甲乙醚灵', '【条件】自己或者对方场上有持有和原本攻击力不同攻击力的表侧表示怪兽的场合才能发动。
【效果】选自己墓地1只怪兽（5～8星）加入手卡。这个回合，自己不能把「炎灵 甲乙醚灵」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP037', '罗蕾莱河女', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以选对方墓地1只效果怪兽（3·4星/攻击力1500以下）。选的场合，再直到下次的对方回合结束时让双方不能把原本卡名和那只怪兽相同的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP039', '两手上小龙', '「小巧玲龙」＋怪兽（1星/龙族/攻击力0）
这张卡可以用接触融合术。
【条件】无
【永续效果】这张卡的攻击力上升［自己墓地的怪兽数量］×200。自己场上的表侧表示怪兽（7～9星/龙族）不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP040', '超击龙 星齿车戒龙IF', '「连击龙 德拉基亚斯」＋怪兽（1星/龙族/攻击力0）
【条件】自己墓地的怪兽只有多头龙族·龙族的场合，把卡组最上面的卡送去墓地才能发动。
【选择效果】●这张卡的攻击力直到回合结束时上升2000。●选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP043', '歌怜奏女 二重奏八音盒人偶', '「歌怜奏女 八音盒人偶」＋「歌怜奏女 八音盒人偶」
这张卡可以用接触融合术。
【条件】无
【效果】选对方墓地最多4张卡回到卡组。那之后，可以选自己墓地1只怪兽（3·4星）在自己场上表侧表示特殊召唤。这个回合，自己不能把「歌怜奏女 二重奏八音盒人偶」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP046', '小龙手果实', '【条件】自己场上有怪兽的场合才能发动。
【效果】选自己墓地1只怪兽（龙族/攻击力0/守备力1400）在自己场上表侧表示特殊召唤。这个效果把「背上小龙」特殊召唤的场合，再选那只怪兽以外的自己场上1只怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP047', '龙之呼应', '【条件】自己卡组的卡是10张以上，自己墓地的怪兽只有多头龙族·龙族的场合才能发动。
【效果】选自己墓地1只怪兽回到卡组。那之后，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP048', '转戒指×转戒指', '【条件】自己在这次主要阶段没有抽卡的场合，把手卡的怪兽（龙族·魔法师族/攻击力0/守备力1400）合计2只送去墓地才能发动。
【效果】自己抽3张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP23-JP052', '王牌剑一斩', '【条件】把2张手卡送去墓地或这个回合是后攻玩家的最初回合的场合才能发动。
【效果】选对方场上1张卡破坏。那之后，可以选自己墓地1只怪兽（光属性/机械族/攻击力2500/守备力1600）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP001', '叛骨装剑 盖加斯瓦尔格尔', '【条件】无
【永续效果】自己回合内，这张卡的攻击力上升1000。自己墓地有「叛骨之苏芙蕾思」的场合，这张卡不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP002', '叛骨装典 苏芙蕾楼罗', '【条件】无
【永续效果】原本种族是不死族的自己怪兽的攻击破坏怪兽送去墓地时，给与对方为［自己墓地的等级最高的怪兽的等级］×200伤害。自己墓地有「叛骨之盖加斯特」的场合，守备表示的这张卡不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP003', '髑岩王 华劣斯托姆', '怪兽（8星以下/不死族）×3
【条件】无
【永续效果】自己场上的魔法·陷阱卡不会被对方的效果破坏。对方回合内，这张卡和自己场上的魔法·陷阱卡不会因效果回到手卡·卡组·额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP004', '髑岩骑士 莫德纳', '这张卡可以把1只怪兽（不死族）解放攻击表示上级召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（风属性/不死族），那个攻击力直到回合结束时上升［自己场上的表侧表示怪兽（不死族）数量］×400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP005', '叛骨之盖加斯特', '【条件】自己墓地的怪兽是5只以上的场合，把手卡1只怪兽送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。这个回合，自己不能把表侧表示的这张卡为上级召唤而解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP006', '叛骨之镇法', '墓地的这张卡的卡名变成「叛骨之盖加斯特」。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的等级直到回合结束时上升1星。那之后，可以选自己墓地1只5星「叛骨之盖加斯特」加入手卡或在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP007', '髑岩妃 索普拉', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】自己卡组最上面的卡送去墓地。那之后，可以选自己墓地1只怪兽（3星/不死族/攻击力1200）或者1张「髑巌襲来」加入手卡。这个回合，自己不能把「髑岩妃 索普拉」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP008', '叛骨之苏芙蕾思', '【条件】把手卡1只怪兽送去墓地才能发动。
【效果】选对方场上1只怪兽把表示形式变更。自己墓地的怪兽是5只以上的场合，可以再选自己墓地1只「叛骨之盖加斯特」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP009', '叛骨装魂 梅尼尔', '【条件】这张卡召唤的回合，把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】选自己墓地1只「叛骨之盖加斯特」或者「叛骨之苏芙蕾思」和1张仪式术魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP010', '叛骨之梅尼', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】选自己场上1只表侧表示的「叛骨之盖加斯特」或者「叛骨之苏芙蕾思」。直到下次的对方回合结束时，那只怪兽的攻击力上升700，不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP011', '起死骸生的阵雨', '【条件】无
【效果】等级合计直到5以上的自己场上的表侧表示怪兽（不死族）作为素材送去墓地，把「叛骨装剑 盖加斯瓦尔格尔」仪式术召唤（不能把多余怪兽作为素材）。这个效果把原本卡名是「叛骨之盖加斯特」的怪兽送去墓地的场合，可以再选对方场上1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP012', '起死骸生的暴风', '【条件】无
【效果】等级合计直到3以上的自己场上的表侧表示怪兽（不死族）作为素材送去墓地，把「叛骨装典 苏芙蕾楼罗」仪式术召唤（不能把多余怪兽作为素材）。这个效果把原本卡名是「叛骨之苏芙蕾思」的怪兽送去墓地的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP013', '风吹的起死骸生', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（风属性/不死族）或者1张「叛骨的命运」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP014', '初始的起死骸生', '【条件】自己没有把「ビギニング・スカルライズ」发动的回合，把手卡1只「叛骨之盖加斯特」或者「叛骨之苏芙蕾思」送去墓地才能发动。
【效果】自己抽3张。自己墓地的怪兽是4只以上的场合，再选自己1张手卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP015', '髑岩袭来', '【条件】双方场上的怪兽数量是合计3只以上的场合才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，可以让自己的场上·墓地的怪兽（不死族）作为素材回到持有者卡组把怪兽（不死族/守备力0）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP016', '叛骨的命运', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】选自己场上最多2只攻击表示怪兽（5星以下/风属性/不死族）。这个回合，那些怪兽不会被战斗和对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP017', '骨脊鞭', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】选自己墓地1只怪兽（5星以下/不死族）加入手卡或在自己场上表侧表示特殊召唤。那之后，自己场上有表侧表示怪兽（风属性）的场合，可以选对方场上1只表侧表示怪兽（8星以上）回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP026', '火星心帽子', '【条件】这张卡召唤的回合才能发动。
【效果】选这张卡以外的自己的手卡·场上1张卡送去墓地。那之后，可以选自己墓地1只怪兽（炎属性/魔法师族/攻击力600以外）加入手卡。这个回合，自己不能把「火星心帽子」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP027', '火星心使魔', '【条件】这张卡召唤的回合，自己卡组的卡是10张以上的场合才能发动。
【效果】选这张卡以外的自己的手卡·场上2张卡送去墓地。那之后，自己墓地有「火星心少女」「火星」「火星幕帘」的其中任意种的场合，自己可以抽2张。这个回合，自己不用怪兽（炎属性/魔法师族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP032', '相变异态大飞蛾', '「进化之茧」＋怪兽（5星以上/地属性/昆虫族）
墓地的这张卡的卡名变成「大飞蛾」。
【条件】无
【永续效果】这张卡的卡名变成「大飞蛾」，不会被对方的效果破坏。自己怪兽（8星/昆虫族）的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP034', '飞蛾宝宝', '成长后会是什么样的虫子暂时还不清楚的小幼虫。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP035', '大飞蛾', '把自己场上1只表侧表示的「飞蛾宝宝」送去墓地，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【效果】无', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP036', '鼓动的进化之茧', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「进化之茧」。那之后，可以让包含这张卡的自己的场上·墓地的怪兽作为素材回到持有者卡组把「究极完全态大飞蛾」融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP037', '连装炮机甲铠', '自己场上有表侧表示怪兽（地属性/昆虫族）的场合，这张卡可以不用解放作召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（地属性/昆虫族），那个攻击力直到回合结束时上升700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP039', '进化之茧', '【条件】无
【效果】包含这张卡的自己的手卡·场上的怪兽作为素材送去墓地，把怪兽（8星以下/地属性/昆虫族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP040', '成群的昆虫人', '【条件】自己墓地有怪兽（地属性/昆虫族/守备力2000）的场合，把这张卡以外的自己的手卡·场上1只怪兽送去墓地才能发动。
【效果】选自己墓地1只怪兽（地属性/昆虫族/守备力2000）加入手卡。这个效果选「连装炮机甲铠」的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP041', '进化的飞蛾宝宝', '【条件】把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「飞蛾宝宝」。那之后，可以选自己墓地1只「飞蛾宝宝」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP042', '树海的魔草', '【条件】无
【效果】选自己场上1只怪兽送去墓地。那之后，可以选自己墓地1只效果怪兽（6～8星/地属性/昆虫族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP043', '软玉虫笛', '【条件】无
【效果】选自己墓地1只怪兽（2星以下/地属性/昆虫族）加入手卡。那之后，可以把自己的手卡·场上的怪兽（地属性/昆虫族）作为素材送去墓地把怪兽（6星以下/昆虫族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP044', '治愈之圣风 拉纳', '把这张卡以外的1张手卡送去墓地，这张卡可以从手卡往自己场上表侧守备表示特殊召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段，把1张手卡送去墓地才能发动。
【效果】选对方场上1张魔法·陷阱卡回到持有者手卡。那之后，可以把这张卡的表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP045', '霜净马 流镝马', '【条件】这张卡召唤的回合，自己的魔法与陷阱区域的卡是1张以下的场合才能发动。
【效果】选传说卡以外的自己墓地1张通常魔法卡在自己的魔法与陷阱区域盖放。这个回合，自己不能把那张卡和「霜浄馬ヤブメ」的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP046', '天始之怪依', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只怪兽（不死族/攻击力1200/守备力0）在自己场上表侧守备表示特殊召唤。这个效果把「天终之怪依」特殊召唤的场合，可以再选对方墓地最多2张卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP047', '天终之怪依', '【条件】无
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己从那之中选1张送去墓地。剩下的卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP048', '梦中之蝴蝶', '【条件】把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】选对方场上1只表侧表示怪兽，那个种族直到回合结束时变成昆虫族。自己或者对方场上有这张卡以外的表侧守备表示怪兽的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP049', '贸绩蚕 丝蛋白蚕', '【条件】自己场上有这张卡以外的表侧表示怪兽（昆虫族）的场合，从卡组上面把2张卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个种族直到回合结束时变成昆虫族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP050', '天堂始终之面妖姬', '「天始之怪依」＋「天终之怪依」
这张卡可以用接触融合术。
【条件】无
【永续效果】这张卡可以直接攻击。这张卡的战斗不会让自己受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP051', '土星力之宝珠', '【条件】自己场上有表侧表示怪兽（6星）的场合，把手卡1只怪兽送去墓地才能发动。
【效果】自己抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP052', '僵尸烟花', '【条件】把手卡1只怪兽（5星以上/不死族）给对方观看才能发动。
【效果】选自己墓地最多2只怪兽（6星以下/不死族）在自己场上表侧表示特殊召唤。那之后，选手卡1只怪兽（5星以上/不死族）送去墓地。这个回合，自己不能用怪兽（不死族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP053', '冥土女仆捣蛋', '【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】选对方墓地最多2只怪兽回到卡组。那之后，自己可以抽出［这个效果回去的效果怪兽（7星）的数量］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP054', '蛛穴丝网', '【条件】对方把怪兽召唤时，让自己墓地1只怪兽（昆虫族）回到卡组下面才能发动。
【效果】那只召唤的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP055', '火星心少女', '【条件】把手卡1只怪兽（4星以下）送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降500。那之后，可以选自己墓地的「火星」「火星幕帘」各最多1张在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP056', '卡片炮击士', '【条件】自己卡组的卡是10张以上的场合，从卡组上面把最多3张卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［这个效果的条件送去墓地的卡数量］×500。那之后，可以把自己场上的这张卡送去墓地。这个效果送去墓地的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP057', '火星', '【条件】无
【效果】给与对方200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP058', '神风防护罩 -大气之力-', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】对方场上的攻击表示怪兽全部回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP059', '死者苏生', '【条件】无
【效果】选自己或者对方的墓地1只怪兽在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/AP02-JP060', '火星幕帘', '【条件】自己墓地有怪兽（魔法师族）的场合，对方怪兽的攻击宣言时才能发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP000', '流星黑龙', '「真红眼黑龙」＋「流星之龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP001', '五神龙', '怪兽（龙族）×5
这张卡不用融合术召唤不能特殊召唤。
【条件】无
【永续效果】这张卡不会被和怪兽（暗属性·地属性·水属性·炎属性·风属性）的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP002', '百兽王 贝希摩斯', '这张卡可以把1只怪兽解放攻击表示上级召唤。那个场合，这张卡的原本攻击力变成2000。
【条件】这张卡召唤的回合才能发动。
【效果】自己墓地的怪兽（兽族）选［这张卡上级召唤时解放的怪兽数量］加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP003', '大巨角猛犸', '【条件】这张卡召唤的回合，把卡组最上面的卡送去墓地才能发动。
【效果】直到下次的对方回合结束时，这张卡是表侧表示的期间，双方不能把表侧表示怪兽（4星以下）的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP004', '合成魔兽 加泽特', '【条件】无
【永续效果】这张卡的攻击力上升［这张卡攻击表示上级召唤时解放的2只怪兽的原本攻击力合计］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP005', '传说的魔术师', '【条件】无
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从翻开的卡之中选1只怪兽送去墓地。剩下的卡回到卡组。那之后，可以选自己墓地1只传说通常怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP006', '傲慢之壶', '【条件】自己没有把魔法卡发动的回合才能发动。
【效果】自己抽2张。这个效果的发动后，直到回合结束时自己不能把魔法卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP007', '传说的战士-破坏剑士', '墓地的这张卡的卡名变成「破坏剑士」。
【条件】无
【永续效果】这张卡不能直接攻击。这张卡的攻击力上升［对方场上的表侧表示怪兽（龙族）数量］×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP008', '虚无魔人', '这张卡不能特殊召唤。
【条件】无
【永续效果】双方不能把怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP009', '恶魔战士', '【条件】自己场上有这张卡以外的表侧表示怪兽（恶魔族）的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之中有怪兽（6星/恶魔族）的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP010', '传说的剑士', '【条件】这张卡召唤的回合，让自己墓地1只怪兽回到卡组下面才能发动。
【效果】这张卡的攻击力直到回合结束时上升300。那之后，可以选自己墓地1只传说怪兽（战士族）加入手卡。加入的场合，这个回合，自己不用怪兽（天界战士族或者战士族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP011', '善变的女神', '【条件】对方场上有怪兽的场合才能发动。
【效果】进行1次投掷硬币。表的场合，这张卡的攻击力直到回合结束时上升1000。里的场合，自己场上的这张卡送去墓地，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP012', '黑魔术师的幕帘', '【条件】支付700基本分才能发动。
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从翻开的卡之中选「黑魔术师」「黑魔导士少女」合计最多2只加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP013', '传说的原石', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从翻开的卡之中选1只传说通常怪兽（龙族）在自己场上表侧表示特殊召唤。剩下的卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP014', '天使的施舍', '【条件】无
【效果】自己抽3张。那之后，自己选2张手卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP015', '破坏剑士', '【条件】无
【永续效果】这张卡的攻击力上升［对方场上的表侧表示怪兽（龙族）数量和对方墓地的怪兽（龙族）数量的合计］×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP016', '钢铁马 鞅论倍赌马', '【条件】无
【效果】进行［对方场上的表侧表示怪兽数量］的投掷硬币。那之内1次以上是表的场合，这个回合，这张卡可以作2次攻击。那之内3次都是表的场合，再在这个回合让这张卡的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP017', '钻石龙', '全身由钻石构成的龙。用耀眼的光来蒙蔽敌人的双眼。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP018', '恶魔召唤', '使用黑暗力量，迷惑人心的恶魔。在恶魔族中以相当强大的力量著称。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP019', '伟大魔兽 加泽特', '【条件】无
【永续效果】这张卡的攻击力上升［这张卡攻击表示上级召唤时解放的1只怪兽的原本攻击力］×2。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP020', '迅捷旅鼠', '【条件】这张卡召唤的回合，对方场上有怪兽的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以从这个效果送去墓地的卡之中选1只「迅捷旅鼠」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP021', '未熟的魔王', '【条件】无
【效果】从自己卡组上面把5张卡翻开，给双方确认。自己可以从翻开的卡之中选1只传说怪兽（恶魔族）加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP022', '最终战争', '【条件】把5张手卡送去墓地才能发动。
【效果】双方场上的卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP023', '大行进前夜', '【条件】把手卡1只怪兽（7星以上/兽族）给对方观看才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从翻开的卡之中选最多2只怪兽（4星以下/兽族）在自己场上里侧守备表示特殊召唤。剩下的卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP024', '龙族融合', '【条件】自己场上有表侧表示怪兽（7星以上/龙族）的场合才能发动。
【效果】自己场上的表侧表示的通常怪兽（龙族）1只和自己墓地的怪兽（龙族）1只以上作为素材回到持有者卡组作融合术召唤。这个回合，自己不用融合术怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP025', '融合', '【条件】无
【效果】自己的手卡·场上的怪兽作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP026', '原初的一挥', '【条件】对方怪兽的攻击宣言时，支付400基本分才能发动。
【效果】攻击的怪兽的攻击力直到回合结束时下降700。自己场上有表侧表示的传说通常怪兽的场合，可以再选对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP027', '退回', '【条件】对方把墓地的卡加入手卡时才能发动。
【效果】对方手卡随机选1张回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP028', '邪神之大灾害', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】双方场上的魔法·陷阱卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP029', '流星之龙', '从宇宙尽头坠落地球的流星之龙。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP030', '翼龙战士', '剑技出众的蜥蜴人。可以音速舞剑。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP031', '梅尔基多四面兽', '一边变换4张假面，一边发起4种攻击的怪物。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP032', '假面咒术师 诅咒之喉', '以诅咒的咒文念杀对手的假面怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP033', '哥布林掘穴队长', '【条件】自己墓地有「战士生还」或者「落穴」的场合，把卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降［自己墓地的「战士生还」「落穴」数量合计］×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP034', '升格的魔镜', '【条件】让这张卡以外的自己场上1只怪兽回到持有者卡组下面才能发动。
【效果】选自己墓地1只「恶魔的召唤」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP035', '恶魔盗贼-恶魔使役者', '【条件】把自己场上1只表侧表示怪兽（恶魔族）送去墓地才能发动。
【效果】选自己场上最多2只表侧表示怪兽（恶魔族）。这个回合，那些怪兽不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP036', '名匠 虎铁', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只通常怪兽（4星以下）或者1张装备魔法卡回到卡组上面。这个效果让传说怪兽或者「名匠の兜」回去的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP037', '龙破坏之证人', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1只「破坏剑士」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP038', '角子老虎机PG-7', '【条件】这张卡召唤的回合才能发动。
【效果】选持有进行投掷硬币效果的自己墓地1只怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP039', '陷穴鼹鼠', '【条件】这张卡召唤的回合，自己墓地有「落穴」的场合才能发动。
【效果】选自己墓地1张陷阱卡在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP040', '邪神之卖棺者', '【条件】自己墓地有「邪神之大灾害」的场合才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）破坏。那之后，可以选自己墓地1张传说卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP041', '飞兔', '【条件】自己场上有这张卡以外的表侧表示怪兽（兽族）的场合，让自己墓地1只怪兽（兽族）回到卡组上面才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降400。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP042', '手札活杀', '【条件】无
【效果】有手卡的玩家把手卡全部送去墓地。那之后，自己可以选自己场上1只表侧表示怪兽那个攻击力直到回合结束时上升［这个效果送去墓地的卡数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP043', '东洋的妖刀', '【条件】自己场上有表侧表示怪兽（7星以上/天界战士族或者战士族）的场合才能发动。
【效果】选对方场上1只表侧表示的通常怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP044', '魔歼光', '【条件】自己场上有表侧表示的「恶魔的召唤」的场合，把手卡1只怪兽（恶魔族）送去墓地才能发动。
【效果】对方场上的攻击表示怪兽（8星以下）全部破坏。这个回合，自己不能用效果怪兽攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP045', '名匠之兜', '【条件】可以给自己场上1只表侧表示怪兽装备。
【效果】装备怪兽的攻击力·守备力上升200。装备怪兽是「名匠 虎铁」或者原本等级是4星以下的传说怪兽的场合，再让攻击力上升［那只怪兽的原本攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP046', '野兽的激怒', '【条件】自己场上有表侧表示怪兽（兽族或者兽战士族）合计2只以上的场合才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，可以选自己墓地1张场地魔法卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP047', '强者的愉悦', '【条件】对方把怪兽召唤时才能发动。
【效果】选自己场上1只表侧表示的通常怪兽，那个攻击力·守备力直到回合结束时上升［对方召唤的那只怪兽的等级］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP048', '手札增刷', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】自己直到手卡变成5张为止抽卡，自己手卡全部给对方观看。那之中有怪兽的场合，再让自己回复［那些怪兽数量］×200基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP049', '潜入开始', '【条件】无
【效果】选自己手卡或者自己墓地1只通常怪兽（7星）在自己场上表侧表示特殊召唤。这个回合，这个效果特殊召唤的怪兽的攻击力上升700，不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP1-JP050', '七宝船', '【条件】把手卡1只怪兽送去墓地才能发动。
【效果】自己抽1张。这个效果的条件把怪兽（7星）送去墓地的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP001', '天使的施舍', '【条件】无
【效果】自己抽3张。那之后，自己选2张手卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP002', '强欲而谦虚之壶', '【条件】自己没有把怪兽特殊召唤的回合才能发动。
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己从那之中选1张加入手卡。剩下的卡回到卡组。这个回合，自己不能把怪兽特殊召唤，不能把「强欲而谦虚之壶」发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP003', '冰帝 美比乌斯', '【条件】这张卡攻击表示上级召唤的回合才能发动。
【效果】选自己或者对方场上的魔法·陷阱卡合计最多2张破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP004', '古代的机械巨人', '这张卡不能特殊召唤。
【条件】无
【永续效果】这张卡的攻击宣言时对方不能把陷阱卡发动，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP005', '古代的机械恐兽', '自己场上有持有永续效果的表侧表示怪兽（地属性/机械族）的场合，可以把这张卡召唤的场合需要的解放减少1只。
【条件】无
【永续效果】这张卡的攻击宣言时对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP006', '古代的机械强兵', '自己场上有表侧表示的「古代的机械巨人」「古代的机械士兵」「古代的机械兽」的其中任意种的场合，可以把这张卡召唤的场合需要的解放减少1只。
【条件】无
【永续效果】自己回合内，这张卡的攻击力上升1000。这张卡的攻击宣言时对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP007', '古代的机械兽', '这张卡不能特殊召唤。
【条件】无
【永续效果】这张卡的攻击宣言时对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP008', '古代的机械士兵', '【条件】无
【永续效果】这张卡的攻击宣言时对方不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP009', '古代的机械军医', '【条件】把自己场上1张魔法·陷阱卡送去墓地才能发动。
【效果】选持有永续效果的自己墓地1只怪兽（地属性/机械族）加入手卡。这个效果的条件把「齿车街区」或者「古代的机械炮击」送去墓地的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP010', '古代的机械给兵', '【条件】把自己场上1张魔法·陷阱卡送去墓地，让自己墓地2只怪兽（地属性/机械族）回到卡组才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。这个效果的条件把「齿车街区」送去墓地的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP011', '古代的齿车冠', '【条件】这张卡召唤的回合，自己墓地的怪兽只有机械族的场合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1张「齿车街区」或者「古代的机械变速」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP012', '古代的整备场', '【条件】无
【效果】选自己墓地1只攻击力·守备力是相同数值的效果怪兽（地属性/机械族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP013', '古代的机械变速', '【条件】可以给自己场上1只原本的攻击力·守备力是相同数值的表侧表示怪兽（地属性/机械族）装备。
【效果】装备怪兽的攻击力上升400。装备怪兽是「古代的机械巨人」或者「古代的机械兽」的场合，再让那个攻击力上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP014', '齿车街区', '【条件】无
【效果】只要这张卡在场地区域处于表侧表示，双方场上的表侧表示怪兽（地属性/机械族）的攻击力上升200，双方可以把攻击力·守备力是相同数值的怪兽（地属性/机械族）召唤的场合需要的解放减少1只。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP015', '古代的机械炮击', '【条件】对方怪兽的攻击宣言时，让自己墓地4只怪兽（机械族）回到卡组才能发动。
【效果】选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP016', '重钢铁徽章之阿修罗明星', '「虚钢演机」＋怪兽（9星/电子人族）
【条件】让1张手卡回到卡组下面才能发动。
【选择效果】●选自己墓地1只怪兽（9星/电子人族）在自己场上表侧守备表示特殊召唤。●选对方场上1只表侧表示怪兽（电子人族以外），这张卡的攻击力直到回合结束时上升［选的怪兽的攻击力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP017', '重钢铁徽章之弗栗多明星', '「虚钢演机」＋「钢铁徽章之弗栗多明星」
【条件】无
【选择效果】●选自己墓地1只怪兽（9星/电子人族）在自己场上表侧守备表示特殊召唤。●选对方场上1只表侧表示怪兽（电子人族以外）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP018', '钢铁徽章之美杜莎明星', '「虚钢演机」＋「邪恶耍球人」
【条件】让自己墓地1只怪兽回到卡组下面才能发动。
【选择效果】●选对方场上1张里侧表示的魔法·陷阱卡。那张卡直到下次的对方回合结束时不能发动。●选对方场上1只表侧表示怪兽（恶魔族）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP019', '钢铁徽章之格尼乌斯明星', '「虚钢演机」＋「吸引石人」
【条件】自己卡组的卡是10张以上的场合才能发动。
【选择效果】●自己抽1张。●选对方墓地最多6只怪兽（岩石族）回到卡组。那之后，给与对方1400伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP020', '钢铁徽章之阿修罗明星', '「虚钢演机」＋「剑舞者」
【条件】把卡组最上面的卡送去墓地才能发动。
【选择效果】●选对方场上1张里侧表示的卡破坏。●选自己场上1只表侧表示怪兽（电子人族），那个攻击力直到回合结束时上升［对方场上的表侧表示怪兽（战士族）的攻击力合计］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP021', '钢铁徽章之弗栗多明星', '「虚钢演机」＋「蛇蜿龙」
【条件】无
【选择效果】●选对方场上1只怪兽变成表侧攻击表示或者里侧守备表示。●对方场上的表侧表示怪兽（龙族）选最多有［自己场上的表侧表示怪兽（电子人族）数量］破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP022', '钢铁徽章之赫拉克勒斯明星', '「虚钢演机」＋「魔法杂耍人」
【条件】让自己墓地1张卡回到卡组下面才能发动。
【选择效果】●选对方墓地最多3只怪兽回到卡组。●选对方场上最多2只表侧表示怪兽（魔法师族）回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP023', '钢铁徽章之拉冬明星', '「虚钢演机」＋「优雅恐龙」
【条件】把1张手卡送去墓地才能发动。
【选择效果】●选对方场上1只表侧表示怪兽，那个攻击力·守备力直到回合结束时下降1500。●对方场上的全部表侧表示怪兽（恐龙族）的攻击力·守备力直到回合结束时下降2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP024', '钢铁徽章之眼镜王蛇明星', '「虚钢演机」＋「王冠蛇」
【条件】把1张手卡送去墓地才能发动。
【选择效果】●自己抽2张。那之后，自己选1张手卡送去墓地。●选对方场上最多3只表侧表示怪兽（爬虫类族），那些攻击力·守备力直到回合结束时下降1000。这个回合，这张卡可以作2次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP025', '虚钢再演机', '【条件】自己卡组的卡是10张以上的场合，从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡的卡名直到下次的对方回合结束时变成「虚钢演机」。那之后，可以选自己墓地1张「死者転生」回到卡组下面。回去的场合，再让自己可以抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP026', '吸引石人', '【条件】这张卡召唤的回合，把手卡1只通常怪兽（光属性/守备力500）给对方观看才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以给与对方500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP027', '邪恶耍球人', '【条件】把手卡1只怪兽（光属性/守备力500）给对方观看才能发动。
【效果】选对方场上1只表侧表示怪兽，那个种族直到回合结束时变成恶魔族或者和这个效果的条件给人观看的怪兽相同种族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP028', '幻想假面大师', '【条件】把额外卡组1只融合术怪兽（9星/电子人族）给对方观看，宣言1个在那只怪兽有作为素材记述的卡名才能发动。
【效果】这张卡的卡名在这个回合变成这个效果的条件宣言的卡名。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP029', '虚钢主演机', '【条件】从卡组上面把3张卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「虚钢演机」。那之后，可以选自己墓地的通常怪兽（光属性/守备力500）和「融合术」各最多1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP030', '虚钢演机', '没有除了笑以外的情感表现的机械人偶。以观众的情感为能源。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP031', '优雅恐龙', '不喜欢争斗的和蔼恐龙。总是温和地注视着观众。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP032', '蛇蜿龙', '住过清澈水潭的美丽之龙。现在以马戏团吉祥物的身份在观众中博得人气。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP033', '剑舞者', '曾经侍奉大国的厉害剑士。在观众注视下以准确无比的控制掷出飞剑。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP034', '魔法杂耍人', '对过去只字不提而充满谜团的男子。如魔法一般操纵着魔棒来俘虏观众。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP035', '王冠蛇', '总是很开朗爱亲近人的蛇。随着笛声跳起舞来让观众入迷。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP036', '钢铁徽章融合', '【条件】无
【效果】自己的手卡·场上的怪兽作为素材送去墓地，把怪兽（电子人族）融合术召唤。那之后，可以选自己墓地1张「融合术」或者这个效果送去自己墓地的1只怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP037', '虚钢演机名优', '【条件】无
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选1只通常怪兽（光属性/守备力500）或者1张「融合术」送去墓地。剩下的卡用喜欢的顺序回到卡组下面。送去墓地的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP038', '融合术', '【条件】无
【效果】自己场上的表侧表示怪兽作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP039', '死者转生', '【条件】自己墓地有怪兽的场合，把1张手卡送去墓地才能发动。
【效果】选自己墓地1只怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP040', '虚钢演机急转', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】自己的场上·墓地的怪兽作为素材回到持有者卡组，把怪兽（电子人族）融合术召唤。那之后，可以选对方场上1只表侧表示怪兽（8星以下）破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP045', '传说的射手', '【条件】把手卡1张传说卡给对方观看才能发动。
【效果】选对方场上最多2只怪兽把表示形式变更。这张卡是攻击表示的场合，可以再选自己墓地1只「传说的猎人」在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP046', '传说的猎人', '【条件】把手卡1张传说卡给对方观看才能发动。
【效果】选对方墓地最多2只怪兽回到卡组。这张卡是攻击表示的场合，可以再选自己墓地1只「レジェンド・シューター」在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP047', '传说的侦察者', '【条件】自己卡组的卡是10张以上的场合，把手卡1张传说卡给对方观看才能发动。
【效果】自己抽1张。那之后，自己选1张手卡送去墓地。这个回合，传说怪兽攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP048', '传说的魔术师', '【条件】无
【效果】从自己卡组上面把3张卡翻开，给双方确认。自己可以从那之中选1只怪兽送去墓地。剩下的卡回到卡组。那之后，可以选自己墓地1只传说通常怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP049', '传说的剑士', '【条件】这张卡召唤的回合，让自己墓地1只怪兽回到卡组下面才能发动。
【效果】这张卡的攻击力直到回合结束时上升300。那之后，可以选自己墓地1只传说怪兽（战士族）加入手卡。选的场合，这个回合，自己不用怪兽（天界战士族·战士族）不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP050', '古之决战', '【条件】无
【效果】选自己场上最多3只表侧表示怪兽（光属性/守备力300）。这个回合，那些怪兽的攻击力上升500，不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP051', '传说的一击', '【条件】支付300基本分才能发动。
【效果】选自己墓地1只怪兽（4星/攻击力1600以下）或者传说通常怪兽在自己场上表侧表示特殊召唤。这个效果把「レジェンド・マジシャン」或者传说通常怪兽特殊召唤的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP052', '传继的一闪', '【条件】把手卡1张传说卡送去墓地才能发动。
【效果】选对方场上1张卡破坏。那之后，自己墓地有传说怪兽（战士族）的场合，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP053', '传说之徽', '【条件】自己卡组的卡是10张以上，自己墓地有怪兽（光属性/守备力300）2只以上的场合才能发动。
【效果】选自己墓地1只传说怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP054', '现世之战', '【条件】对方回合对方抽卡时或者对方回合对方把怪兽召唤·特殊召唤时，让自己墓地1只传说怪兽回到卡组才能发动。
【效果】选自己场上最多3只表侧表示怪兽。这个回合，那些怪兽的攻击力上升1200，不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP055', '白骨', '任何地方都会出现的骸骨怪。攻击很弱但聚集起来非同小可。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP056', '白骨王', '【条件】无
【永续效果】这张卡的攻击力上升［自己墓地的「白骨王」「白骨」数量合计］×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP057', '白骨男爵', '对方回合内，墓地的这张卡的卡名变成「白骨」。
【条件】把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】自己把卡组最上面的卡送去墓地。那之后，自己墓地有「白骨」或者「白骨王」的场合，可以再从自己卡组上面把2张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP058', '影之食尸鬼', '【条件】无
【永续效果】这张卡的攻击力上升［自己墓地的怪兽数量］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP059', '僵尸烟花', '【条件】把手卡1只怪兽（5星以上/不死族）给对方观看才能发动。
【效果】选自己墓地最多2只怪兽（6星以下/不死族）在自己场上表侧表示特殊召唤。那之后，自己选手卡1只怪兽（5星以上/不死族）送去墓地。这个回合，自己不能用怪兽（不死族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP060', '火焰支配者', '【条件】无
【永续效果】怪兽（炎属性）攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP061', '传说的种火', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，自己墓地有传说怪兽（炎属性/炎族）的场合，可以选对方场上最多2只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP062', '化学化火精灵', '【条件】让自己墓地3只怪兽（炎族）回到卡组才能发动。
【效果】对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降［对方墓地的怪兽数量］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP063', '火轰岚凰 化学火山化凤凰［L］', '【条件】让自己墓地1只怪兽（炎属性/雷族）回到卡组才能发动。
【效果】选对方场上1只表侧表示怪兽（9星以下）破坏。这张卡是极大模式的场合，可以再选对方场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP064', '火轰岚凰 化学火山化凤凰', '可以和「火轰岚凰 化学火山化凤凰［L］」「火轰岚凰 化学火山化凤凰［R］」集齐作极大召唤。
【条件】极大模式：把手卡1只怪兽（炎属性或者炎族）送去墓地才能发动。
【效果】给与对方1000伤害。并且再在这个回合让这张卡不会被对方的陷阱卡的效果破坏，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP065', '火轰岚凰 化学火山化凤凰［R］', '【条件】让自己墓地1只怪兽（炎属性/水族）回到卡组才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。这张卡是极大模式的场合，可以再选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP066', '秩序守护者', '「秩序守护者」以外的自己场上的表侧表示怪兽（光属性）是2只的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【效果】无', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP067', '风帝 莱扎', '【条件】这张卡攻击表示上级召唤的回合才能发动。
【效果】选自己或者对方场上1张卡回到持有者卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP068', '深渊士兵', '【条件】把手卡1只怪兽（水属性）送去墓地才能发动。
【效果】选自己或者对方场上1张卡回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP069', 'RAM云雄羊', '【条件】自己没有把「RAM云雄羊」的效果发动的回合才能发动。
【效果】选自己场上1只怪兽送去墓地。那之后，可以选自己墓地1只怪兽（电子界族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP070', '接合科技狮', '【条件】这张卡召唤的回合才能发动。
【效果】自己选对方墓地1张魔法·陷阱卡。对方把那张卡在自身场上盖放。那之后，自己可以选自己墓地1只怪兽（7星以上/地属性/机械族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP071', '劈裂史莱姆', '【条件】把自己场上1只表侧表示怪兽（攻击力1500以上）送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降1000。那之后，可以选自己墓地1只效果怪兽（4星/攻击力1500以上）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP072', '傲慢之壶', '【条件】自己没有把魔法卡发动的回合才能发动。
【效果】自己抽2张。这个效果的发动后，直到回合结束时自己不能把魔法卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP073', '天之招来', '【条件】无
【效果】从自己卡组上面把3张卡送去墓地。自己场上没有怪兽的场合，可以再选自己墓地1只怪兽（10星）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP074', '起始之星', '【条件】支付500基本分才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以从自己墓地的通常怪兽（5星以下）、「融合术」、「融合」之中选1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP075', '飓风', '【条件】无
【效果】这张卡以外的双方场上的魔法·陷阱卡全部回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP076', '黑洞', '【条件】无
【效果】双方场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP077', '融合', '【条件】无
【效果】自己的手卡·场上的怪兽作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP078', '激流葬', '【条件】自己或者对方把怪兽召唤·特殊召唤时才能发动。
【效果】双方场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP079', '魔法筒', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】那次攻击无效，给与对方为［那只怪兽的攻击力］的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/LGP2-JP080', '蓄积硫酸的落穴', '【条件】对方从手卡把怪兽召唤·盖放时或者对方把魔法卡发动后才能发动。
【效果】选对方场上1只里侧表示怪兽确认。那只怪兽的原本守备力是2000以下的场合，再把那只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP000', '恶魔召唤', '使用黑暗力量，迷惑人心的恶魔。在恶魔族中以相当强大的力量著称。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP001', '甲虫装甲骑士', '昆虫战士当中只有精英中的精英才能加入的「无死虫团」的精锐骑士。他们的高强战斗能力不可无视。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP002', '银红脉冲星', '【条件】对方场上有表侧表示怪兽（7星以上）的场合才能发动。
【效果】选自己手卡或者自己墓地1只通常怪兽（7星/银河族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP003', '哨兵军官', '【条件】自己墓地的怪兽只有银河族的场合才能发动。
【效果】自己的手卡·场上的怪兽（光属性）1只和怪兽（暗属性）1只作为素材送去墓地，把怪兽（9星/光属性/银河族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP004', '混沌闪亮星', '【条件】把手卡1只怪兽（光属性·暗属性/银河族）送去墓地才能发动。
【效果】自己抽1张。这个回合，「银河星忘却龙」或者「虚空噬骸兵 镇魂鹰巨人」攻击表示上级召唤的场合，表侧表示的这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP005', '混沌核球巨人', '【条件】让自己墓地的怪兽（光属性·暗属性/银河族）合计2只用喜欢的顺序回到卡组下面才能发动。
【效果】选自己墓地1只「银河星忘却龙」或者「虚空噬骸兵 镇魂鹰巨人」在自己场上里侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP006', '旋涡混沌射手', '【条件】让自己墓地的怪兽（光属性·暗属性/银河族）合计2只用喜欢的顺序回到卡组下面才能发动。
【效果】选自己墓地的通常怪兽（攻击力1600/银河族）和「银河混沌融合」各最多1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP007', '变星升龙', '【条件】把额外卡组1只融合术怪兽（9星/银河族）给对方观看，宣言1个在那只怪兽有作为素材记述的卡名才能发动。
【效果】这个回合，自己把表侧表示的这张卡用「融合术」的效果作为融合术召唤的素材的场合，那个卡名变成这个效果的条件宣言的卡名。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP008', '银河舰忘却龙·方舟', '【条件】让自己墓地2只通常怪兽回到卡组才能发动。
【效果】这张卡直到下次的对方回合结束时不会被效果破坏。这张卡召唤·特殊召唤的自己主要阶段把这个效果发动的场合，可以再给与对方为［自己场上的怪兽数量］×400伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP009', '虚空噬骸兵·宇宙星兵', '【条件】让自己墓地3只怪兽（暗属性/银河族）回到卡组才能发动。
【效果】自己场上的这张卡送去墓地。那之后，可以选对方场上1张魔法·陷阱卡破坏。破坏的场合，可以再选自己墓地1张「宇宙风暴」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP010', '虚空噬骸兵·伙友骑兵', '【条件】这张卡召唤的回合，自己场上有这张卡以外的表侧表示怪兽（银河族）的场合，把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】这张卡的守备力直到下次的对方回合结束时上升1300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP011', '宇宙树顶苍鹰', '【条件】无
【永续效果】这张卡的攻击力上升［自己场上的表侧表示的融合术怪兽数量］×800。自己场上的攻击表示怪兽（电子界族）不会因对方的效果变成守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP012', '昆遁忍虫 念珠之空蝉', '【条件】无
【永续效果】持有永续效果的自己怪兽（暗属性/昆虫族）的攻击带有贯通。自己怪兽（昆虫族）的战斗不会让自己受到战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP013', '昆遁忍虫 迷网之蜘蛛', '【条件】无
【永续效果】自己场上的表侧表示怪兽的原本种族只有昆虫族，对方向表侧表示怪兽攻击的场合，只能向自己场上的攻击力最高的怪兽攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP014', '昆遁忍虫 刺又之独角仙', '【条件】无
【永续效果】自己场上有这张卡以外的表侧表示怪兽（昆虫族）的场合，这张卡不会被和怪兽（攻击力2000以上）的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP015', '昆遁忍虫 变妖魔笛之凤蝶', '【条件】无
【永续效果】对方场上的表侧表示怪兽的种族变成昆虫族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP016', '昆遁忍虫 红莲天刀之七星瓢虫', '【条件】无
【永续效果】这张卡的攻击力上升［双方场上的表侧表示怪兽（昆虫族）数量］×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP017', '天才吉他手 ～敏捷混音～', '墓地的这张卡的卡名变成「天才吉他手」。
【条件】无
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以让自己场上的全部表侧表示怪兽的攻击力直到回合结束时上升［自己墓地的「朋友！」数量］×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP018', '觉醒的剑背角龙', '【条件】自己墓地的怪兽只有恐龙族的场合，支付500基本分才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以选自己墓地1张怪兽（地属性/恐龙族/攻击力1100）或者「奇跡の超進化」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP019', '恐龙驾帝 恐龙帝王', '这张卡可以把1只怪兽（恐龙族）解放攻击表示上级召唤。
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选自己或者对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降800。那之后，可以选自己墓地1只极大怪兽（恐龙族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP020', '恶魔咒术师', '【条件】把手卡1只怪兽（暗属性/恶魔族）送去墓地才能发动。
【效果】自己抽1张。那之后，可以选对方场上1只表侧表示怪兽（3星以上）那个等级直到回合结束时下降2星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP021', '恶魔传令', '【条件】自己场上有表侧表示的「恶魔的召唤」的场合才能发动。
【效果】选对方场上1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP022', '恶魔枪兵', '【条件】自己场上有表侧表示的「恶魔的召唤」的场合，这张卡召唤的回合才能发动。
【效果】选对方场上1只怪兽破坏。那之后，自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP023', '惑乱的骸骨恶魔', '手卡或者墓地的这张卡的卡名变成「恶魔的召唤」。
【条件】把手卡1只怪兽（暗属性/恶魔族）送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「恶魔的召唤」。那之后，可以选极大怪兽以外的对方场上1只表侧表示怪兽（8星以下）得到那个控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP024', '卡片防御士', '【条件】无
【永续效果】对方回合内，自己场上的魔法·陷阱卡不会因效果回到手卡·卡组·额外卡组。自己场上有表侧表示的通常怪兽（战士族）或者融合术怪兽（战士族）的场合，自己场上的表侧表示怪兽的攻击力上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP025', '备用零件', '【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升800。那之后，可以选自己墓地的「绿色零件」「红色零件」「黄色零件」的其中1只加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP026', '魔力动物商人', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选自己墓地的「魔力动物硬币」「魔力动物护盾」各最多1张加入手卡。这个效果把2张加入手卡的场合，再把自己场上的这张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP027', '魔力动物守卫者', '【条件】这张卡召唤·特殊召唤的自己主要阶段，把1张手卡送去墓地才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之后，可以选自己墓地1只怪兽（7·8星/光属性/兽族/守备力1500以上）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP028', '魔力动物巫师', '【条件】无
【永续效果】自己场上的表侧表示怪兽（兽族）的攻击力·守备力上升400，那攻击带有贯通。自己场上的表侧表示怪兽（光属性/兽族）的等级上升2星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP029', '魔力动物骑士', '【条件】无
【永续效果】自己场上的表侧表示怪兽（兽族）不会被对方的效果破坏。自己场上的表侧表示怪兽（光属性/兽族）的等级上升2星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP030', '魔力动物双剑士', '【条件】无
【永续效果】自己把怪兽（兽族）表侧表示召唤·特殊召唤时对方不能把陷阱卡发动。自己场上的表侧表示怪兽（光属性/兽族）的等级上升2星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP031', '魔力动物鞭手', '这张卡可以把1只怪兽（光属性）解放攻击表示上级召唤。
【条件】让自己墓地1只怪兽（兽族）回到卡组下面才能发动。
【效果】选持有比这张卡的等级低的等级的对方场上1只表侧表示怪兽，那个攻击力直到回合结束时下降2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP032', '魔力动物射手', '这张卡可以把1只怪兽（光属性）解放攻击表示上级召唤。
【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】选对方场上1只怪兽把表示形式变更。那之后，可以选持有比这张卡的等级低的等级的对方场上1只表侧表示怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP033', '梦中之钩蛱蝶', '【条件】自己场上有这张卡以外的表侧表示怪兽（光属性/昆虫族）的场合，把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】选对方场上1只表侧表示怪兽（3星以上），那个等级直到回合结束时下降2星。那之后，可以选对方场上1只表侧表示怪兽那个种族直到下次的对方回合结束时变成昆虫族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP034', '梦中之丽天牛', '【条件】自己卡组的卡是10张以上的场合，把1张手卡送去墓地才能发动。
【效果】自己抽1张。那之后，可以选自己墓地1只「梦中丝绸蚕」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP035', '绝望狂魔 死线魔', '【条件】这张卡召唤的回合，把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1只「绝望狂魔 死局魔」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP036', '圣丽的冻姬 艾丝', '【条件】这张卡召唤的回合才能发动。
【效果】选自己手卡或者自己墓地1只怪兽（战士族/攻击力2500/守备力2500）在自己场上表侧守备表示特殊召唤。那之后，可以选自己场上1只表侧表示怪兽（水属性）把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP037', '气球动物伙伴', '【条件】自己没有把怪兽特殊召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以从那之中选1只怪兽（6星以下）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP038', '叉犀强力独角仙', '【条件】自己墓地有怪兽（暗属性/昆虫族）4只以上的场合才能发动。
【效果】选持有永续效果的自己墓地最多2只怪兽（昆虫族/守备力400）在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP039', '茧蛹大王独角仙', '【条件】自己卡组的卡是10张以上的场合，把手卡1只怪兽（暗属性/昆虫族）送去墓地才能发动。
【效果】自己抽1张。自己墓地有怪兽（暗属性）2只以上的场合，可以再从自己卡组上面把3张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP040', '食魂者 巴祖', '【条件】让自己墓地最多3只怪兽用喜欢的顺序回到卡组下面才能发动。
【效果】这张卡的攻击力直到下次的对方回合结束时上升［这个效果的条件回去的怪兽数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP041', '混沌哨兵', '怪兽（攻击力1500以上）＋怪兽（攻击力1500以下）
这张卡不用「哨兵军官」「银河混沌融合」的效果不能特殊召唤。
【条件】无
【永续效果】对方回合内，自己场上的魔法·陷阱卡不会因效果回到手卡·卡组·额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP042', '银河舰失落忘却龙', '「银河星忘却龙」＋怪兽（7·8星/银河族）
【条件】让自己墓地1只通常怪兽回到卡组才能发动。
【效果】对方场上的里侧表示怪兽全部变成表侧攻击表示，这张卡的攻击力直到回合结束时上升700。那之后，可以把原本攻击力是2500以下的对方场上的表侧表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP043', '银河舰混沌忘却龙', '「银河星忘却龙」＋「虚空噬骸兵 镇魂鹰巨人」
【条件】无
【永续效果】这张卡不会被效果破坏，这张卡的攻击力上升［自己墓地的通常怪兽（银河族）数量］×300。对方场上没有魔法·陷阱卡的场合，这张卡的攻击力上升1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP044', '虚空噬骸兵·禁忌镇魂鹰巨人', '「虚空噬骸兵 镇魂鹰巨人」＋「虚空噬骸兵 苍白骑士」
这张卡可以用接触融合术。
【条件】从卡组上面把3张卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升900。那之后，可以把对方场上的卡选最多有［这个效果的条件送去墓地的怪兽（暗属性/银河族/攻击力1600以上）数量］破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP045', '骰子炸药美腿女郎·火焰小双骰', '「骰子炸药少女·小双骰」＋「骰子小钥心·小合」
【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】掷2次骰子。出现数目合计的效果适用。
●7·11：对方场上的怪兽全部破坏。那之后，这张卡的攻击力直到回合结束时上升2000。
●那以外：这张卡的攻击力直到下次的对方回合结束时上升［出现的数目合计］×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP046', '小麦布料得墨忒耳·炖锅', '「小麦布料得墨忒耳」＋「电子界香料忍炖锅」
【条件】无
【永续效果】这张卡不会被对方的效果破坏。自己怪兽（7星以上/炎属性）的攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP047', '耳语喵妖精', '「耳语妖精」＋怪兽（4星以下/地属性）
这张卡可以用接触融合术。
【条件】这张卡融合术召唤的自己主要阶段才能发动。
【效果】选对方场上1张魔法·陷阱卡回到持有者卡组下面。那之后，可以选自己墓地1只「はぐれ使い魔」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP048', '恶魔显现', '「恶魔的召唤」＋怪兽（暗属性）
【条件】无
【永续效果】这张卡的卡名变成「恶魔的召唤」。自己场上的表侧表示的「恶魔的召唤」的攻击力上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP049', '磁石骑士β', '「磁石战士β」＋怪兽（4星以下/岩石族）
【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽。这个回合，那只怪兽的攻击力上升300，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP050', '绮罗流圣之交融公主', '「流圣之交融公主」＋通常怪兽
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力直到下次的对方回合结束时下降1700。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP051', '银河混沌融合', '【条件】无
【效果】自己的手卡·场上的怪兽（光属性/银河族）1只和怪兽（暗属性/银河族）1只作为素材送去墓地，把怪兽（9星/银河族）融合术召唤。这个效果把原本等级是7星以上的场上的怪兽2只送去墓地的场合，可以再选对方场上最多2张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP052', '虚空尘融合', '【条件】让自己墓地1只通常怪兽（暗属性/银河族）回到卡组才能发动。
【效果】自己墓地的怪兽（暗属性/银河族）2只作为素材回到卡组，把怪兽（9星/暗属性/银河族/守备力2000以上）融合术召唤。这个回合，自己不用由这个效果特殊召唤的怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP053', '昆遁忍法-蓝隐虫', '【条件】把手卡1只通常怪兽或者怪兽（4星以下/昆虫族）送去墓地才能发动。
【效果】选持有永续效果的自己墓地1只怪兽（5～8星/暗属性/昆虫族/守备力400）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP054', '昆遁忍法-五翅二虫', '【条件】把手卡1只怪兽（昆虫族）送去墓地才能发动。
【效果】从自己卡组上面把5张卡翻开，给双方确认。自己可以从那之中选最多2只怪兽（暗属性/昆虫族/守备力400）加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP055', '恶魔的供物', '【条件】让自己墓地2只怪兽（恶魔族）用喜欢的顺序回到卡组下面才能发动。
【效果】选对方场上1只表侧表示怪兽（8星以下）。这个回合，自己把「恶魔的召唤」攻击表示上级召唤的场合，可以作为自己场上1只怪兽的代替而把选的对方的表侧表示怪兽解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP056', '魔力动物硬币', '【条件】无
【效果】选自己场上1只怪兽送去墓地。那之后，可以选自己墓地1只怪兽（7·8星/光属性/兽族/守备力1500以上）加入手卡。这个效果的发动后，直到回合结束时自己不能把原本等级是6星以下的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP057', '魔力动物护盾', '【条件】可以给自己场上1只表侧表示怪兽（光属性/兽族）装备。
【效果】装备怪兽的攻击力·守备力上升600，等级上升3星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP058', '梦翔之爱', '【条件】把自己场上1只表侧表示怪兽（昆虫族）送去墓地才能发动。
【效果】自己抽2张。这个回合，自己不能用怪兽（昆虫族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP059', '摆尾攻击', '【条件】无
【效果】选自己场上1只表侧表示怪兽（5星以上/恐龙族）。选持有比那只怪兽的等级低的等级的对方场上的表侧表示怪兽或者对方场上的里侧表示怪兽合计最多2只回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP060', '镇魂回击', '【条件】自己基本分比对方少2500以上的场合，由自己的表侧表示的「虚空噬骸兵 镇魂鹰巨人」承受攻击的对方怪兽的攻击宣言时才能发动。
【效果】那次攻击无效。那之后，可以给与对方为［攻击的怪兽的攻击力］的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP061', '任务完了', '【条件】对方把怪兽召唤时，让自己墓地1只怪兽（7星）或者1张「潜入开始」回到卡组下面才能发动。
【效果】那只召唤的怪兽破坏。那之后，自己可以直到手卡变成5张为止抽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP062', '恶魔的雷击', '【条件】自己场上有表侧表示怪兽（6星以上/暗属性/恶魔族）的场合，对方把怪兽召唤时才能发动。
【效果】选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP063', '魔力动物威严', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】选自己场上1只表侧表示怪兽（光属性/兽族）。选持有比选的怪兽的等级低的等级的对方场上最多2只表侧表示怪兽变成里侧守备表示。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP064', '骨脊鞭', '【条件】对方把怪兽召唤·特殊召唤时才能发动。
【效果】选自己墓地1只怪兽（5星以下/不死族）加入手卡或在自己场上表侧表示特殊召唤。那之后，自己场上有表侧表示怪兽（风属性）的场合，可以选对方场上1只表侧表示怪兽（8星以上）回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP065', '元素英雄 电流翼侠', '「元素英雄 电光侠」＋「元素英雄 羽翼侠」
这张卡不用融合术召唤不能特殊召唤。
【条件】这张卡特殊召唤的自己主要阶段才能发动。
【效果】自己墓地的怪兽作为素材回到卡组，把不用融合术召唤不能特殊召唤的怪兽（6～8星/战士族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/KP20-JP066', '奇迹接触', '【条件】无
【效果】自己的场上·墓地的怪兽作为素材回到持有者卡组，把有「元素英雄 新宇侠」的卡名作为素材记述的怪兽融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP001', '真红眼极炎龙［L］', '【条件】无
【永续效果】这张卡不会被效果破坏。极大模式的这张卡战斗破坏怪兽送去墓地时，给与对方2400伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP002', '真红眼极炎龙', '可以和「真红眼极炎龙［L］」「真红眼极炎龙［R］」集齐作极大召唤。
【条件】这张卡召唤的回合或者这张卡是极大模式的场合才能发动。
【效果】选对方场上1张里侧表示的卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP003', '真红眼极炎龙［R］', '【条件】无
【永续效果】对方回合内，自己场上的魔法·陷阱卡不会因效果回到手卡·卡组·额外卡组。把这张卡作为融合术召唤的素材的场合，这张卡的卡名变成「真红眼黑龙」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP004', '暗黑魔龙', '「恶魔的召唤」＋「真红眼黑龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP005', '暗黑龙魔', '「恶魔的召唤」＋「真红眼黑龙」
【条件】把卡组最上面的卡送去墓地才能发动。
【效果】自己场上的全部表侧表示怪兽的攻击力直到回合结束时上升500。那之后，可以把对方场上的表侧表示怪兽（攻击力3100以下）全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP006', '流星骸骨恶魔', '「恶魔的召唤」＋怪兽（地属性/龙族/攻击力1800）
【条件】无
【永续效果】对方回合内，自己场上的怪兽不会因效果回到手卡·卡组·额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP007', '流星黑龙', '「真红眼黑龙」＋「流星之龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP008', '流星黑火星龙', '「真红眼黑龙」＋「流星之龙」
【条件】自己墓地有「流星之龙」的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升［自己墓地的怪兽数量］×200，那攻击带有贯通。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP009', '流星黑龙兽', '「真红眼黑龙」＋「流星之龙兽」
【条件】自己墓地有「流星炎融合」的场合，把卡组最上面的卡送去墓地才能发动。
【效果】这张卡直到下次的对方回合结束时不会被对方的效果破坏。自己墓地有「流星炎融合」2张以上的场合，再给与对方500伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP010', '流星群龙', '「流星之龙」＋「流星之龙兽」
【条件】无
【效果】选自己墓地1只怪兽（地属性/龙族/攻击力1800）在自己场上表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP011', '决战的骸骨恶魔', '手卡或者墓地的这张卡的卡名变成「恶魔的召唤」。
【条件】把1张手卡送去墓地才能发动。
【效果】这张卡的卡名在这个回合变成「恶魔的召唤」。那之后，可以选自己墓地1只通常怪兽（7星以下）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP012', '真红眼冥龙', '【条件】这张卡召唤的回合才能发动。
【效果】自己的场上·墓地的怪兽作为素材回到持有者卡组，把效果怪兽以外的怪兽（暗属性·炎属性）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP013', '流星之龙兽', '自己场上没有怪兽的场合，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选1只「流星之龙」或者1张「流星炎融合」加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP014', '火箭卫星兵', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只「流星之龙」或者1张「流星炎融合」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP015', '真红眼月龙', '手卡的这张卡的卡名变成「真红眼黑龙」。
【条件】无
【永续效果】把这张卡作为融合术召唤的素材的场合，这张卡的卡名变成「真红眼黑龙」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP016', '真红眼雷龙', '【条件】这张卡召唤·特殊召唤的自己主要阶段才能发动。
【效果】从自己卡组上面把4张卡翻开，给双方确认。自己可以从那之中选1只「真红眼冥龙」或者「真红眼月龙」加入手卡。剩下的卡用喜欢的顺序回到卡组下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP017', '变形史莱姆-恶魔龙形态', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】自己的手卡·场上的怪兽作为素材送去墓地，把有「恶魔的召唤」或者「真红眼黑龙」的卡名作为素材记述的怪兽融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP018', '陨石龙之雏', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只怪兽（地属性/龙族/攻击力1800）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP019', '无貌之死路魔', '把这张卡以外的手卡1只怪兽（恶魔族）给对方观看，这张卡可以从手卡往自己场上表侧表示特殊召唤。
【条件】无
【永续效果】自己场上的表侧表示怪兽（恶魔族）的攻击力上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP020', '恶魔战士', '【条件】自己场上有这张卡以外的表侧表示怪兽（恶魔族）的场合才能发动。
【效果】从自己卡组上面把3张卡送去墓地。那之中有怪兽（6星/恶魔族）的场合，再让自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP021', '日食角魔龙', '【条件】这张卡召唤·特殊召唤的自己主要阶段，对方场上的表侧表示怪兽的等级合计是10星以上的场合才能发动。
【效果】选自己墓地1只怪兽（暗属性/龙族·恶魔族/守备力1200）加入手卡。这个回合，自己不能用效果怪兽（6星以下）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP022', '极臣魔龙 扎哈克', '【条件】把手卡1只怪兽送去墓地才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选自己墓地1只极大怪兽（10星/暗属性/龙族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP023', '无力化龙', '【条件】这张卡召唤的回合才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，自己墓地有「攻击无力化」的场合，可以选对方场上最多3只表侧表示怪兽那些攻击力直到下次的对方回合结束时下降2000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP024', '升格的魔镜', '【条件】让这张卡以外的自己场上1只怪兽回到持有者卡组下面才能发动。
【效果】选自己墓地1只「恶魔的召唤」在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP025', '凤凰龙', '【条件】自己墓地有怪兽（5星以上/龙族）的场合，把1张手卡送去墓地才能发动。
【效果】选自己墓地1只怪兽（5星以上/龙族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP026', '流星之龙', '从宇宙尽头坠落地球的流星之龙。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP027', '黑炎弹', '【条件】自己场上有表侧表示的「真红眼黑龙」的场合才能发动。
【效果】给与对方2400伤害。这个回合，自己不能用「真红眼黑龙」攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP028', '燃召暗黑流星弹', '【条件】让自己墓地2只怪兽回到卡组才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。那之后，可以选效果怪兽以外的自己墓地1只融合术怪兽（暗属性·炎属性）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP029', '流星炎融合', '【条件】无
【效果】包含「真红眼黑龙」「恶魔的召唤」「流星之龙」其中任意种的自己的手卡·场上的怪兽2只作为素材送去墓地作融合术召唤。这个效果把效果怪兽以外的怪兽特殊召唤的场合，可以再选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP030', '对峙的黑龙', '【条件】自己场上有表侧表示怪兽（7星以上/暗属性·炎属性/龙族）的场合，对方把效果怪兽召唤时才能发动。
【效果】那只召唤的怪兽变成里侧守备表示。对方手卡是3张以上的场合，可以再把对方手卡随机选1张送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP031', '大剑龙驾 恐龙联力车［L］', '手卡的这张卡的卡名变成「大恐龙驾 恐龙联力车［L］」。
【条件】极大模式：把卡组最上面的卡送去墓地才能发动。
【效果】选对方场上1只怪兽回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP032', '大恐龙驾 恐龙联力车', '可以和「大恐龙驾 恐龙联力车［L］」「大恐龙驾 恐龙联力车［R］」集齐作极大召唤。
【条件】极大模式：对方场上没有表侧表示怪兽（9星以上）的场合，把手卡1只怪兽送去墓地才能发动。
【效果】选对方场上最多2只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP033', '大铠龙驾 恐龙联力车［R］', '手卡的这张卡的卡名变成「大恐龙驾 恐龙联力车［R］」。
【条件】从卡组上面把2张卡送去墓地才能发动。
【效果】这张卡直到下次的对方回合结束时不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP034', '大恐龙驾 恐龙联力车［L］', '【条件】极大模式
【永续效果】这张卡不会被和怪兽（7星以下）的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP035', '大恐龙驾 恐龙联力车［R］', '【条件】极大模式
【永续效果】这张卡不会被对方的陷阱卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP036', '极超成金恐龙王', '「超级恐龙王」＋「成金恐龙王」
【条件】让自己墓地1只怪兽（恐龙族）回到卡组上面或下面才能发动。
【效果】这张卡的攻击力直到回合结束时上升700。自己墓地有「成金哥布林」的场合，可以再选自己墓地1张魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP037', '腕龙', '「双头恐龙王」＋「贪尸龙」', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP038', '恐龙驾 恐龙车暴龙', '【条件】自己墓地的怪兽只有恐龙族的场合，把自己场上1张卡送去墓地才能发动。
【效果】选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP039', '恐龙驾 恐龙车角龙', '【条件】这张卡召唤的回合，自己墓地的怪兽只有恐龙族的场合才能发动。
【效果】选自己墓地1只极大怪兽（地属性/恐龙族）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP040', '成金恐龙王', '【条件】对方手卡是0张的场合才能发动。
【效果】双方抽1张。那之后，自己可以选自己墓地1张「成金哥布林」在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP041', '抑龙 斯氏风神翼龙', '【条件】这张卡召唤的回合才能发动。
【效果】选自己墓地1只怪兽（4星/恐龙族/守备力1200）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP042', '收集的白金小翼龙', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只怪兽（8·10星/恐龙族）或者1张「恐龙体温」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP043', '超级恐龙王', '【条件】这张卡召唤·特殊召唤的自己主要阶段，自己墓地有通常怪兽（6星以下/恐龙族）的场合，把卡组最上面的卡送去墓地才能发动。
【效果】选自己墓地1只通常怪兽（6星以下/恐龙族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP044', '愤碎龙 凶怒甲龙', '【条件】自己场上有这张卡以外的表侧表示怪兽（恐龙族）的场合，把卡组最上面的卡送去墓地才能发动。
【效果】对方场上的攻击力最高的表侧表示怪兽全部的攻击力直到回合结束时下降［自己场上的守备力最高的表侧表示怪兽的守备力］。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP045', '龙骸之角龙魂', '【条件】自己墓地有通常怪兽（恐龙族）的场合，从卡组上面把2张卡送去墓地才能发动。
【效果】选自己场上1只表侧表示怪兽（恐龙族），那个攻击力直到回合结束时上升［自己墓地的通常怪兽（恐龙族）数量］×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP046', '贪尸龙', '拥有咬碎一切之口的恐龙。它的攻击很强。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP047', '双头恐龙王', '恐龙族中的强力卡。用2个头同时攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP048', '侏罗纪抽卡', '【条件】把手卡1只怪兽（恐龙族）送去墓地才能发动。
【效果】自己抽2张。这个回合，自己不能用怪兽（恐龙族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP049', '大恐龙联力冲击', '【条件】让自己墓地4只怪兽（恐龙族）回到卡组才能发动。
【效果】选对方场上1张卡破坏。那之后，自己场上有表侧表示怪兽（10星）的场合，可以给与对方1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP050', '恐龙体温', '【条件】可以给自己场上1只表侧表示怪兽（恐龙族）装备。
【效果】装备怪兽不会被对方的效果破坏，那攻击带有贯通。对方回合只要装备怪兽在自己场上处于表侧表示，装备怪兽不会因效果回到手卡·卡组·额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP051', '奇迹之超进化', '【条件】对方回合对方抽卡时才能发动。
【效果】选自己场上1只表侧表示怪兽（恐龙族）。这个回合，那只怪兽不会被效果破坏。并且，可以再让自己墓地的怪兽（恐龙族）2只作为素材回到卡组把怪兽（9星以下/恐龙族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP052', '现梦中之丝绸蚕', '效果怪兽（7～9星/昆虫族）×2
【条件】这张卡融合术召唤的自己主要阶段，让自己墓地3只怪兽（9星以外/昆虫族）回到卡组才能发动。
【效果】这张卡的攻击力直到回合结束时上升500。那之后，可以选对方场上1张卡回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP053', '荣华梦中之丝绸蚕', '效果怪兽（7～9星/昆虫族）＋效果怪兽（昆虫族）
【条件】无
【永续效果】自己场上的表侧表示怪兽（昆虫族）不会被对方的效果破坏。对方不能把自己场上的怪兽作为融合术召唤的素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP054', '梦中之幼虫', '效果怪兽（6星以下/昆虫族）×2
【条件】无
【永续效果】自己场上的表侧表示怪兽（昆虫族）的攻击力上升800。对方回合内，自己场上的魔法·陷阱卡不会因效果回到手卡·卡组·额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP056', '梦中之大黄蜂', '【条件】自己墓地有怪兽（光属性/昆虫族）的场合，从卡组上面把3张卡送去墓地才能发动。
【效果】这张卡的攻击力直到回合结束时上升500。那之后，可以选自己墓地1只「梦中之丝绸蚕」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP057', '梦中之瓢虫', '【条件】自己场上有这张卡以外的表侧表示怪兽（光属性/昆虫族）的场合，把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】选对方场上1只表侧表示怪兽，那个攻击力·守备力直到回合结束时下降500。那之后，可以选对方场上1只表侧表示怪兽那个种族直到下次的对方回合结束时变成昆虫族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP058', '梦中之吉丁虫', '【条件】自己场上有这张卡以外的表侧表示怪兽（光属性/昆虫族）的场合，把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】选对方场上1只怪兽把表示形式变更。那之后，可以选对方场上1只表侧表示怪兽那个种族直到下次的对方回合结束时变成昆虫族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP059', '梦中之日铜罗花金龟', '【条件】自己场上有这张卡以外的表侧表示怪兽（光属性/昆虫族）的场合，把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以选对方场上1只表侧表示怪兽那个种族直到下次的对方回合结束时变成昆虫族。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP060', '梦中之萤火虫', '【条件】对方场上有怪兽2只以上的场合，把自己场上的表侧表示的这张卡和手卡1只怪兽送去墓地才能发动。
【效果】选持有和这个效果的条件从手卡送去墓地的怪兽相同种族的对方场上1只表侧表示怪兽（5～8星）得到那个控制权（向自己场上移动，由自己使用）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP061', '梦中之蝴蝶', '【条件】把攻击表示的这张卡变成表侧守备表示才能发动。
【效果】选对方场上1只表侧表示怪兽，那个种族直到回合结束时变成昆虫族。自己或者对方场上有这张卡以外的表侧守备表示怪兽的场合，再让自己可以抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP062', '代打蝗虫', '【条件】把自己场上的表侧表示的这张卡送去墓地才能发动。
【效果】手卡1只怪兽（昆虫族）在自己场上表侧表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP063', '龙蛾幼虫', '【条件】把手卡1只怪兽（昆虫族）送去墓地才能发动。
【效果】自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP064', '梦中的甘言', '【条件】无
【效果】从自己卡组上面把2张卡送去墓地。那之后，可以从那之中选怪兽（光属性/昆虫族）、「梦中的拥抱」、「梦中的再诞」的其中1张加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP065', '梦中的拥抱', '【条件】无
【效果】自己场上的表侧表示怪兽1只和自己或者对方场上的表侧表示怪兽（9星以下）1只作为素材送去墓地，把怪兽（光属性/昆虫族）融合术召唤。这个回合，自己不能用怪兽（昆虫族以外）攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP066', '侵入甲虫', '【条件】双方场上的表侧表示怪兽（昆虫族）合计是2只以上的场合，把1张手卡送去墓地才能发动。
【效果】自己抽1张。那之后，可以选对方场上1张魔法·陷阱卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP067', '梦中的再诞', '【条件】自己墓地有怪兽（昆虫族）的场合，对方回合对方抽卡时或者对方回合对方把怪兽召唤·特殊召唤时才能发动。
【效果】自己场上的表侧表示怪兽1只和自己或者对方场上的表侧表示怪兽（9星以下）1只作为素材送去墓地，把怪兽（光属性/昆虫族）融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP068', '蛛穴丝网', '【条件】对方把怪兽召唤时，让自己墓地1只怪兽（昆虫族）回到卡组下面才能发动。
【效果】那只召唤的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP069', '流圣之交融公主', '【条件】自己在这次主要阶段没有抽卡的场合才能发动。
【效果】选自己墓地1张「星之再起」或者「起始之星」加入手卡。那之后，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP070', '魔力动物魔女', '【条件】把手卡最多2只效果怪兽（7·8星/光属性）给对方观看才能发动。
【效果】自己抽出［这个效果的条件给人观看的怪兽的数量］。那之后，自己让手卡选［这个效果抽出的数量］回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP071', '深海龙 蝙蝠鳗', '【条件】把手卡最多3只怪兽（10星）给对方观看才能发动。
【效果】自己抽出［这个效果的条件给人观看的怪兽的数量］。那之后，自己让手卡选［这个效果抽出的数量］回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP072', '星之交替龙', '【条件】自己场上没有这张卡以外的怪兽的场合，让自己场上的这张卡回到持有者手卡才能发动。
【效果】选自己墓地1只怪兽（4星以下）在自己场上里侧守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不能从自己的手卡·墓地把怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP073', '星之再起', '【条件】让1张手卡回到卡组下面才能发动。
【效果】选自己墓地1只通常怪兽（5星以下）在自己场上表侧表示特殊召唤。那之后，可以选自己墓地1张「融合术」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP074', '天之加护', '【条件】无
【效果】手卡的怪兽选喜欢的数量送去墓地。［这个效果送去墓地的怪兽的等级合计］是10星以上的场合，再让自己可以抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP075', '融合术', '【条件】无
【效果】自己场上的表侧表示怪兽作为素材送去墓地作融合术召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP076', '真红眼黑龙', '拥有真红之眼的黑龙。愤怒的黑炎会把映入其眼者全部烧成灰烬。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP077', '恶魔召唤', '使用黑暗力量，迷惑人心的恶魔。在恶魔族中以相当强大的力量著称。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP078', '超传导恐兽', '【条件】把自己场上1只怪兽送去墓地才能发动。
【效果】给与对方1000伤害。这个回合，这张卡不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP079', '幻影之龙', '【条件】无
【永续效果】对方在双方的战斗阶段中不能把陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP080', '噩梦再临', '【条件】无
【效果】选自己墓地2只怪兽（暗属性/守备力0）加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP081', '成金哥布林', '【条件】无
【效果】自己抽1张。那之后，对方回复1000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP082', '闪电旋涡', '【条件】把1张手卡送去墓地才能发动。
【效果】对方场上的表侧表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP083', '攻击无力化', '【条件】对方怪兽的攻击宣言时才能发动。
【效果】那次攻击无效。这个回合，对方不能攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('RD/TB02-JP084', '波纹防护罩 -波浪之力-', '【条件】对方怪兽的直接攻击宣言时才能发动。
【效果】对方场上的攻击表示怪兽全部回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);

PRAGMA foreign_keys = true;
